#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define MCP3008_CS_PIN   8
#define MCP3008_CLK_PIN  10
#define MCP3008_MOSI_PIN 9
#define MCP3008_MISO_PIN 11

int main() {
    int fd, gpioHandle;
    int adcValue;
    struct gpio_desc desc;
    struct gpio_config gpioConfig;
    struct gpio_adc_config adcConfig;
    struct timespec startTime, endTime;
    double moistureTrend;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up GPIO pins
    gpioConfig.mode = GPIO_MODE_ANALOG;
    gpioConfig.pull = GPIO_PULL_UP;
    gpioConfig.speed = GPIO_SPEED_FREQ_HIGH;
    gpioConfig.intr_type = GPIO_INTR_TYPE_EDGE_FALLING;
    gpioConfig.intr_edge = GPIO_INTR_EDGE_FALLING;

    gpioHandle = gpioSetup(MCP3008_CS_PIN, MCP3008_CLK_PIN, MCP3008_MOSI_PIN, MCP3008_MISO_PIN, &gpioConfig);
    if (gpioHandle < 0) {
        fprintf(stderr, "Error: Failed to set up GPIO pins\n");
        gpioTerminate();
        return 1;
    }

    // Set up ADC channel
    adcConfig.channel = ADC_CHANNEL_0;
    adcConfig.sample_time = 100; // Sample every 100ms
    adcConfig.resolution = ADC_RESOLUTION_10BIT;

    // Open SPI device
    fd = pigpio_open(0);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    // Set up SPI transfer parameters
    gpio_adc_config(gpioHandle, &adcConfig);
    gpio_adc_start(gpioHandle);

    // Start reading ADC values
    while (1) {
        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &startTime);

        // Read ADC value
        adcValue = pigpio_read_adc(fd, 0);

        // Calculate moisture trend
        moistureTrend = (adcValue - 512) * (1023.0 / 1023.0) * (100.0 / 1023.0);

        // Log timestamp and moisture trend
        printf("Timestamp: %s, Moisture Trend: %.2f\n", ctime(&startTime.tv_sec), moistureTrend);

        // Sleep for 1 second
        sleep(1);

        // Get current time again
        clock_gettime(CLOCK_MONOTONIC, &endTime);
        double elapsedTime = (endTime.tv_sec - startTime.tv_sec) + (endTime.tv_nsec - startTime.tv_nsec) / 1000000000.0;

        // Calculate the ADC value's percentage of full scale
        adcValue = (adcValue - 512) * (1023.0 / 1023.0) * (100.0 / 1023.0) * (1.0 / (2.0 * (pow(2.0, 11.0))));

        // Log the ADC value and elapsed time
        printf("ADC Value: %d, Elapsed Time: %.2f seconds\n", adcValue, elapsedTime);
    }

    // Clean up GPIO pins
    gpioTerminate();

    return 0;
}

