#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>

#define SPI_DEVICE_PATH "/dev/spidev0.0"
#define MCP3008_CHANNEL_COUNT 8
#define ADC_MAX_VALUE 1023
#define ADC_MIN_VALUE 0
#define ADC_LINEAR_MAP_RANGE 10.0f / 40.0f

int main() {
    int fd, gpio_fd, spi_fd;
    struct spi_device *spi;
    struct gpio_desc *gpio;
    struct mcp3008_config config = {
        .channel_count = MCP3008_CHANNEL_COUNT,
        .channel_order = MCP3008_CHANNEL_ORDER_LSB_FIRST,
    };
    struct mcp3008_data data;
    char filename[128] = "flame_data.csv";
    char timestamp[32] = {0};
    char line[128] = {0};
    FILE *fp;
    int i, j, k;
    int adc_value, temperature;
    int ret;

    // Initialize pigpio library
    if (gpio_init() < 0 || spi_init() < 0) {
        fprintf(stderr, "Error initializing pigpio or SPI\n");
        return 1;
    }

    // Open SPI device
    if ((spi_open(SPI_DEVICE_PATH, &spi) < 0) ||
        (gpio_open(GPIO_MODE_OUTPUT, &gpio_fd) < 0) ||
        (gpio_open(GPIO_MODE_INPUT, &gpio_fd) < 0)) {
        fprintf(stderr, "Error opening SPI device\n");
        return 1;
    }

    // Open SPI device for reading
    if ((spi_open(SPI_DEVICE_PATH, &spi) < 0) ||
        (gpio_open(GPIO_MODE_OUTPUT, &gpio_fd) < 0) ||
        (gpio_open(GPIO_MODE_INPUT, &gpio_fd) < 0)) {
        fprintf(stderr, "Error opening SPI device for reading\n");
        return 1;
    }

    // Set SPI device configuration
    if (spi_set_mode(spi, SPI_MODE_0) < 0) {
        fprintf(stderr, "Error setting SPI mode\n");
        return 1;
    }

    if (spi_set_speed(spi, 1000000) < 0) {
        fprintf(stderr, "Error setting SPI speed\n");
        return 1;
    }

    // Set GPIO4 as SPI0 CE0/GPIO8
    if (gpio_set_level(gpio_fd, GPIO_OUTPUT, 4) < 0) {
        fprintf(stderr, "Error setting GPIO4 as SPI0 CE0/GPIO8\n");
        return 1;
    }

    if (gpio_set_level(gpio_fd, GPIO_OUTPUT, 8) < 0) {
        fprintf(stderr, "Error setting GPIO8 as SPI0 CE0/GPIO8\n");
        return 1;
    }

    // Set up MCP3008 ADC
    if (mcp3008_init(&config) < 0) {
        fprintf(stderr, "Error initializing MCP3008 ADC\n");
        return 1;
    }

    // Read analog value from KY-026
    if (mcp3008_read_channel(&data, 0) < 0) {
        fprintf(stderr, "Error reading analog value from KY-026\n");
        return 1;
    }

    adc_value = data.values[0];

    // Read digital value from KY-026
    if (mcp3008_read_channel(&data, 1) < 0) {
        fprintf(stderr, "Error reading digital value from KY-026\n");
        return 1;
    }

    k = data.values[1];

    // Read analog value from MCP3008 channel 0
    if (mcp3008_read_channel(&data, 0) < 0) {
        fprintf(stderr, "Error reading analog value from MCP3008 channel 0\n");
        return 1;
    }

    temperature = (adc_value * ADC_MAX_VALUE) / ADC_LINEAR_MAP_RANGE;

    // Log timestamped CSV row
    snprintf(timestamp, sizeof(timestamp), "%s,%d,%d\n", timestamp, (int)adc_value, temperature);

    // Open CSV file for writing
    if ((fp = fopen(filename, "a")) == NULL) {
        fprintf(stderr, "Error opening CSV file for writing\n");
        return 1;
    }

    // Write timestamped CSV row
    fputs(timestamp, fp);

    // Close CSV file
    fclose(fp);

    // Release SPI device
    spi_close(spi);

    // Release GPIO devices
    gpio_close(gpio_fd);
    gpio_close(gpio_fd);

    // Release MCP3008 ADC
    mcp3008_exit();

    return 0;
}

