#include <sys/types.h>
#include <sys/stat.h>

#define I2C_BUS_NUM 1
#define I2C_DEVICE_ADDR 0x28

// Constants
#define CO_ELEMENT_NO2_RESISTANCE_MULTIPLIER 0.0078
#define CO_ELEMENT_CO_RESISTANCE_MULTIPLIER 0.0078
#define CO_ELEMENT_NO2_RESISTANCE_OFFSET 0.5
#define CO_ELEMENT_CO_RESISTANCE_OFFSET 0.5
#define CO_ELEMENT_NO2_RESISTANCE_MIN 0.3
#define CO_ELEMENT_NO2_RESISTANCE_MAX 0.9
#define CO_ELEMENT_CO_RESISTANCE_MIN 0.3
#define CO_ELEMENT_CO_RESISTANCE_MAX 0.9

// Function prototypes
void initialize_pigpio();
void cleanup_pigpio();
int read_i2c_sensor(int i2c_fd, uint16_t* raw_value);
void convert_raw_to_ppm(int raw_value, int* ppm);
void log_ppm_to_file(int ppm, char* timestamp);

int main() {
    int i2c_fd;
    int ppm_value;
    int error_code;

    // Initialize pigpio
    initialize_pigpio();

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C device address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_DEVICE_ADDR) < 0) {
        perror("Error setting I2C device address");
        exit(EXIT_FAILURE);
    }

    // Open I2C device file
    if ((error_code = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Error opening I2C device file");
        exit(EXIT_FAILURE);
    }

    // Read raw CO resistance value
    if ((error_code = read_i2c_sensor(i2c_fd, &raw_co_value)) < 0) {
        perror("Error reading CO sensor");
        exit(EXIT_FAILURE);
    }

    // Convert raw CO resistance value to ppm
    ppm_value = convert_raw_to_ppm(raw_co_value, &co_ppm);

    // Log the timestamped PPM value
    log_ppm_to_file(ppm_value, "2022-08-15 12:00:00");

    // Close I2C device file
    close(error_code);

    // Close I2C bus
    close(i2c_fd);

    // Cleanup pigpio
    cleanup_pigpio();

    return 0;
}

void initialize_pigpio() {
    int error_code;

    // Initialize pigpio library
    if ((error_code = pigpio_init()) < 0) {
        perror("Error initializing pigpio library");
        exit(EXIT_FAILURE);
    }

    // Enable I2C
    if (!pigpio_i2c_setup(I2C_BUS_NUM, I2C_DEVICE_ADDR)) {
        perror("Error setting up I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C speed
    if (pigpio_set_speed(100000) < 0) {
        perror("Error setting I2C speed");
        exit(EXIT_FAILURE);
    }
}

void cleanup_pigpio() {
    if (pigpio_exit() < 0) {
        perror("Error exiting pigpio library");
        exit(EXIT_FAILURE);
    }
}

int read_i2c_sensor(int i2c_fd, uint16_t* raw_value) {
    int error_code;
    struct i2c_msg msg[2];
    msg[0].addr = I2C_DEVICE_ADDR;
    msg[0].flags = 0;
    msg[1].addr = I2C_DEVICE_ADDR;
    msg[1].flags = I2C_M_RD;
    msg[1].len = 2;
    msg[1].buf = (void*)raw_value;

    error_code = i2c_transfer(i2c_fd, msg, 2);

    if (error_code < 0) {
        perror("Error reading I2C sensor");
        exit(EXIT_FAILURE);
    }

    return error_code;
}

void convert_raw_to_ppm(int raw_value, int* ppm) {
    int co_ppm;
    int co_resistance;

    // Read CO sensor raw resistance value
    if ((error_code = read_i2c_sensor(i2c_fd, &raw_co_value)) < 0) {
        perror("Error reading CO sensor");
        exit(EXIT_FAILURE);
    }

    // Calculate CO resistance
    co_resistance = (raw_co_value * CO_ELEMENT_CO_RESISTANCE_MULTIPLIER) + CO_ELEMENT_CO_RESISTANCE_OFFSET;

    // Calculate CO concentration in PPM
    co_ppm = (raw_co_value * CO_ELEMENT_NO2_RESISTANCE_MULTIPLIER) / (1.0 + (co_resistance / (CO_ELEMENT_NO2_RESISTANCE_MULTIPLIER * CO_ELEMENT_NO2_RESISTANCE_OFFSET)));

    *ppm = co_ppm;
}

void log_ppm_to_file(int ppm, char* timestamp) {
    FILE* log_file = fopen("co_log.txt", "a");

    if (log_file == NULL) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    char log_line[50];
    sprintf(log_line, "%s, %s\n", timestamp, ppm);
    fprintf(log_file, "%s\n", log_line);

    fclose(log_file);
}

