#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_ADDR 0x48
#define LED_GPIO 17

// Constants
#define SAMPLING_FREQ 10000
#define THRESHOLD 50.0

// Data structures
struct CurrentData {
    float voltage;
    float current;
};

// Global variables
static gpio_t gpio;
static pigpio_error_t error;
static pigpio_i2c_t i2c;
static pigpio_i2c_fd_t i2c_fd;
static struct CurrentData current_data[100];
static int current_index = 0;
static bool warning_led_on = false;

// Function prototypes
void initialize_gpio();
void initialize_pigpio();
void initialize_i2c();
void read_sensor();
void log_current();
void handle_warning_led();
void handle_sigint();

int main() {
    // Initialize GPIO and pigpio
    initialize_gpio();
    initialize_pigpio();

    // Initialize I2C
    initialize_i2c();

    // Start sampling and logging
    while (true) {
        read_sensor();
        log_current();
        sleep(1);
    }

    // Cleanup
    close(i2c_fd);
    gpio_release(gpio);
    pigpio_exit();

    return 0;
}

void initialize_gpio() {
    gpio = pigpio_initialize();
    if (gpio == NULL) {
        printf("Failed to initialize GPIO.\n");
        return;
    }

    pigpio_set_mode(gpio, PI_OUTPUT);
    pigpio_set_dir(gpio, PI_OUTPUT);
}

void initialize_pigpio() {
    error = pigpio_init();
    if (error != PI_SUCCESS) {
        printf("Failed to initialize pigpio: %s\n", pigpio_strerror(error));
        return;
    }

    i2c_fd = pigpio_i2c_open(gpio, PI_I2C_SDA_GPIO(2), PI_I2C_SCL_GPIO(3), 1);
    if (i2c_fd == NULL) {
        printf("Failed to open I2C bus.\n");
        return;
    }

    pigpio_i2c_set_speed(i2c_fd, SAMPLING_FREQ);
}

void initialize_i2c() {
    struct i2c_rdwr_ioctl_data data;
    data.flags = 0;
    data.timeout_ms = 100;

    if (ioctl(i2c_fd, I2C_RDWR, &data) < 0) {
        printf("Failed to open I2C device.\n");
        return;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        printf("Failed to set I2C slave address.\n");
        return;
    }

    if (ioctl(i2c_fd, I2C_RDWR, &data) < 0) {
        printf("Failed to set I2C device to slave mode.\n");
        return;
    }
}

void read_sensor() {
    struct CurrentData current;

    if (pigpio_i2c_read_device(i2c_fd, I2C_ADDR, &current, 1) != 1) {
        printf("Failed to read current data from sensor.\n");
        return;
    }

    current_data[current_index].voltage = current.voltage * (5.0 / (float)0x5A);
    current_data[current_index].current = current.current * (float)0.5 / (float)100.0;

    if (current_index >= 100) {
        current_index = 0;
    }

    current_index++;
}

void log_current() {
    int i;
    for (i = 0; i < current_index; i++) {
        printf("Current: %.2fA, Voltage: %.2fV\n", current_data[i].current, current_data[i].voltage);
    }
}

void handle_warning_led() {
    if (warning_led_on) {
        pigpio_set_gpio_level(LED_GPIO, 1);
        sleep(1);
        pigpio_set_gpio_level(LED_GPIO, 0);
        warning_led_on = false;
    }
}

void handle_sigint() {
    printf("Shutting down...\n");
    warning_led_on = false;
    pigpio_exit();
}

int main() {
    // Initialize GPIO and pigpio
    initialize_gpio();
    initialize_pigpio();

    // Initialize I2C
    initialize_i2c();

    // Start sampling and logging
    while (true) {
        read_sensor();
        log_current();
        sleep(1);
    }

    // Cleanup
    close(i2c_fd);
    gpio_release(gpio);
    pigpio_exit();

    return 0;
}

