int main() {
    int i2c_fd;
    int gpio_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_mem *gpio_mem;
    char color_log_file[128];
    char header_row[32];
    char *log_file = color_log_file;
    int log_file_fd;
    int log_file_size = 0;
    int log_file_offset = 0;
    int log_file_write_status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = pigpioOpenI2C(I2C_BUS_NUM, I2C_ADDR)) < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open GPIO memory
    gpio_mem = (struct gpio_mem *)gpioMmap(0x3F000000, 0x1000);
    if (gpio_mem == NULL) {
        fprintf(stderr, "Error mapping GPIO memory\n");
        gpioTerminate();
        return 1;
    }

    // Create color log file
    snprintf(color_log_file, sizeof(color_log_file), "color_log.csv");
    if ((log_file_fd = open(color_log_file, O_CREAT | O_WRONLY | O_TRUNC, 0644)) < 0) {
        fprintf(stderr, "Error creating color log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up header row
    snprintf(header_row, sizeof(header_row), "%.4s,%.4s,%.4s,%.4s\n",
             "YYYY-MM-DD HH:MM:SS", "", "", "", "");

    // Main loop
    while (1) {
        // Read sensor ID
        if (i2cReadReg16(i2c_fd, I2C_ADDR, 0x12) < 0) {
            fprintf(stderr, "Error reading sensor ID\n");
            gpioTerminate();
            return 1;
        }
        uint16_t id_data = i2c_data.data;
        if (id_data != 0x4444) {
            fprintf(stderr, "Sensor ID does not match 0x4444\n");
            gpioTerminate();
            return 1;
        }

        // Configure sensor
        if (i2cWriteReg16(i2c_fd, I2C_ADDR, 0x01, 0xFF) < 0) {
            fprintf(stderr, "Error configuring sensor\n");
            gpioTerminate();
            return 1;
        }
        if (i2cWriteReg16(i2c_fd, I2C_ADDR, 0x0F, 0x01) < 0) {
            fprintf(stderr, "Error configuring sensor\n");
            gpioTerminate();
            return 1;
        }

        // Power on ADC and wait at least 3 ms
        if (i2cWriteReg8(i2c_fd, I2C_ADDR, 0x00, 0x01 | 0x02) < 0) {
            fprintf(stderr, "Error powering on ADC\n");
            gpioTerminate();
            return 1;
        }
        sleep(3);

        // Read sensor data
        uint16_t clear_data, red_data, green_data, blue_data;
        if (i2cReadReg16(i2c_fd, I2C_ADDR, 0x14, &clear_data) < 0 ||
            i2cReadReg16(i2c_fd, I2C_ADDR, 0x15, &red_data) < 0 ||
            i2cReadReg16(i2c_fd, I2C_ADDR, 0x16, &green_data) < 0 ||
            i2cReadReg16(i2c_fd, I2C_ADDR, 0x17, &blue_data) < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            gpioTerminate();
            return 1;
        }

        // Append data to CSV file
        if (log_file_size == 0) {
            log_file_offset = 0;
        } else {
            log_file_offset += snprintf(log_file + log_file_offset, sizeof(log_file) - log_file_offset,
                                         "%.4s,%.4s,%.4s,%.4s\n",
                                         "YYYY-MM-DD HH:MM:SS",
                                         (char *)&clear_data,
                                         (char *)&red_data,
                                         (char *)&green_data,
                                         (char *)&blue_data);
        }
        log_file_write_status = write(log_file_fd, log_file + log_file_offset, log_file_size - log_file_offset);
        if (log_file_write_status < 0) {
            fprintf(stderr, "Error writing to color log file\n");
            gpioTerminate();
            return 1;
        }

        // Append header row
        if (log_file_size == 0) {
            log_file_write_status = write(log_file_fd, header_row, sizeof(header_row) - 1);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    gpioTerminate();
    close(log_file_fd);
    munmap(gpio_mem, 0x1000);
    pigpioClose(i2c_fd);

    return 0;
}
