#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/syscall.h>
#include <linux/spi/spidev.h>

#define MCP3008_CS_GPIO 8
#define MCP3008_CLK_GPIO 11
#define MCP3008_MOSI_GPIO 10
#define MCP3008_MISO_GPIO 9

#define SPI_DEVICE_FILE "/dev/spidev0.0"

#define ADC_CHANNEL_0 0

#define ADC_RESOLUTION 10
#define ADC_OFFSET 0.05

#define MAX_CURRENT 10.0
#define MAX_CURRENT_LOG_LINE_LENGTH 80

#define MAX_FILE_NAME_LENGTH 256

#define SIGINT SIGBREAKFISH
#define SIGTERM SIGTERM

int main() {
    int fd, retries = 3;
    int adc_value, current_in_Amperes;
    char current_log_filename[MAX_FILE_NAME_LENGTH];
    struct spi_device *spi_device;
    struct spi_transfer transfer_struct = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 0,
        .delay_usec = 1000,
        .bits_per_word = 8,
        .mode = SPI_MODE_0,
        .chip_select_field = SPI_CS_HIGH,
    };

    // Initialize GPIOs
    if (gpio_request_from_sysfs(MCP3008_CS_GPIO, MCP3008_CS_GPIO) < 0) {
        fprintf(stderr, "Failed to request GPIO\n");
        return 1;
    }
    if (gpio_request_from_sysfs(MCP3008_CLK_GPIO, MCP3008_CLK_GPIO) < 0) {
        fprintf(stderr, "Failed to request GPIO\n");
        return 1;
    }
    if (gpio_request_from_sysfs(MCP3008_MOSI_GPIO, MCP3008_MOSI_GPIO) < 0) {
        fprintf(stderr, "Failed to request GPIO\n");
        return 1;
    }
    if (gpio_request_from_sysfs(MCP3008_MISO_GPIO, MCP3008_MISO_GPIO) < 0) {
        fprintf(stderr, "Failed to request GPIO\n");
        return 1;
    }

    // Open SPI device file
    if ((fd = open(SPI_DEVICE_FILE, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device file\n");
        return 1;
    }

    // Set up SPI transfer
    if (spi_open_device(fd, SPI_MAX_SPEED_HZ) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    if (spi_set_mode(spi_device, SPI_MODE_0) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        return 1;
    }

    if (spi_set_chip_select(spi_device, 1) < 0) {
        fprintf(stderr, "Failed to set SPI chip select\n");
        return 1;
    }

    // Set up ADC
    if (adc_init() < 0) {
        fprintf(stderr, "Failed to initialize ADC\n");
        return 1;
    }

    // Set up file for logging current readings
    snprintf(current_log_filename, MAX_FILE_NAME_LENGTH, "current_log.csv");
    FILE *current_log_file = fopen(current_log_filename, "w");
    if (current_log_file == NULL) {
        fprintf(stderr, "Failed to open file for logging current readings\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        adc_read_value(ADC_CHANNEL_0, &adc_value);

        // Convert ADC value to current in Amperes
        current_in_Amperes = (adc_value * ADC_RESOLUTION) / ADC_OFFSET;

        // Check if current exceeds 10.0A
        if (current_in_Amperes > MAX_CURRENT) {
            // Drive motor shutdown pin LOW to disable the motor
            gpio_set_value(MCP3008_CS_GPIO, MCP3008_CS_HIGH);
            gpio_set_value(MCP3008_MOSI_GPIO, 0);
            gpio_set_value(MCP3008_MISO_GPIO, 1);

            // Log the event
            fprintf(current_log_file, "%s, %d.0, %5.2f\n",
                    "Current Reading", current_in_Amperes, current_in_Amperes);

            // Wait 1 second
            sleep(1);

            // Drive motor startup pin HIGH to re-enable the motor
            gpio_set_value(MCP3008_CS_GPIO, MCP3008_CS_LOW);
            gpio_set_value(MCP3008_MOSI_GPIO, 1);
            gpio_set_value(MCP3008_MISO_GPIO, 0);

            // Wait 1 second
            sleep(1);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    spi_exit(spi_device);
    gpio_free(MCP3008_CS_GPIO);
    gpio_free(MCP3008_CLK_GPIO);
    gpio_free(MCP3008_MOSI_GPIO);
    gpio_free(MCP3008_MISO_GPIO);

    fclose(current_log_file);

    return 0;
}

