#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>

#include <pigpio.h>

#define MCP3008_CHANNEL_COUNT 8
#define CO_SENSOR_CHANNEL 0
#define ALARM_GPIO_PIN 4
#define ALARM_GPIO_VALUE 0

int main() {
    int spi_fd, gpio_fd, log_fd;
    struct spi_device *spi;
    struct gpio_desc *gpio;
    struct timeval start_time, end_time;
    double voltage;
    char log_file_name[] = "co_log.txt";

    // Initialize SPI and GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (spiOpen("/dev/spidev0.0", &spi_fd) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    gpio_fd = gpioOpen(spi_fd, "/sys/class/gpio/gpio24");
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO file\n");
        return 1;
    }

    // Configure SPI bus at 1 MHz
    if (gpioSetSpeed(gpio_fd, SPI_MODE0) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        return 1;
    }

    // Set up SPI transfer function
    if (gpioTransfer(gpio_fd, GPIO_OUTPUT_LEVEL_HIGH, ALARM_GPIO_VALUE) < 0) {
        fprintf(stderr, "Failed to set GPIO output level\n");
        return 1;
    }

    // Open log file
    log_fd = open(log_file_name, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Start reading ADC values
    while (1) {
        // Read ADC value
        if (gpioTransfer(gpio_fd, GPIO_INPUT_LEVEL, ALARM_GPIO_VALUE) < 0) {
            fprintf(stderr, "Failed to read GPIO input level\n");
            return 1;
        }

        // Convert ADC value to voltage
        voltage = (double)ALARM_GPIO_VALUE / 1023.0 * 3.3;

        // Check if voltage exceeds 2.5V
        if (voltage > 2.5) {
            // Set GPIO4 to HIGH to trigger alarm
            gpioWrite(gpio_fd, ALARM_GPIO_VALUE, ALARM_GPIO_VALUE);
        } else {
            // Set GPIO4 to LOW to turn off alarm
            gpioWrite(gpio_fd, ALARM_GPIO_VALUE, 0);
        }

        // Log the reading
        if (gpioTransfer(gpio_fd, GPIO_OUTPUT_LEVEL_LOW, 0) < 0) {
            fprintf(stderr, "Failed to write to GPIO\n");
            return 1;
        }

        // Log the reading
        struct timeval now;
        gettimeofday(&now, NULL);
        char log_line[32];
        sprintf(log_line, "%s,%.2f V\n", ctime(&now.tv_sec), voltage);
        if (write(log_fd, log_line, strlen(log_line)) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
            return 1;
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close log file and SPI handle
    close(log_fd);
    gpioClose(spi_fd);
    gpioClose(gpio_fd);

    // Clean up GPIO resources
    gpioTerminate();

    return 0;
}

