#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <time.h>
#include <stdint.h>
#include <string.h>

#include <pigpio.h>

#define MCP3008_CS_PIN 8
#define MCP3008_CLK_PIN 11
#define MCP3008_MISO_PIN 9
#define MCP3008_MOSI_PIN 10

int main() {
    int fd;
    int gpioHandle;
    int spiHandle;
    int i;
    int adcValue;
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data i2c_data;
    char logFilePath[128];
    char* logMessage;
    char* leakAlarmMessage;
    pid_t pid;
    sigset_t set;
    struct sigaction action;
    int exitCode;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Open SPI bus
    if ((fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set up SPI transfer parameters
    if (spiXfer(fd, (uint8_t*)&msgs[0], 1, I2C_MEASUREMENT) < 0) {
        fprintf(stderr, "Failed to transfer data to MCP3008: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Open MCP3008
    if ((gpioHandle = gpioOpen(MCP3008_CS_PIN)) < 0) {
        fprintf(stderr, "Failed to open MCP3008: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Open log file
    if ((fd = open(logFilePath, O_APPEND | O_CREAT | O_TRUNC, 0644)) < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set up log message
    logMessage = "Methane concentration: ";
    leakAlarmMessage = "Leak detected! Aborting.";

    // Set up signal handlers
    sigemptyset(&set);
    sigaddset(&set, SIGINT);
    sigaddset(&set, SIGTERM);
    action.sa_handler = SIGINT | SIGTERM;
    action.sa_flags = SA_RESETHAND | SA_SIGINFO;
    if (sigaction(SIGINT, &action, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Start main loop
    while (1) {
        // Read ADC value
        if (spiXfer(fd, (uint8_t*)&msgs[1], 1, I2C_MEASUREMENT) < 0) {
            fprintf(stderr, "Failed to transfer data to MCP3008: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }
        adcValue = ((msgs[1].buf[2] & 0x03) << 8) | msgs[1].buf[3];

        // Convert ADC value to methane concentration
        if (adcValue < 0 || adcValue > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", adcValue);
            continue;
        }
        adcValue /= 10;
        adcValue *= 5000;

        // Log the reading
        if (adcValue > 1000) {
            fprintf(stderr, "Leak detected!\n");
            exit(EXIT_FAILURE);
        }
