#define ADC_CHANNELS 0
#define ADC_RESOLUTION 10
#define ADC_SENSITIVITY 300

int main() {
    int fd, gpio_fd, spi_fd;
    struct spi_device *spi;
    struct gpio_desc *gpio;
    struct gpio_config gpio_config = {
        .pin_bit_mask = GPIO_INPUT_MASK,
        .direction_output = 1,
    };

    // Initialize pigpio library
    if (gpio_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    // Open SPI device file
    if ((fd = open(SPI_DEVICE_FILE, O_RDWR)) < 0) {
        fprintf(stderr, "Error: Failed to open SPI device file\n");
        gpio_exit();
        return 1;
    }

    // Open GPIO file
    if ((gpio_fd = open("/dev/gpiochip0", O_RDWR)) < 0) {
        fprintf(stderr, "Error: Failed to open GPIO file\n");
        close(fd);
        gpio_exit();
        return 1;
    }

    // Open SPI device file
    if ((spi = spi_open(spi_fd)) < 0) {
        fprintf(stderr, "Error: Failed to open SPI device file\n");
        close(gpio_fd);
        gpio_exit();
        return 1;
    }

    // Set SPI mode, polarity, and phase
    if (spi_set_mode(spi, SPI_MODE_0) < 0) {
        fprintf(stderr, "Error: Failed to set SPI mode\n");
        spi_close(spi);
        close(gpio_fd);
        gpio_exit();
        return 1;
    }

    // Set SPI clock speed
    if (spi_set_speed(spi, 1000000) < 0) {
        fprintf(stderr, "Error: Failed to set SPI clock speed\n");
        spi_close(spi);
        close(gpio_fd);
        gpio_exit();
        return 1;
    }

    // Set SPI chip select pin
    if (gpio_request_from_sysfs(gpio_fd, GPIO_ADJUST_PUD_UP, &gpio) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO\n");
        spi_close(spi);
        close(gpio_fd);
        gpio_exit();
        return 1;
    }
    gpio_set_dir(gpio, GPIO_OUTPUT);
    gpio_set_value(gpio, 1);

    // Set SPI chip select pin to low
    gpio_set_value(gpio, 0);

    // Set up SPI transfer parameters
    if (spi_transfer(spi, (unsigned char *)&spi_data, 1, SPI_TRANSFER_BLOCKING) < 0) {
        fprintf(stderr, "Error: Failed to send SPI transfer\n");
        spi_close(spi);
        close(gpio_fd);
        gpio_exit();
        return 1;
    }

    // Close SPI device file
    close(spi_fd);

    // Close GPIO file
    close(gpio_fd);

    // Close pigpio library
    gpio_exit();

    // Read X, Y, Z ADC values from MCP3008
    if (read_adc_values(spi, ADC_CHANNELS) < 0) {
        fprintf(stderr, "Error: Failed to read ADC values\n");
        return 1;
    }

    // Log the X, Y, Z raw ADC values to impact_log.txt
    FILE *log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        return 1;
    }

    for (int i = 0; i < ADC_RESOLUTION; i++) {
        fprintf(log_file, "%f, ", adc_values[i]);
    }

    fprintf(log_file, "\n");
    fclose(log_file);

