#define SENSOR_ADDRESS 0x04 // SpiroQuant A+ ES1-005 Mass Flow Sensor I2C address
#define SENSOR_CS_PIN 8 // CE0/GPIO8
#define ADC_CS_PIN 9 // CE1/GPIO9
#define ADC_SPI_DEVICE 0 // SPI device number

#define ADC_RESOLUTION 10 // ADC resolution (10-bit)
#define ADC_MAX_VALUE (1 << ADC_RESOLUTION) - 1
#define ADC_MIN_VALUE 0

#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 5.0

#define BAUDRATE 1000000 // 1 MHz
#define SPI_CHANNEL 0

#define FILE_NAME "flow_log.csv"

int main() {
    int rc;
    int adcValue;
    float flowRate;
    char timestamp[30];
    FILE *fp;
    char *line = NULL;
    char *delim = ",";
    char *error_message = NULL;

    // Initialize pigpio
    if (gpio_init() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return 1;
    }

    if (pippoio_init() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Open SPI device
    if ((fp = fopen("/dev/spidev0.0", "r")) == NULL) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return 1;
    }

    // Set up SPI transfer parameters
    if (pippoio_set_mode(SPI_MODE_0, BAUDRATE, SPI_CS_HIGH, SPI_CS_LOW, 0) < 0) {
        fprintf(stderr, "Error setting up SPI transfer parameters: %s\n", strerror(errno));
        return 1;
    }

    // Set up ADC channel
    if (pippoio_set_channel(ADC_CS_PIN, ADC_RESOLUTION) < 0) {
        fprintf(stderr, "Error setting up ADC channel: %s\n", strerror(errno));
        return 1;
    }

    // Set up ADC conversion
    if (pippoio_set_adc_conversion(ADC_CS_PIN, ADC_MAX_VALUE, ADC_MIN_VALUE) < 0) {
        fprintf(stderr, "Error setting up ADC conversion: %s\n", strerror(errno));
        return 1;
    }

    // Set up timestamp
    if (snprintf(timestamp, sizeof(timestamp), "%s%d", "YYYY-MM-DD ", (int)time(NULL)) < 0) {
        fprintf(stderr, "Error formatting timestamp: %s\n", strerror(errno));
        return 1;
    }

    // Set up log file
    if ((fp = fopen(FILE_NAME, "a")) == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Set up error message
    if ((error_message = (char *)malloc(256 * sizeof(char))) == NULL) {
        fprintf(stderr, "Error allocating memory: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor value
        if ((rc = pigpio_read_adc(SENSOR_CS_PIN, &adcValue, ADC_RESOLUTION)) < 0) {
            fprintf(stderr, "Error reading ADC value: %s\n", strerror(errno));
            free(error_message);
            error_message = (char *)malloc(256 * sizeof(char));
            snprintf(error_message, 256, "Error: %s\n", strerror(errno));
            break;
        }

        // Check if ADC value is 0 or full-scale
        if (adcValue == 0 || adcValue == ADC_MAX_VALUE) {
            fprintf(stderr, "Sensor absent: ADC value is either 0 or full-scale\n");
            free(error_message);
            error_message = (char *)malloc(256 * sizeof(char));
            snprintf(error_message, 256, "Error: Sensor absent: ADC value is either 0 or full-scale\n");
            break;
        }

        // Calculate flow rate
        flowRate = (adcValue * ADC_MAX_VALUE) / ADC_RESOLUTION;

        // Check if flow rate is within valid range
        if (flowRate < FLOW_RATE_MIN || flowRate > FLOW_RATE_MAX) {
            fprintf(stderr, "Error: Flow rate is out of range: %f\n", flowRate);
            free(error_message);
            error_message = (char *)malloc(256 * sizeof(char));
            snprintf(error_message, 256, "Error: Flow rate is out of range: %f\n", flowRate);
            break;
        }

        // Log data
        if (fprintf(fp, "%s,%f\n", timestamp, flowRate) < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            free(error_message);
            error_message = (char *)malloc(256 * sizeof(char));
            snprintf(error_message, 256, "Error: %s\n", strerror(errno));
            break;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up resources
    fclose(fp);
    pippoio_exit();
    gpio_exit();

    free(error_message);
    return 0;
}

