    int retry_limit = 3;
    int retry_interval = 500;

    // Open SPI device
    fd = open(MCP3008_SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return 1;
    }

    // Open GPIO file
    gpio_file = gpiod_open(fd, MCP3008_CS_GPIO);
    if (gpio_file == NULL) {
        perror("Error opening GPIO file");
        goto error_close_spi;
    }

    // Set GPIO value to 0
    gpio_value_range_data_raw.value = 0;
    gpio_value_range_data_raw.flags = GPIGPIO_VALUE_RAW_LOW;
    gpio_value_range_data_raw.value_raw = 0;
    gpio_value_range_data_raw.flags_raw = GPIGPIO_VALUE_RAW_LOW;
    gpio_value_range_data_raw.value_range_data = &gpio_value_range_data_raw;

    retry_count = 0;
    retry_limit = 3;
    retry_interval = 500;

error_close_spi:
    // Close SPI device
    close(fd);

    // Close GPIO file
    gpiod_close(gpio_file);

error_close_gpio:
    // Close libgpiod resources
    gpiod_release(fd);

    // Log error and exit
    perror("Error");
    return 1;
}

void read_sensor() {
    int adc_value;
    int compensated_voltage_raw;
    int temperature_raw;
    int temperature;

    // Read ADC value
    retry_count = 0;
    retry_limit = 3;
    retry_interval = 500;

error_read_sensor:
    while (retry_count < retry_limit) {
        retry_count++;
        adc_value = gpiod_get_value(gpio_file);
        if (adc_value == 0) {
            usleep(retry_interval);
            continue;
        }

        break;
    }

    // Check if ADC value is out of range
    if (adc_value < 0 || adc_value > 1023) {
        retry_count = 0;
        retry_limit = 3;
        retry_interval = 500;

        while (retry_count < retry_limit) {
            retry_count++;
            adc_value = gpiod_get_value(gpio_file);
            if (adc_value == 0) {
                usleep(retry_interval);
                continue;
            }

            break;
        }

        // If ADC value is out of range, log the error and skip iteration
        perror("ADC value out of range");
        return;
    }

    // Read temperature compensation value
    retry_count = 0;
    retry_limit = 3;
    retry_interval = 500;

error_read_temperature:
    while (retry_count < retry_limit) {
        retry_count++;
        compensated_voltage_raw = (adc_value << 1) + 0x3B;
        temperature_raw = compensated_voltage_raw >> 4;

        temperature = temperature_raw * 0.001 + 25.0;

        break;
    }

    // Compute compensated voltage
    compensated_voltage[0] = (compensated_voltage_raw >> 8) & 0xFF;
    compensated_voltage[1] = compensated_voltage_raw & 0xFF;

    // Log compensated voltage
    snprintf(timestamp, sizeof(timestamp), "%s", asctime(localtime(&end_time.tv_sec)));
    snprintf(voltage, sizeof(voltage), "%.2f", compensated_voltage[0] / 10.0);
    snprintf(compensated_voltage, sizeof(compensated_voltage), "%.2f", compensated_voltage[1] / 10.0);
    snprintf(temperature, sizeof(temperature), "%.2f", temperature);
    snprintf(flame_detected, sizeof(flame_detected), "%.2f", (temperature > 1.0) ? 1 : 0);

    // Log each reading
    snprintf(timestamp, sizeof(timestamp), "%s", asctime(localtime(&end_time.tv_sec)));
    snprintf(raw_adc, sizeof(raw_adc), "%d", adc_value);
    snprintf(voltage, sizeof(voltage), "%.2f", compensated_voltage[0] / 10.0);
    snprintf(compensated_voltage, sizeof(compensated_voltage), "%.2f", compensated_voltage[1] / 10.0);
    snprintf(temperature, sizeof(temperature), "%.2f", temperature);
    snprintf(flame_detected, sizeof(flame_detected), "%.2f", (temperature > 1.0) ? 1 : 0);

    // Log each reading to flame_log.txt
    FILE *log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(log_file, "%s,raw_adc,%s,voltage,%s,compensated_voltage,%s,temperature,%s,flame_detected\n",
            timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);

    fclose(log_file);

error_log:
    // Close log file
    fclose(log_file);

    // Release libgpiod resources
    gpiod_release(gpio_file);

error_close_gpio:
    // Close libgpiod resources
    gpiod_release(fd);

error_close_spi:
    // Close SPI device
    close(fd);

    return 0;
}

int main_loop() {
    while (1) {
        // Read sensor
        read_sensor();

        // Check if flame is detected
        if (strcmp(flame_detected, "1") == 0) {
            // Turn buzzer ON
            gpio_value_range_data_raw.value = 1;
            gpio_value_range_data_raw.flags = GPIGPIO_VALUE_RAW_LOW;
            gpio_value_range_data_raw.value_raw = 1;
            gpio_value_range_data_raw.flags_raw = GPIGPIO_VALUE_RAW_LOW;
            gpio_value_range_data_raw.value_range_data = &gpio_value_range_data_raw;

            // Wait for flame to be extinguished
            while (1) {
                usleep(500000);
                if (retrieve_sensor_value()) {
                    break;
                }
            }
        } else {
            // Turn buzzer OFF
            gpio_value_range_data_raw.value = 0;
            gpio_value_range_data_raw.flags = GPIGPIO_VALUE_RAW_LOW;
            gpio_value_range_data_raw.value_raw = 0;
            gpio_value_range_data_raw.flags_raw = GPIGPIO_VALUE_RAW_LOW;
            gpio_value_range_data_raw.value_range_data = &gpio_value_range_data_raw;

            // Wait for flame to be detected again
            while (1) {
                usleep(500000);
                if (retrieve_sensor_value()) {
                    break;
                }
            }
        }

        // Sleep for 500ms
        sleep(500);
    }

    return 0;
}

int main() {
    int ret;

    // Initialize libgpiod
    ret = gpiod_init();
    if (ret < 0) {
        perror("Error initializing libgpiod");
        return 1;
    }

    // Run main loop
    main_loop();

    // Clean up libgpiod
    gpiod_exit();

    return 0;
}
