#define KY_036_SPI_MODE 0
#define KY_036_SPI_CS_GPIO_NUM 8

#define KY_036_I2C_ADDR 0x50

#define SOIL_MOISTURE_LOG_FILE "soil_moisture.log"

int main(int argc, char *argv[]) {
    int fd, gpio_fd, i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_desc *gpio_desc;
    struct spi_device *spi_dev;
    struct spi_transfer transfer_data[1];
    uint16_t adc_value;
    int moisture_percentage;
