    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open SPI bus\n");
        return 1;
    }

    // Set SPI mode, clock speed, and chip select GPIO
    if (ioctl(fd, SPI_IOC_WR_MODE, KY_036_SPI_MODE) < 0) {
        fprintf(stderr, "Error: Failed to set SPI mode\n");
        return 1;
    }
    if (ioctl(fd, SPI_IOC_WR_CLK_SPEED_HZ, KY_036_SPI_BUS_SPEED) < 0) {
        fprintf(stderr, "Error: Failed to set SPI clock speed\n");
        return 1;
    }
    if (ioctl(fd, SPI_IOC_WR_CS_POLARITY, SPI_CS_LOW) < 0) {
        fprintf(stderr, "Error: Failed to set SPI chip select polarity\n");
        return 1;
    }
    if (ioctl(fd, SPI_IOC_RD_CS_POLARITY, SPI_CS_LOW) < 0) {
        fprintf(stderr, "Error: Failed to set SPI chip select polarity\n");
        return 1;
    }
    if (ioctl(fd, SPI_IOC_RD_CS_PHASE, SPI_CS_LOW) < 0) {
        fprintf(stderr, "Error: Failed to set SPI chip select phase\n");
        return 1;
    }
    if (ioctl(fd, SPI_IOC_WR_CS_PHASE, SPI_CS_HIGH) < 0) {
        fprintf(stderr, "Error: Failed to set SPI chip select phase\n");
        return 1;
    }

    // Open MCP3008 10-bit ADC
    if ((gpio_fd = gpioOpen(MCP3008_CS_NAME)) < 0) {
        fprintf(stderr, "Error: Failed to open MCP3008 GPIO\n");
        return 1;
    }
    if ((i2c_fd = i2cOpen(0)) < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MCP3008_CS_GPIO_NUM) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address\n");
        return 1;
    }

    // Open SPI device
    if ((spi_dev = spiOpen(fd)) < 0) {
        fprintf(stderr, "Error: Failed to open SPI device\n");
        return 1;
    }

    // Set SPI device configuration
    if (spiSetDeviceConfig(spi_dev, KY_036_SPI_MODE, KY_036_SPI_CS_GPIO_NUM, KY_036_SPI_CLK_SPEED,
                            KY_036_SPI_DATA_WIDTH, KY_036_SPI_CPOL) < 0) {
        fprintf(stderr, "Error: Failed to set SPI device configuration\n");
        return 1;
    }

    // Set ADC channel
    if (ioctl(spi_dev, SPI_IOC_WR_REG32, KY_036_AIN_PIN) < 0) {
        fprintf(stderr, "Error: Failed to set ADC channel\n");
        return 1;
    }

    // Set ADC resolution
    if (ioctl(spi_dev, SPI_IOC_WR_REG16, KY_036_RESOLUTION) < 0) {
        fprintf(stderr, "Error: Failed to set ADC resolution\n");
        return 1;
    }

    // Set ADC reference voltage
    if (ioctl(spi_dev, SPI_IOC_WR_REG16, KY_036_REFERENCE_VOLTAGE) < 0) {
        fprintf(stderr, "Error: Failed to set ADC reference voltage\n");
        return 1;
    }

    // Set ADC sample time
    if (ioctl(spi_dev, SPI_IOC_WR_REG16, KY_036_SAMPLE_TIME) < 0) {
        fprintf(stderr, "Error: Failed to set ADC sample time\n");
        return 1;
    }

    // Set ADC data transfer mode
    if (ioctl(spi_dev, SPI_IOC_WR_REG16, KY_036_DATA_MODE) < 0) {
        fprintf(stderr, "Error: Failed to set ADC data transfer mode\n");
        return 1;
    }

    // Set ADC data transfer size
    if (ioctl(spi_dev, SPI_IOC_WR_REG16, KY_036_DATA_SIZE) < 0) {
        fprintf(stderr, "Error: Failed to set ADC data transfer size\n");
        return 1;
    }

    // Set ADC data transfer direction
    if (ioctl(spi_dev, SPI_IOC_WR_REG16, KY_036_DATA_DIRECTION) < 0) {
        fprintf(stderr, "Error: Failed to set ADC data transfer direction\n");
        return 1;
    }

    // Set ADC data transfer start
    if (ioctl(spi_dev, SPI_IOC_RD_REG32, KY_036_DATA_START) < 0) {
        fprintf(stderr, "Error: Failed to set ADC data transfer start\n");
        return 1;
    }

    // Set ADC data transfer end
    if (ioctl(spi_dev, SPI_IOC_WR_REG32, KY_036_DATA_END) < 0) {
        fprintf(stderr, "Error: Failed to set ADC data transfer end\n");
        return 1;
    }

    // Set ADC data transfer loop
    while (1) {
        // Read ADC value
        if (ioctl(spi_dev, SPI_IOC_RD_REG32, KY_036_DATA) < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            return 1;
        }

        // Calculate moisture percentage
        adc_value = (uint16_t)((KY_036_DATA_PIN * KY_036_RESOLUTION) / (KY_036_RESOLUTION - 1) * (adc_value >> 8) + 0.5);
        adc_value = (adc_value >> 8) * KY_036_RESOLUTION / (KY_036_RESOLUTION - 1);

        // Check if ADC value is within valid range
        if (adc_value < 0 || adc_value > KY_036_RESOLUTION) {
            fprintf(stderr, "Error: Invalid ADC value\n");
            return 1;
        }

        // Log data
        sprintf(log_message, "%.2f", adc_value);
        timestamp[0] = '0';
        strftime(timestamp + 1, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime());
        sprintf(log_message + strlen(log_message), ".%02d", adc_value);
        sprintf(log_message + strlen(log_message), "%d", adc_value);
        log_message[strlen(log_message) - 1] = '\0';

        // Open log file
        if ((fd = open(SOIL_MOISTURE_LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
            fprintf(stderr, "Error: Failed to open log file\n");
            return 1;
        }

        // Write log message to file
        if (write(fd, log_message, strlen(log_message) + 1) < 0) {
            fprintf(stderr, "Error: Failed to write log message to file\n");
            return 1;
        }

        // Close log file
        if (close(fd) < 0) {
            fprintf(stderr, "Error: Failed to close log file\n");
            return 1;
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up SPI and I2C resources
    gpioTerminate();
    spiTerminate();

    return 0;
}

