#include <linux/gpio.h>

#define MCP3008_CS_GPIO_NUM 8
#define MCP3008_CS_GPIO_NAME "gpio8"
#define MCP3008_CS_SPI_DEVICE "/dev/spidev0.0"

#define ADC_CHANNEL_0 0
#define ADC_DRY_CALC_VALUE 700
#define ADC_WET_CALC_VALUE 300

int main() {
    int fd, spi_fd;
    struct spi_device *spi_dev;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int adc_channel;
    int moisture_percent;
    char buffer[3];

    // Initialize SPI device
    fd = open(MCP3008_CS_SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        exit(EXIT_FAILURE);
    }

    spi_fd = open(MCP3008_CS_SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        exit(EXIT_FAILURE);
    }

    // Initialize SPI device
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_3)) {
        perror("Error setting SPI mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8)) {
        perror("Error setting SPI bits per word");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000)) {
        perror("Error setting SPI max speed");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO pins
    chip = gpiod_chip_open(MCP3008_CS_GPIO_NAME);
    if (chip == NULL) {
        perror("Error opening GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, MCP3008_CS_GPIO_NAME);
    if (line == NULL) {
        perror("Error getting GPIO line");
        exit(EXIT_FAILURE);
    }

    if (gpio_request_from_sysfs(line->dev, MCP3008_CS_GPIO_NAME, MCP3008_CS_GPIO_NAME) < 0) {
        perror("Error requesting GPIO line");
        exit(EXIT_FAILURE);
    }

    // Initialize ADC
    adc_channel = gpio_request_from_sysfs(line->adc_gpio, MCP3008_CS_GPIO_NAME, MCP3008_CS_GPIO_NAME);
    if (adc_channel < 0) {
        perror("Error requesting ADC channel");
        exit(EXIT_FAILURE);
    }

    // Initialize libgpiod
    if (gpiod_chip_open_by_name(chip, MCP3008_CS_GPIO_NAME) < 0) {
        perror("Error opening GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Initialize SPI transfer buffer
    memset(buffer, 0, sizeof(buffer));

    // Read ADC data
    if (gpio_read(adc_channel) < 0) {
        perror("Error reading ADC channel");
        exit(EXIT_FAILURE);
    }

    // Calculate moisture percentage
    moisture_percent = (buffer[0] << 8) | buffer[1];
    if (moisture_percent < ADC_DRY_CALC_VALUE) {
        moisture_percent = ADC_DRY_CALC_VALUE;
    } else if (moisture_percent > ADC_WET_CALC_VALUE) {
        moisture_percent = ADC_WET_CALC_VALUE;
    }

    // Log and print ADC data and moisture percentage
    printf("Raw ADC Reading: %d\n", buffer[0]);
    printf("Moisture Percentage: %.2f%%\n", (float)moisture_percent / ADC_DRY_CALC_VALUE * 100);

    // Release resources
    gpio_free(adc_channel);
    gpiod_chip_close(chip);
    close(spi_fd);
    close(fd);

    return 0;
}

