#include <fcntl.h>
#include <linux/spi/spi.h>

#include <pigpio.h>

#define MCP3008_CS_GPIO_NUM 8
#define MCP3008_CLK_GPIO_NUM 9
#define MCP3008_MOSI_GPIO_NUM 10
#define MCP3008_MISO_GPIO_NUM 11

#define ADC_START 0x20
#define ADC_CONTINUE 0x21
#define ADC_STOP 0x23

#define ADC_RES_BITS 10
#define ADC_RES_MASK ((1 << ADC_RES_BITS) - 1)

#define ADC_REF_VOLT ((3.3 * ADC_RES_MASK) / (2 ** ADC_RES_BITS))

#define ADC_SCALE_FACTOR (ADC_REF_VOLT / 1023)

#define ADC_THRESHOLD_MIN 0
#define ADC_THRESHOLD_MAX 1023

#define PRESSURE_THRESHOLD 0.5
#define PRESSURE_THRESHOLD_MAX 4.5

#define PRESSURE_SCALE_FACTOR (PRESSURE_THRESHOLD_MAX / ADC_RES_MASK)

#define ISO8601_FORMAT "%Y-%m-%dT%H:%M:%S"

int main() {
    int rc;
    int fd;
    struct spi_device *spi;
    struct gpio *gpio;
    struct gpio_mem *mem;
    struct gpio_mem_config gpio_config = {
        .base = {
            .base = 0x20,
            .irq = 0,
        },
        .size = {
            .size = 0x100,
        },
    };

    gpio = gpio_open(MCP3008_CS_GPIO_NUM, MCP3008_CLK_GPIO_NUM, MCP3008_MOSI_GPIO_NUM, MCP3008_MISO_GPIO_NUM, &gpio_config);
    if (!gpio) {
        fprintf(stderr, "Failed to open GPIO\n");
        return 1;
    }

    mem = gpio_get_mem(gpio);
    if (!mem) {
        fprintf(stderr, "Failed to get GPIO memory\n");
        gpio_close(gpio);
        return 1;
    }

    spi = spi_open(0);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI\n");
        gpio_close(gpio);
        return 1;
    }

    if (spi_setup(spi, 1000000, SPI_MODE_0 | SPI_CPOL_LOW, SPI_HALF_PHASE) < 0) {
        fprintf(stderr, "Failed to set up SPI\n");
        spi_close(spi);
        gpio_close(gpio);
        return 1;
    }

    if (spi_transfer(spi, (uint8_t *)&spi_mem(mem)->data, 1, NULL, 0) < 0) {
        fprintf(stderr, "Failed to write to SPI\n");
        spi_close(spi);
        gpio_close(gpio);
        return 1;
    }

    gpio_close(gpio);

    rc = pigpio_init();
    if (rc < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(-rc));
        return 1;
    }

    if (pigpio_set_mode(GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", strerror(-rc));
        return 1;
    }

    while (1) {
        int adcValue;
        struct spi_transfer transfer;
        uint8_t buffer[2];

        adcValue = pigpio_get_adc(gpio, MCP3008_START);

        if (adcValue < 0) {
            fprintf(stderr, "Failed to read ADC: %s\n", strerror(-adcValue));
            continue;
        }

        buffer[0] = ADC_START;
        buffer[1] = adcValue;

        if (spi_transfer(spi, (uint8_t *)&buffer, 2, NULL, 0) < 0) {
            fprintf(stderr, "Failed to write to SPI\n");
            continue;
        }

        if (spi_transfer(spi, (uint8_t *)&buffer[1], 1, NULL, 0) < 0) {
            fprintf(stderr, "Failed to read from SPI\n");
            continue;
        }

        buffer[0] = ADC_CONTINUE;
        buffer[1] = 0;

        if (spi_transfer(spi, (uint8_t *)&buffer, 2, NULL, 0) < 0) {
            fprintf(stderr, "Failed to write to SPI\n");
            continue;
        }

        if (spi_transfer(spi, (uint8_t *)&buffer[1], 1, NULL, 0) < 0) {
            fprintf(stderr, "Failed to read from SPI\n");
            continue;
        }

        float voltage = (buffer[1] << 8) / ADC_RES_MASK;

        if (voltage < ADC_THRESHOLD_MIN || voltage > ADC_THRESHOLD_MAX) {
            fprintf(stderr, "Sensor out of range: %fV\n", voltage);
            continue;
        }

        float pressure = (voltage - ADC_REF_VOLT) * ADC_SCALE_FACTOR;

        if (pressure < PRESSURE_THRESHOLD_MIN || pressure > PRESSURE_THRESHOLD_MAX) {
            fprintf(stderr, "Sensor absent: %fV\n", voltage);
            continue;
        }

        float kPa = pressure * PRESSURE_SCALE_FACTOR;

        printf("Pressure: %.2f kPa\n", kPa);

        sleep(1);
    }

    pigpio_exit();

    return 0;
}

