#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spi.h>
#include <linux/gpio.h>

#define MCP3008_CS_GPIO_PIN 11
#define MCP3008_CS_GPIO_NAME "MCP3008_CS"

#define SEN0193_CS_GPIO_PIN 8
#define SEN0193_CS_GPIO_NAME "SEN0193_CS"

#define ADC_SPEED 1000000 // SPI speed in Hz (1 MHz)
#define ADC_RESOLUTION 10 // 10-bit ADC

#define MIN_ADC_VALUE 300 // Dry soil threshold
#define MAX_ADC_VALUE 700 // Saturated soil threshold

#define SEN0193_CHANNEL 0

int main() {
    int fd, spi_fd, gpio_fd;
    struct spi_device *spi;
    struct gpio_desc *gpio;
    struct gpio_channel *channel;
    struct gpio_config gpio_config;
    struct gpio_adc_config adc_config;
    struct gpio_adc_data adc_data;
    char timestamp[50];
    int adc_value, moisture_percentage;

    // Initialize SPI and GPIO
    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        exit(EXIT_FAILURE);
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        exit(EXIT_FAILURE);
    }

    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Error opening GPIO device");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO lines
    gpio_config.gpio_dir = GPIO_OUTPUT;
    gpio_config.gpio_value = 0;
    gpio_config.gpio_speed = GPIO_SPEED_FREQ_HIGH;
    gpio_config.gpio_intr_type = GPIO_INTR_TYPE_EDGE;
    gpio_config.gpio_edge_type = GPIO_EDGE_FALLING;
    gpio_config.gpio_num = SEN0193_CS_GPIO_PIN;
    gpio_config.gpio_flags = GPIO_OUTPUT_EN;

    if (ioctl(gpio_fd, GPIO_SET_OUTPUT_LINE, &gpio_config) < 0) {
        perror("Error setting up GPIO line");
        exit(EXIT_FAILURE);
    }

    gpio_config.gpio_num = MCP3008_CS_GPIO_PIN;
    gpio_config.gpio_flags = GPIO_OUTPUT_EN;

    if (ioctl(gpio_fd, GPIO_SET_OUTPUT_LINE, &gpio_config) < 0) {
        perror("Error setting up GPIO line");
        exit(EXIT_FAILURE);
    }

    // Set up ADC
    adc_config.adc_channel = SEN0193_CHANNEL;
    adc_config.adc_speed = ADC_SPEED;
    adc_config.adc_resolution = ADC_RESOLUTION;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &adc_config) < 0) {
        perror("Error setting up ADC");
        exit(EXIT_FAILURE);
    }

    // Open MCP3008 ADC
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_0) < 0) {
        perror("Error setting up MCP3008 ADC");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, 0) < 0) {
        perror("Error setting up MCP3008 ADC");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_CHANNEL, MCP3008_CS_GPIO_NAME) < 0) {
        perror("Error setting up MCP3008 ADC");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_CHANNEL, &MCP3008_CS_GPIO_NAME) < 0) {
        perror("Error setting up MCP3008 ADC");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_RES_MODE, SPI_RES_MODE_MODE_0) < 0) {
        perror("Error setting up MCP3008 ADC");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_RES_MODE, &SPI_RES_MODE_MODE_0) < 0) {
        perror("Error setting up MCP3008 ADC");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_DATA_MODE, SPI_MODE_0) < 0) {
        perror("Error setting up MCP3008 ADC");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_DATA_MODE, &SPI_MODE_0) < 0) {
        perror("Error setting up MCP3008 ADC");
        exit(EXIT_FAILURE);
    }

    // Read data from SEN0193 sensor
    adc_data.adc_channel = SEN0193_CHANNEL;
    adc_data.adc_speed = ADC_SPEED;
    adc_data.adc_resolution = ADC_RESOLUTION;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &adc_data) < 0) {
        perror("Error reading data from SEN0193 sensor");
        exit(EXIT_FAILURE);
    }

    adc_value = adc_data.adc_data;

    // Convert ADC value to moisture percentage
    if (adc_value == 0) {
        printf("Sensor is absent or there is a wiring fault.\n");
        exit(EXIT_FAILURE);
    }

    if (adc_value > ADC_RESOLUTION) {
        adc_value = ADC_RESOLUTION - 1;
    }

    moisture_percentage = (adc_value - MIN_ADC_VALUE) * (MAX_ADC_VALUE - MIN_ADC_VALUE) / (ADC_RESOLUTION - MIN_ADC_VALUE + 1);

    // Log the moisture percentage
    sprintf(timestamp, "%.2f", time(NULL));
    printf("Moisture percentage: %.2f%%\n", moisture_percentage);

    // Release resources
    close(spi_fd);
    close(gpio_fd);
    close(fd);

    return 0;
}

