#define VH400_DATA_PIN 0x00
#define VH400_PULSE_THRESHOLD 300
#define VH400_HYSTERESIS 600

#define BUFFER_CAPACITY 20
#define BUFFER_INDEX 0

struct moisture_data {
    int timestamp;
    int moisture_level;
    int pump_state;
};

struct moisture_data buffer[BUFFER_CAPACITY];
int buffer_index = 0;

int init_pigpio() {
    int result = pigpio_init();
    if (result == -1) {
        fprintf(stderr, "Error initializing pigpio: %s\n", pigpio_error_str(result));
        return -1;
    }
    return 0;
}

int close_pigpio() {
