    if (result == -1) {
        fprintf(stderr, "Error closing pigpio: %s\n", pigpio_error_str(result));
        return -1;
    }
    return 0;
}

int open_spi_device(int spi_device) {
    int result = spi_open(spi_device);
    if (result == -1) {
        fprintf(stderr, "Error opening SPI device: %s\n", spi_strerror(result));
        return -1;
    }
    return 0;
}

int read_adc_value(int spi_device, int channel) {
    int result = spi_transfer(spi_device, (uint8_t *)&channel, 1, 0);
    if (result == -1) {
        fprintf(stderr, "Error reading ADC value: %s\n", spi_strerror(result));
        return -1;
    }
    return result;
}

int read_adc_data(int spi_device, int channel, int *adc_value) {
    int result = spi_transfer(spi_device, (uint8_t *)adc_value, 1, 0);
    if (result == -1) {
        fprintf(stderr, "Error reading ADC data: %s\n", spi_strerror(result));
        return -1;
    }
    return 0;
}

int write_spi_register(int spi_device, int register_address, uint8_t data) {
    int result = spi_write(spi_device, &register_address, 1, &data, 1);
    if (result == -1) {
        fprintf(stderr, "Error writing SPI register: %s\n", spi_strerror(result));
        return -1;
    }
    return 0;
}

