    int timestamp = time(NULL);
    if (timestamp >= BUFFER_INDEX) {
        buffer_index = (buffer_index + 1) % BUFFER_CAPACITY;
    }
    buffer[buffer_index].timestamp = timestamp;
    buffer[buffer_index].moisture_level = data.moisture_level;
    buffer[buffer_index].pump_state = data.pump_state;
