#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define BUZZER_GPIO_PIN 24
#define ADC_CHANNEL_PIN 0
#define ADC_RESOLUTION 8
#define ADC_SAMPLING_INTERVAL_MS 500

int main() {
    int gpioHandle, spiHandle, adcHandle;
    int adcValue, buzzerState;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    if (spiInit() < 0) {
        fprintf(stderr, "Error: Failed to initialize SPI\n");
        return 1;
    }

    if (adcInit() < 0) {
        fprintf(stderr, "Error: Failed to initialize ADC\n");
        return 1;
    }

    // Set GPIO8 as CE0 for MCP3008 ADC
    if (gpioSetMode(8, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO8 as CE0\n");
        return 1;
    }

    // Set GPIO24 as active buzzer output
    if (gpioSetMode(24, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO24 as active buzzer output\n");
        return 1;
    }

    // Set buzzer to OFF state
    buzzerState = 0;

    // Set up SPI communication
    spiHandle = spiOpen(0);
    if (spiHandle < 0) {
        fprintf(stderr, "Error: Failed to open SPI\n");
        return 1;
    }

    if (spiTransfer(spiHandle, (uint8_t*)&spiConfig, sizeof(spiConfig)) < 0) {
        fprintf(stderr, "Error: Failed to send SPI configuration\n");
        return 1;
    }

    if (spiTransfer(spiHandle, (uint8_t*)&spiConfig, sizeof(spiConfig)) < 0) {
        fprintf(stderr, "Error: Failed to send SPI configuration\n");
        return 1;
    }

    // Set up ADC communication
    adcHandle = adcOpen(0);
    if (adcHandle < 0) {
        fprintf(stderr, "Error: Failed to open ADC\n");
        return 1;
    }

    if (adcConfigure(adcHandle, ADC_CHANNEL_PIN, ADC_RESOLUTION) < 0) {
        fprintf(stderr, "Error: Failed to configure ADC\n");
        return 1;
    }

    // Set up SPI transfer for reading ADC values
    if (spiTransfer(spiHandle, (uint8_t*)&adcValue, sizeof(adcValue)) < 0) {
        fprintf(stderr, "Error: Failed to read ADC value\n");
        return 1;
    }

    // Set up SIGINT handler
    signal(SIGINT, sigintHandler);

    while (1) {
        // Read ADC value
        if (adcRead(adcHandle) < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            return 1;
        }

        // Check if gas sensor value has dropped below threshold
        if (adcValue < 500) {
            // Turn off buzzer
            gpioWrite(24, 0);
        } else {
            // Turn on buzzer
            gpioWrite(24, 1);
        }

        // Wait for next ADC reading
        sleep(ADC_SAMPLING_INTERVAL_MS);
    }

    // Close SPI and ADC handles
    spiClose(spiHandle);
    adcClose(adcHandle);

    // Reset GPIO states
    gpioSetMode(8, PI_INPUT);
    gpioSetMode(24, PI_INPUT);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

// SIGINT handler
void sigintHandler(int signum) {
    printf("Received SIGINT signal. Closing SPI handle, resetting GPIO states, and calling gpioTerminate() before exiting...\n");
    gpioClose(spiHandle);
    gpioClose(adcHandle);
    gpioTerminate();
}

