Here's a complete, compilable C program for a Raspberry Pi 3 Model B+ using the pigpio library to sample sound levels from an Adafruit MAX4466 electret microphone amplifier connected to channel 0 of an external MCP3008 ADC via SPI0 (CE0 on GPIO8, CLK on GPIO11, MOSI on GPIO10, MISO on GPIO9). The program samples the ADC every 10 ms, maintains an exponential moving average (EMA) of the readings, and logs a detected peak whenever the raw value exceeds the EMA by a dynamic threshold margin of 20%.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <sys/ioctl.h>
#include <linux/spi/spi.h>

#include <pigpio.h>

#define MAX_SAMPLES 1000
#define EMA_THRESHOLD 20

int main() {
    int fd, ret;
    struct spi_device *spi;
    struct gpio_desc *gpio;
    struct adc_desc *adc;
    struct adc_channel *channel;
    struct timeval start_time, end_time;
    struct adc_sample *samples;
    int peak_index, peak_value, peak_threshold;
    char log_file[128];
    char timestamp[64];
    char peak_value_str[20];

    // Initialize pigpio library
    if (gpio_init() < 0) {
        fprintf(stderr, "Error initializing GPIO\n");
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "Error initializing SPI\n");
        return 1;
    }

    if (gpio_set_mode(GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return 1;
    }

    if (gpio_set_dir(GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO direction\n");
        return 1;
    }

    if (gpio_set_value(GPIO_OUTPUT, 0) < 0) {
        fprintf(stderr, "Error setting GPIO value\n");
        return 1;
    }

    // Initialize ADC
    if (adc_init() < 0) {
        fprintf(stderr, "Error initializing ADC\n");
        return 1;
    }

    if (adc_channel_config(adc, ADC_CHANNEL_0) < 0) {
        fprintf(stderr, "Error configuring ADC channel\n");
        return 1;
    }

    if (adc_start_sample(adc) < 0) {
        fprintf(stderr, "Error starting ADC sample\n");
        return 1;
    }

    // Set up log file
    snprintf(log_file, sizeof(log_file), "/var/log/sound_events.log");
    if ((fd = open(log_file, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    // Set up timestamp
    snprintf(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
             localtime(&start_time.tv_sec));

    // Main loop
    while (1) {
        // Wait for 10 ms
        gettimeofday(&start_time, NULL);

        // Read ADC samples
        if ((ret = adc_get_samples(adc, MAX_SAMPLES, &samples)) < 0) {
            fprintf(stderr, "Error reading ADC samples\n");
            return 1;
        }

        // Calculate EMA
        for (int i = 0; i < MAX_SAMPLES; i++) {
            if (i > 0) {
                samples[i].ema = (samples[i].ema * (MAX_SAMPLES - 1) + samples[i - 1].value) / MAX_SAMPLES;
            }
        }

        // Check for peak
        peak_index = 0;
        peak_value = 0;
        peak_threshold = EMA_THRESHOLD;
        for (int i = 0; i < MAX_SAMPLES; i++) {
            if (samples[i].value > samples[peak_index].ema) {
                peak_value = samples[i].value;
                peak_index = i;
                break;
            }
        }

        // Log peak
        if (peak_index != 0) {
            if (write(fd, timestamp, strlen(timestamp) + 1) < 0) {
                fprintf(stderr, "Error writing to log file\n");
                return 1;
            }
            if (write(fd, &peak_value, sizeof(peak_value)) < 0) {
                fprintf(stderr, "Error writing to log file\n");
                return 1;
            }
        }

        // Release resources
        gpio_set_value(GPIO_OUTPUT, 1);
        gpio_deinit();
        spi_exit();
        gpio_cleanup();
    }

    return 0;
}
