#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/spi/spi.h>

#include <pigpio.h>

#define MCP3008_CS_GPIO_NUM 0
#define MCP3008_CS_SPEED_NSLOTS 1
#define MCP3008_CS_SPEED_NSHIFTS 2

#define VH400_CHANNEL_A 0
#define VH400_CHANNEL_B 1
#define VH400_THRESHOLD 300

int main() {
    int gpioHandle, adcHandle, relayHandle;
    int adcValue, relayState;
    char fileName[] = "watering_events.txt";
    FILE *file;
    struct spi_device *spi;
    struct gpio_desc *gpioDesc;
    struct adc_desc *adcDesc;
    struct relay_desc *relayDesc;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    // Initialize ADC
    gpioHandle = gpioSetup(MCP3008_CS_GPIO_NUM);
    if (gpioHandle < 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO\n");
        return 1;
    }
    gpioDesc = (struct gpio_desc *)gpioHandle;
    gpioDesc->flags = GPIO_FLAG_IN;
    gpioDesc->value = 0;

    adcHandle = adcSetup(MCP3008_CS_SPEED_NSHIFTS);
    if (adcHandle < 0) {
        fprintf(stderr, "Error: Failed to initialize ADC\n");
        return 1;
    }
    adcDesc = (struct adc_desc *)adcHandle;
    adcDesc->flags = ADC_FLAG_INPUT;

    relayHandle = gpioSetup(18);
    if (relayHandle < 0) {
        fprintf(stderr, "Error: Failed to initialize relay\n");
        return 1;
    }

    // Open file for logging
    file = fopen(fileName, "w");
    if (file == NULL) {
        fprintf(stderr, "Error: Failed to open file for logging\n");
        return 1;
    }

    // Initialize SPI device
    spi = spiSetup(1);
    if (spi == NULL) {
        fprintf(stderr, "Error: Failed to initialize SPI device\n");
        return 1;
    }

    // Set up SPI transfer parameters
    spiXfer(spi, (uint8_t *)&adcValue, 1, NULL, 0);
    spiXfer(spi, (uint8_t *)&VH400_CHANNEL_A, 1, NULL, 0);
    spiXfer(spi, (uint8_t *)&VH400_CHANNEL_B, 1, NULL, 0);

    // Main loop
    while (1) {
        // Read ADC value
        adcValue = adcRead(adcDesc);

        // Check if ADC reading is below threshold
        if (adcValue < VH400_THRESHOLD) {
            // Deactivate pump
            relayWrite(relayHandle, 0);

            // Log timestamp and moisture level
            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timeString[80];
            strftime(timeString, sizeof(timeString), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(file, "Watering event at %s: %d\n", timeString, adcValue);

            // Wait for 10 seconds
            sleep(10);
        }

        // Check for SPI transfer errors
        if (spiXfer(spi, (uint8_t *)&relayState, 1, NULL, 0) < 0) {
            fprintf(stderr, "Error: Failed to read relay state\n");
            return 1;
        }

        // Check for stuck or invalid ADC values
        if (adcValue < 0 || adcValue > 1023) {
            fprintf(stderr, "Error: Invalid ADC reading\n");
            return 1;
        }

        // Check if pump should be activated
        if (relayState == 0) {
            relayWrite(relayHandle, 1);
        } else {
            relayWrite(relayHandle, 0);
        }
    }

    // Clean up resources
    gpioClose(gpioHandle);
    adcClose(adcDesc);
    spiClose(spi);

    fclose(file);

    // Clean up pigpio library
    gpioTerminate();

    return 0;
}

