#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>

#define MCP3008_COMMAND_START 0x01
#define MCP3008_COMMAND_CONFIG 0x00
#define MCP3008_COMMAND_READ_DATA 0x03

#define MCP3008_CS_PIN 8
#define MCP3008_CLK_PIN 11
#define MCP3008_MISO_PIN 9
#define MCP3008_MOSI_PIN 10

#define VREF_VOLTAGE 3.3

int main() {
    int spi_fd, gpio_fd;
    struct spi_device *spi_dev;
    struct gpio_desc *gpio_desc;
    unsigned char config_byte;
    unsigned int raw_value, voltage;
    unsigned int i;

    // Open spidev device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening spidev device");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO and SPI device
    gpio_desc = gpio_get_desc(MCP3008_CS_PIN);
    gpio_desc->flags = GPIOF_EXPORT_DIR_FIXED | GPIOF_EXPORT_DIR_INACTIVE;
    gpio_desc->value = 0;
    gpio_desc->direction = GPIO_MODE_OUTPUT;
    gpio_desc->edge = GPIO_FALLING;
    gpio_desc->base = spi_dev->busnum;
    gpio_desc->pin = MCP3008_CS_PIN;

    gpio_desc->gpio_set_level = gpio_set_level;
    gpio_desc->gpio_read_level = gpio_read_level;

    gpio_desc->gpio_set_level(gpio_desc, 1);

    spi_dev = spi_open(spi_fd);
    if (spi_dev == NULL) {
        perror("Error opening SPI device");
        exit(EXIT_FAILURE);
    }

    // Send MCP3008 command
    spi_write(spi_dev, &MCP3008_COMMAND_START, 1);
    spi_write(spi_dev, &config_byte, 1);
    spi_write(spi_dev, &MCP3008_COMMAND_CONFIG, 1);
    spi_write(spi_dev, &MCP3008_COMMAND_READ_DATA, 1);

    // Read 10-bit value from MCP3008
    spi_read(spi_dev, &raw_value, 1);
    spi_read(spi_dev, &voltage, 1);

    // Print raw value and voltage
    printf("Raw value: %u\n", raw_value);
    printf("Voltage: %.2f V\n", (float)voltage / (VREF_VOLTAGE / 1023.0));

    // Set up SPI transfer for reading data
    spi_transfer(spi_dev, &raw_value, 1, NULL, 0);
    spi_transfer(spi_dev, &voltage, 1, NULL, 0);

    // Close SPI device and file descriptor
    spi_close(spi_dev);
    close(spi_fd);

    // Clean up GPIO resources
    gpio_desc->gpio_free(gpio_desc);

    return 0;
}

