#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>

#include <pigpio.h>

#define VREF 3.3
#define CHANNEL_COUNT 3
#define CHANNEL_OFFSET 0

int gpio_fd;

void signal_handler(int signum) {
    gpio_exit();
    exit(0);
}

int main() {
    int rc;

    // Initialize pigpio
    if ((rc = pigpio_init()) != 0) {
        fprintf(stderr, "Error initializing pigpio: %d\n", rc);
        return 1;
    }

    // Open SPI device
    gpio_fd = pigpio_open(0);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", rc);
        return 1;
    }

    // Set up SPI configuration
    if ((rc = pigpio_set_mode(gpio_fd, PI_MODE_SPI)) != 0) {
        fprintf(stderr, "Error setting SPI mode: %d\n", rc);
        return 1;
    }

    if ((rc = pigpio_set_speed(gpio_fd, 1000000)) != 0) {
        fprintf(stderr, "Error setting SPI speed: %d\n", rc);
        return 1;
    }

    // Set up SPI transfer parameters
    if ((rc = pigpio_set_transfer_mode(gpio_fd, PI_TRANSFER_MODE_SINGLE)) != 0) {
        fprintf(stderr, "Error setting SPI transfer mode: %d\n", rc);
        return 1;
    }

    if ((rc = pigpio_set_chip_select(gpio_fd, PI_UNUSED)) != 0) {
        fprintf(stderr, "Error setting SPI chip select: %d\n", rc);
        return 1;
    }

    // Set up SPI transfer parameters for each channel
    for (int i = 0; i < CHANNEL_COUNT; i++) {
        if ((rc = pigpio_set_transfer_mode(gpio_fd, PI_TRANSFER_MODE_SINGLE)) != 0) {
            fprintf(stderr, "Error setting SPI transfer mode: %d\n", rc);
            return 1;
        }

        if ((rc = pigpio_set_chip_select(gpio_fd, i + CHANNEL_OFFSET)) != 0) {
            fprintf(stderr, "Error setting SPI chip select: %d\n", rc);
            return 1;
        }

        if ((rc = pigpio_set_frequency(gpio_fd, 1000000)) != 0) {
            fprintf(stderr, "Error setting SPI frequency: %d\n", rc);
            return 1;
        }

        if ((rc = pigpio_set_data_width(gpio_fd, PI_DATA_WIDTH_8)) != 0) {
            fprintf(stderr, "Error setting SPI data width: %d\n", rc);
            return 1;
        }

        if ((rc = pigpio_set_transfer_size(gpio_fd, 1)) != 0) {
            fprintf(stderr, "Error setting SPI transfer size: %d\n", rc);
            return 1;
        }

        if ((rc = pigpio_set_transfer_mode(gpio_fd, PI_TRANSFER_MODE_CONTINUOUS)) != 0) {
            fprintf(stderr, "Error setting SPI transfer mode: %d\n", rc);
            return 1;
        }

        if ((rc = pigpio_set_data_order(gpio_fd, PI_DATA_ORDER_MSB)) != 0) {
            fprintf(stderr, "Error setting SPI data order: %d\n", rc);
            return 1;
        }

        if ((rc = pigpio_set_sample_rate(gpio_fd, 1000000)) != 0) {
            fprintf(stderr, "Error setting SPI sample rate: %d\n", rc);
            return 1;
        }

        if ((rc = pigpio_set_channel_mode(gpio_fd, PI_CHANNEL_MODE_INPUT)) != 0) {
            fprintf(stderr, "Error setting SPI channel mode: %d\n", rc);
            return 1;
        }

        if ((rc = pigpio_set_channel_range(gpio_fd, i + CHANNEL_OFFSET, 0, 1023)) != 0) {
            fprintf(stderr, "Error setting SPI channel range: %d\n", rc);
            return 1;
        }
    }

    // Start SPI transfer loop
    while (1) {
        // Wait for 5 seconds
        struct timeval start, end;
        gettimeofday(&start, NULL);

        // Perform SPI transfer
        if ((rc = pigpio_transfer(gpio_fd, 0, &data, 1)) != 0) {
            fprintf(stderr, "Error performing SPI transfer: %d\n", rc);
            return 1;
        }

        // Check if 5 seconds have passed
        if (gettimeofday(&end, NULL) < start) {
            fprintf(stderr, "Error: Timeout\n");
            return 1;
        }

        // Log timestamped voltage values
        FILE *fp = fopen("sensor_data.csv", "a");
        if (fp == NULL) {
            fprintf(stderr, "Error opening file sensor_data.csv\n");
            return 1;
        }

        fprintf(fp, "%d,%d,%d\n", (int)(data * VREF / 1023), (int)(data * VREF / 1023), (int)(data * VREF / 1023));

        fclose(fp);
    }

    // Clean up
    pigpio_exit();

    return 0;
}

