    msg[0].flags = 0;
    msg[0].len = 2;
    msg[0].buf = (uint8_t*)&sound_level_db;
    msg[1].addr = MAX9814_ADDR;
    msg[1].flags = 0;
    msg[1].len = 2;
    msg[1].buf = (uint8_t*)&light_level_lux;

    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
