        log_error(1);
        return;
    }

    if (write(i2c_fd, msg, sizeof(msg)) != sizeof(msg)) {
        log_error(1);
        return;
    }

    if (read(i2c_fd, &sound_level_db, sizeof(sound_level_db)) != sizeof(sound_level_db)) {
        log_error(1);
        return;
    }

    if (read(i2c_fd, &light_level_lux, sizeof(light_level_lux)) != sizeof(light_level_lux)) {
        log_error(1);
        return;
    }

    if (close(i2c_fd) < 0) {
        log_error(1);
        return;
    }

    if (write(i2c_fd, msg, sizeof(msg)) != sizeof(msg)) {
        log_error(1);
        return;
    }

    if (close(i2c_fd) < 0) {
        log_error(1);
        return;
    }

    if (read(i2c_fd, &timestamp[0], 1) != 1) {
        log_error(1);
        return;
    }

