    // Clean up
    close(MAX9814_CS_GPIO_NUM);
    close(BH1750_CS_GPIO_NUM);
    close(csv_file);
    gpio_free(MAX9814_CS_GPIO_NUM);
    gpio_free(BH1750_CS_GPIO_NUM);

    return 0;
}

