#define GPIO_BASE 0x20  // Base address of GPIO controller
#define GPIO_CS_PIN 17   // GPIO17 is used as CE0
#define ADC_CS_PIN 0     // MCP3008's CS pin is GPIO0
#define ADC_CHANNEL 0    // MCP3008's channel 0
#define SPI_CLK_FREQ 1000000 // 1 MHz SPI clock

int main() {
    int fd, gpio_fd, adc_fd;
    struct spi_device *spi;
    struct gpio_desc *gpio;
    struct gpio_config gpio_config;
    struct adc_desc adc;
    struct adc_config adc_config;
    struct timeval start_time, end_time;
    char log_file[128] = "door_events.log";
    int log_fd;
    int relay_pin = 5;  // MCP3008's channel 0
    int debounce_delay = 100;  // 1 ms debounce delay
    int proximity_threshold = 20;  // Distance threshold for door opening

    // Initialize GPIO, SPI, and file I/O
    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        exit(EXIT_FAILURE);
    }

    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Error opening GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpio_config.gpio_dir = GPIO_OUTPUT;
    gpio_config.gpio_value = 0;
    if (ioctl(gpio_fd, GPIO_GET_LINE, &gpio_config) < 0) {
        perror("Error getting GPIO line");
        exit(EXIT_FAILURE);
    }

    adc_fd = open("/dev/spidev0.1", O_RDWR);
    if (adc_fd < 0) {
        perror("Error opening ADC device");
        exit(EXIT_FAILURE);
    }

    adc_config.adc_channel = ADC_CHANNEL;
    if (ioctl(adc_fd, ADC_SET_CONFIG, &adc_config) < 0) {
        perror("Error setting ADC configuration");
        exit(EXIT_FAILURE);
    }

    // Initialize SPI device
    spi = &gpiochip_spi0;
    if (spi_open(spi, 0) < 0) {
        perror("Error opening SPI device");
        exit(EXIT_FAILURE);
    }

    // Set SPI clock frequency
    if (spi_set_max_speed_hz(spi, SPI_CLK_FREQ) < 0) {
        perror("Error setting SPI clock frequency");
        exit(EXIT_FAILURE);
    }

    // Set GPIO and ADC pins
    gpio_config.gpio_dir = GPIO_OUTPUT;
    gpio_config.gpio_value = 0;
    if (ioctl(gpio_fd, GPIO_GET_LINE, &gpio_config) < 0) {
        perror("Error getting GPIO line");
        exit(EXIT_FAILURE);
    }

    gpio_config.gpio_dir = GPIO_INPUT;
    gpio_config.gpio_value = 1;
    if (ioctl(gpio_fd, GPIO_SET_LINE, &gpio_config) < 0) {
        perror("Error setting GPIO line");
        exit(EXIT_FAILURE);
    }

    adc_config.adc_channel = ADC_CHANNEL;
    if (ioctl(adc_fd, ADC_SET_CONFIG, &adc_config) < 0) {
        perror("Error setting ADC configuration");
        exit(EXIT_FAILURE);
    }

    // Set ADC channel
    if (ioctl(adc_fd, ADC_SET_CHANNEL, &adc_config) < 0) {
        perror("Error setting ADC channel");
        exit(EXIT_FAILURE);
    }

    // Set relay pin
    if (ioctl(relay_pin, GPIO_SET_VALUE, 1) < 0) {
        perror("Error setting relay pin");
        exit(EXIT_FAILURE);
    }

    // Initialize log file
    log_fd = open(log_file, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read sensor data
        if (ioctl(adc_fd, ADC_START_CONTINUOUS, 0) < 0) {
            perror("Error starting ADC continuous mode");
            exit(EXIT_FAILURE);
        }

        // Wait for sensor data
        if (ioctl(adc_fd, ADC_WAIT_FOR_DATA, 0) < 0) {
            perror("Error waiting for ADC data");
            exit(EXIT_FAILURE);
        }

        // Read sensor data
        if (ioctl(adc_fd, ADC_GET_DATA, &adc.adc_data) < 0) {
            perror("Error reading ADC data");
            exit(EXIT_FAILURE);
        }

        // Check if proximity is detected
        if (adc.adc_data > proximity_threshold) {
            // Energize relay
            if (ioctl(relay_pin, GPIO_SET_VALUE, 1) < 0) {
                perror("Error setting relay pin");
                exit(EXIT_FAILURE);
            }

            // Log event
            struct timeval now;
            gettimeofday(&now, NULL);
            char log_message[32];
            sprintf(log_message, "Proximity detected at %s\n", ctime(&now.tv_sec));
            write(log_fd, log_message, strlen(log_message));

            // Debounce delay
            sleep(debounce_delay);
        }

        // Wait for 1 s
        sleep(1);
    }

    // Clean up
    close(adc_fd);
    close(relay_pin);
    close(log_fd);
    ioctl(spi_fd, SPI_CLR_FALLING_EDGE);
    ioctl(spi_fd, SPI_SET_MAX_SPEED_HZ, SPI_CLK_FREQ);
    ioctl(gpio_fd, GPIO_CLR_LINE, gpio_config.gpio_line);
    close(gpio_fd);
    return 0;
}

