    if (gpio_open_device(GPIO_DIR_IN, &gpio_desc) < 0) {
        fprintf(stderr, "Failed to open GPIO device\n");
        return 1;
    }
    if (gpio_open_device(GPIO_DIR_OUT, &gpio_desc) < 0) {
        fprintf(stderr, "Failed to open GPIO device\n");
        return 1;
    }
    if (spi_open_device(SPI_BUS_1, &spi_desc) < 0) {
