    int retry_count = 0;
    int retry_delay = 100;

    while (1) {
        if (gpio_open(MCP3008_CS_PIN) < 0) {
            fprintf(stderr, "Failed to open SPI bus: %s\n", strerror(errno));
            continue;
        }

        gpio_set_mode(MCP3008_CS_PIN, PI_MODE_OUTPUT);

        int adc_value = -1;
        int retry_max = 5;

        while (retry_count < retry_max) {
            if (gpio_read(MCP3008_CS_PIN) < 0) {
                fprintf(stderr, "Failed to read from MCP3008: %s\n", strerror(errno));
                continue;
            }

            adc_value = gpio_read(MCP3008_CS_PIN);
            if (adc_value >= 0) {
                break;
            }

            usleep(retry_delay * (1 << retry_count));
            retry_count++;
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read from MCP3008 after %d attempts: %s\n", retry_max, strerror(errno));
            continue;
        }

        int moisture_percentage = (adc_value * (1023 / 255)) * 100;
        printf("Soil Moisture: %d%%\n", moisture_percentage);

        // Log the timestamp and soil moisture value to 'soil_data.txt'
