            fprintf(stderr, "Failed to read from MCP3008 after %d attempts: %s\n", retry_max, strerror(errno));
            continue;
        }

        int moisture_percentage = (adc_value * (1023 / 255)) * 100;
        printf("Soil Moisture: %d%%\n", moisture_percentage);

        // Log the timestamp and soil moisture value to 'soil_data.txt'
        FILE *fp = fopen("soil_data.txt", "a");
        if (fp) {
            char buffer[20];
            sprintf(buffer, "%s, %d\n", get_current_time(), moisture_percentage);
            fputs(buffer, fp);
            fclose(fp);
        }

        // Release SPI resources
        gpio_close(MCP3008_CS_PIN);
        gpio_release();
    }

    return 0;
}

int gpio_open(int channel) {
    gpio_init();
    gpio_set_mode(channel, PI_MODE_OUTPUT);
    gpio_set_level(channel, 1);
    return 0;
}

void gpio_close(int channel) {
    gpio_release();
}

int gpio_read(int channel) {
    gpio_init();
    gpio_set_level(channel, gpio_read(channel) ? 0 : 1);
    gpio_delay_us(10);
    return gpio_read(channel);
}

void gpio_set_mode(int channel, int mode) {
    gpio_init();
    gpio_set_mode(channel, mode);
}
```

To compile and run the program, use the following commands:

```
gcc -o soil_moisture soil_moisture.c -lpigpio -lrt -lrt -lwiringPi
./soil_moisture
```

This code assumes that you have the pigpio library installed and properly configured on your Raspberry Pi.

