#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>
#include <sys/stat.h>
#include <fcntl.h>

#define MCP3008_CS_GPIO 8
#define MCP3008_CS_VALUE (1 << MCP3008_CS_GPIO)

#define SPI0_CLK_FREQ 1000000
#define SPI0_CLK_FREQ_HZ 1000000

#define ADC_RESOLUTION 10
#define ADC_THRESHOLD_ABOVE 50
#define ADC_THRESHOLD_BELOW 20

#define ADC_CLASSIFY_THRESHOLD (ADC_THRESHOLD_ABOVE + ADC_THRESHOLD_BELOW)

#define ADC_READ_ATTEMPTS 3

#define ADC_LOG_FILENAME "alcohol_log.txt"

int main() {
    int fd, rc, i;
    int spi_fd, cs_gpio, adc_gpio;
    unsigned int adc_data;
    char tx[4] = {0};
    char rx[2];
    char log_message[100];

    // Initialize GPIO and SPI
    cs_gpio = gpio_request_from_sysfs(MCP3008_CS_GPIO);
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    gpio_request_from_sysfs(cs_gpio);

    // Initialize ADC
    adc_gpio = gpio_request_from_sysfs(MCP3008_CS_GPIO);
    gpio_request_from_sysfs(adc_gpio);

    // Open SPI device
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI0_CLK_FREQ_HZ) < 0) {
        perror("Failed to set SPI clock frequency");
        exit(EXIT_FAILURE);
    }

    // Open log file
    if ((fd = open(ADC_LOG_FILENAME, O_CREAT | O_WRONLY | O_APPEND, 0644)) < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Set up SPI transfer
    tx[0] = 0x01;
    tx[1] = (0x80 | (adc_gpio & 0x0F));
    tx[2] = 0x00;

    // Perform SPI transfer
    rc = write(spi_fd, tx, 3);
    if (rc < 0) {
        perror("Failed to write to SPI device");
        exit(EXIT_FAILURE);
    }

    // Wait for SPI transfer to complete
    while (rc < 3) {
        rc = read(spi_fd, rx, 2);
        if (rc < 0) {
            perror("Failed to read from SPI device");
            exit(EXIT_FAILURE);
        }
    }

    // Read ADC value
    adc_data = (rx[1] << 8) | rx[2];

    // Classify reading
    if (adc_data > ADC_THRESHOLD_ABOVE) {
        printf("Alcohol detected! Limit exceeded.\n");
    } else if (adc_data < ADC_THRESHOLD_BELOW) {
        printf("Sobriety confirmed.\n");
    } else {
        printf("Alcohol level within acceptable range.\n");
    }

    // Close log file
    close(fd);

    // Release GPIO and SPI resources
    gpio_free(adc_gpio);
    gpio_free(cs_gpio);
    close(spi_fd);

    return 0;
}

