#define CH0_GPIO_PIN 8
#define CH0_GPIO_OUTPUT_PIN 11
#define CH0_GPIO_INPUT_PIN  9
#define CH0_SPI_BUS        0
#define CH0_SPI_CS          0
#define CH0_SPI_CLK         11
#define CH0_SPI_MOSI        10
#define CH0_SPI_MISO        9
#define CH0_SPI_MODE        0
#define CH0_SPI_FREQ        1000000

#define RELAY_GPIO_PIN 18
#define RELAY_GPIO_OUTPUT_PIN 17

#define THRESHOLD 300

