    int rc;
    int fd;
    struct gpiod_channel *channel;
    struct gpiod_direction direction;
    struct gpiod_value value;
    struct timespec start_time, end_time;
    char log_file_name[] = "irrigation.log";
    FILE *log_file;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio library\n");
        return 1;
    }

    // Open SPI
    if ((fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Error opening SPI device\n");
        gpioTerminate();
        return 1;
    }

    // Set up SPI configuration
    if (ioctl(fd, SPI_IOC_WR_MODE, CH0_SPI_MODE) < 0) {
        fprintf(stderr, "Error setting SPI mode\n");
        goto error_close_spidev0_0;
    }

    if (ioctl(fd, SPI_IOC_WR_CS, CH0_SPI_CS) < 0) {
        fprintf(stderr, "Error setting SPI chip select\n");
        goto error_close_spidev0_0;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, CH0_SPI_FREQ) < 0) {
        fprintf(stderr, "Error setting SPI frequency\n");
        goto error_close_spidev0_0;
    }

    if (ioctl(fd, SPI_IOC_RD_MODE, &CH0_SPI_MODE) < 0) {
        fprintf(stderr, "Error getting SPI mode\n");
        goto error_close_spidev0_0;
    }

    if (ioctl(fd, SPI_IOC_RD_CS, &CH0_SPI_CS) < 0) {
        fprintf(stderr, "Error getting SPI chip select\n");
        goto error_close_spidev0_0;
    }

    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &CH0_SPI_FREQ) < 0) {
        fprintf(stderr, "Error getting SPI frequency\n");
        goto error_close_spidev0_0;
    }

    // Set up GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO\n");
        goto error_close_spidev0_0;
    }

    if (gpioOpen(RELAY_GPIO_PIN, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Error opening relay GPIO\n");
        goto error_close_gpio;
    }

    if (gpioOpen(CH0_GPIO_PIN, GPIO_INPUT) < 0) {
        fprintf(stderr, "Error opening soil moisture sensor GPIO\n");
        goto error_close_gpio;
    }

    if (gpioOpen(CH0_GPIO_OUTPUT_PIN, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Error opening relay GPIO\n");
        goto error_close_gpio;
    }

    // Set up channel for MCP3008
    channel = gpioChannelOpen(CH0_GPIO_PIN);
    if (channel == NULL) {
        fprintf(stderr, "Error opening channel for MCP3008\n");
        goto error_close_gpio;
    }

    direction.value = GPIO_OUTPUT;
    if (gpioDirectionSet(channel, &direction) < 0) {
        fprintf(stderr, "Error setting channel direction\n");
        goto error_close_gpio;
    }

    // Set up SPI transfer
    if (spiTransfer(fd, CH0_SPI_BUS, CH0_SPI_CS, &value, sizeof(value)) < 0) {
        fprintf(stderr, "Error setting SPI transfer\n");
        goto error_close_spidev0_0;
    }

    // Read soil moisture sensor
    if (value.value == 0) {
        if (write(RELAY_GPIO_OUTPUT_PIN, 1) < 0) {
            fprintf(stderr, "Error turning on relay\n");
            goto error_close_gpio;
