            if (write(RELAY_GPIO_OUTPUT_PIN, 1) < 0) {
                fprintf(stderr, "Error turning on relay\n");
                goto error_close_gpio;
            }

            if (write(CH0_GPIO_OUTPUT_PIN, 1) < 0) {
                fprintf(stderr, "Error turning on relay\n");
                goto error_close_gpio;
            }

            if (write(RELAY_GPIO_OUTPUT_PIN, 0) < 0) {
                fprintf(stderr, "Error turning off relay\n");
                goto error_close_gpio;
            }

            if (write(CH0_GPIO_OUTPUT_PIN, 0) < 0) {
                fprintf(stderr, "Error turning off relay\n");
                goto error_close_gpio;
            }

            if (read(CH0_GPIO_INPUT_PIN, &value, sizeof(value)) < 0) {
                fprintf(stderr, "Error reading soil moisture sensor\n");
                goto error_close_gpio;
