#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <sys/ioctl.h>

#include <pigpio.h>

#define SLAVE_ADDRESS 0x1A // I2C slave address for Honeywell AWM720P
#define ADC_CHANNEL 0 // MCP3008 ADC channel (0, 1, or 2)
#define ADC_RESOLUTION 8 // MCP3008 ADC resolution (8, 10, or 12 bits)

#define SLPM_TO_VOLT 0.5 // Conversion factor to convert SLPM to voltage
#define VOLT_TO_SLPM_PER_LPM 4.5 // Conversion factor to convert voltage to SLPM

#define FILE_APPEND_MODE O_APPEND | O_CREAT | O_WRONLY

void log_error(const char *message, struct timeval *timestamp) {
    char log_message[128];
    strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S", timestamp);

    FILE *log_file = fopen("airflow_log.txt", FILE_APPEND_MODE);
    if (log_file) {
        fprintf(log_file, "%s: %s\n", log_message, message);
        fclose(log_file);
    } else {
        fprintf(stderr, "ERROR: Failed to open log file\n");
    }
}

int main() {
    int rc;
    int adc_channel = ADC_CHANNEL;
    int adc_resolution = ADC_RESOLUTION;
    int adc_voltage_range = (1 << adc_resolution) * SLPM_TO_VOLT;
    int adc_threshold = (1 << (adc_resolution - 1)) * SLPM_TO_VOLT;
    int adc_min_value = (1 << (adc_resolution - 1)) * SLPM_TO_VOLT / 2;
    int adc_max_value = adc_voltage_range - adc_threshold;

    gpio_init();
    gpio_set_mode(GPIO_P0_0, GPIO_MODE_OUTPUT);
    gpio_set_dir(GPIO_P0_0, GPIO_OUTPUT);

    FILE *log_file = fopen("airflow_log.txt", FILE_APPEND_MODE);
    if (!log_file) {
        log_error("ERROR: Failed to open log file", NULL);
        return 1;
    }

    struct timeval start_time, end_time;
    gettimeofday(&start_time, NULL);

    while (1) {
        // Read ADC value
        int adc_value = 0;
        rc = gpio_read(GPIO_P0_0, &adc_value);
        if (rc != 0) {
            log_error("ERROR: Failed to read ADC value", &start_time);
            continue;
        }

        // Scale ADC value to voltage
        double adc_voltage = (adc_value - 0.5) * (adc_voltage_range / (1 << adc_resolution));

        // Convert voltage to SLPM
        double slpm = (adc_voltage - 0.5) * (VOLT_TO_SLPM_PER_LPM) / (1 << adc_resolution);

        // Log the reading
        char log_message[128];
        strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S", &start_time);
        log_message[strlen(log_message) - 1] = '\0'; // Remove trailing newline
        log_error("airflow = %f SLPM", slpm, &start_time);

        // Write log entry to file
        if (write(1, log_message, strlen(log_message) + 1) != strlen(log_message) + 1) {
            log_error("ERROR: Failed to write log entry", &start_time);
            continue;
        }

        // Wait for 100 ms
        usleep(100000);
    }

    // Close log file
    fclose(log_file);

    // Release resources
    gpio_exit();
    return 0;
}

