#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>

#define MCP3008_CS_PIN     (23)
#define MCP3008_CLK_PIN    (24)
#define MCP3008_DIRECTION  (1 << MCP3008_CS_PIN)

#define SPI_MODE_0        (1 << 0)
#define SPI_MODE_1        (1 << 1)
#define SPI_MODE_2        (1 << 2)
#define SPI_MODE_3        (1 << 3)
#define SPI_MODE_4        (1 << 4)
#define SPI_MODE_5        (1 << 5)
#define SPI_MODE_6        (1 << 6)
#define SPI_MODE_7        (1 << 7)

#define SPI_CLK_FREQ_HZ  1000000

#define MCP3008_DATA_LEN  10

int main() {
    int spi_fd, cs_gpio, data_gpio;
    struct spi_device *spi;
    struct gpiod_channel *cs, *data;
    unsigned int data_value;
    unsigned char command[3] = {0x01, 0x80 | (3 << 4), 0x00};
    char filename[50];
    FILE *file;
    int exit_code = 0;

    // Initialize SPI interface
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        exit(EXIT_FAILURE);
    }

    cs_gpio = gpiod_get(spi_fd, "cs");
    if (cs_gpio < 0) {
        perror("Error getting CS GPIO");
        exit(EXIT_FAILURE);
    }

    data_gpio = gpiod_get(spi_fd, "data");
    if (data_gpio < 0) {
        perror("Error getting data GPIO");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode, clock speed, and polarity/phase
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_0) < 0) {
        perror("Error setting SPI mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_CLK_SPEED_HZ, SPI_CLK_FREQ_HZ) < 0) {
        perror("Error setting SPI clock speed");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_POLARITY, SPI_CPOL_LOW) < 0) {
        perror("Error setting SPI polarity");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_PHASE, SPI_PHASE_1_EDGE) < 0) {
        perror("Error setting SPI phase");
        exit(EXIT_FAILURE);
    }

    // Open CSV file
    sprintf(filename, "sensor_data.csv");
    file = fopen(filename, "w");
    if (file == NULL) {
        perror("Error opening CSV file");
        exit(EXIT_FAILURE);
    }

    // Initialize MCP3008 ADC
    if (gpio_request_from_mem(CS_GPIO, MCP3008_CS_PIN, MCP3008_DATA_LEN, &cs) < 0) {
        perror("Error requesting CS GPIO");
        exit(EXIT_FAILURE);
    }

    if (gpio_request_from_mem(DATA_GPIO, MCP3008_DATA_LEN, &data) < 0) {
        perror("Error requesting data GPIO");
        exit(EXIT_FAILURE);
    }

    // Loop to read and log data
    while (1) {
        // Read data from MCP3008
        if (gpio_read(cs) < 0) {
            perror("Error reading CS GPIO");
            exit(EXIT_FAILURE);
        }

        if (gpio_read(data) < 0) {
            perror("Error reading data GPIO");
            exit(EXIT_FAILURE);
        }

        data_value = ((data->value[1] & 0x03) << 8) | data->value[2];

        // Log data to CSV file
        fprintf(file, "%d,%d\n", data_value, data_value);

        // Wait for 1 second
        sleep(1);
    }

    // Release resources
    gpio_free(cs);
    gpio_free(data);
    close(spi_fd);

    return 0;
}

