#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/gpio/event.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>

volatile sig_atomic_t stop_event_flag = 0;

int main() {
    int chip_fd, line_fd, event_fd;
    struct gpiod_event_attr event_attr;
    struct gpiod_event_info event_info;
    char log_file_path[128];
    char log_message[128];

    // Open /dev/gpiochip0
    chip_fd = gpiod_chip_open("/dev/gpiochip0");
    if (chip_fd < 0) {
        perror("Failed to open /dev/gpiochip0");
        exit(EXIT_FAILURE);
    }

    // Get GPIO line 17
    line_fd = gpiod_get_line(chip_fd, 17);
    if (line_fd < 0) {
        perror("Failed to get line 17");
        exit(EXIT_FAILURE);
    }

    // Request line 17 for falling-edge event detection
    event_attr.type = GPIGPIO_EVENT_TYPE_FALLING_EDGE;
    event_attr.line = line_fd;
    event_attr.event_flags = GPIGPIO_EVENT_FLAG_LEVEL_LOW | GPIGPIO_EVENT_FLAG_EDGE_FALLING;
    event_attr.consumer_label = "vibration-monitor";
    event_attr.event_handler = gpiod_event_handler_falling_edge;
    event_attr.event_flags |= GPIGPIO_EVENT_FLAG_NO_EDGE_FALLING;

    event_fd = gpiod_event_request(chip_fd, &event_attr);
    if (event_fd < 0) {
        perror("Failed to request line 17 for falling-edge event detection");
        exit(EXIT_FAILURE);
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!stop_event_flag) {
        // Wait for falling-edge event
        if (gpiod_line_event_wait(event_fd, &event_info, NULL) < 0) {
            perror("Failed to wait for falling-edge event");
            exit(EXIT_FAILURE);
        }

        // Read the event timestamp
        struct timespec ts;
        if (gpiod_line_event_get_timestamp(event_fd, &ts) < 0) {
            perror("Failed to get timestamp");
            exit(EXIT_FAILURE);
        }

        // Append timestamped log message to file
        snprintf(log_file_path, sizeof(log_file_path), "/var/log/vibration_shutdown.log", ts.tv_sec);
        if (append_log_message(log_file_path, log_message) < 0) {
            perror("Failed to append log message");
            exit(EXIT_FAILURE);
        }

        // Print message to stdout
        printf("Vibration detected on line 17\n");

        // Invoke system shutdown
        system("sudo shutdown -h now");
    }

    // Release resources
    gpiod_event_release(event_fd);
    gpiod_line_event_unrequest(line_fd);
    gpiod_chip_release(chip_fd);

    return 0;
}

// Signal handler
void signal_handler(int signum) {
    stop_event_flag = 1;
}

// Append log message to file
int append_log_message(const char* file_path, const char* message) {
    FILE* log_file = fopen(file_path, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    if (fprintf(log_file, "%s\n", message) < 0) {
        perror("Failed to write to log file");
        fclose(log_file);
        return -1;
    }

    fclose(log_file);
    return 0;
}

