    // Request line 17 for falling-edge event detection
    event_attr.type = GPIGPIO_EVENT_TYPE_FALLING_EDGE;
    event_attr.line = line_fd;
    event_attr.event_flags = GPIGPIO_EVENT_FLAG_LEVEL_LOW | GPIGPIO_EVENT_FLAG_EDGE_FALLING;
    event_attr.consumer_label = "vibration-monitor";
    event_attr.event_handler = gpiod_event_handler_falling_edge;
    event_attr.event_flags |= GPIGPIO_EVENT_FLAG_NO_EDGE_FALLING;

    event_fd = gpiod_event_request(chip_fd, &event_attr);
    if (event_fd < 0) {
        perror("Failed to request line 17 for falling-edge event detection");
        exit(EXIT_FAILURE);
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!stop_event_flag) {
        // Wait for falling-edge event
        if (gpiod_line_event_wait(event_fd, &event_info, NULL) < 0) {
            perror("Failed to wait for falling-edge event");
            exit(EXIT_FAILURE);
