    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    if (i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C.\n");
        return 1;
    }

    // Open I2C device file
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C device file.\n");
        return 1;
    }

    // Open SPI device file
    if ((spi_fd = open(MCP3008_CH_0, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device file.\n");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address.\n");
        return 1;
    }

    // Set SPI chip select pin
    if (gpio_set_value(3, 1) < 0) {
        fprintf(stderr, "Failed to set SPI chip select pin.\n");
        return 1;
    }

    // Initialize MCP3008 ADC
    if (mcp3008_init() < 0) {
        fprintf(stderr, "Failed to initialize MCP3008 ADC.\n");
        return 1;
    }

    // Initialize I2C chip
    if (i2c_master_open() < 0) {
        fprintf(stderr, "Failed to open I2C master.\n");
        return 1;
    }

    // Initialize SPI chip
    if (spi_open(spi_fd, 0) < 0) {
        fprintf(stderr, "Failed to open SPI chip.\n");
        return 1;
