    i2c_data.flags = 0;
    i2c_data.buf = (uint8_t *)malloc(2);
    i2c_data.len = 2;
    spi_data.flags = SPI_XFER_MODE_ONE_SHOT;
    spi_data.bits_per_word = 8;
    spi_data.bits_per_word = 8;
    spi_data.xferlen = 2;

