    while (1) {
        // Read ambient light from BH1750 sensor
        if (i2c_master_write_i2c_block_data(i2c_fd, I2C_ADDR, I2C_REG_LIGHT, &i2c_data, 1) < 0) {
            fprintf(stderr, "Failed to read ambient light from BH1750 sensor.\n");
            return 1;
        }

        // Read sound level from MAX4466 analog microphone
        if (mcp3008_read_adc(0, &adc_value) < 0) {
            fprintf(stderr, "Failed to read sound level from MAX4466 analog microphone.\n");
            return 1;
        }

