        time_info.tm_year = 2022;
        time_info.tm_mon = 0;
        time_info.tm_mday = 1;
        time_info.tm_hour = 0;
        time_info.tm_min = 0;
        time_info.tm_sec = 0;
        strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S, ", &time_info);

        // Log data to file
        if (write(1, log_entry, strlen(log_entry)) < 0) {
            fprintf(stderr, "Failed to write log entry to file.\n");
            return 1;
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up resources
    close(i2c_fd);
    close(spi_fd);
    gpio_deinit();
    mcp3008_exit();
    i2c_master_close();
    spi_close();

