        if (retry_count == retries) {
            fprintf(stderr, "Maximum retry count exceeded\n");
            gpio_exit();
            i2c_exit();
            spi_exit();
            return 1;
        }
    }

    // Close log file descriptor
    if (close(log_file_name) < 0) {
        fprintf(stderr, "Failed to close log file\n");
        retry_count++;
        if (retry_count == retries) {
            fprintf(stderr, "Maximum retry count exceeded\n");
            gpio_exit();
            i2c_exit();
            spi_exit();
            return 1;
        }
    }

    // Close SPI and I2C file descriptors
