    gpio_set_mode(MCP3008_SPI_CLK, PI_OUTPUT);
    gpio_set_mode(MCP3008_SPI_MOSI, PI_OUTPUT);
    gpio_set_mode(MCP3008_SPI_MISO, PI_INPUT);

    // Open SPI and log file
    log_file = fopen(log_file_name, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        return 1;
