    gpio_set_mode(MCP3008_SPI_MOSI, PI_OUTPUT);
    gpio_set_mode(MCP3008_SPI_MISO, PI_INPUT);
    gpio_set_level(MCP3008_CS_PIN, 1);
    gpio_delay(1);
    adc_value = gpio_read(MCP3008_SPI_MOSI);

    // Read and convert all three sensors
    while (1) {
        adc_value = gpio_read(MCP3008_SPI_MOSI);
        if (adc_value < ADC_MIN_VALUE || adc_value > ADC_MAX_VALUE) {
            fprintf(stderr, "Error: Invalid ADC value %d\n", adc_value);
            continue;
        }

        moisture_percent = (1.0 - (adc_value / ADC_RESOLUTION)) * 100.0;
        if (moisture_percent < SOIL_SENSOR_THRESHOLD_DRY) {
            log_timestamp("Dry sensor 1");
        } else if (moisture_percent < SOIL_SENSOR_THRESHOLD_WET) {
            log_timestamp("Wet sensor 1");
        } else {
            log_timestamp("Sensor 1 OK");
        }

        adc_value = gpio_read(MCP3008_SPI_MOSI);
        adc_value = gpio_read(MCP3008_SPI_MOSI);
        adc_value = gpio_read(MCP3008_SPI_MOSI);

        // Sleep for 60 seconds
        gpio_delay(60000);
    }

    // Close SPI and log file
    gpio_set_level(MCP3008_CS_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    gpioRelease();

    return 0;
}

