#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define RELAY_PIN_COUNT 4
#define RELAY_PIN_BASE 17

int main() {
    int relays[RELAY_PIN_COUNT];
    int i;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Set all relay pins inactive
    for (i = 0; i < RELAY_PIN_COUNT; i++) {
        relays[i] = gpiod_line_request_output(relay_device, RELAY_PIN_BASE + i);
        if (relays[i] < 0) {
            fprintf(stderr, "Failed to request output for relay %d\n", i);
            gpiod_exit();
            return 1;
        }
    }

    // Signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        // Activate and deactivate each relay in sequence
        for (i = 0; i < RELAY_PIN_COUNT; i++) {
            if (relays[i] >= 0) {
                gpiod_line_set_value(relay_device, RELAY_PIN_BASE + i, 1);
                usleep(1000); // 1 second delay
                gpiod_line_set_value(relay_device, RELAY_PIN_BASE + i, 0);
                usleep(1000); // 1 second delay
            }
        }

        // Wait for 1 second before activating the next relay
        sleep(1);
    }

    // Release all GPIO lines and exit
    for (i = 0; i < RELAY_PIN_COUNT; i++) {
        gpiod_line_release(relay_device, RELAY_PIN_BASE + i);
    }
    gpiod_exit();

    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    printf("Received signal %d. Shutting down GPIO lines and exiting...\n", signum);
    for (int i = 0; i < RELAY_PIN_COUNT; i++) {
        gpiod_line_release(relay_device, RELAY_PIN_BASE + i);
    }
    gpiod_exit();
}

