#define LED_GPIO_FILE "/sys/class/gpio/gpio16/value"

int main() {
    int fd, spi_fd, gpio_fd;
    struct spi_device *spi;
    struct gpio_chip *gpio_chip;
    struct gpio_request gpio_request;
    unsigned int adc_value;
    unsigned int threshold = 500;
    unsigned int debounce_delay = 10;
    unsigned int last_timestamp = 0;
    char log_file[128] = "sound_events.log";

    // Initialize pigpio library
    if (gpio_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize SPI device\n");
        return 1;
    }

    // Open SPI device
    if ((spi_fd = spi_open(SPI_DEVICE_PATH)) < 0) {
        fprintf(stderr, "Error: Failed to open SPI device\n");
        return 1;
    }

    // Open GPIO file
    if ((gpio_fd = open(LED_GPIO_FILE, O_WRONLY)) < 0) {
        fprintf(stderr, "Error: Failed to open GPIO file\n");
        return 1;
    }

    // Set GPIO file to output mode
    if (ioctl(gpio_fd, GPIO_SET_DIR, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO file to output mode\n");
        return 1;
    }

    // Set GPIO file value to 0 (off)
    if (write(gpio_fd, 0, 1) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO file value to 0\n");
        return 1;
    }

    // Set SPI device file descriptor
    if ((fd = open(SPI_DEVICE_PATH, O_RDWR)) < 0) {
        fprintf(stderr, "Error: Failed to open SPI device\n");
        return 1;
    }

    // Set SPI device file descriptor to non-blocking mode
    if (fcntl(fd, F_SETFL, O_NONBLOCK) < 0) {
        fprintf(stderr, "Error: Failed to set SPI device file descriptor to non-blocking mode\n");
        return 1;
    }

    // Set SPI device configuration
    if (spi_set_mode(spi, SPI_MODE_0) < 0) {
        fprintf(stderr, "Error: Failed to set SPI device mode\n");
        return 1;
    }

    // Set SPI device clock polarity and phase
    if (spi_set_bit_order(spi, SPI_BIT_ORDER_MSB) < 0) {
        fprintf(stderr, "Error: Failed to set SPI device bit order\n");
        return 1;
    }

    if (spi_set_data_order(spi, SPI_ORDER_MSB_FIRST) < 0) {
        fprintf(stderr, "Error: Failed to set SPI device data order\n");
        return 1;
    }

    // Set SPI device frequency
    if (spi_set_max_speed_hz(spi, 1000000) < 0) {
        fprintf(stderr, "Error: Failed to set SPI device frequency\n");
        return 1;
    }

    // Set SPI device transfer function
    if (spi_set_mode(spi, SPI_MODE_TX) < 0) {
        fprintf(stderr, "Error: Failed to set SPI device mode\n");
        return 1;
    }

    // Set SPI device transfer function to DMA
    if (spi_set_transfer_function(spi, SPI_TRANSFER_FUNCTION_DMA) < 0) {
        fprintf(stderr, "Error: Failed to set SPI device transfer function\n");
        return 1;
    }

    // Set SPI device transfer function to DMA
    if (spi_set_max_transfer_len(spi, 8) < 0) {
        fprintf(stderr, "Error: Failed to set SPI device transfer function\n");
        return 1;
    }

    // Set SPI device transfer function to DMA
    if (spi_set_chip_select_polarity(spi, 1) < 0) {
        fprintf(stderr, "Error: Failed to set SPI device chip select polarity\n");
        return 1;
    }

    // Set SPI device transfer function to DMA
    if (spi_set_chip_select_speed(spi, 1000000) < 0) {
        fprintf(stderr, "Error: Failed to set SPI device chip select speed\n");
        return 1;
    }

    // Set SPI device transfer function to DMA
    if (spi_set_chip_select(spi, MCP3008_CS_VALUE) < 0) {
        fprintf(stderr, "Error: Failed to set SPI device chip select\n");
        return 1;
    }

    // Set SPI device transfer function to DMA
    if (spi_transfer(spi, (unsigned char *)&adc_value, 1, 0) < 0) {
        fprintf(stderr, "Error: Failed to read ADC value\n");
        return 1;
    }

    // Check if ADC value is within the valid range (0-1023)
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range\n");
        return 1;
    }

    // Calculate the 10-bit ADC value
    unsigned int adc_raw = adc_value * (1023 / MCP3008_MAX_RESOLUTION);

    // Read the MCP3008 channel
    if (mcp3008_read_channel(adc_raw) < 0) {
        fprintf(stderr, "Error: Failed to read MCP3008 channel\n");
        return 1;
    }

    // Check if the selected MCP3008 channel is valid
    if (adc_raw != MCP3008_CHANNEL_0) {
        fprintf(stderr, "Error: Invalid MCP3008 channel selected\n");
        return 1;
    }

    // Read the ADC value every 10 ms
    while (1) {
        // Debounce delay after each trigger
        usleep(debounce_delay * 1000);

        // Read the ADC value
        if (mcp3008_read_channel(adc_raw) < 0) {
            fprintf(stderr, "Error: Failed to read MCP3008 channel\n");
            return 1;
        }

        // Calculate the 10-bit ADC value
        unsigned int adc_raw = adc_value * (1023 / MCP3008_MAX_RESOLUTION);

        // Check if the ADC value is within the valid range (0-1023)
        if (adc_raw < 0 || adc_raw > 1023) {
            fprintf(stderr, "Error: ADC value out of range\n");
            return 1;
        }

        // Calculate the 10-bit ADC value
        unsigned int adc_raw = adc_value * (1023 / MCP3008_MAX_RESOLUTION);

        // Check if the ADC value exceeds the threshold
        if (adc_raw > adc_value + threshold) {
            // Turn on the LED
            if (write(LED_GPIO_FILE, 1, 1) < 0) {
                fprintf(stderr, "Error: Failed to turn on LED\n");
                return 1;
            }

            // Log the timestamp
            struct timeval tv;
            gettimeofday(&tv, NULL);
            struct tm *ltm = localtime(&tv.tv_sec);
            char log_message[32];
            strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S", ltm);
            if (write(log_file, log_message, strlen(log_message)) < 0) {
                fprintf(stderr, "Error: Failed to write log message\n");
                return 1;
            }

            // Wait for 500 ms
            usleep(500 * 1000);

            // Turn off the LED
            if (write(LED_GPIO_FILE, 0, 1) < 0) {
                fprintf(stderr, "Error: Failed to turn off LED\n");
                return 1;
            }
        }

        // Wait for debounce delay
        usleep(debounce_delay * 1000);
    }

    // Clean up SPI and GPIO resources
    spi_exit();
    gpio_exit();

