#include <stdio.h>
#include <stdlib.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>

#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x60

#define GPIO_FILE "/sys/class/gpio/gpio17/value"

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msgs[2];
    struct i2c_client *client;
    int ret;

    // Initialize GPIO file
    if ((fd = open(GPIO_FILE, O_RDWR | O_NONBLOCK)) == -1) {
        perror("Error opening GPIO file");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO direction
    if (ioctl(fd, GPIO_SET_DIR, "out") == -1) {
        perror("Error setting GPIO direction");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    if ((client = i2c_init_client(I2C_BUS, I2C_ADDR)) == NULL) {
        perror("Error initializing I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set up I2C message structure
    msgs[0].addr = client->addr;
    msgs[0].flags = 0;
    msgs[1].addr = client->addr;
    msgs[1].flags = I2C_M_RD;

    // Read sensor data
    if ((ret = i2c_transfer(client, msgs, 2)) == -1) {
        perror("Error reading sensor data");
        exit(EXIT_FAILURE);
    }

    // Convert sensor data to voltage
    float voltage = (float)msgs[0].data;

    // Convert voltage to distance
    float distance = (float)26.0 / (voltage + 0.0) - 6.0;

    // Log distance and timestamp
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *ltm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);

    FILE *fp = fopen("distance_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening distance_log.txt");
        exit(EXIT_FAILURE);
    }

    fprintf(fp, "%.4f\n", distance);
    fprintf(fp, "%.4f\n", timestamp);
    fclose(fp);

    // Print proximity-based pet feeder activation
    if (distance < 200.0) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }

    // Close GPIO file and I2C bus
    close(fd);
    i2c_exit_client(client);

    return 0;
}

