        fprintf(stderr, "Failed to stop ADC conversion\n");
        return 1;
    }

    // Close SPI file
    fclose(fp);

    // Close ADC
    if (adc_close(adc_fd) < 0) {
        fprintf(stderr, "Failed to close ADC\n");
        return 1;
    }

    // Close GPIO line
    if (gpio_close(GPIO_FILE, GPIO_LINE_17) < 0) {
        fprintf(stderr, "Failed to close GPIO line\n");
        return 1;
