#define MCP3008_CS_PIN 8
#define MCP3008_CLK_PIN 10
#define MCP3008_MOSI_PIN 9
#define MCP3008_MISO_PIN 11

#define SPI0_CS_PIN 0
#define SPI0_CLK_PIN 11
#define SPI0_MOSI_PIN 10
#define SPI0_MISO_PIN 9

#define VDD_PIN 5
#define AGND_PIN 0
#define VREF_PIN 3

#define VOLTAGE_RATIOMETRIC_THRESHOLD 2.5
#define VOLTAGE_FULLSCALE 5.0
#define CURRENT_INTERPOLATION_FACTOR 50.0

#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S %3.2f"

int main() {
    int ret;
    int chipSelect = MCP3008_CS_PIN;
    int clockSelect = MCP3008_CLK_PIN;
    int dataSelect = MCP3008_MOSI_PIN;
    int misoSelect = MCP3008_MISO_PIN;
    int spiHandle;
    struct spi_device *spi;
    struct spi_transfer transfer[3];
    uint8_t tx[4] = {0x01, 0x80 | (0 << 4), 0x00};
    uint16_t rx[2];
    int voltage, current;

    if (gpioInitialise() != 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (spiOpen(SPI0_CS_PIN, SPI0_CLK_PIN, SPI0_MOSI_PIN, SPI0_MISO_PIN, &spi) != 0) {
        fprintf(stderr, "Failed to open SPI0\n");
        gpioTerminate();
        return 1;
    }

    if (spiXfer(spi, transfer, 3) != 3) {
        fprintf(stderr, "Failed to read MCP3008 channel 0\n");
        spiClose(spi);
        gpioTerminate();
        return 1;
    }

    voltage = ((rx[1] & 0x03) << 8) | rx[2];
    if (voltage < 0 || voltage > VREF_PIN) {
        fprintf(stderr, "Invalid voltage reading from MCP3008 channel 0\n");
        spiClose(spi);
        gpioTerminate();
        return 1;
    }

    current = (voltage - 2.5) * (50.0 / 2.5);
    if (current < 0) {
        fprintf(stderr, "Invalid current reading from MCP3008 channel 0\n");
        spiClose(spi);
        gpioTerminate();
        return 1;
    }

    if (gpioDelay(100000) != 0) {
        fprintf(stderr, "Failed to append timestamp to current_log.txt\n");
        spiClose(spi);
        gpioTerminate();
        return 1;
    }

    char timestamp[30];
    struct timeval tv;
    gettimeofday(&tv, NULL);
    strftime(timestamp, sizeof(timestamp), TIMESTAMP_FORMAT, &tv);

    FILE *logFile = fopen("current_log.txt", "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open current_log.txt\n");
        spiClose(spi);
        gpioTerminate();
        return 1;
    }

    fprintf(logFile, "%s\n", timestamp);
    fprintf(logFile, "%.2f A\n", current);
    fclose(logFile);

    spiClose(spi);
    gpioTerminate();

    return 0;
}

