void read_mcp3008(int channel) {
    gpio_init();
    gpio_set_mode(channel, PI_OUTPUT);
    gpio_write(channel, 0);
    gpio_delay_us(10);
    gpio_write(channel, 1);
    gpio_delay_us(10);
    uint16_t data = gpio_read(channel);
    return data;
}

double calculate_moisture_level(int adc_value) {
    return (adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC) * 100.0;
}

void log_data(double moisture_level) {
    char timestamp[26];
    time_t now = time(NULL);
    struct tm *ltm = localtime(&now);
    strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", ltm);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
