    if (gpio_set_mode(17, PI_INPUT) < 0) {
        perror("Failed to set GPIO17 as input");
        return 1;
    }
    if (gpio_set_pull_up_down(17, PI_UP) < 0) {
        perror("Failed to set GPIO17 pull-down");
        return 1;
    }

    // Initialize syslog
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_AUTH);

    // Set up motion detection sensor
    sensor = pigpio_get_gpio_number("PIR");
    if (sensor < 0) {
        perror("Failed to get PIR GPIO number");
        return 1;
    }

    // Set up libcamera-still command-line utility
    camera = pigpio_open_camera();
    if (camera < 0) {
        perror("Failed to open camera");
        return 1;
    }

    // Main loop
    while (1) {
        // Poll sensor for motion
        err = pigpio_get_motion_detection(sensor, &sensor_state);
        if (err < 0) {
            perror("Failed to get motion detection state");
            continue;
        }

        // Check if motion is detected
        if (sensor_state == PI_DETECTED) {
            // Apply debounce delay
            tv.tv_sec = 0;
            tv.tv_usec = 200000;
            pigpio_delay_us(tv.tv_usec);

            // Capture JPEG image with timestamp
            snprintf(filename, sizeof(filename), "%s%s.jpg", CAMERA_PATH, ISO_8601_TIMESTAMP_FORMAT);
            child = fork();
            if (child == 0) {
                // Child process
                if (pigpio_capture_image(camera, CAMERA_PATH, filename) < 0) {
                    perror("Failed to capture image");
                    exit(1);
                }
                exit(0);
            }

            // Wait for child process to finish
            waitpid(child, &status, 0);
        }

        // Log key events
        if (syslog(LOG_INFO, "Startup") == -1) {
            perror("Failed to log startup");
            exit(1);
        }
        if (syslog(LOG_INFO, "Motion detected") == -1) {
            perror("Failed to log motion detected");
            exit(1);
        }
        if (syslog(LOG_INFO, "Capture success") == -1) {
            perror("Failed to log capture success");
            exit(1);
        }
        if (syslog(LOG_INFO, "Capture failure") == -1) {
            perror("Failed to log capture failure");
            exit(1);
        }
        if (syslog(LOG_INFO, "Shutdown") == -1) {
            perror("Failed to log shutdown");
            exit(1);
        }

        // Wait for 50 ms
        usleep(50000);
    }

    // Clean up
    pigpio_close_camera(camera);
    pigpio_release_gpio(sensor);
    gpio_deinit();

    closelog();

    return 0;
}
