    fd = open("/dev/video0", O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        perror("Error opening video device");
        exit(EXIT_FAILURE);
    }

    // Query the output information
    ret = ioctl(fd, VIDIOC_QUERYBUF_SIZE, &output_info);
    if (ret < 0) {
        perror("Error querying output buffer size");
        exit(EXIT_FAILURE);
    }

    // Set the output format
    ret = ioctl(fd, VIDIOC_S_OUTPUT_INFO, &output_info);
    if (ret < 0) {
        perror("Error setting output format");
        exit(EXIT_FAILURE);
