    stream_parm.b_timecode_out_flags_mux_flags = 0;
    stream_parm.b_timecode_out_flags_mux_flags_mux = 0;
    stream_parm.b_timecode_out_flags_mux_flags_mux_flags = 0;
    stream_parm.b_timecode_out_flags_mux_flags_mux_flags_mux = 0;

    // Set up the select() function
    struct timeval timeout;
    timeout.tv_sec = 0;
    timeout.tv_usec = 1000000;

    // Initialize the select() function
    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    // Main loop
    while (!exit_gracefully) {
        // Wait for input or output
        int input_ready = select(fd + 1, &fds, NULL, NULL, &timeout);
        if (input_ready == -1) {
            perror("Error in select()");
            exit(EXIT_FAILURE);
        }

        // Check for input
        if (FD_ISSET(fd, &fds)) {
            // Read from the input buffer
            ret = read(fd, buffer, BUF_SIZE);
            if (ret < 0) {
                perror("Error reading from input buffer");
                exit(EXIT_FAILURE);
            }

            // Log the timestamp
            gettimeofday(&ts, NULL);
            jiffies_to_msecs(&ts, &ts);
            snprintf(filename, 128, "frame_log.txt");
            open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
            write(fileno(stdout), buffer, ret);
            write(fileno(stdout), &ts, sizeof(struct timeval));
            write(fileno(stdout), &jiffies, sizeof(jiffies));
            close(fileno(stdout));
        }

        // Check for output
        if (FD_ISSET(fd, &fds)) {
            // Write to the output buffer
            ret = write(fd, buffer, BUF_SIZE);
            if (ret < 0) {
                perror("Error writing to output buffer");
                exit(EXIT_FAILURE);
            }
        }
    }

    // Clean up
    close(fd);
    munmap(mmap_offset_range.addr, BUF_SIZE);
    exit(EXIT_SUCCESS);
