    buffer[0] = '\0';
    for (i = 0; i < BUF_SIZE; i++) {
        buffer[i] = (char)i;
    }
    mmap_offset_range.addr = mmap(NULL, BUF_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mmap_offset_range.addr == MAP_FAILED) {
