#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define V4L2_DEVICE_GROUP_INDEX 0
#define V4L2_CAPTURE_MODE 1
#define V4L2_BUF_TYPE_VIDEO_CAPTURE 2

#define V4L2_PIX_FMT_MJPEG 0x3432
#define V4L2_FIELD_NONE 0

#define VIDIOC_QUERYCAP VIDIOC_G_CAP
#define VIDIOC_STREAMON VIDIOC_S_STREAMON
#define VIDIOC_STREAMOFF VIDIOC_S_STREAMOFF
#define VIDIOC_G_FMT VIDIOC_G_FMT
#define VIDIOC_S_FMT VIDIOC_S_FMT

#define V4L2_BUF_COUNT_MAX 8

int main() {
    int fd, i, ret;
    struct v4l2_capability cap_capability;
    struct v4l2_streamparm stream_parm;
    struct v4l2_format format;
    struct v4l2_mmap_offset_range mmap_offset_range;
    struct v4l2_buffer buffer;
    char *filename = "image.jpg";
    unsigned int mmap_count = 0;

    // Open the device
    fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    // Query device capabilities
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap_capability);
    if (ret < 0) {
        perror("Error querying device capabilities");
        close(fd);
        return 1;
    }

    if (!(cap_capability.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        perror("V4L2_CAP_VIDEO_CAPTURE not supported");
        close(fd);
        return 1;
    }

    if (!(cap_capability.capabilities & V4L2_CAP_STREAMING)) {
        perror("V4L2_CAP_STREAMING not supported");
        close(fd);
        return 1;
    }

    // Request the format
    memset(&format, 0, sizeof(format));
    format.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    format.fmt.pix.width = 1920;
    format.fmt.pix.height = 1080;
    format.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    format.fmt.pix.field = V4L2_FIELD_NONE;
    format.fmt.pix.mjpeg.mjpeg_mode = V4L2_MJPEG_MODE_AUTO;
    format.fmt.pix.mjpeg.jpeg_quality = 10;

    ret = ioctl(fd, VIDIOC_S_FMT, &format);
    if (ret < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    // Request MMAP buffers
    memset(&stream_parm, 0, sizeof(stream_parm));
    stream_parm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    stream_parm.mem_type = V4L2_MEM_MMAP;
    stream_parm.mmap.count = V4L2_BUF_COUNT_MAX;

    ret = ioctl(fd, VIDIOC_STREAMON, &stream_parm);
    if (ret < 0) {
        perror("Error enabling MMAP buffers");
        close(fd);
        return 1;
    }

    // Allocate and map MMAP buffers
    mmap_offset_range.count = V4L2_BUF_COUNT_MAX;
    mmap_offset_range.offset = 0;
    mmap_offset_range.length = mmap_count * sizeof(unsigned char);

    for (i = 0; i < V4L2_BUF_COUNT_MAX; i++) {
        ret = ioctl(fd, VIDIOC_QUERYBUF, &buffer);
        if (ret < 0) {
            perror("Error querying buffer");
            close(fd);
            return 1;
        }

        buffer.index = i;
        buffer.flags = V4L2_BUF_FLAG_MMAP;
        buffer.userptr = mmap_offset_range.userptr;

        ret = ioctl(fd, VIDIOC_MAPBUF, &buffer);
        if (ret < 0) {
            perror("Error mapping buffer");
            close(fd);
            return 1;
        }

        mmap_offset_range.offset += buffer.length;
        mmap_count++;
    }

    // Start streaming
    ret = ioctl(fd, VIDIOC_STREAMON, NULL);
    if (ret < 0) {
        perror("Error enabling streaming");
        close(fd);
        return 1;
    }

    // Dequeue and process each buffer
    while (mmap_count > 0) {
        ret = ioctl(fd, VIDIOC_DQBUF, &buffer);
        if (ret < 0) {
            perror("Error dequeuing buffer");
            close(fd);
            return 1;
        }

        // Check buf.bytesused > 0
        if (buffer.bytesused == 0) {
            continue;
        }

        // Write raw MJPEG bytes to disk
        write(1, buffer.data, buffer.bytesused);

        // Unmap and release MMAP buffers
        ret = ioctl(fd, VIDIOC_UNMAPBUF, &buffer);
        if (ret < 0) {
            perror("Error unmapping buffer");
            close(fd);
            return 1;
        }

        mmap_offset_range.offset += buffer.length;
        mmap_count--;
    }

    // Stop streaming
    ret = ioctl(fd, VIDIOC_STREAMOFF, NULL);
    if (ret < 0) {
        perror("Error disabling streaming");
        close(fd);
        return 1;
    }

    // Close the file descriptor
    close(fd);

    return 0;
}

