#define VIDEO_DEVICE "/dev/video0"
#define AUTO_FOCUS_CONTROL_ID 0x1a

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_querycap qcap;
    struct v4l2_frmsizeenum fsize_enum;
    struct v4l2_queryframeinterval fint_enum;
    int focus_control_id;

    // Open the device
    fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening device");
        exit(EXIT_FAILURE);
    }

    // Query device capabilities
    memset(&cap, 0, sizeof(cap));
    cap.capabilities = V4L2_CAP_VIDEO_OUTPUT | V4L2_CAP_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying device capabilities");
        exit(EXIT_FAILURE);
    }

    // Check if autofocus is supported
    focus_control_id = AUTO_FOCUS_CONTROL_ID;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &focus_control_id) < 0) {
        if (errno == ENODEV) {
            printf("Autofocus is not supported by the camera.\n");
        } else {
            perror("Error querying autofocus control");
            exit(EXIT_FAILURE);
        }
    }

    // Enumerate frame sizes
    memset(&fsize_enum, 0, sizeof(fsize_enum));
    fsize_enum.type = V4L2_FRMSIZE_TYPE_DISCRETE;
    fsize_enum.discrete.max = 1024;
    fsize_enum.discrete.step = 4;
    if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fsize_enum) < 0) {
        perror("Error enumerating frame sizes");
        exit(EXIT_FAILURE);
    }

    // Enumerate frame intervals
    memset(&fint_enum, 0, sizeof(fint_enum));
    fint_enum.type = V4L2_FRMINTERVAL_TYPE_DISCRETE;
    fint_enum.discrete.max = 1000;
    fint_enum.discrete.step = 1;
    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &fint_enum) < 0) {
        perror("Error enumerating frame intervals");
        exit(EXIT_FAILURE);
    }

    // Print the supported resolutions, frame rates, and autofocus support
    printf("Supported resolutions:\n");
    for (int i = 0; i < fsize_enum.discrete.count; i++) {
        printf("- Resolution: %dx%d, Frame rate: %d fps\n", fsize_enum.discrete.list[i].width, fsize_enum.discrete.list[i].height, fsize_enum.discrete.list[i].fps);
    }

    printf("Autofocus support: %s\n", focus_control_id == AUTO_FOCUS_CONTROL_ID ? "Yes" : "No");

    close(fd);
    return 0;
}

