#define VIDIOC_QUERYCAP "VIDIOC_QUERYCAP"
#define VIDIOC_G_FMT "VIDIOC_G_FMT"
#define VIDIOC_S_FMT "VIDIOC_S_FMT"
#define VIDIOC_G_CROP "VIDIOC_G_CROP"
#define VIDIOC_S_CROP "VIDIOC_S_CROP"

#define V4L2_PIX_FMT_YUYV 0x1035
#define V4L2_FIELD_NONE 0

#define BUF_SIZE 4096

int main() {
    int fd, ret;
    struct v4l2_cap_capabilities cap_caps;
    struct v4l2_query_format format;
    struct v4l2_buffer buffer;
    struct v4l2_rect cropped_rect;
    struct v4l2_rect crop_rect;
    void *mmap_addr;
    struct v4l2_mmap_offset offset;
    struct v4l2_mmap_range *mmap_ranges;
    int i;

    // Open /dev/video0
    fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("Error opening video device");
        exit(EXIT_FAILURE);
    }

    // Check if it's a V4L2 video capture device
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap_caps);
    if (ret < 0) {
        perror("Error querying capabilities");
        exit(EXIT_FAILURE);
    }

    if (!(strstr(cap_caps.driver, "v4l2") && strstr(cap_caps.card, "Raspberry Pi"))) {
        perror("Unsupported device");
        exit(EXIT_FAILURE);
    }

    // Set the format to 640x480, YUYV, and no field
    format.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    format.fmt.pix.width = 640;
    format.fmt.pix.height = 480;
    format.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    format.fmt.pix.field = V4L2_FIELD_NONE;

    // Request one buffer
    format.fmt.pix.buffercount = 1;

    // Set the cropping region
    cropped_rect.x = 100;
    cropped_rect.y = 50;
    cropped_rect.width = 200;
    cropped_rect.height = 150;

    // Set the crop region
    crop_rect.x = 0;
    crop_rect.y = 0;
    crop_rect.width = 640;
    crop_rect.height = 480;

    // Set the buffer size
    buffer.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buffer.memory = V4L2_MEMORY_MMAP;
    buffer.size = BUF_SIZE;

    // Request the buffer
    ret = ioctl(fd, VIDIOC_G_FMT, &format);
    if (ret < 0) {
        perror("Error getting format");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(fd, VIDIOC_S_FMT, &format);
    if (ret < 0) {
        perror("Error setting format");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(fd, VIDIOC_G_CROP, &cropped_rect);
    if (ret < 0) {
        perror("Error getting cropping region");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(fd, VIDIOC_S_CROP, &crop_rect);
    if (ret < 0) {
        perror("Error setting cropping region");
        exit(EXIT_FAILURE);
    }

