        if (ioctl(tiltServo, PI_PWM_PULSEWIDTH, (tiltAngle / 180) * 2500) < 0) {
            printf("Error: Failed to set PWM pulse width.\n");
            continue;
        }

        printf("PWM settings updated.\n");

        usleep(100000); // 100 ms delay

        if (ioctl(panServo, PI_PWM_PULSEWIDTH, 0) < 0) {
            printf("Error: Failed to set PWM pulse width to neutral position.\n");
            continue;
        }

        if (ioctl(tiltServo, PI_PWM_PULSEWIDTH, 0) < 0) {
            printf("Error: Failed to set PWM pulse width to neutral position.\n");
            continue;
        }

        printf("Pan-tilt mount set to neutral position.\n");

        if (ioctl(panServo, PI_PWM_PULSEWIDTH, 0) < 0) {
            printf("Error: Failed to set PWM pulse width to neutral position.\n");
            continue;
        }

        if (ioctl(tiltServo, PI_PWM_PULSEWIDTH, 0) < 0) {
            printf("Error: Failed to set PWM pulse width to neutral position.\n");
            continue;
        }

        printf("Pan-tilt mount set to neutral position.\n");

        if (read(0, &input, 1) != 1) {
