        gpiod_exit();
        return 1;
    }

    // Get line info
    if (gpiod_line_info_get(chip_fd, &line_info) < 0) {
        fprintf(stderr, "Failed to get line info\n");
        gpiod_chip_close(chip_fd);
        gpiod_exit();
        return 1;
    }

    // Open lines
    for (i = 0; i < LED_MATRIX_SIZE; i++) {
