            gpiod_line_release(chip_fd, line_info.line);
            gpiod_chip_close(chip_fd);
            gpiod_exit();
            return 1;
        }
    }

    // Set column cathodes to HIGH
    for (col = 0; col < LED_MATRIX_SIZE; col++) {
        if (gpiod_line_request_output(chip_fd, line_info.line, column_status) < 0) {
            fprintf(stderr, "Failed to request output for line %d\n", line_info.line);
            gpiod_line_release(chip_fd, line_info.line);
            gpiod_chip_close(chip_fd);
            gpiod_exit();
            return 1;
