            gpiod_chip_close(chip_fd);
            gpiod_exit();
            return 1;
        }
        row_status[i] = 0;
    }

    // Animation loop
    while (1) {
        // Clear the matrix
        for (col = 0; col < LED_MATRIX_SIZE; col++) {
            if (column_status[col] == 1) {
                for (i = 0; i < LED_MATRIX_SIZE; i++) {
