                fprintf(stderr, "Failed to check line %d\n", line_info.line);
                gpiod_line_release(chip_fd, line_info.line);
                gpiod_chip_close(chip_fd);
                gpiod_exit();
                return 1;
            }
        }
    }

    // Clean up
    for (i = 0; i < LED_MATRIX_SIZE; i++) {
        gpio_output(LED_MATRIX_SIZE * ROW_PINS[i], 0);
