// Structs
struct i2c_msg {
    int32_t addr;
    int16_t data[];
    int len;
};

// Global variables
int i2c_fd;
struct i2c_msg msg;
uint8_t sensor_id[2];

// Function prototypes
void init_i2c();
void cleanup_i2c();
void read_distance(int target_index);
void log_distance(int target_index, float distance);
void log_iso8601(int timestamp);

int main() {
    int exit_code = 0;

    init_i2c();

    while (1) {
        // Read sensor ID
        if (read_distance(0) != 0) {
            fprintf(stderr, "Error reading sensor ID\n");
            exit_code = 1;
            break;
        }

        // Verify sensor ID
        if (sensor_id[0] != 0x54 || sensor_id[1] != 0x55) {
            fprintf(stderr, "Sensor model ID mismatch: 0x%02x 0x%02x\n", sensor_id[0], sensor_id[1]);
            exit_code = 1;
            break;
        }

        // Log distance and timestamp
        log_distance(0, get_distance());
        log_iso8601(get_timestamp());

        // Wait for 100 ms
        sleep(100);
    }

    cleanup_i2c();
    return exit_code;
}

