#include <sys/stat.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60

int main() {
    int i2c_fd;
    int err;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msgs[2];
    struct timespec start, stop;
    struct timespec elapsed;
    char log_file_path[128] = "biometric_log.txt";
    char log_message[128] = " ";

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = pigpio_open(I2C_BUS)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C speed to 100kHz
    if (pigpio_set_speed(I2C_BUS, 100000) < 0) {
        fprintf(stderr, "Failed to set I2C speed\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C address to Si1145 sensor
    if (pigpio_set_mode(I2C_BUS, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        gpioTerminate();
        return 1;
    }

    // Read PART ID register
    if (pigpio_read_reg(I2C_BUS, 0x00, &data.reg, 1) < 0) {
        fprintf(stderr, "Failed to read PART ID register\n");
        gpioTerminate();
        return 1;
    }

    if (data.reg != 0x45) {
        fprintf(stderr, "Sensor's PART ID register does not read 0x45\n");
        gpioTerminate();
        return 1;
    }

    // Initialize sensor by writing to command register
    if (pigpio_write_reg(I2C_BUS, 0x18, 0x01) < 0) {
        fprintf(stderr, "Failed to write to command register\n");
        gpioTerminate();
        return 1;
    }

    // Wait for sensor to clear any stale IRQ
    if (pigpio_delay_us(100) < 0) {
        fprintf(stderr, "Failed to wait for sensor to clear IRQ\n");
        gpioTerminate();
        return 1;
    }

    // Set measurement rates and clear any stale IRQ
    if (pigpio_write_reg(I2C_BUS, 0x1A, 0x0C) < 0) {
        fprintf(stderr, "Failed to write to command register\n");
        gpioTerminate();
        return 1;
    }

    // Wait for sensor to finish measurement
    if (pigpio_delay_us(1000) < 0) {
        fprintf(stderr, "Failed to wait for sensor to finish measurement\n");
        gpioTerminate();
        return 1;
    }

    // Log readings with ISO-8601 timestamps
    start_time(&start);
    while (1) {
        if (pigpio_read_reg(I2C_BUS, 0x00, &data.reg, 1) < 0) {
            fprintf(stderr, "Failed to read data register\n");
            gpioTerminate();
            return 1;
        }

        if (data.reg & 0x80) {
            // Log data
            elapsed.tv_sec = start.tv_sec;
            elapsed.tv_nsec = start.tv_nsec;
            printf("%.6f\n", (double)(elapsed.tv_sec) / 1000000000.0 + (double)(elapsed.tv_nsec) / 1000000000.0);
        }

        // Wait for 500 ms
        if (pigpio_delay_ms(500) < 0) {
            fprintf(stderr, "Failed to wait for 500 ms\n");
            gpioTerminate();
            return 1;
        }
    }

    // Log sensor measurements
    elapsed.tv_sec = start.tv_sec;
    elapsed.tv_nsec = start.tv_nsec;
    printf("%.6f\n", (double)(elapsed.tv_sec) / 1000000000.0 + (double)(elapsed.tv_nsec) / 1000000000.0);

    // Close I2C handle
    if (pigpio_close(i2c_fd) < 0) {
        fprintf(stderr, "Failed to close I2C handle\n");
        gpioTerminate();
        return 1;
    }

    // Close log file
    if (open_log_file(log_file_path) < 0) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Log error and exit
    if (log_error(log_message) < 0) {
        fprintf(stderr, "Failed to log error\n");
        gpioTerminate();
        return 1;
    }

    gpioTerminate();
    return 0;
}

int open_log_file(char *file_path) {
    FILE *log_file = fopen(file_path, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }
    return log_file;
}

int log_error(char *message) {
    char log_message[128] = " ";
    strncat(log_message, message, 128);
    if (fprintf(stderr, "%s\n", log_message) < 0) {
        fprintf(stderr, "Failed to log error\n");
        return -1;
    }
    return 0;
}

