#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/stat.h>
#include <iostream>
#include <fstream>
#include <cstring>

#define I2C_SLAVE 0x5A
#define MEAS_RATE0 0x08
#define COMMAND 0x47

int main() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_rdwr_ioctl_data_setup setup;
    struct i2c_rdwr_ioctl_data_setup_info info;
    struct i2c_msg msg[2];
    int ret;

    // Open /dev/i2c-1
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        perror("Error opening i2c-1");
        exit(EXIT_FAILURE);
    }

    // Set the 7-bit slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE) == -1) {
        perror("Error setting I2C slave address");
        exit(EXIT_FAILURE);
    }

    // Perform register reads and writes
    memset(&data, 0, sizeof(data));
    memset(&setup, 0, sizeof(setup));
    memset(&info, 0, sizeof(info));

    // Read the PART_ID register
    if (ioctl(i2c_fd, I2C_RDWR, &data) == -1) {
        if (errno == EINVAL) {
            fprintf(stderr, "Si1182 part identifier not found\n");
        } else {
            perror("Error reading PART_ID register");
            exit(EXIT_FAILURE);
        }
    }

    // Check if the PART_ID matches the expected Si1182 part identifier
    if (data.msg[0].addr != I2C_SLAVE) {
        fprintf(stderr, "Unexpected I2C slave address\n");
        exit(EXIT_FAILURE);
    }
    if (memcmp(data.msg[0].buf, "\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00", 16) != 0) {
        fprintf(stderr, "Unexpected PART_ID value\n");
        exit(EXIT_FAILURE);
    }

    // Configure continuous proximity measurement
    if (ioctl(i2c_fd, I2C_RDWR, &data) == -1) {
        perror("Error configuring continuous proximity measurement");
        exit(EXIT_FAILURE);
    }

    // Set MEAS_RATE0 register value
    if (ioctl(i2c_fd, I2C_RDWR, &data) == -1) {
        perror("Error setting MEAS_RATE0 register value");
        exit(EXIT_FAILURE);
    }
    data.msg[0].len = 2;
    data.msg[0].buf[0] = (uint8_t)(MEAS_RATE0 >> 8);
    data.msg[0].buf[1] = (uint8_t)(MEAS_RATE0 & 0xFF);
    if (ioctl(i2c_fd, I2C_RDWR, &data) == -1) {
        perror("Error setting MEAS_RATE0 register value");
        exit(EXIT_FAILURE);
    }

    // Reset/start command
    if (ioctl(i2c_fd, I2C_RDWR, &data) == -1) {
        perror("Error resetting/starting command");
        exit(EXIT_FAILURE);
    }

    // Set up the SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = SIGINT;
    sa.sa_flags = SA_RESTART | SA_SIGINFO;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting up SIGINT/SIGTERM handler");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error setting up SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    // Start the loop
    while (1) {
        // Read proximity data
        if (ioctl(i2c_fd, I2C_RDWR, &data) == -1) {
            perror("Error reading proximity data");
            continue;
        }

        // Combine little-endian proximity data
        uint16_t proximity_data = (data.msg[0].buf[0] << 8) | data.msg[0].buf[1];

        // Compute BPM from proximity signal
        int bpm = (proximity_data >> 8) * (60 / (MEAS_RATE0 & 0xFF));

        // Log the timestamp and BPM
        char timestamp[26];
        struct timeval tv;
        gettimeofday(&tv, NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
        std::cout << timestamp << "," << bpm << std::endl;

        // Flush the output and close the file descriptor
        fflush(stdout);
        if (close(i2c_fd) == -1) {
            perror("Error closing i2c-1 file descriptor");
            exit(EXIT_FAILURE);
        }

        // Close the CSV file
        if (close(1) == -1) {
            perror("Error closing heartrate.csv file");
            exit(EXIT_FAILURE);
        }

        // Exit the loop
        break;
    }

    // Clean up
    if (close(i2c_fd) == -1) {
        perror("Error closing i2c-1 file descriptor");
        exit(EXIT_FAILURE);
    }

    if (close(1) == -1) {
        perror("Error closing heartrate.csv file");
        exit(EXIT_FAILURE);
    }

    return 0;
}
