#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define TCRT5000_GPIO_BASE 17
#define TCRT5000_GPIO_PIN 17
#define TCRT5000_GPIO_FILE "/dev/pigpio"

int main() {
    int fd, gpio_fd;
    struct gpio_desc desc;
    struct timespec start_time, end_time;
    int sensor_read_success = 0;
    int sensor_read_failure = 0;
    char obstacle_log_file[128] = "obstacle_log.txt";

    gpio_fd = pigpio_open(TCRT5000_GPIO_FILE, PI_UNUSED);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO file");
        exit(EXIT_FAILURE);
    }

    if (pigpio_set_mode(gpio_fd, PI_OUTPUT) < 0) {
        perror("Failed to set mode");
        exit(EXIT_FAILURE);
    }

    if (pigpio_pin_mode(gpio_fd, TCRT5000_GPIO_PIN, PI_DIGITAL) < 0) {
        perror("Failed to set pin mode");
        exit(EXIT_FAILURE);
    }

    pigpio_gpio_write(gpio_fd, 0); // Set both sensors to low

    start_time.tv_sec = 0;
    start_time.tv_nsec = 1000000;

    while (1) {
        if (pigpio_gpio_read(gpio_fd, TCRT5000_GPIO_PIN) < 0) {
            sensor_read_failure++;
            if (sensor_read_failure > 1) {
                fprintf(stderr, "Failed to read sensor %d\n", TCRT5000_GPIO_PIN);
                continue;
            }
        }

        end_time.tv_sec = 0;
        end_time.tv_nsec = 1000000;

        if (pigpio_get_time(start_time, &start_time) < 0 ||
            pigpio_get_time(end_time, &end_time) < 0) {
            perror("Failed to get time");
            exit(EXIT_FAILURE);
        }

        int sensor_reading = (end_time.tv_sec - start_time.tv_sec) * 1000000 + end_time.tv_nsec / 1000000;

        if (sensor_reading > 100) {
            sensor_read_success++;
            if (sensor_read_success > 1) {
                fprintf(stderr, "Sensor 1 reading: %d\n", sensor_reading);
            }
            if (sensor_reading > 200) {
                fprintf(stderr, "Sensor 2 reading: %d\n", sensor_reading);
            }
        }

        sleep(100);
    }

    pigpio_gpio_write(gpio_fd, 1); // Set both sensors back to high
    pigpio_close(gpio_fd);

    return 0;
}

