#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <sys/time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x6A

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[2];
    int rc;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C bus address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C bus address\n");
        goto close_i2c_bus;
    }

    // Open sensor
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Error: Failed to open sensor\n");
        goto close_i2c_bus;
    }

    // Set sensor address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set sensor address\n");
        goto close_sensor;
    }

    // Set up I2C message structure
    msg[0].addr = I2C_ADDR;
    msg[0].flags = 0;
    msg[0].len = 2;
    msg[0].buf = (void *)&data;
    msg[1].addr = I2C_ADDR;
    msg[1].flags = 0;
    msg[1].len = 2;
    msg[1].buf = (void *)&data;

    // Set up I2C read/write operation
    data.cmd = I2C_RDWR;
    data.flags = 0;
    data.timeout_us = 100;

    // Read distance measurement
    if ((rc = i2c_rdwr(fd, msg, 2, &data)) < 0) {
        fprintf(stderr, "Error: Failed to read distance measurement\n");
        goto close_sensor;
    }

    // Log distance measurement with ISO-8601 timestamp
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[30];
    snprintf(timestamp, sizeof(timestamp), "%s.%06u", tv.tv_sec, tv.tv_usec);
    FILE *fp = fopen("distance_log.txt", "a");
    if (fp) {
        fprintf(fp, "%.6f, %s\n", data.msg[0].buf[1], timestamp);
        fclose(fp);
    }

    // Check if distance is below 20 cm
    if (data.msg[0].buf[1] < 20) {
        // Turn on LED connected to BCM GPIO 17
        gpioSetPWM(17, 50);
    } else {
        // Turn off LED connected to BCM GPIO 17
        gpioSetPWM(17, 0);
    }

    // Clean up I2C message structure
    free(data.msg);

    // Close I2C bus
    close(fd);

close_i2c_bus:
    gpioTerminate();

close_sensor:
    close(fd);

return 0;
}

