#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x29

int main() {
    int i2c_fd;
    int result;
    int distance;
    char buffer[2];
    char error_message[256];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C device
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Error: Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C bus number and address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C address\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Check for Adafruit VL53L0X sensor presence
    if (read_sensor_model_id() < 0) {
        fprintf(stderr, "Error: Failed to read sensor model ID\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Check sensor model ID
    if (read_sensor_id() != 0xEE) {
        fprintf(stderr, "Error: Sensor model ID does not match\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Perform single-shot ranging loop
    while (1) {
        // Write 0x01 to SYSRANGE_START (register 0x00) to begin a measurement
        if (write(i2c_fd, &buffer, 1) != 1) {
            fprintf(stderr, "Error: Failed to write to I2C device\n");
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Poll RESULT_INTERRUPT_STATUS (register 0x13) until bit 0 is set
        if (read(i2c_fd, &result, 1) != 1) {
            fprintf(stderr, "Error: Failed to read from I2C device\n");
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        if (result & 0x80) {
            // Read the 16-bit distance from RESULT_RANGE_STATUS (register 0x14, two bytes, little-endian)
            if (read(i2c_fd, &distance, 2) != 2) {
                fprintf(stderr, "Error: Failed to read from I2C device\n");
                close(i2c_fd);
                gpioTerminate();
                return 1;
            }

            // Clear the interrupt by writing 0x01 to SYSTEM_INTERRUPT_CLEAR (register 0x0B)
            if (write(i2c_fd, &distance, 2) != 2) {
                fprintf(stderr, "Error: Failed to write to I2C device\n");
                close(i2c_fd);
                gpioTerminate();
                return 1;
            }

            // Print the distance reading to stdout every 500 ms
            printf("%.2f-%.2f Distance: %d mm\n", (float)distance / 10.0, (float)distance / 100.0, distance);

            // Wait for 100 ms before the next measurement
            sleep(100);
        }

        // Wait for user input to exit the loop
        if (read(STDIN_FILENO, &error_message[0], sizeof(error_message)) != sizeof(error_message)) {
            fprintf(stderr, "Error: Failed to read user input\n");
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Print warning to stderr and continue to the next iteration
        fprintf(stderr, "Warning: I2C read/write error: %s\n", error_message);
    }

    // Clean up
    gpioTerminate();
    close(i2c_fd);

    return 0;
}

