#include <fcntl.h>
#include <string.h>
#include <stdlib.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define SENSOR_ADDRESS 0x39
#define CONFIG_REG_ADDRESS 0x18
#define IRQ_STATUS_REG_ADDRESS 0x25

int main() {
    int i2c_fd;
    int gpio_fd;
    int result;
    int sensorAbsent = 1;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = pigpioOpenI2C(I2C_BUS_NUM)) < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open GPIO
    if ((gpio_fd = pigpioOpen(i2c_fd)) < 0) {
        fprintf(stderr, "Error: Failed to open GPIO\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C speed to 100kHz
    if (pigpioSetSpeed(i2c_fd, 100000) < 0) {
        fprintf(stderr, "Error: Failed to set I2C speed\n");
        gpioTerminate();
        return 1;
    }

    // Write 0x01 to the CONFIG register to enable proximity mode
    if (pigpioSetReg(gpio_fd, CONFIG_REG_ADDRESS, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write to CONFIG register\n");
        gpioTerminate();
        return 1;
    }

    // Wait for sensor to become absent
    while (sensorAbsent) {
        if (pigpioWaitForIrq(gpio_fd, IRQ_STATUS_REG_ADDRESS, 1, NULL) < 0) {
            fprintf(stderr, "Error: Failed to wait for IRQ status\n");
            gpioTerminate();
            return 1;
        }
    }

    // Read 16-bit proximity result from registers 0x2A and 0x2B
    uint16_t proximityResult = pigpioGet16(gpio_fd, IRQ_STATUS_REG_ADDRESS + 1);
    uint16_t proximityResultLSB = pigpioGet16(gpio_fd, IRQ_STATUS_REG_ADDRESS);
    uint16_t proximityResultMSB = pigpioGet16(gpio_fd, IRQ_STATUS_REG_ADDRESS + 1);

    // Print proximity result every 500 ms
    while (1) {
        printf("Proximity Result: LSB=%04x MSB=%04x\n", proximityResultLSB, proximityResultMSB);
        sleep(500);
    }

    // Cleanup
    gpioTerminate();
    pigpioClose(gpio_fd);
    pigpioClose(i2c_fd);

    return 0;
}

// SIGINT handler
void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    gpioTerminate();
    pigpioClose(gpio_fd);
    pigpioClose(i2c_fd);
}

// Terminate the pigpio library and close I2C handle
void gpioTerminate() {
    if (pigpioIsInitialized()) {
        pigpioTerminate();
    }
    if (gpio_fd >= 0) {
        pigpioClose(gpio_fd);
    }
    if (i2c_fd >= 0) {
        pigpioClose(i2c_fd);
    }
}

