#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/delay.h>
#include <linux/time.h>

#define I2C_SLAVE 0x4C
#define I2C_TIMEOUT_MS 100
#define I2C_READ_TIMEOUT_MS 100

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[2];
    int ret;

    // Open /dev/i2c-1 with error checking
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        exit(EXIT_FAILURE);
    }

    // Set the slave address via ioctl I2C_SLAVE
    if (ioctl(fd, I2C_SLAVE, I2C_SLAVE) < 0) {
        perror("Error setting I2C slave address");
        exit(EXIT_FAILURE);
    }

    // Verify the device responds
    if (ioctl(fd, I2C_RDWR, I2C_RDWR) < 0) {
        perror("Error reading from I2C device");
        exit(EXIT_FAILURE);
    }

    // Read the 16-bit distance register at offset 0x00, little-endian
    msg[0].addr = I2C_SLAVE;
    msg[0].flags = 0;
    msg[0].buf = &data.msg[0];
    msg[0].len = 2;
    msg[0].timeout = I2C_READ_TIMEOUT_MS;
    msg[0].flags |= I2C_M_RD;
    msg[1].addr = I2C_SLAVE;
    msg[1].flags = 0;
    msg[1].buf = &data.msg[2];
    msg[1].len = 2;
    msg[1].timeout = I2C_READ_TIMEOUT_MS;
    msg[1].flags |= I2C_M_RD;

    ret = ioctl(fd, I2C_RDWR, &data);
    if (ret < 0) {
        perror("Error reading distance register");
        exit(EXIT_FAILURE);
    }

    // Convert the raw value to millimetres using the factor 0.125 mm per count
    int distance = (data.msg[0] << 8) | data.msg[1];
    distance = distance * 0.125;

    // Print the distance as 'Distance: <value> mm'
    printf("Distance: %d mm\n", distance);

    // Loop reading every 500 ms using nanosleep
    while (1) {
        nanosleep(&data.msg[0], &data.msg[1]);
    }

    // Close the I2C file descriptor
    close(fd);

    return 0;
}

