#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <termios.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define LED_GPIO 17
#define LED_ON   gpioSetOutput(LED_GPIO)
#define LED_OFF  gpioClearOutput(LED_GPIO)

int main() {
    int fd;
    struct termios options;
    struct sigaction action;
    char buffer[1024];
    char *log_file = "intrusion_log.csv";
    char *log_line = NULL;
    int distanceThreshold = 1.0;
    int intruderCount = 0;
    int intruderTime = 0;
    int lastDistance = 0;
    int lastTime = 0;
    int intruder = 0;

    // Initialize GPIO and pigpio
    if (gpioInitialise() < 0) {
        printf("Error: Failed to initialize GPIO.\n");
        return 1;
    }

    if (piSetup() < 0) {
        printf("Error: Failed to initialize pigpio.\n");
        return 1;
    }

    // Open UART
    fd = open("/dev/serial0", O_RDWR | O_NOCTTY);
    if (fd < 0) {
        printf("Error: Failed to open UART.\n");
        return 1;
    }

    // Set UART parameters
    options.c_cflag = B115200 | CS8 | CLOCAL | CREAD;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;

    tcgetattr(fd, &options);
    cfsetattr(fd, TCSANOW, &options);

    // Set LED
    gpioSetOutput(LED_GPIO);
    LED_ON;

    // Initialize pigpio for I/O operations
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        printf("Error: Failed to set LED as output.\n");
        return 1;
    }

    // Initialize IWR1443 sensor
    if (i2cInit() < 0) {
        printf("Error: Failed to initialize IWR1443 sensor.\n");
        return 1;
    }

    if (i2cWriteReg16(IWR1443_I2C_ADDR, IWR1443_REG_MODE, 0x0003) < 0) {
        printf("Error: Failed to set IWR1443 mode.\n");
        return 1;
    }

    if (i2cWriteReg16(IWR1443_I2C_ADDR, IWR1443_REG_RANGE_RES, 0x0C00) < 0) {
        printf("Error: Failed to set IWR1443 range resolution.\n");
        return 1;
    }

    if (i2cWriteReg16(IWR1443_I2C_ADDR, IWR1443_REG_RANGE_BIN_COUNT, 0x3C00) < 0) {
        printf("Error: Failed to set IWR1443 range bin count.\n");
        return 1;
    }

    // Initialize log file
    FILE *log_file_fp = fopen(log_file, "w");
    if (log_file_fp == NULL) {
        printf("Error: Failed to open log file.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read UART data
        if (read(fd, buffer, sizeof(buffer)) < 0) {
            printf("Error: Failed to read UART data.\n");
            return 1;
        }

        // Parse data
        if (parseData(buffer) == 1) {
            // Log intrusion
            intruderTime = time(NULL);
            distance = getDistance();
            if (distance > lastDistance) {
                if (distanceThreshold == 1.0) {
                    logIntrusion(log_file_fp, intruderTime, distance);
                }
                intruderCount++;
                intruderTime = time(NULL);
            }
            lastDistance = distance;
        }

        // Check for LED state
        if (getLEDState() == 1) {
            LED_OFF;
        }

        // Check for I/O errors
        if (getIOOperationError() != 0) {
            printf("Error: UART or I/O operation error.\n");
            return 1;
        }

        // Check for sensor absence or bus error
        if (getSensorAbsent() || getBusError() != 0) {
            printf("Error: Sensor absence or bus error.\n");
            return 1;
        }

        // Check for intruder detection
        if (intruder) {
            // Log intrusion
            logIntrusion(log_file_fp, intruderTime, distance);
            intruderCount++;
            intruderTime = time(NULL);
        }

        // Wait for 2 seconds
        sleep(2);
    }

    // Cleanup
    fclose(log_file_fp);
    gpioRelease();
    piCleanup();

    return 0;
}

