#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define BUZZER_GPIO 18
#define BUZZER_ACTIVE_HIGH 1
#define BUZZER_ACTIVE_LOW 0

int main() {
    int chip_fd, line_fd, err;
    struct gpiod_line_config line_config;
    struct gpiod_event event;
    char line_name[] = "/dev/gpiochip0";
    char buf[32];

    // Initialize libgpiod
    if ((err = gpiod_init()) != 0) {
        fprintf(stderr, "Error initializing libgpiod: %s\n", gpiod_strerror(err));
        return 1;
    }

    // Open the chip
    if ((chip_fd = gpiod_chip_open(line_name)) < 0) {
        fprintf(stderr, "Error opening chip: %s\n", line_name);
        gpiod_exit();
        return 1;
    }

    // Open the line
    if ((line_fd = gpiod_line_open(chip_fd, line_name)) < 0) {
        fprintf(stderr, "Error opening line: %s\n", line_name);
        gpiod_line_close(line_fd);
        gpiod_chip_close(chip_fd);
        gpiod_exit();
        return 1;
    }

    // Configure the line
    line_config.type = GPID_LINE_TYPE_GPIO;
    line_config.direction = GPID_LINE_DIRECTION_OUTPUT;
    line_config.active_low = 1;
    if ((err = gpiod_line_config_set(line_fd, &line_config)) < 0) {
        fprintf(stderr, "Error configuring line: %s\n", line_name);
        gpiod_line_close(line_fd);
        gpiod_chip_close(chip_fd);
        gpiod_exit();
        return 1;
    }

    // Set the line to active-low
    if ((err = gpiod_line_set_active_low(line_fd, 1)) < 0) {
        fprintf(stderr, "Error setting line active-low: %s\n", line_name);
        gpiod_line_close(line_fd);
        gpiod_chip_close(chip_fd);
        gpiod_exit();
        return 1;
    }

    // Poll the sensor
    while (1) {
        memset(buf, 0, sizeof(buf));
        if ((err = gpiod_event_poll(line_fd, 1, buf, sizeof(buf), NULL)) < 0) {
            fprintf(stderr, "Error polling line: %s\n", line_name);
            gpiod_line_close(line_fd);
            gpiod_chip_close(chip_fd);
            gpiod_exit();
            return 1;
        }

        if (buf[0] == 1) {
            printf("Obstacle detected, activating buzzer\n");
            if (write(BUZZER_GPIO, BUZZER_ACTIVE_HIGH, sizeof(BUZZER_ACTIVE_HIGH)) < 0) {
                fprintf(stderr, "Error activating buzzer: %s\n", line_name);
                gpiod_line_close(line_fd);
                gpiod_chip_close(chip_fd);
                gpiod_exit();
                return 1;
            }
        } else {
            printf("Obstacle removed, deactivating buzzer\n");
            if (write(BUZZER_GPIO, BUZZER_ACTIVE_LOW, sizeof(BUZZER_ACTIVE_LOW)) < 0) {
                fprintf(stderr, "Error deactivating buzzer: %s\n", line_name);
                gpiod_line_close(line_fd);
                gpiod_chip_close(chip_fd);
                gpiod_exit();
                return 1;
            }
        }

        // Log state transition
        struct timeval now;
        gettimeofday(&now, NULL);
        char timestamp[41];
        snprintf(timestamp, sizeof(timestamp), "%.6f", now.tv_sec);
        printf("[%s] %s\n", timestamp, buf ? "1" : "0");

        // Wait for 100 ms
        sleep(100);
    }

    // Clean up
    gpiod_line_close(line_fd);
    gpiod_chip_close(chip_fd);
    gpiod_exit();

    return 0;
}

