#include <fcntl.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x29

#define TIMEOUT_MS 100
#define THRESHOLD_STOP 300
#define THRESHOLD_APPROACH 300
#define THRESHOLD_SLOW 600
#define THRESHOLD_CLEAR 1200

void log_distance(const char* filename, int16_t distance, uint16_t timestamp) {
    FILE* file = fopen(filename, "a");
    if (file) {
        fprintf(file, "%d,%d\n", timestamp, distance);
        fclose(file);
    } else {
        fprintf(stderr, "Error: Unable to open log file %s\n", filename);
    }
}

int main() {
    int ret;
    int i;
    int16_t distance;
    uint16_t timestamp;
    char log_filename[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Unable to initialize pigpio\n");
        return 1;
    }

    // Check if the sensor is present
    if (gpioReadReg16(I2C_ADDR, 0x010F) != 0xEA) {
        fprintf(stderr, "Error: Sensor not found at address 0x29\n");
        gpioTerminate();
        return 1;
    }

    // Perform a software reset
    gpioWrite(I2C_ADDR, 0x00, 1);
    gpioDelay(2);
    gpioWrite(I2C_ADDR, 0x00, 0);

    // Set up the I2C handle
    int i2c_fd = i2cOpen(I2C_BUS_NUM);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Unable to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    snprintf(log_filename, sizeof(log_filename), "distance_log.csv");
    int log_fd = open(log_filename, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error: Unable to open log file %s\n", log_filename);
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Perform continuous ranging
    for (timestamp = 0; ; timestamp += 100) {
        distance = gpioReadReg16(I2C_ADDR, 0x078);
        if (distance == 0) {
            break;
        }

        log_distance(log_filename, distance, timestamp);

        // Check if the distance is within the thresholds
        if (distance < THRESHOLD_STOP) {
            printf("STOP\n");
        } else if (distance < THRESHOLD_APPROACH) {
            printf("APPROACH\n");
        } else if (distance < THRESHOLD_SLOW) {
            printf("SLOW\n");
        } else {
            printf("CLEAR\n");
        }

        // Wait for the next reading
        gpioDelay(TIMEOUT_MS);
    }

    // Clean up
    gpioClose(i2c_fd);
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

