#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/time.h>

#define TCRT5000_GPIO_BASE_ADDRESS 0x20200000
#define TCRT5000_GPIO_PIN_1 17
#define TCRT5000_GPIO_PIN_2 27

#define DEBOUNCE_TIMEOUT 50

int main() {
    int fd, ret;
    struct gpio_desc *desc;
    struct gpio_event event;
    struct timespec start_time, end_time;
    char filename[32];
    char *sensor_id;
    char *event_type;

    // Initialize the pigpio library
    if ((ret = gpioInitialise()) != 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", gpioErrorStr(ret));
        return 1;
    }

    // Set the GPIO pins as input
    if ((ret = gpioSetMode(TCRT5000_GPIO_BASE_ADDRESS, TCRT5000_GPIO_PIN_1, GPIO_MODE_INPUT)) != 0) {
        fprintf(stderr, "Error setting mode for GPIO pin 1: %s\n", gpioErrorStr(ret));
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioSetMode(TCRT5000_GPIO_BASE_ADDRESS, TCRT5000_GPIO_PIN_2, GPIO_MODE_INPUT)) != 0) {
        fprintf(stderr, "Error setting mode for GPIO pin 2: %s\n", gpioErrorStr(ret));
        gpioTerminate();
        return 1;
    }

    // Open the log file
    snprintf(filename, sizeof(filename), "proximity_log.txt");
    fd = open(filename, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (fd == -1) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Log every state transition
    sensor_id = "1";
    event_type = "DETECTED";
    start_time.tv_sec = 0;
    start_time.tv_nsec = 0;
    while (1) {
        // Poll both sensors
        if ((ret = gpioRead(TCRT5000_GPIO_BASE_ADDRESS, TCRT5000_GPIO_PIN_1, &event)) != 0) {
            fprintf(stderr, "Error reading sensor 1: %s\n", gpioErrorStr(ret));
