        exit(EXIT_FAILURE);
    }

    // Initialize the i2c-gpio driver
    if (ioctl(fd, I2C_SLAVE, I2C_GPIO_RPI_GPIO_BASE + I2C_GPIO_P0_0) < 0) {
        perror("Error initializing i2c-gpio driver");
        exit(EXIT_FAILURE);
    }

    // Set the sensor to 8x8 zone grid
    if (ioctl(fd, VL53L5CX_SET_GRID_SIZE, ZONE_SIZE) < 0) {
        perror("Error setting zone grid size");
        exit(EXIT_FAILURE);
    }

    // Set the sensor to read distances
    if (ioctl(fd, VL53L5CX_SET_DISTANCE_READ_MODE, 1) < 0) {
        perror("Error setting distance read mode");
        exit(EXIT_FAILURE);
    }

    // Set the sensor to continuous mode
    if (ioctl(fd, VL53L5CX_SET_MODE, VL53L5CX_MODE_CONTINUOUS) < 0) {
        perror("Error setting mode");
        exit(EXIT_FAILURE);
    }

    // Set the sensor to trigger mode
    if (ioctl(fd, VL53L5CX_SET_MODE, VL53L5CX_MODE_TRIGGER) < 0) {
        perror("Error setting mode");
        exit(EXIT_FAILURE);
    }

    // Set the sensor to trigger the measurement
    if (ioctl(fd, VL53L5CX_START_MEASUREMENT, 0) < 0) {
        perror("Error starting measurement");
        exit(EXIT_FAILURE);
    }

    // Wait for the sensor to finish measuring
    while (ioctl(fd, VL53L5CX_GET_MEASUREMENT_STATUS, 0) == 0) {
        usleep(500000);
    }

    // Stop the measurement
    if (ioctl(fd, VL53L5CX_STOP_MEASUREMENT, 0) < 0) {
        perror("Error stopping measurement");
        exit(EXIT_FAILURE);
    }

    // Close the i2c device
    if (close(fd) < 0) {
        perror("Error closing I2C device");
        exit(EXIT_FAILURE);
    }

