#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <stdlib.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDRESS 0x29

int main() {
    int fd;
    int result;
    int buzzer_gpio = 22;

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    // Set the active buzzer GPIO
    gpioSetMode(buzzer_gpio, PI_OUTPUT);

    // Set the I2C bus number and address
    if (gpioI2cSetup(I2C_BUS_NUM, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error: Failed to set up I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set the continuous ranging mode
    if (gpioSetMode(I2C_BUS_NUM, I2C_SLAVE__DEVICE_ADDRESS, PI_MODE_CONTINUOUS_RANGING) < 0) {
        fprintf(stderr, "Error: Failed to set continuous ranging mode\n");
        gpioTerminate();
        return 1;
    }

    // Set the sensor registers
    if (gpioSetReg(I2C_BUS_NUM, 0x0001, 0x0001) < 0) {
        fprintf(stderr, "Error: Failed to set SOFT_RESET register\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetReg(I2C_BUS_NUM, 0x0001, 0x0007) < 0) {
        fprintf(stderr, "Error: Failed to set I2C_SLAVE__DEVICE_ADDRESS register\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetReg(I2C_BUS_NUM, 0x0007, 0x0007) < 0) {
        fprintf(stderr, "Error: Failed to set SYSTEM__MODE_START register\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetReg(I2C_BUS_NUM, 0x0096, 0x0096) < 0) {
        fprintf(stderr, "Error: Failed to set RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM register\n");
        gpioTerminate();
        return 1;
    }

    // Trigger distance readings every 500 ms
    while (1) {
        // Check for I2C errors
        if ((result = gpioI2cTransfer(I2C_BUS_NUM, 0x00, (char*)&result, 1)) < 0) {
            fprintf(stderr, "Error: Failed to read I2C error\n");
            continue;
        }

        // Check if the measured distance is below 100 mm
        if (result < 100) {
            // Switch on the buzzer
            gpioSetPwm(buzzer_gpio, 0, 0, 0);
            printf("Buzzer activated for distance below 100 mm\n");
        } else {
            // Switch off the buzzer
            gpioSetPwm(buzzer_gpio, 0, 0, 0);
            printf("Buzzer deactivated for distance above 100 mm\n");
        }

        // Wait for 500 ms
        sleep(0.5);
    }

    // Clean up resources
    gpioTerminate();

    return 0;
}

