#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <linux/gpio.h>
#include <linux/delay.h>
#include <linux/time.h>

#include <pigpio.h>

#define TRIG_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

#define TRIG_TIMEOUT 1000000 // 1 second in microseconds
#define ECHO_THRESHOLD 30 // cm

int main() {
    int err, gpioHandle, i2cHandle;
    struct i2c_msg i2cMsg[2];
    struct i2c_rdwr_ioctl_data i2cData;
    uint8_t data[4];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set trigger pin as output\n");
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set echo pin as input\n");
        return 1;
    }

    if (gpioSetAlertFuncEx(TRIG_PIN, TRIG_HIGH, TRIG_LOW, gpioAlertCallback, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set interrupt function for trigger\n");
        return 1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, ECHO_HIGH, ECHO_LOW, gpioAlertCallback, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set interrupt function for echo\n");
        return 1;
    }

    // Open I2C bus
    if ((i2cHandle = i2cOpen(1)) < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        return 1;
    }

    // Set I2C address for the sensor
    if (i2cSetAddress(i2cHandle, 0x1A) < 0) {
        fprintf(stderr, "Error: Failed to set I2C address for sensor\n");
        return 1;
    }

    // Open the sensor
    if ((err = i2c_master_write_byte(i2cHandle, 0x00, &data[0])) < 0) {
        fprintf(stderr, "Error: Failed to write to sensor\n");
        return 1;
    }

    if (data[0] != 0x55) {
        fprintf(stderr, "Error: Invalid sensor response\n");
        return 1;
    }

    // Set up the sensor for ultrasonic measurement
    if (i2c_master_write_byte(i2cHandle, 0x00, &data[0]) < 0) {
        fprintf(stderr, "Error: Failed to write to sensor\n");
        return 1;
    }

    if (data[0] != 0xAA) {
        fprintf(stderr, "Error: Invalid sensor response\n");
        return 1;
    }

    // Set up the trigger pulse
    if (gpioSetPWMFrequency(TRIG_PIN, 100000) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency for trigger\n");
        return 1;
    }

    if (gpioSetPWMChannel(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to set PWM channel for trigger\n");
        return 1;
    }

    if (gpioSetPWMValue(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to set PWM value for trigger\n");
        return 1;
    }

    // Set up the echo pulse
    if (gpioSetPWMFrequency(ECHO_PIN, 100000) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency for echo\n");
        return 1;
    }

    if (gpioSetPWMChannel(ECHO_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to set PWM channel for echo\n");
        return 1;
    }

    if (gpioSetPWMValue(ECHO_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to set PWM value for echo\n");
        return 1;
    }

    // Set up the buzzer
    if (gpioSetPWMFrequency(BUZZER_PIN, 100000) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency for buzzer\n");
        return 1;
    }

    if (gpioSetPWMChannel(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to set PWM channel for buzzer\n");
        return 1;
    }

    if (gpioSetPWMValue(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to set PWM value for buzzer\n");
        return 1;
    }

    // Set up the interrupt handler
    gpioSetAlertFuncEx(TRIG_PIN, TRIG_HIGH, TRIG_LOW, gpioAlertCallback, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, ECHO_HIGH, ECHO_LOW, gpioAlertCallback, NULL);

    while (1) {
        // Trigger the sensor
        gpioSetPWMValue(TRIG_PIN, TRIG_HIGH);
        gpioDelay(TRIG_TIMEOUT / 1000);
        gpioSetPWMValue(TRIG_PIN, TRIG_LOW);

        // Wait for the echo pulse
        while (gpioGetPWMValue(ECHO_PIN) == 0) {
            // No echo detected
            if (gpioGetAlertStatus() & PI_ALERT_TRIGGER) {
                fprintf(stderr, "Error: Trigger interrupt detected\n");
                return 1;
            }
        }

        // Measure the echo pulse width
        gpioSetPWMValue(ECHO_PIN, ECHO_HIGH);
        gpioDelay(TRIG_TIMEOUT / 1000);
        gpioSetPWMValue(ECHO_PIN, ECHO_LOW);

        // Compute the distance in centimeters
        int pulseWidth = gpioGetPWMValue(ECHO_PIN);
        int distance = (pulseWidth / 2) * 34300 / 2;

        // Check if the distance is within valid range
        if (distance < 2 || distance > 400) {
            fprintf(stderr, "Error: Invalid distance reading\n");
            return 1;
        }

        // Display the distance on the console every 100 ms
        printf("Distance: %.2f cm\n", distance);

        // Check if the distance is less than 30 cm
        if (distance < ECHO_THRESHOLD) {
            // Turn on the buzzer
            gpioSetPWMValue(BUZZER_PIN, BUZZER_HIGH);
            usleep(100 * 1000);
        }

        // Check if the distance is greater than 30 cm
        if (distance > ECHO_THRESHOLD) {
            // Turn off the buzzer
            gpioSetPWMValue(BUZZER_PIN, BUZZER_LOW);
            usleep(100 * 1000);
        }
    }

    // Clean up
    gpioTerminate();

    return 0;
}

