        gpioSetPWMValue(TRIG_PIN, TRIG_LOW);

        // Wait for the echo pulse
        while (gpioGetPWMValue(ECHO_PIN) == 0) {
            // No echo detected
            if (gpioGetAlertStatus() & PI_ALERT_TRIGGER) {
                fprintf(stderr, "Error: Trigger interrupt detected\n");
                return 1;
            }
        }

        // Measure the echo pulse width
        gpioSetPWMValue(ECHO_PIN, ECHO_HIGH);
        gpioDelay(TRIG_TIMEOUT / 1000);
        gpioSetPWMValue(ECHO_PIN, ECHO_LOW);

        // Compute the distance in centimeters
        int pulseWidth = gpioGetPWMValue(ECHO_PIN);
        int distance = (pulseWidth / 2) * 34300 / 2;

        // Check if the distance is within valid range
        if (distance < 2 || distance > 400) {
            fprintf(stderr, "Error: Invalid distance reading\n");
            return 1;
        }

        // Display the distance on the console every 100 ms
        printf("Distance: %.2f cm\n", distance);

        // Check if the distance is less than 30 cm
        if (distance < ECHO_THRESHOLD) {
            // Turn on the buzzer
            gpioSetPWMValue(BUZZER_PIN, BUZZER_HIGH);
            usleep(100 * 1000);
        }

        // Check if the distance is greater than 30 cm
        if (distance > ECHO_THRESHOLD) {
            // Turn off the buzzer
            gpioSetPWMValue(BUZZER_PIN, BUZZER_LOW);
            usleep(100 * 1000);
        }
    }

    // Clean up
    gpioTerminate();

    return 0;
}
