#include <fcntl.h>
#include <string.h>
#include <stdlib.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x29

int main() {
    int fd;
    int ret;
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    uint16_t distance;
    int motor_direction = 0;
    int motor_stop = 0;
    int motor_running = 0;
    int motor_gpio_num = 17;
    int motor_gpio_direction = 1;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    if ((i2c_fd = ioctl(fd, I2C_SLAVE, I2C_ADDR)) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        goto close_i2c_bus;
    }

    // Perform soft reset
    if ((ret = pigpio_ioctl(i2c_fd, PI_I2C_WRITE, 0)) < 0) {
        fprintf(stderr, "Failed to perform soft reset\n");
        goto close_i2c_device;
    }

    // Wait for 1 ms
    if ((ret = usec_delay(1000)) < 0) {
        fprintf(stderr, "Failed to wait for 1 ms\n");
        goto close_i2c_device;
    }

    // Start measurement
    if ((ret = pigpio_ioctl(i2c_fd, PI_I2C_WRITE, 0x01)) < 0) {
        fprintf(stderr, "Failed to start measurement\n");
        goto close_i2c_device;
    }

    // Wait for data ready
    while (1) {
        if ((ret = pigpio_ioctl(i2c_fd, PI_I2C_READ, &i2c_data, sizeof(i2c_data))) < 0) {
            fprintf(stderr, "Failed to read data ready\n");
            goto close_i2c_device;
        }

        if (i2c_data.wr_len == 0) {
            break;
        }

        // Read distance from registers 0x0096-0x0097
        if ((ret = pigpio_ioctl(i2c_fd, PI_I2C_READ, &distance, sizeof(distance))) < 0) {
            fprintf(stderr, "Failed to read distance\n");
            goto close_i2c_device;
        }

        // Check motor direction
        if (distance < 100) {
            motor_direction = 1;
        } else if (distance > 300) {
            motor_direction = -1;
        }

        // Check motor state
        if (distance < 10) {
            motor_running = 1;
        } else if (distance > 30) {
            motor_running = 0;
        } else {
            motor_running = 0;
        }

        // Stop the motor
        gpioSetPwm(motor_gpio_num, 0, 0);
        gpioDelay(motor_gpio_direction);
        gpioSetPwm(motor_gpio_num, 0, motor_stop);

        // Log distance and motor state
        printf("Distance: %d\n", distance);
        printf("Motor state: %d\n", motor_state);

        // Release resources
        gpioTerminate();
        close(i2c_fd);
        close(fd);
        return 0;
    }

close_i2c_device:
    ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    gpioTerminate();
    close(i2c_fd);
    close(fd);
    return 1;
}

