#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_DEVICE_ADDR 0x29
#define GPIO_TRIGGER 27

int main() {
    int fd;
    int ret;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[2];
    char buffer[2];
    char *log_message;
    int log_level;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    // Open the I2C bus
    if ((fd = i2cOpen(I2C_BUS_NUM)) < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Open the I2C device
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as an output and set it high
    if (gpioSetMode(GPIO_TRIGGER, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO27 as output");
        goto error_open_i2c;
    }
    if (gpioSetValue(GPIO_TRIGGER, 1) < 0) {
        perror("Failed to set GPIO27 high");
        goto error_set_gpio_value;
    }

    // Configure the sensor
    if (gpioWrite(GPIO_TRIGGER, 0) < 0) {
        perror("Failed to set XSHUT low");
        goto error_set_gpio_value;
    }
    if (gpioWrite(GPIO_TRIGGER, 1) < 0) {
        perror("Failed to set XSHUT high");
        goto error_set_gpio_value;
    }

    // Write continuous mode to the sensor
    if (gpioWrite(GPIO_TRIGGER, 0) < 0) {
        perror("Failed to set continuous mode");
        goto error_set_gpio_value;
    }

    // Write 0x00 to register 0x0018, 0x00 to register 0x0019, and 0x01 to register 0x0020
    if (gpioWrite(GPIO_TRIGGER, 0) < 0) {
        perror("Failed to write to sensor");
        goto error_set_gpio_value;
    }

    // Wait 100 ms
    usleep(100000);

    // Read the 2-byte little-endian distance from register 0x0014
    if (gpioRead(GPIO_TRIGGER, &data.buf[0], 1) < 0) {
        perror("Failed to read distance");
        goto error_set_gpio_value;
    }
    if (data.buf[1] == 0) {
        log_level = LOG_ERR;
    } else {
        log_level = LOG_INFO;
    }

    // Read the 1-byte status from register 0x0016
    if (gpioRead(GPIO_TRIGGER, &data.buf[0], 1) < 0) {
        perror("Failed to read status");
        goto error_set_gpio_value;
    }
    log_message = "Success";
    if (data.buf[0] == 0) {
        log_message = "Failed";
    }

    // Log the results
    syslog(log_level, "%s: Distance: %f mm, Status: %c", log_message, data.buf[1] / 10.0, data.buf[0]);

    // Close the I2C device
    if (close(fd) < 0) {
        perror("Failed to close I2C device");
        goto error_close_i2c;
    }

    // Terminate pigpio
    if (gpioTerminate() < 0) {
        perror("Failed to terminate pigpio");
        goto error_close_i2c;
    }

    return 0;

error_close_i2c:
    i2cClose(fd);
error_set_gpio_value:
    gpioSetValue(GPIO_TRIGGER, 0);
error_open_i2c:
    i2cClose(fd);
    gpioTerminate();
    return 1;
}

