#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/input.h>
#include <linux/uaccess.h>
#include <poll.h>
#include <sys/time.h>
#include <sys/stat.h>
#include <errno.h>

#include <pigpio.h>

#define SERVO_PULSE_WIDTH_MIN 500
#define SERVO_PULSE_WIDTH_MAX 2500

volatile sig_atomic_t stop_servo = 0;

void handle_pulse_width(int fd, uint32_t *data, uint16_t *width) {
    if (*width > SERVO_PULSE_WIDTH_MAX || *width < SERVO_PULSE_WIDTH_MIN) {
        *width = SERVO_PULSE_WIDTH_MIN;
    }
    gpio_set_servo_pulsewidth(18, *width);
}

void handle_timeout(int fd, uint32_t *data, uint16_t *width) {
    if (*width > SERVO_PULSE_WIDTH_MAX || *width < SERVO_PULSE_WIDTH_MIN) {
        *width = SERVO_PULSE_WIDTH_MIN;
    }
    gpio_set_servo_pulsewidth(18, *width);
}

void handle_error(int fd, uint32_t *data, uint16_t *width) {
    fprintf(stderr, "Error reading pulse width: %s\n", strerror(errno));
    *width = -1.0;
}

void log_distance(uint32_t distance, uint16_t pulse_width) {
    FILE *file = fopen("distance_log.csv", "a");
    if (file) {
        fprintf(file, "%u, %u.0\n", distance, pulse_width);
        fclose(file);
    } else {
        fprintf(stderr, "Failed to open distance log file\n");
    }
}

void map_distance_to_angle(uint32_t distance, uint16_t pulse_width) {
    uint16_t angle = (pulse_width - SERVO_PULSE_WIDTH_MIN) * 180 / (SERVO_PULSE_WIDTH_MAX - SERVO_PULSE_WIDTH_MIN);
    angle = (angle + 90) % 360;
    return angle;
}

void map_angle_to_pulse_width(uint16_t angle, uint16_t *width) {
    *width = (angle - 90) * (SERVO_PULSE_WIDTH_MAX - SERVO_PULSE_WIDTH_MIN) / 180 + SERVO_PULSE_WIDTH_MIN;
}

int main(int argc, char *argv[]) {
    int fd;
    uint16_t distance, pulse_width;
    uint16_t angle;
    uint32_t data;
    struct pollfd fds[1];
    struct timespec timeout;
    bool pulse_width_available;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    fd = open(argv[1], O_RDONLY | O_NONBLOCK);
    if (fd < 0) {
        handle_error(fd, &data, &pulse_width);
        return 1;
    }

    if (ioctl(fd, PI_GET_LINEAR_TRIGGER_THRESHOLD, &data) < 0) {
        handle_error(fd, &data, &pulse_width);
        return 1;
    }

    if (ioctl(fd, PI_GET_LINEAR_ECHO_THRESHOLD, &data) < 0) {
        handle_error(fd, &data, &pulse_width);
        return 1;
    }

    if (ioctl(fd, PI_GET_SERVO_PULSEWIDTH, &data) < 0) {
        handle_error(fd, &data, &pulse_width);
        return 1;
    }

    fds[0].fd = fd;
    fds[0].events = POLLIN;

