    gpio_request_from_sysfs(GPIO_INPUT_DIGITAL, GPIO_INPUT_MODE_PP, &gpio_15_input, 1);
}

void read_distance()
{
    uint16_t distance;
    int error;

    do {
        error = pigpio_read_i2c_reg16(I2C_BUS_NUM, I2C_ADDRESS, 0x00, &distance);
        if (error != 0) {
            handle_i2c_error(error);
        }
    } while (distance < RANGE_THRESHOLD);
}

void set_warning_led()
{
    gpio_set_value(LED_GPIO, GPIO_HIGH);
}

void set_gpio_17_high()
{
    gpio_set_value(LED_GPIO, GPIO_HIGH);
}

void set_gpio_17_low()
{
    gpio_set_value(LED_GPIO, GPIO_LOW);
}

void handle_i2c_error(int error)
{
    printf("Error reading/writing I2C: %d\n", error);
    handle_sigint();
}

void handle_sigint()
{
    gpio_set_value(LED_GPIO, GPIO_LOW);
    gpio_close();
    exit(0);
}

