#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>

#define PWM_FREQ_MIN 200
#define PWM_FREQ_MAX 2000
#define PWM_FREQ_STEP 50

int main() {
    int fd, gpioHandle, pwmHandle;
    struct gpio *gpio;
    struct pwm *pwm;
    struct timespec timeout;
    int distance, frequency;
    int previous_frequency;

    // Initialize pigpio
    if (gpio_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    if (gpio_set_mode(23, PI_OUT) < 0 ||
        gpio_set_mode(18, PI_OUT) < 0 ||
        gpio_set_mode(24, PI_OUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes\n");
        gpio_exit();
        return 1;
    }

    // Open PWM channel
    if ((fd = open("/dev/pigpio_pwm", O_RDWR)) < 0) {
        fprintf(stderr, "Error: Failed to open PWM channel\n");
        gpio_exit();
        return 1;
    }

    if (ioctl(fd, PI_SET_PWM_CHANNEL, 18) < 0) {
        fprintf(stderr, "Error: Failed to set PWM channel\n");
        close(fd);
        gpio_exit();
        return 1;
    }

    if (ioctl(fd, PI_SET_PWM_FREQ, PWM_FREQ_MIN) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency\n");
        close(fd);
        gpio_exit();
        return 1;
    }

    if (ioctl(fd, PI_SET_PWM_MODE, PWM_MODE_PWM) < 0) {
        fprintf(stderr, "Error: Failed to set PWM mode\n");
        close(fd);
        gpio_exit();
        return 1;
    }

    if (ioctl(fd, PI_SET_PWM_RES, PWM_RES_12BIT) < 0) {
        fprintf(stderr, "Error: Failed to set PWM resolution\n");
        close(fd);
        gpio_exit();
        return 1;
    }

    gpioHandle = gpio_open_sysfs("/dev/pigpio_pwm", PI_OUTPUT);
    if (gpioHandle < 0) {
        fprintf(stderr, "Error: Failed to open GPIO file\n");
        close(fd);
        gpio_exit();
        return 1;
    }

    pwmHandle = pwm_open(gpioHandle, PWM_MODE_PWM, PWM_FREQ_MIN, PWM_FREQ_MAX, PWM_FREQ_STEP);
    if (pwmHandle < 0) {
        fprintf(stderr, "Error: Failed to open PWM channel\n");
        pwm_close(pwmHandle);
        gpio_close(gpioHandle);
        gpio_exit();
        return 1;
    }

    // Set initial frequency
    if (pwm_set_frequency(pwmHandle, PWM_FREQ_MIN) < 0) {
        fprintf(stderr, "Error: Failed to set initial frequency\n");
        pwm_close(pwmHandle);
        gpio_close(gpioHandle);
        gpio_exit();
        return 1;
    }

    // Set initial distance
    distance = 2;

    // Set initial frequency
    frequency = pwm_get_frequency(pwmHandle);

    // Set initial distance
    previous_frequency = frequency;

    // Set up SIGINT and SIGTERM handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    while (1) {
        // Read distance from HC-SR04
        if (ioctl(23, PI_GET_ECHO_THRESHOLD, &timeout) < 0) {
            fprintf(stderr, "Error: Failed to read echo threshold\n");
            continue;
        }

        if (timeout.tv_sec >= 200) {
            // Distance is out of range
            frequency = previous_frequency;
        } else {
            // Calculate frequency
            frequency = 200 * exp(distance / 50);

            // Set new frequency
            if (pwm_set_frequency(pwmHandle, frequency) < 0) {
                fprintf(stderr, "Error: Failed to set new frequency\n");
                continue;
            }

            // Set new distance
            distance = (int) (distance * 2);

            // Update previous frequency
            previous_frequency = frequency;
        }

        // Update PWM output
        if (pwm_set_duty(pwmHandle, pwm_get_duty(pwmHandle) + 50) < 0) {
            fprintf(stderr, "Error: Failed to set PWM duty\n");
            continue;
        }

        // Wait for PWM output to change
        if (pwm_wait(pwmHandle, &timeout) < 0) {
            fprintf(stderr, "Error: Failed to wait for PWM output to change\n");
            continue;
        }

        // Check for error
        if (pwm_get_duty(pwmHandle) != pwm_get_duty(pwmHandle) + 50) {
            fprintf(stderr, "Error: PWM output is not at 50% duty cycle\n");
            continue;
        }

        // Release resources
        pwm_close(pwmHandle);
        gpio_close(gpioHandle);
        gpio_exit();
    }

    return 0;
}

// SIGINT and SIGTERM handlers
void handle_sigint(int signum) {
    printf("Received SIGINT or SIGTERM, stopping PWM output and terminating pigpio\n");
    pwm_close(pwmHandle);
    gpio_close(gpioHandle);
    gpio_exit();
}

void handle_sigterm(int signum) {
    printf("Received SIGTERM, stopping PWM output and terminating pigpio\n");
    pwm_close(pwmHandle);
    gpio_close(gpioHandle);
    gpio_exit();
}

