#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>

#define TRIG_PIN 17
#define ECHO_PIN 18

int main() {
    int fd;
    int ret;
    int timeout = 500;
    int distance = 0;
    int min_distance = 2;
    int max_distance = 400;
    int threshold_distance = 10;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return 1;
    }

    fd = open("/dev/pigpio", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening pigpio device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(fd, PI_SET_MODE, PI_MODE_GPIONODE) < 0) {
        fprintf(stderr, "Error setting pigpio mode: %s\n", strerror(errno));
        goto error_exit;
    }

    if (gpioSetMode(fd, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting pigpio output: %s\n", strerror(errno));
        goto error_exit;
    }

    gpioSetTrig(fd, TRIG_PIN);
    gpioDelay(2);
    gpioSetTrig(fd, 0);

    while (1) {
        struct timespec start, stop;
        int timeout_us = timeout * 1000;

        if (gpioGetValue(fd) == 0) {
            gpioDelay(50);
        }

        start = get_time();
        ret = gpioEcho(fd, ECHO_PIN);
        stop = get_time();

        if (ret < 0) {
            fprintf(stderr, "Error measuring echo pulse: %s\n", strerror(errno));
            goto error_exit;
        }

        stop.tv_sec -= start.tv_sec;
        stop.tv_nsec -= start.tv_nsec;

        if (stop.tv_nsec < 0) {
            stop.tv_sec--;
            stop.tv_nsec += 1000000000;
        }

        if (timeout_us > stop.tv_sec * 1000000 + stop.tv_nsec) {
            fprintf(stderr, "Timeout waiting for echo pulse: %s\n", strerror(errno));
            goto error_exit;
        }

        stop.tv_sec -= timeout;
        stop.tv_nsec = 0;

        if (timeout_us < stop.tv_sec * 1000000 + stop.tv_nsec) {
            fprintf(stderr, "Timeout waiting for trigger pulse: %s\n", strerror(errno));
            goto error_exit;
        }

        if (gpioGetValue(fd) == 1) {
            break;
        }

        if (timeout_us < 500) {
            timeout_us += 500;
        }

        if (timeout_us > timeout) {
            fprintf(stderr, "Timeout waiting for trigger pulse: %s\n", strerror(errno));
            goto error_exit;
        }

        gpioDelay(50);
    }

    distance = (stop.tv_sec - start.tv_sec) * 29100 + (stop.tv_nsec - start.tv_nsec) / 1000000;

    if (distance < min_distance || distance > max_distance) {
        fprintf(stderr, "Invalid reading: distance too far or too close\n");
        goto error_exit;
    }

    if (distance < threshold_distance) {
        fprintf(stderr, "Too close!\n");
    } else {
        printf("Distance: %.1f cm\n", distance);
    }

    gpioTerminate();

error_exit:
    gpioClose(fd);
    return 1;
}

