#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x60

int main() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_rdwr_ioctl_data *i2c_data_ptr;
    struct i2c_msg i2c_msgs[2];
    uint16_t als_visible;
    uint8_t reg_low, reg_high;
    char log_file_name[] = "proximity_log.csv";
    char header_line[] = "timestamp,als_visible";

    // Open the I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Check if the sensor is present
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        if (errno == ENODEV) {
            fprintf(stderr, "Sensor not present on I2C address 0x%02x\n", I2C_ADDR);
        } else {
            perror("Error checking sensor presence");
            exit(EXIT_FAILURE);
        }
    }

    // Initialize the I2C file descriptor
    if (ioctl(i2c_fd, I2C_RDWR, I2C_ADDR) < 0) {
        perror("Error initializing I2C file descriptor");
        exit(EXIT_FAILURE);
    }

    // Read the 16-bit visible ambient light value from registers 0x22 and 0x23
    reg_low = i2c_msgs[0].addr;
    reg_high = i2c_msgs[1].addr;
    if (ioctl(i2c_fd, I2C_RDWR, reg_low) < 0) {
        perror("Error reading low byte of visible ambient light");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_RDWR, reg_high) < 0) {
        perror("Error reading high byte of visible ambient light");
        exit(EXIT_FAILURE);
    }
    als_visible = (uint16_t)((reg_low << 8) | reg_high);

    // Log the reading with an ISO-8601 timestamp
    printf("timestamp,als_visible\n");
    printf("%s,%d\n", header_line, als_visible);

    // Read the 16-bit visible ambient light value from registers 0x22 and 0x23 every 5 seconds
    while (1) {
        // Wait for 5 seconds
        sleep(5);

        // Read the 16-bit visible ambient light value from registers 0x22 and 0x23
        reg_low = i2c_msgs[0].addr;
        reg_high = i2c_msgs[1].addr;
        if (ioctl(i2c_fd, I2C_RDWR, reg_low) < 0) {
            perror("Error reading low byte of visible ambient light");
            exit(EXIT_FAILURE);
        }
        if (ioctl(i2c_fd, I2C_RDWR, reg_high) < 0) {
            perror("Error reading high byte of visible ambient light");
            exit(EXIT_FAILURE);
        }
        als_visible = (uint16_t)((reg_low << 8) | reg_high);

        // Log the reading with an ISO-8601 timestamp
        printf("timestamp,als_visible\n");
        printf("%s,%d\n", header_line, als_visible);

        // Release the I2C file descriptor
        if (ioctl(i2c_fd, I2C_RDWR, I2C_ADDR) < 0) {
            perror("Error releasing I2C file descriptor");
            exit(EXIT_FAILURE);
        }
    }

    // Close the I2C file descriptor
    if (close(i2c_fd) < 0) {
        perror("Error closing I2C file descriptor");
        exit(EXIT_FAILURE);
    }

    return 0;
}

