```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define BUZZER_PIN 27
#define TRIGGER_PIN 17
#define ECHO_PIN 18

int main() {
    int ret;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Set trigger and echo pins as output
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetAlertFuncEx(NULL, NULL, NULL, NULL, NULL) < 0) {
        fprintf(stderr, "Failed to set alert function: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set echo pin as input with falling/rising edge alert callback
    if (gpioSetAlertFuncEx(NULL, NULL, NULL, NULL, &gpioCallback) < 0) {
        fprintf(stderr, "Failed to set falling/rising edge alert function: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set buzzer pin as output
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin as output: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Trigger the sensor and measure the distance
    gpioWrite(TRIGGER_PIN, PI_HIGH);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, PI_LOW);

    // Read the echo pulse width
    int64_t start_time = gpioRead(ECHO_PIN);
    int64_t end_time = gpioRead(ECHO_PIN);
    int64_t pulse_width = end_time - start_time;

