#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x29

int main() {
    int i2c_fd, gpio_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    struct gpio_desc gpio_desc;
    uint16_t model_id;
    uint16_t timing_budget;
    uint16_t distance_reg;
    uint16_t hysteresis_threshold;
    uint16_t servo_pulse_width;
    uint16_t open_close_interval;
    uint16_t open_close_count;
    struct timespec open_close_start;
    struct timespec open_close_end;
    char log_file_path[128];

    // Initialize I2C bus
    if (i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        return 1;
    }

    // Open the I2C file descriptor
    if ((i2c_fd = i2c_open(I2C_BUS_NUM)) < 0) {
        fprintf(stderr, "Failed to open I2C file descriptor\n");
        return 1;
    }

    // Open GPIO file descriptor
    if ((gpio_fd = open("/dev/gpiochip0", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open GPIO file descriptor\n");
        return 1;
    }

    // Set GPIO18 as PWM-capable
    if (gpio_set_mode(gpio_fd, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO18 as PWM-capable\n");
        return 1;
    }

    // Set GPIO18 as a PWM-capable pin
    if (gpio_set_pwm_mode(gpio_fd, GPIO_PWM_MODE_PULSE, GPIO_PWM_MODE_CHANNEL_1) < 0) {
        fprintf(stderr, "Failed to set GPIO18 as PWM-capable\n");
        return 1;
    }

    // Set GPIO18 as a hardware PWM-capable pin
    if (gpio_set_pwm_range(gpio_fd, GPIO_PWM_RANGE_16) < 0) {
        fprintf(stderr, "Failed to set GPIO18 as hardware PWM-capable\n");
        return 1;
    }

    // Set GPIO18 as a PWM-capable pin
    if (gpio_set_pwm_channel(gpio_fd, GPIO_PWM_CHANNEL_1) < 0) {
        fprintf(stderr, "Failed to set GPIO18 as PWM-capable\n");
        return 1;
    }

    // Set GPIO18 as an output
    if (gpio_set_direction(gpio_fd, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO18 as an output\n");
        return 1;
    }

    // Set the I2C slave address
    if (i2c_set_slave(i2c_fd, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return 1;
    }

    // Verify the VL53L1X model ID
    if (i2c_rdwr(i2c_fd, I2C_RDWR_START, &i2c_msgs[0], 1) < 0) {
        fprintf(stderr, "Failed to read model ID\n");
        return 1;
    }

    model_id = i2c_msgs[0].buf[0];
    if (model_id != 0xEA) {
        fprintf(stderr, "Invalid VL53L1X model ID\n");
        return 1;
    }

    // Set the timing budget
    if (i2c_rdwr(i2c_fd, I2C_RDWR_START, &i2c_msgs[0], 1) < 0) {
        fprintf(stderr, "Failed to set timing budget\n");
        return 1;
    }

    if (i2c_rdwr(i2c_fd, I2C_RDWR_START, &i2c_msgs[1], 1) < 0) {
        fprintf(stderr, "Failed to set timing budget\n");
        return 1;
    }

    // Start ranging
    if (i2c_rdwr(i2c_fd, I2C_RDWR_START, &i2c_msgs[0], 1) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        return 1;
    }

    // Wait for the sensor to finish ranging
    while (i2c_rdwr(i2c_fd, I2C_RDWR_START, &i2c_msgs[0], 1) < 0) {
        // Do nothing
    }

    // Read the 16-bit distance register
    if (i2c_rdwr(i2c_fd, I2C_RDWR_START, &i2c_msgs[0], 1) < 0) {
        fprintf(stderr, "Failed to read distance register\n");
        return 1;
    }

    distance_reg = i2c_msgs[0].buf[0];

    // Set the hysteresis threshold
    if (i2c_rdwr(i2c_fd, I2C_RDWR_START, &i2c_msgs[0], 1) < 0) {
        fprintf(stderr, "Failed to set hysteresis threshold\n");
        return 1;
    }

    hysteresis_threshold = 0xFE00;

    // Set the 16-bit distance register to the hysteresis threshold
    if (i2c_wr_word(i2c_fd, distance_reg, hysteresis_threshold) < 0) {
        fprintf(stderr, "Failed to set hysteresis threshold\n");
        return 1;
    }

    // Set the servo pulse width
    if (i2c_rdwr(i2c_fd, I2C_RDWR_START, &i2c_msgs[0], 1) < 0) {
        fprintf(stderr, "Failed to set servo pulse width\n");
        return 1;
    }

    servo_pulse_width = 0x1000;

    if (i2c_wr_word(i2c_fd, servo_pulse_width, 0) < 0) {
        fprintf(stderr, "Failed to set servo pulse width\n");
        return 1;
    }

    // Set the servo open/close interval
    if (i2c_rdwr(i2c_fd, I2C_RDWR_START, &i2c_msgs[0], 1) < 0) {
        fprintf(stderr, "Failed to set servo open/close interval\n");
        return 1;
    }

    if (i2c_wr_word(i2c_fd, open_close_interval, 0) < 0) {
        fprintf(stderr, "Failed to set servo open/close interval\n");
        return 1;
    }

    // Set the servo open/close count
    if (i2c_wr_word(i2c_fd, open_close_count, 0) < 0) {
        fprintf(stderr, "Failed to set servo open/close count\n");
        return 1;
    }

    // Open the gate
    if (i2c_wr_word(i2c_fd, 1, 0) < 0) {
        fprintf(stderr, "Failed to open the gate\n");
        return 1;
    }

    // Wait for the servo to open the gate
    while (i2c_rdwr(i2c_fd, I2C_RDWR_START, &i2c_msgs[0], 1) < 0) {
        // Do nothing
    }

    // Log the open/close event
    snprintf(log_file_path, 128, "gate_log.txt", open_close_count);
    open_close_start.tv_sec = (time(NULL) / 1000000);
    open_close_start.tv_nsec = (time(NULL) % 1000000) * 1000;
    open_close_end.tv_sec = (time(NULL) / 1000000);
    open_close_end.tv_nsec = (time(NULL) % 1000000) * 1000;

    open_close_interval = open_close_count;

    if (i2c_wr_word(i2c_fd, open_close_count, open_close_interval) < 0) {
        fprintf(stderr, "Failed to log open/close event\n");
        return 1;
    }

    // Close the gate
    if (i2c_wr_word(i2c_fd, 0, 0) < 0) {
        fprintf(stderr, "Failed to close the gate\n");
        return 1;
    }

    // Wait for the servo to close the gate
    while (i2c_rdwr(i2c_fd, I2C_RDWR_START, &i2c_msgs[0], 1) < 0) {
        // Do nothing
    }

    // Log the close event
    snprintf(log_file_path, 128, "gate_log.txt", open_close_count);
    open_close_start.tv_sec = (time(NULL) / 1000000);
    open_close_start.tv_nsec = (time(NULL) % 1000000) * 1000;
    open_close_end.tv_sec = (time(NULL) / 1000000);
    open_close_end.tv_nsec = (time(NULL) % 1000000) * 1000;

    close_interval = open_close_count;

    if (i2c_wr_word(i2c_fd, open_close_count, close_interval) < 0) {
        fprintf(stderr, "Failed to log close event\n");
        return 1;
    }

    // Release the I2C handle
    i2c_close(i2c_fd);

    // Clean up
    return 0;
}

