    int fd;
    int i2c_fd;
    int gpio_fd;
    pid_t pid;
    char buffer[10];
    char log_file_name[] = "error_log.txt";
    char temp_log_file_name[] = "enclosure_temp_log.txt";

    // Initialize pigpio library
    if (gpio_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    if ((i2c_fd = i2c_open(I2C_BUS_NUM)) < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }

    // Open GPIO
    if ((gpio_fd = gpio_open(I2C_BUS_NUM, I2C_ADDRESS)) < 0) {
        fprintf(stderr, "Error: Failed to open GPIO\n");
        exit(EXIT_FAILURE);
    }

    // Start I2C communication
    if (i2c_master_start(i2c_fd) < 0) {
        fprintf(stderr, "Error: Failed to start I2C communication\n");
        exit(EXIT_FAILURE);
    }

    // Sample temperature every 5 seconds
    while (1) {
        // Wait for 5 seconds
        sleep(5);

        // Read temperature from the sensor
        if (i2c_master_write(i2c_fd, 0x00, &buffer[0], 1) < 0) {
            fprintf(stderr, "Error: Failed to write to sensor\n");
            exit(EXIT_FAILURE);
        }

        if (i2c_master_read(i2c_fd, &buffer[0], 1, 1) < 0) {
            fprintf(stderr, "Error: Failed to read from sensor\n");
            exit(EXIT_FAILURE);
        }

        // Log the temperature and timestamp
        if (i2c_master_write(i2c_fd, 0x01, &buffer[0], 1) < 0) {
            fprintf(stderr, "Error: Failed to write to log file\n");
            exit(EXIT_FAILURE);
        }

        if (i2c_master_read(i2c_fd, &buffer[0], 1, 1) < 0) {
            fprintf(stderr, "Error: Failed to read from log file\n");
            exit(EXIT_FAILURE);
        }

        // Log errors
        if (i2c_master_write(i2c_fd, 0x02, &buffer[0], 1) < 0) {
            fprintf(stderr, "Error: Failed to write to error log file\n");
            exit(EXIT_FAILURE);
        }

        if (i2c_master_read(i2c_fd, &buffer[0], 1, 1) < 0) {
            fprintf(stderr, "Error: Failed to read from error log file\n");
            exit(EXIT_FAILURE);
        }

        // Close I2C bus and GPIO
        if (i2c_master_stop(i2c_fd) < 0) {
            fprintf(stderr, "Error: Failed to stop I2C communication\n");
            exit(EXIT_FAILURE);
        }
        if (gpio_close(gpio_fd) < 0) {
            fprintf(stderr, "Error: Failed to close GPIO\n");
            exit(EXIT_FAILURE);
        }

        // Cleanup
        gpio_unexport(I2C_BUS_NUM);
        i2c_close(i2c_fd);
    }

    return 0;
}

