#include <linux/i2c-dev.h>

#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x25

int main() {
    int fd;
    int ret;
    uint8_t buffer[9];
    uint8_t crc_calculated;
    uint8_t crc_expected;
    uint8_t i2c_data[9];
    uint8_t i2c_address = I2C_ADDR;
    uint8_t i2c_sensor_data[9];
    uint16_t pressure_raw, temperature_raw;
    float pressure_scaled, temperature_scaled;
    char timestamp[26];
    char log_file[50];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    // Open the I2C bus
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set the I2C bus speed
    if (ioctl(fd, I2C_SLAVE, i2c_address) < 0) {
        fprintf(stderr, "Error: Failed to set I2C bus speed\n");
        goto error_close_bus;
    }

    // Open the sensor
    ret = pigpio_open_device(&pi, i2c_sensor_data, I2C_ADDR, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to open sensor\n");
        goto error_close_bus;
    }

    // Configure the sensor for continuous measurement
    if (pigpio_set_mode(pi, i2c_sensor_data, PI_MODE_CONT) < 0) {
        fprintf(stderr, "Error: Failed to set mode to continuous\n");
        goto error_close_sensor;
    }

    // Set the sensor to read data
    if (pigpio_set_mode(pi, i2c_sensor_data, PI_MODE_READ) < 0) {
        fprintf(stderr, "Error: Failed to set mode to read\n");
        goto error_close_sensor;
    }

    // Wait for the sensor to settle
    if (pigpio_delay_us(pi, 100) < 0) {
        fprintf(stderr, "Error: Failed to wait for sensor to settle\n");
        goto error_close_sensor;
    }

    // Send command bytes 0x36 0x08 to the sensor
    if (pigpio_i2c_write(pi, i2c_sensor_data, 2, &buffer[0], 2) < 0) {
        fprintf(stderr, "Error: Failed to send command bytes\n");
        goto error_close_sensor;
    }

    // Wait at least 1 ms
    if (pigpio_delay_us(pi, 1000) < 0) {
        fprintf(stderr, "Error: Failed to wait for 1 ms\n");
        goto error_close_sensor;
    }

    // Read 9-byte data frame
    if (pigpio_i2c_read(pi, i2c_sensor_data, 9, &i2c_data[0], &i2c_data[9]) < 0) {
        fprintf(stderr, "Error: Failed to read data frame\n");
        goto error_close_sensor;
    }

    // Calculate CRC-8 checksum
    crc_calculated = pigpio_crc8(i2c_data, 9, 0x31, 0xFF);
    crc_expected = 0x35;

    // Check CRC-8
    for (int i = 0; i < 9; i++) {
        if (i2c_data[i] != crc_expected) {
            fprintf(stderr, "Error: CRC-8 check failed\n");
            goto error_close_sensor;
        }
    }

    // Read sensor data
    pressure_raw = i2c_data[0];
    temperature_raw = i2c_data[1];

    // Convert raw pressure and temperature to scaled values
    pressure_scaled = (pressure_raw * 0.01) / 0.01;
    temperature_scaled = (temperature_raw * 0.01) / 0.01;

    // Format timestamp
    snprintf(timestamp, 26, "%.6f", pi.ticks_per_second / 1000000.0);

    // Log the data to a CSV file
    snprintf(log_file, 50, "pressure_log.csv");
    FILE *fp = fopen(log_file, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        goto error_close_sensor;
    }

    // Write header row
    fprintf(fp, "timestamp,pressure,temperature\n");

    // Write data rows
    fprintf(fp, "%s,%f,%f\n", timestamp, pressure_scaled, temperature_scaled);

    // Close the log file
    fclose(fp);

error_close_log:
    fprintf(stderr, "Error: Failed to close log file\n");
    goto error_close_sensor;

error_close_sensor:
    pigpio_close_device(pi);

error_close_bus:
    gpioTerminate();

    return 1;
}

