int main() {
    int fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    char buffer[9];
    uint8_t crc8_table[256] = {0};

    // Initialize I2C library
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C library\n");
        return 1;
    }

    if (pi_open_device(I2C_BUS, I2C_ADDR, &fd) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    // Set up the I2C device
    if (pi_set_mode(fd, I2C_MODE_I2C) < 0) {
        fprintf(stderr, "Failed to set I2C mode\n");
        return 1;
    }

    // Set up the I2C file descriptor
    if (pi_ioctl(fd, I2C_RDWR, I2C_RDWR) < 0) {
        fprintf(stderr, "Failed to set I2C file descriptor\n");
        return 1;
    }

    // Set up the buffer for reading data
    buffer[0] = 0x362F;
    buffer[1] = 0;
    buffer[2] = 0;
    buffer[3] = 0;
    buffer[4] = 0;
    buffer[5] = 0;
    buffer[6] = 0;
    buffer[7] = 0;
    buffer[8] = 0;

    // Read data from the sensor
    if (pi_ioctl(fd, I2C_RDWR, &i2c_data) < 0) {
        fprintf(stderr, "Failed to read data from the sensor\n");
        return 1;
    }

    // Wait for approximately 45 ms
    gpio_delay(45);

    // Read 9 bytes: 3 bytes pressure + CRC, 3 bytes temperature + CRC, and 3 bytes scale factor + CRC
    if (pi_read(fd, &i2c_data, buffer, 9, &crc8_table[0]) < 0) {
        fprintf(stderr, "Failed to read data from the sensor\n");
        return 1;
    }

    // Validate the CRC
    if (crc8_check(crc8_table, buffer, 9) != 0) {
        fprintf(stderr, "CRC check failed\n");
        return 1;
    }

    // Convert raw pressure to Pa
    float pressure = (buffer[2] << 8) | buffer[3];
    pressure /= (1 << 8);

    // Convert raw temperature to °C
    float temperature = (buffer[4] << 8) | buffer[5];
    temperature /= (1 << 8);

    // Log the data
    FILE *log_file = fopen("airflow_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", time(NULL), pressure, temperature);

    // Release resources
    pi_close(fd);
    gpio_cleanup();

    fclose(log_file);

    return 0;
}

