        exit(EXIT_FAILURE);
    }

    if (open(pressure_log_file_path, O_WRONLY | O_CREAT | O_TRUNC, 0644) < 0) {
        perror("Failed to open pressure log file");
        exit(EXIT_FAILURE);
    }

