    }

    // Initialize i2c-dev
    if (ioctl(0, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    // Initialize gpio
    gpio_req.gpio_request_type = GPIO_REQUEST_TYPE_OUTPUT;
    gpio_req.gpio_line = GPIO_LINE_0;
    gpio_req.gpio_value = 0;
