        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    // Initialize pressure sensor
    if (gpio_request(gpio_fd, &gpio_req) < 0) {
        perror("Failed to request GPIO");
        exit(EXIT_FAILURE);
    }

