#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <time.h>

#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x40

#define TEMP_THRESHOLD 28.0
#define HUMIDITY_THRESHOLD 125.0
#define HUMIDITY_HYSTERESIS 6.0

int fan_gpio_pin = 18;

int main() {
    int i;
    int retry_count = 3;
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    uint16_t temp_data[2];
    uint16_t humidity_data[2];
    struct timespec start_time, end_time;
    struct sigaction sa;
    gpio_t gpio;
    int ret;

    gpio_init();
    gpio_set_mode(fan_gpio_pin, GPIO_OUTPUT);

    gpio_set_dir(fan_gpio_pin, GPIO_OUTPUT);
    gpio_set_level(fan_gpio_pin, 0);

    gpio_set_mode(I2C_BUS_NUM, GPIO_MODE_OUTPUT);
    gpio_set_level(I2C_BUS_NUM, 1);

    retry_count = 3;

    while (1) {
        // Wait for 2 seconds
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        while (clock_gettime(CLOCK_MONOTONIC, &end_time) == 0) {
            if (end_time.tv_sec >= 2) {
                break;
            }
        }

        // Trigger Hold Master measurement commands
        gpio_set_level(fan_gpio_pin, 1);
        gpio_delay_usec(10);
        gpio_set_level(fan_gpio_pin, 0);

        // Wait for at least 10 ms after each trigger
        gpio_delay_usec(10);

        // Read temperature and humidity data
        ret = pigpio_i2c_read_reg16(I2C_BUS_NUM, I2C_ADDR, 0xE3, &temp_data[0], 1);
        if (ret != 0) {
            printf("Failed to read temperature data: %d\n", ret);
            continue;
        }

        ret = pigpio_i2c_read_reg16(I2C_BUS_NUM, I2C_ADDR, 0xE5, &humidity_data[0], 1);
        if (ret != 0) {
            printf("Failed to read humidity data: %d\n", ret);
            continue;
        }

        // Convert raw values
        float temperature = 175.72 * temp_data[0] / 65536.0 - 46.85;
        float humidity = 125.0 * humidity_data[0] / 65536.0 - 6.0;

        // Log the readings
        printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);

        // Check hysteresis band
        if (temperature > TEMP_THRESHOLD && humidity > HUMIDITY_THRESHOLD) {
            gpio_set_level(fan_gpio_pin, 1);
        } else if (temperature < TEMP_THRESHOLD && humidity < HUMIDITY_THRESHOLD) {
            gpio_set_level(fan_gpio_pin, 0);
        }

        // Print the circular buffer
        for (i = 0; i < 60; i++) {
            printf("Timestamp: %lu, Temperature: %.2f °C, Humidity: %.2f %% \n", i, temperature, humidity);
        }

        // Wait for a short period before the next measurement
        gpio_delay_usec(1000);
    }

    // Close the I2C handle
    gpio_close(I2C_BUS_NUM);

    // Degrade gracefully
    printf("Degraded gracefully\n");

    // Turn off the fan
    gpio_set_level(fan_gpio_pin, 0);

    // Deactivate the GPIO interrupt
    gpio_deactivate(fan_gpio_pin);

    // Clean up
    gpio_exit();

    return 0;
}

