#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDRESS 0x62

// Global variables
uint8_t i2c_data[2];
uint8_t i2c_response[9];
uint8_t i2c_crc_check[2];
uint8_t i2c_crc_sum = 0;

int i2c_fd;
int i2c_gpio_pin = 17;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        printf("Error: pigpio initialization failed.\n");
        return 1;
    }

    // Set up GPIO 17 as an output
    gpioSetMode(i2c_gpio_pin, PI_OUTPUT);

    // Open I2C bus
    if ((i2c_fd = i2cOpen(I2C_BUS_NUM)) < 0) {
        printf("Error: Failed to open I2C bus.\n");
        gpioTerminate();
        return 1;
    }

    // Set up I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        printf("Error: Failed to set I2C address.\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize pigpio for I2C communication
    if (gpioSetSpeed(i2c_fd, PI_FAST) < 0) {
        printf("Error: Failed to set pigpio speed to fast.\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    gpioSetPwmFrequency(i2c_gpio_pin, 1000);
    gpioWrite(i2c_gpio_pin, 1);
    gpioDelay(100);
    gpioWrite(i2c_gpio_pin, 0);

    while (1) {
        // Wait for data ready status
        if (gpioRead(i2c_gpio_pin) == 0) {
            // Poll for data
            if (i2cRead(i2c_fd, i2c_data, 2) < 0) {
                printf("Error: Failed to read data from I2C.\n");
                gpioClose(i2c_fd);
                gpioTerminate();
                return 1;
            }

            // Check if data is valid
            if (i2c_data[0] == 0x21B1 && i2c_data[1] == 0xE4B8) {
                // Read measurement
                if (i2cRead(i2c_fd, i2c_data, 9) < 0) {
                    printf("Error: Failed to read measurement from I2C.\n");
                    gpioClose(i2c_fd);
                    gpioTerminate();
                    return 1;
                }

                // Validate CRC-8 checksum
                for (int i = 0; i < 2; i++) {
                    i2c_crc_check[i] = i2c_data[i + 2];
                    for (int j = 0; j < 8; j++) {
                        if (i2c_crc_check[i] != i2c_crc_sum & (1 << (7 - j))) {
                            printf("Error: CRC-8 checksum mismatch.\n");
                            gpioClose(i2c_fd);
                            gpioTerminate();
                            return 1;
                        }
                        i2c_crc_sum = (i2c_crc_sum >> 1) ^ (i2c_crc_check[i] << (7 - j));
                    }
                }

                // Print valid reading
                printf("CO2: %d ppm, Temperature: %d C, Humidity: %d%%\n",
                       i2c_data[3], i2c_data[4], i2c_data[5]);

                // Print valid reading to stdout
                printf("CO2: %d ppm, Temperature: %d C, Humidity: %d%%\n",
                       i2c_data[3], i2c_data[4], i2c_data[5]);
            }
        }

        // Stop periodic measurement
        gpioWrite(i2c_gpio_pin, 0);
        gpioDelay(100);
        gpioWrite(i2c_gpio_pin, 1);

        // Check for sensor absence or bus error
        if (gpioRead(i2c_gpio_pin) == 0) {
            printf("Sensor absent or bus error.\n");
            gpioClose(i2c_fd);
            gpioTerminate();
            return 1;
        }
    }

    // Clean up
    gpioClose(i2c_fd);
    gpioTerminate();
    return 0;
}

