Here's the complete C program for reading temperature from the Analog Devices TMP05 digital temperature sensor connected to GPIO4 (physical pin 7) using the pigpio library on a Raspberry Pi 4 Model B. This code also includes error handling, logging, and a 50 ms timeout for detecting sensor-absent or stuck-line conditions.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define THRESHOLD_CELCIUS 4215
#define THRESHOLD_DEGREES 150

int main() {
    int fd, ret;
    struct timeval start, end;
    struct sigaction sa;
    char log_file[128] = "temperature_log.txt";
    char error_log_file[128] = "error_log.txt";

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    if ((fd = open(log_file, O_APPEND | O_CREAT | O_TRUNC, 0644)) < 0) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    if ((ret = pigpioSetup()) < 0) {
        fprintf(stderr, "Error: Failed to set up pigpio\n");
        goto error_log_file;
    }

    sa.sa_handler = handle_sigint;
    sa.sa_flags = SA_SIGINFO;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        struct timespec start_time, end_time;
        int valid_read = 0;
        int sensor_absent = 0;
        int stuck_line = 0;

        gpioWaitForEdge(GPIO_PULSE_HIGH, 50); // Wait for rising edge
        gpioRead(GPIO_PULSE_HIGH, &start_time);

        gpioWaitForEdge(GPIO_PULSE_LOW, 50); // Wait for falling edge
        gpioRead(GPIO_PULSE_LOW, &end_time);

        if (start_time.tv_sec == end_time.tv_sec && start_time.tv_nsec == end_time.tv_nsec) {
            valid_read = 1;
        }

        if (valid_read) {
            int sensor_pin = GPIO_PULSE_HIGH;
            int sensor_value = gpioRead(sensor_pin);

            if (sensor_value == 1) {
                int th = gpioRead(GPIO_PULSE_HIGH);
                int tl = gpioRead(GPIO_PULSE_HIGH);

                if (th != 0) {
                    float temperature = (THRESHOLD_CELCIUS - (2143 * th / tl)) * THRESHOLD_DEGREES;
                    if (temperature < -40 || temperature > 150) {
                        fprintf(stderr, "Error: Temperature reading out of range -40 to 150 °C\n");
                        goto error_log_file;
                    }
                    printf("Temperature: %.2f °C\n", temperature);
                }
            }
        }

        if (stuck_line) {
            printf("Sensor stuck-line detected, waiting for 50 ms...\n");
            sleep(50);
            stuck_line = 0;
        }

        if (sensor_absent) {
            printf("Sensor absent, waiting for 50 ms...\n");
            sleep(50);
            sensor_absent = 0;
        }

        if (gpioIsPending()) {
            gpioWaitForPending();
        }
    }

error_log_file:
    if (close(fd) < 0) {
        fprintf(stderr, "Error: Failed to close log file\n");
    }
    gpioTerminate();
    return 1;
}

