#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/i2c-gpio.h>
#include <linux/i2c-sysfs.h>
#include <linux/delay.h>
#include <linux/time.h>
#include <linux/crc.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x25

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

void i2c_init(int fd) {
    struct i2c_rdwr_ioctl_data data;
    data.flags = 0;
    data.timeout_ms = 100;
    data.mode = I2C_MODE_I2C;
    data.addr = I2C_ADDR;
    data.flags |= I2C_RDWR;

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        perror("Error initializing I2C bus");
        exit(EXIT_FAILURE);
    }
}

void i2c_release(int fd) {
    if (ioctl(fd, I2C_RDWR, 0) < 0) {
        perror("Error releasing I2C bus");
        exit(EXIT_FAILURE);
    }
}

void i2c_check_crc8(uint8_t* data, uint8_t crc8_initial_value, uint8_t crc8_polynomial) {
    uint8_t crc8_calculated;
    uint8_t crc8_expected;

    crc8_calculated = crc8_calculate(crc8_polynomial, data, 9);
    crc8_expected = crc8_initial_value ^ crc8_calculated;

    if (crc8_calculated != crc8_expected) {
        printf("CRC-8 checksum error!\n");
        exit(EXIT_FAILURE);
    }
}

void send_continuous_measurement(int fd) {
    uint8_t measurement_data[9];
    uint8_t crc8_calculated;
    uint8_t crc8_expected;

    // Send continuous measurement command (0x362F)
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error sending continuous measurement command");
        exit(EXIT_FAILURE);
    }

    // Wait for conversion time of approximately 45 ms
    delay(45);

    // Read 9 bytes containing pressure, temperature, and scale factor
    if (ioctl(fd, I2C_RDWR, measurement_data) < 0) {
        perror("Error reading data from sensor");
        exit(EXIT_FAILURE);
    }

    // Calculate CRC-8 checksum
    crc8_calculated = crc8_calculate(CRC8_POLYNOMIAL, measurement_data, 9);
    crc8_expected = CRC8_INITIAL_VALUE ^ crc8_calculated;

    // Check CRC-8 checksum
    if (crc8_calculated != crc8_expected) {
        printf("CRC-8 checksum error!\n");
        exit(EXIT_FAILURE);
    }

    // Log the data to 'airflow.csv'
    FILE* file = fopen("airflow.csv", "a");
    if (file == NULL) {
        perror("Error opening file for writing");
        exit(EXIT_FAILURE);
    }

    fprintf(file, "%.2f,%.2f,%.2X\n", (float)measurement_data[0] / 10.0, (float)measurement_data[1] / 10.0, measurement_data[2]);

    fclose(file);
}

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;

    i2c_init(fd);

    // Open I2C file descriptor
    if (ioctl(fd, I2C_RDWR, 0) < 0) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Send continuous measurement command
    if (send_continuous_measurement(fd) < 0) {
        perror("Error sending continuous measurement command");
        exit(EXIT_FAILURE);
    }

    // Wait for sensor absence or bus error
    while (!is_sensor_present(fd) && !is_bus_error(fd)) {
        // Do nothing
    }

    // Release I2C file descriptor
    i2c_release(fd);

    return 0;
}

