    if (send_continuous_measurement(fd) < 0) {
        perror("Error sending continuous measurement command");
        exit(EXIT_FAILURE);
    }

    // Wait for sensor absence or bus error
    while (!is_sensor_present(fd) && !is_bus_error(fd)) {
        // Do nothing
    }

    // Release I2C file descriptor
    i2c_release(fd);

    return 0;
}
