    int rc;
    int16_t raw_data[2];
    uint8_t crc_data[2];
    uint8_t crc_calc[2];
    char timestamp[26];
    char* csv_file = "environment.csv";
    FILE* csv_file_handle;
    struct stat stat_buf;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library.\n");
        return 1;
    }

    if ((i2c_fd = pigpio_open(I2C_ADDR)) < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus.\n");
        gpioTerminate();
        return 1;
    }

    if (pigpio_set_mode(i2c_fd, PI_MODE_I2C) < 0) {
        fprintf(stderr, "Error: Failed to set I2C mode.\n");
        gpioTerminate();
        return 1;
    }

    if (pigpio_memset(raw_data, 0, sizeof(raw_data)) < 0) {
        fprintf(stderr, "Error: Failed to clear raw data.\n");
        gpioTerminate();
        return 1;
    }

    if (pigpio_memset(crc_data, 0, sizeof(crc_data)) < 0) {
        fprintf(stderr, "Error: Failed to clear crc data.\n");
        gpioTerminate();
        return 1;
    }

    if (pigpio_memset(crc_calc, 0, sizeof(crc_calc)) < 0) {
        fprintf(stderr, "Error: Failed to clear crc calc data.\n");
        gpioTerminate();
        return 1;
    }

    if (pigpio_memset(timestamp, 0, sizeof(timestamp)) < 0) {
        fprintf(stderr, "Error: Failed to clear timestamp.\n");
        gpioTerminate();
        return 1;
    }

    if ((csv_file_handle = fopen(csv_file, "a")) == NULL) {
        fprintf(stderr, "Error: Failed to open file for writing.\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        if (pigpio_memset(raw_data, 0, sizeof(raw_data)) < 0) {
            fprintf(stderr, "Error: Failed to clear raw data.\n");
            gpioTerminate();
            return 1;
        }

        if (pigpio_memset(crc_data, 0, sizeof(crc_data)) < 0) {
            fprintf(stderr, "Error: Failed to clear crc data.\n");
            gpioTerminate();
            return 1;
        }

        if (pigpio_memset(crc_calc, 0, sizeof(crc_calc)) < 0) {
            fprintf(stderr, "Error: Failed to clear crc calc data.\n");
            gpioTerminate();
            return 1;
        }

        if (pigpio_memset(timestamp, 0, sizeof(timestamp)) < 0) {
            fprintf(stderr, "Error: Failed to clear timestamp.\n");
            gpioTerminate();
            return 1;
        }

        if (pigpio_read(i2c_fd, I2C_ADDR, I2C_TIMEOUT_MS, raw_data, sizeof(raw_data)) < 0) {
            fprintf(stderr, "Error: Failed to read data from I2C bus.\n");
            gpioTerminate();
            return 1;
        }

        if (pigpio_read(i2c_fd, I2C_ADDR, I2C_TIMEOUT_MS, crc_data, sizeof(crc_data)) < 0) {
            fprintf(stderr, "Error: Failed to read crc data from I2C bus.\n");
            gpioTerminate();
            return 1;
        }

        if (pigpio_calculate_crc8(crc_data, sizeof(crc_data), crc_calc) < 0) {
            fprintf(stderr, "Error: Failed to calculate crc8 checksum.\n");
            gpioTerminate();
            return 1;
        }

        if (memcmp(crc_data, crc_calc, sizeof(crc_data)) != 0) {
            fprintf(stderr, "Error: CRC8 checksum validation failed.\n");
            gpioTerminate();
            return 1;
        }

        if (pigpio_memset(timestamp, 0, sizeof(timestamp)) < 0) {
            fprintf(stderr, "Error: Failed to clear timestamp.\n");
            gpioTerminate();
            return 1;
        }

        if (pigpio_read(i2c_fd, I2C_ADDR, I2C_TIMEOUT_MS, timestamp, sizeof(timestamp)) < 0) {
            fprintf(stderr, "Error: Failed to read timestamp from I2C bus.\n");
            gpioTerminate();
            return 1;
        }

        time_t now = time(NULL);
        struct tm* timeinfo = localtime(&now);
        strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", timeinfo);

        if (fprintf(csv_file_handle, "%s,%s,%s\n", timestamp,
                     (char*)&raw_data[0], (char*)&raw_data[1]) < 0) {
            fprintf(stderr, "Error: Failed to write to CSV file.\n");
            gpioTerminate();
            return 1;
        }

        usleep(15000); // Wait for 15 seconds

        if (pigpio_memset(timestamp, 0, sizeof(timestamp)) < 0) {
            fprintf(stderr, "Error: Failed to clear timestamp.\n");
            gpioTerminate();
            return 1;
        }

        if (pigpio_memset(timestamp, 0, sizeof(timestamp)) < 0) {
            fprintf(stderr, "Error: Failed to clear timestamp.\n");
            gpioTerminate();
            return 1;
        }

        if (pigpio_read(i2c_fd, I2C_ADDR, I2C_TIMEOUT_MS, timestamp, sizeof(timestamp)) < 0) {
            fprintf(stderr, "Error: Failed to read timestamp from I2C bus.\n");
            gpioTerminate();
            return 1;
        }

        time_t now = time(NULL);
        struct tm* timeinfo = localtime(&now);
        strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", timeinfo);

        if (fprintf(csv_file_handle, "%s,%s,%s\n", timestamp,
