        return 1;
    }

    if (pi_set_speed(I2C_BUS_NUM, 100000) < 0) {
        fprintf(stderr, "Error: Failed to set I2C speed.\n");
        return 1;
    }

    if (pi_address(I2C_BUS_NUM, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error: Failed to set I2C address.\n");
        return 1;
    }

    if (pi_open_i2c_bus(I2C_BUS_NUM) < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus.\n");
        return 1;
    }

    if ((i2c_fd = pi_open_i2c_device(I2C_BUS_NUM, I2C_ADDRESS)) < 0) {
        fprintf(stderr, "Error: Failed to open I2C device.\n");
        return 1;
    }

    if (pi_write_i2c_block_data(i2c_fd, 0x00, &pressure_data, 1, &i2c_data) < 0) {
        fprintf(stderr, "Error: Failed to write to I2C device.\n");
        return 1;
    }

    if (pi_write_i2c_block_data(i2c_fd, 0x03, &pressure_data[1], 1, &i2c_data) < 0) {
        fprintf(stderr, "Error: Failed to write to I2C device.\n");
        return 1;
    }

    if (pi_read_i2c_block_data(i2c_fd, 0x03, pressure_data, 3, &i2c_data) < 0) {
