        return 1;
    }

    if (pi_calculate_crc8(pressure_data, 3, crc_data) < 0) {
        fprintf(stderr, "Error: Failed to calculate CRC8.\n");
        return 1;
    }

    if (memcmp(crc_data, crc_calculated, 4) != 0) {
        fprintf(stderr, "Error: CRC8 failed.\n");
        return 1;
    }

    raw_pressure = (float)pressure_data[0] / 10.0;
    pressure_scale_factor = 60.0;
    raw_pressure *= pressure_scale_factor;

    if (pi_set_i2c_clock(I2C_BUS_NUM, 100000) < 0) {
        fprintf(stderr, "Error: Failed to set I2C clock.\n");
        return 1;
    }

    if (pi_set_mode(I2C_BUS_NUM, I2C_MODE_SLAVE) < 0) {
        fprintf(stderr, "Error: Failed to set I2C mode.\n");
        return 1;
    }

    if (pi_write_i2c_block_data(i2c_fd, 0x01, &raw_pressure, sizeof(raw_pressure), &i2c_data) < 0) {
        fprintf(stderr, "Error: Failed to write to I2C device.\n");
        return 1;
    }

    if (pi_write_i2c_block_data(i2c_fd, 0x04, &raw_pressure, sizeof(raw_pressure), &i2c_data) < 0) {
        fprintf(stderr, "Error: Failed to write to I2C device.\n");
        return 1;
    }

    if (pi_read_i2c_block_data(i2c_fd, 0x04, pressure_data, 3, &i2c_data) < 0) {
        fprintf(stderr, "Error: Failed to read from I2C device.\n");
        return 1;
    }

    if (pi_calculate_crc8(pressure_data, 3, crc_data) < 0) {
        fprintf(stderr, "Error: Failed to calculate CRC8.\n");
        return 1;
    }

    if (memcmp(crc_data, crc_calculated, 4) != 0) {
        fprintf(stderr, "Error: CRC8 failed.\n");
        return 1;
    }

    if (pi_close_i2c_device(i2c_fd) < 0) {
        fprintf(stderr, "Error: Failed to close I2C device.\n");
        return 1;
