#define I2C_BUS_NUM 1
#define SLAVE_ADDRESS 0x28

int main() {
    int fd;
    int ret;
    int fan_duty_cycle = 0;
    uint16_t raw_flow_reading;
    uint16_t flow_reading;
    float flow_rate;
    float fan_duty_cycle_percent;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    if (gpioSetMode(18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO 18 as hardware PWM\n");
        return 1;
    }

    if ((fd = open("/dev/pigpio", O_RDWR)) < 0) {
        fprintf(stderr, "Error opening I2C device file\n");
        return 1;
    }

    if ((ret = ioctl(fd, PI_SET_MODE, I2C_BUS_NUM)) < 0) {
        fprintf(stderr, "Error setting I2C bus number\n");
        return 1;
    }

    if ((ret = ioctl(fd, PI_SET_SPEED, 100000)) < 0) {
        fprintf(stderr, "Error setting I2C speed\n");
        return 1;
    }

    // Open I2C device file
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Error opening I2C device file\n");
        return 1;
    }

    if ((ret = ioctl(fd, PI_SET_ADDRESS, SLAVE_ADDRESS)) < 0) {
        fprintf(stderr, "Error setting I2C slave address\n");
        return 1;
    }

    if ((ret = ioctl(fd, PI_GET_REPORT, &raw_flow_reading)) < 0) {
        fprintf(stderr, "Error reading raw flow reading\n");
        return 1;
    }

    // Read the sensor data
    if ((ret = ioctl(fd, PI_GET_FLOW_READING, &flow_reading)) < 0) {
        fprintf(stderr, "Error reading flow reading\n");
        return 1;
    }

    // Compute flow rate
    flow_rate = (float)flow_reading << 2;

    // Scale the fan's PWM duty cycle
    fan_duty_cycle_percent = (float)flow_rate / 1638.0;

    // Set the PWM duty cycle
    if (gpioSetPWM(18, fan_duty_cycle_percent) < 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return 1;
    }

    // Sample the sensor every 100 ms
    struct timespec ts;
    gettimeofday(&ts, NULL);
    struct timeval tv;
    tv.tv_sec = ts.tv_sec;
    tv.tv_usec = ts.tv_usec;

    while (1) {
        // Wait for 100 ms
        nanosleep(&tv, &ts);

        // Log the sensor reading
        char log_line[50];
        snprintf(log_line, sizeof(log_line), "%.2f,%.2f\n", ts.tv_sec, flow_reading);
        if (write(1, log_line, strlen(log_line)) < 0) {
            fprintf(stderr, "Error writing to log file\n");
            return 1;
        }

        // Close the log file
        if (close(1) < 0) {
            fprintf(stderr, "Error closing log file\n");
            return 1;
        }

        // Shutdown the fan
        if (gpioSetPWM(18, 0) < 0) {
            fprintf(stderr, "Error setting PWM duty cycle to 0\n");
            return 1;
        }

        // Close the I2C handle
        if (close(fd) < 0) {
            fprintf(stderr, "Error closing I2C handle\n");
            return 1;
        }

        // Terminate pigpio
        gpioTerminate();

        break;
    }

    return 0;
}

