#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define I2C_BUS_1 1
#define I2C_ADDRESS 0x21

int main(int argc, char *argv[]) {
    int fd;
    int i;
    int16_t pressure_raw[9];
    int16_t temperature_raw[9];
    int16_t scale_factor_raw;
    int16_t pressure_crc[9];
    int16_t temperature_crc[9];
    int16_t scale_factor_crc;
    int16_t crc_result;
    uint8_t pressure_msb, pressure_lsb, pressure_crc_word[2];
    uint8_t temperature_msb, temperature_lsb, temperature_crc_word[2];
    uint8_t scale_factor_msb, scale_factor_lsb, scale_factor_crc;
    uint8_t i2c_error;

    if (argc < 2) {
        printf("Usage: %s <sampling_interval>\n", argv[0]);
        return 1;
    }

    // Initialize the I2C bus
    if (gpioInitialise() < 0) {
        printf("Error: Failed to initialize I2C bus.\n");
        return 1;
    }

    // Open the I2C device file
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        printf("Error: Failed to open I2C device file.\n");
        gpioTerminate();
        return 1;
    }

    // Set the I2C bus address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        printf("Error: Failed to set I2C bus address.\n");
        gpioTerminate();
        return 1;
    }

    // Set the sampling interval
    if (sscanf(argv[1], "%d", &sampling_interval) != 1) {
        printf("Error: Invalid sampling interval.\n");
        gpioTerminate();
        return 1;
    }

    // Start the sensor
    if (gpioSetPWMFrequency(GPIO_PWM_FREQ_HZ, 100) < 0) {
        printf("Error: Failed to set PWM frequency.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWM(GPIO_PWM_CHANNEL_1, 0, 0) < 0) {
        printf("Error: Failed to set PWM duty.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWM(GPIO_PWM_CHANNEL_1, 0, (sampling_interval * 100) / 1000) < 0) {
        printf("Error: Failed to set PWM duty.\n");
        gpioTerminate();
        return 1;
    }

    // Start the sensor
    if (gpioSetMode(GPIO_MODE_OUTPUT) < 0) {
        printf("Error: Failed to set I2C device as output.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(GPIO_PWM_CHANNEL_1, 0) < 0) {
        printf("Error: Failed to start I2C device.\n");
        gpioTerminate();
        return 1;
    }

    // Send the continuous-measurement command bytes
    if (gpioSetMode(GPIO_MODE_OUTPUT) < 0) {
        printf("Error: Failed to set I2C device as output.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(GPIO_PWM_CHANNEL_1, 0) < 0) {
        printf("Error: Failed to start I2C device.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(I2C_ADDRESS, 0) < 0) {
        printf("Error: Failed to start I2C device.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(I2C_ADDRESS + 1, 0x36) < 0) {
        printf("Error: Failed to start I2C device.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(I2C_ADDRESS + 2, 0x2F) < 0) {
        printf("Error: Failed to start I2C device.\n");
        gpioTerminate();
        return 1;
    }

    // Poll 9 bytes per reading
    for (i = 0; i < 9; i++) {
        pressure_raw[i] = 0;
        temperature_raw[i] = 0;
        scale_factor_raw = 0;

        // Read pressure
        if (gpioRead(GPIO_PWM_CHANNEL_1, &pressure_msb, 1) < 0) {
            printf("Error: Failed to read pressure.\n");
            gpioTerminate();
            return 1;
        }

        if (gpioRead(GPIO_PWM_CHANNEL_1, &pressure_lsb, 1) < 0) {
            printf("Error: Failed to read pressure.\n");
            gpioTerminate();
            return 1;
        }

        pressure_raw[i] = pressure_msb << 8 | pressure_lsb;

        // Read temperature
        if (gpioRead(GPIO_PWM_CHANNEL_1, &temperature_msb, 1) < 0) {
            printf("Error: Failed to read temperature.\n");
            gpioTerminate();
            return 1;
        }

        if (gpioRead(GPIO_PWM_CHANNEL_1, &temperature_lsb, 1) < 0) {
            printf("Error: Failed to read temperature.\n");
            gpioTerminate();
            return 1;
        }

        temperature_raw[i] = temperature_msb << 8 | temperature_lsb;

        // Read scale factor
        if (gpioRead(GPIO_PWM_CHANNEL_1, &scale_factor_msb, 1) < 0) {
            printf("Error: Failed to read scale factor.\n");
            gpioTerminate();
            return 1;
        }

        if (gpioRead(GPIO_PWM_CHANNEL_1, &scale_factor_lsb, 1) < 0) {
            printf("Error: Failed to read scale factor.\n");
            gpioTerminate();
            return 1;
        }

        scale_factor_raw = scale_factor_msb << 8 | scale_factor_lsb;

        // Read CRC
        if (gpioRead(GPIO_PWM_CHANNEL_1, &pressure_crc_word[0], 1) < 0) {
            printf("Error: Failed to read CRC.\n");
            gpioTerminate();
            return 1;
        }

        if (gpioRead(GPIO_PWM_CHANNEL_1, &pressure_crc_word[1], 1) < 0) {
            printf("Error: Failed to read CRC.\n");
            gpioTerminate();
            return 1;
        }

        pressure_crc_word[0] = pressure_crc_word[0] << 8 | pressure_crc_word[1];
        pressure_crc_word[1] = 0;

        // Read CRC
        if (gpioRead(GPIO_PWM_CHANNEL_1, &temperature_crc_word[0], 1) < 0) {
            printf("Error: Failed to read CRC.\n");
            gpioTerminate();
            return 1;
        }

        if (gpioRead(GPIO_PWM_CHANNEL_1, &temperature_crc_word[1], 1) < 0) {
            printf("Error: Failed to read CRC.\n");
            gpioTerminate();
            return 1;
        }

        temperature_crc_word[0] = temperature_crc_word[0] << 8 | temperature_crc_word[1];
        temperature_crc_word[1] = 0;

        // Convert raw pressure to pressure_pa
        if (scale_factor_raw != 0) {
            pressure_pa = pressure_raw / scale_factor_raw;
        } else {
            pressure_pa = 0;
        }

        // Convert raw temperature to temperature_pa
        if (temperature_crc_word[0] != 0 || temperature_crc_word[1] != 0) {
            temperature_pa = temperature_raw / (1 << temperature_crc_word[1]);
        } else {
            temperature_pa = temperature_raw;
        }

        // Log each timestamped reading
        printf("Pressure: %.2f, Temperature: %.2f, Scale Factor: %.2f\n", pressure_pa, temperature_pa, scale_factor_raw);

        // Wait for the next reading
        usleep(sampling_interval * 1000);
    }

    // Stop the sensor
    if (gpioSetPWM(GPIO_PWM_CHANNEL_1, 0, 0) < 0) {
        printf("Error: Failed to stop PWM duty.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(GPIO_PWM_CHANNEL_1, 0) < 0) {
        printf("Error: Failed to stop I2C device.\n");
        gpioTerminate();
        return 1;
    }

    // Clean up
    gpioTerminate();
    return 0;
}

