```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS_1 1
#define I2C_ADDRESS 0x60

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msgs[2];
    struct i2c_rdwr_req i2c_reqs[2];
    struct timespec start_time, end_time;
    char buffer[10];
    int i;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    // Set I2C bus 1 as the default bus
    if (gpioSetBusses(I2C_BUS_1) < 0) {
        fprintf(stderr, "Error: Failed to set I2C bus 1 as default\n");
        gpioTerminate();
        return 1;
    }

    // Open the I2C device file
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Error: Failed to open I2C device file\n");
        gpioTerminate();
        return 1;
    }

    // Set the I2C device to the default I2C bus
    if (gpioSetDevice(fd) < 0) {
        fprintf(stderr, "Error: Failed to set I2C device\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set the I2C address of the sensor
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error: Failed to set I2C address of the sensor\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set the I2C transfer mode to 7-bit addressing
    if (ioctl(fd, I2C_SLAVE_MODE, 0) < 0) {
        fprintf(stderr, "Error: Failed to set I2C transfer mode to 7-bit addressing\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Perform I2C read/write operations
    for (i = 0; i < 2; i++) {
        // Set the I2C transfer mode to 7-bit addressing
        if (ioctl(fd, I2C_SLAVE_MODE, 0) < 0) {
            fprintf(stderr, "Error: Failed to set I2C transfer mode to 7-bit addressing\n");
            close(fd);
            gpioTerminate();
            return 1;
        }

        // Start the timer
        start_time.tv_sec = 0;
        start_time.tv_nsec = 1000000;

        // Perform I2C read/write operations
        if (i == 0) {
            // Perform I2C read operation
            if (ioctl(fd, I2C_RDWR, &msgs[0]) < 0) {
                fprintf(stderr, "Error: Failed to perform I2C read operation\n");
                close(fd);
                gpioTerminate();
                return 1;
            }

            // Get the number of bytes read
            int bytes_read = msgs[0].len;

            // Set the buffer for the read data
            if (read(fd, &buffer, bytes_read) != bytes_read) {
                fprintf(stderr, "Error: Failed to read data from I2C device\n");
                close(fd);
                gpioTerminate();
                return 1;
            }

            // Stop the timer
            end_time.tv_sec = 0;
            end_time.tv_nsec = 1000000;
            nanosleep(&end_time, &start_time);
        } else {
            // Perform I2C write operation
            if (ioctl(fd, I2C_RDWR, &msgs[0]) < 0) {
                fprintf(stderr, "Error: Failed to perform I2C write operation\n");
                close(fd);
                gpioTerminate();
                return 1;
            }

            // Get the number of bytes written
            int bytes_written = msgs[0].len;

            // Set the buffer for the write data
            if (write(fd, &buffer, bytes_written) != bytes_written) {
                fprintf(stderr, "Error: Failed to write data to I2C device\n");
                close(fd);
                gpioTerminate();
                return 1;
            }
        }
    }

    // Stop the timer
    end_time.tv_sec = 0;
    end_time.tv_nsec = 1000000;
    nanosleep(&end_time, &start_time);

    // Release the I2C device
    if (ioctl(fd, I2C_RDWR, NULL) < 0) {
        fprintf(stderr, "Error: Failed to release I2C device\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Clean up pigpio library
