#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x25
#define I2C_SDA_PIN 2
#define I2C_SCL_PIN 3

#define I2C_COMMAND_PRESSURE 0x362F
#define I2C_COMMAND_TEMPERATURE 0x0000
#define I2C_COMMAND_CRC_8 0x00

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

#define I2C_TIMEOUT_MS 45
#define I2C_READ_TIMEOUT_MS 1000

#define BUF_SIZE 9

void i2c_init() {
    int i;
    for (i = 0; i < I2C_COMMAND_PRESSURE; i++) {
        if (i2c_smbus_write_byte_data(I2C_ADDR, I2C_SDA_PIN, I2C_COMMAND_PRESSURE) < 0) {
            fprintf(stderr, "Failed to write command to I2C bus.\n");
            exit(EXIT_FAILURE);
        }
        if (i2c_smbus_read_byte_data(I2C_ADDR, I2C_SCL_PIN, &i) < 0) {
            fprintf(stderr, "Failed to read command from I2C bus.\n");
            exit(EXIT_FAILURE);
        }
    }
}

void i2c_write_byte(int fd, uint8_t data) {
    if (write(fd, &data, 1) < 0) {
        fprintf(stderr, "Failed to write byte to I2C bus.\n");
        exit(EXIT_FAILURE);
    }
}

void i2c_read_byte(int fd, uint8_t* data) {
    if (read(fd, data, 1) < 0) {
        fprintf(stderr, "Failed to read byte from I2C bus.\n");
        exit(EXIT_FAILURE);
    }
}

void i2c_read_bytes(int fd, uint8_t* buffer, int size) {
    int bytes_read = 0;
    while (bytes_read < size) {
        if (read(fd, buffer + bytes_read, 1) < 0) {
            fprintf(stderr, "Failed to read data from I2C bus.\n");
            exit(EXIT_FAILURE);
        }
        bytes_read++;
    }
}

void i2c_write_bytes(int fd, const uint8_t* buffer, int size) {
    int bytes_written = 0;
    while (bytes_written < size) {
        if (write(fd, buffer + bytes_written, 1) < 0) {
            fprintf(stderr, "Failed to write data to I2C bus.\n");
            exit(EXIT_FAILURE);
        }
        bytes_written++;
    }
}

void i2c_check_crc8(uint8_t* data) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < 9; i++) {
        crc = crc ^ data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
        if (crc == CRC8_INITIAL_VALUE) {
            printf("CRC8: OK\n");
        } else {
            printf("CRC8: Failed\n");
        }
    }
}

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data i2c_data;

    i2c_init();

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device.\n");
        exit(EXIT_FAILURE);
    }

    i2c_write_byte(fd, I2C_COMMAND_PRESSURE);
    i2c_write_byte(fd, I2C_COMMAND_CRC_8);

    i2c_write_bytes(fd, (uint8_t*) &I2C_SDA_PIN, 1);
    i2c_write_bytes(fd, (uint8_t*) &I2C_SCL_PIN, 1);

    i2c_read_bytes(fd, (uint8_t*) &i2c_data.wr_buf, I2C_READ_TIMEOUT_MS);
    i2c_read_bytes(fd, (uint8_t*) &i2c_data.rd_buf, I2C_READ_TIMEOUT_MS);

    i2c_read_bytes(fd, (uint8_t*) &i2c_data.wr_buf[2], 3);

    i2c_check_crc8(&i2c_data.rd_buf[2]);

    i2c_read_bytes(fd, (uint8_t*) &i2c_data.wr_buf[2], 3);

    i2c_read_bytes(fd, (uint8_t*) &i2c_data.rd_buf[2], 3);

    i2c_check_crc8(&i2c_data.rd_buf[2]);

    i2c_read_bytes(fd, (uint8_t*) &i2c_data.wr_buf[2], 3);

    i2c_read_bytes(fd, (uint8_t*) &i2c_data.rd_buf[2], 3);

    i2c_check_crc8(&i2c_data.rd_buf[2]);

    close(fd);

