        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    // Open the I2C bus
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set the I2C address of the sensor
    if (ioctl(fd, I2C_SLAVE, SDP800_ADDRESS) < 0) {
        fprintf(stderr, "Error: Failed to set I2C address of the sensor\n");
        gpioTerminate();
        return 1;
    }

    // Set the continuous-measurement command bytes
    if (ioctl(fd, I2C_RDWR, SDP800_CMD_READ_MEASUREMENTS) < 0) {
        fprintf(stderr, "Error: Failed to set continuous-measurement command bytes\n");
        gpioTerminate();
        return 1;
    }

    // Wait for 8 ms to allow the sensor to complete the measurement
    if (nanosleep(&start_time, NULL) < 0) {
        fprintf(stderr, "Error: Failed to wait for 8 ms\n");
        gpioTerminate();
        return 1;
    }

    // Read 3 bytes: 2 data bytes and 1 CRC byte
    if (ioctl(fd, I2C_RDWR, SDP800_CMD_READ_MEASUREMENTS_WITH_CRC) < 0) {
        fprintf(stderr, "Error: Failed to read 3 bytes from the sensor\n");
        gpioTerminate();
        return 1;
    }

    // Verify the CRC-8 checksum
    if (memcmp(&data.wr_buf[2], &data.wr_buf[0], 2) != 0) {
        fprintf(stderr, "Error: CRC-8 checksum verification failed\n");
        gpioTerminate();
        return 1;
    }

    // Convert the raw 16-bit signed value to pressure in Pa
    pressure = (int)((data.wr_buf[0] << 8) + data.wr_buf[1]);
    pressure /= 60.0;

    // Log the pressure reading and a timestamp
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&end_time.tv_sec)) == NULL) {
        fprintf(stderr, "Error: Failed to format timestamp\n");
        gpioTerminate();
        return 1;
    }

    // Write the pressure reading and timestamp to the CSV file
    if ((csv_file = fopen(csv_file_name, "a")) == NULL) {
        fprintf(stderr, "Error: Failed to open CSV file\n");
        gpioTerminate();
        return 1;
    }

    if (fprintf(csv_file, "%s,%s\n", timestamp, &pressure) < 0) {
        fprintf(stderr, "Error: Failed to write to CSV file\n");
        fclose(csv_file);
        gpioTerminate();
        return 1;
    }

    // Close the CSV file
    fclose(csv_file);

    // Release resources
    gpioTerminate();

    return 0;
}

