#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <string.h>
#include <time.h>

#include <gpiod.h>

#define I2C_BUS_NUM 1
#define I2C_ADDRESS 0x40

int main() {
    int i2c_fd;
    struct gpiod_i2c_config i2c_config = GPIOD_I2C_DEFAULT_CONFIG(I2C_BUS_NUM);
    struct gpiod_i2c_data i2c_data;

    // Initialize pigpio library
    if (gpiod_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus
    if (gpiod_i2c_open(&i2c_config, I2C_BUS_NUM, &i2c_data) < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpiod_exit();
        return 1;
    }

    // Open pressure sensor
    if (gpiod_i2c_open_device(&i2c_data, I2C_ADDRESS, &i2c_fd) < 0) {
        fprintf(stderr, "Error: Failed to open pressure sensor\n");
        gpiod_i2c_close(&i2c_data);
        gpiod_exit();
        return 1;
    }

    // Read pressure every 1 second
    while (1) {
        struct gpiod_i2c_data i2c_data;
        uint16_t pressure_raw;

        if (gpiod_i2c_read_block_data(i2c_fd, &i2c_data, &pressure_raw, 1) < 0) {
            fprintf(stderr, "Error: Failed to read pressure sensor\n");
            gpiod_i2c_close(&i2c_data);
            gpiod_i2c_close(&i2c_data);
            gpiod_exit();
            return 1;
        }

        // Convert raw pressure to kPa
        uint16_t pressure_kPa = (pressure_raw << 1) / 10;

        // Check pressure range
        if (pressure_kPa < 200 || pressure_kPa > 250) {
            fprintf(stderr, "Warning: Pressure reading outside safe range (200-250 kPa)\n");
        }

        // Log pressure and timestamp
        struct timeval now;
        gettimeofday(&now, NULL);
        char timestamp[32];
        snprintf(timestamp, sizeof(timestamp), "%s.%06u", ctime(&now.tv_sec), (unsigned int)now.tv_usec);
        char pressure_kPa_str[20];
        snprintf(pressure_kPa_str, sizeof(pressure_kPa_str), "%.2f", pressure_kPa);
        printf("timestamp,pressure_kPa\n%s,%s\n", timestamp, pressure_kPa_str);

        // Flush and close log file
        if (fclose(stdout) != 0) {
            fprintf(stderr, "Error: Failed to flush log file\n");
            gpiod_i2c_close(&i2c_data);
            gpiod_i2c_close(&i2c_data);
            gpiod_exit();
            return 1;
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    gpiod_i2c_close(&i2c_data);
    gpiod_i2c_close(&i2c_data);
    gpiod_exit();

    return 0;
}

