#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS_NUM 1
#define I2C_SLAVE_ADDR 0x27

int main() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    uint8_t raw_T, raw_H;
    float temperature, humidity;
    char environmental_data_log_path[128] = "environmental_data.log";
    int log_file_size = 0;
    int log_file_max_size = 1048576; // 1 MB in bytes

    // Open the I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C bus speed
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_BUS_NUM) < 0) {
        perror("Error setting I2C bus speed");
        exit(EXIT_FAILURE);
    }

    // Open the I2C device file
    if ((i2c_data.flags = 0) && (i2c_data.flags = ioctl(i2c_fd, I2C_RDWR, I2C_SLAVE_ADDR)) < 0) {
        perror("Error opening I2C device file");
        exit(EXIT_FAILURE);
    }

    // Perform I2C communication
    if (ioctl(i2c_fd, I2C_RDWR, 0) < 0) {
        perror("Error performing I2C communication");
        exit(EXIT_FAILURE);
    }

    // Trigger the measurement
    if (ioctl(i2c_fd, I2C_WRITE, 0x00) < 0) {
        perror("Error triggering measurement");
        exit(EXIT_FAILURE);
    }

    // Wait for the measurement to complete
    sleep(40);

    // Read 4 bytes from the sensor
    if (ioctl(i2c_fd, I2C_RDWR, 0) < 0) {
        perror("Error reading sensor data");
        exit(EXIT_FAILURE);
    }

    // Validate the sensor status bits
    if (ioctl(i2c_fd, I2C_RDWR, 0) < 0) {
        perror("Error reading sensor data");
        exit(EXIT_FAILURE);
    }

    // Convert raw values to temperature and humidity
    raw_T = i2c_data.buf[0];
    raw_H = i2c_data.buf[1];

    // Calculate temperature and humidity
    temperature = raw_T * 165.0 / 16383.0 - 40.0;
    humidity = raw_H * 100.0 / 16383.0;

    // Log the data
    if (log_file_size + strlen(environmental_data_log_path) + 1 >= log_file_max_size) {
        close(i2c_fd);
        unlink(environmental_data_log_path);
        perror("Error truncating log file");
        exit(EXIT_FAILURE);
    }

    snprintf(environmental_data_log_path, sizeof(environmental_data_log_path), "%s/%s",
             log_file_path, environmental_data_log_path);
    FILE *log_file = fopen(environmental_data_log_path, "a");
    if (!log_file) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "Timestamp: %s, Temperature: %.2f, Humidity: %.2f\n",
            strftime(NULL, 0, "%Y-%m-%d %H:%M:%S"), temperature, humidity);
    fclose(log_file);

    // Clean up
    close(i2c_fd);
    unlink(environmental_data_log_path);

    return 0;
}

