        fprintf(stderr, "Error: Failed to set I2C address\n");
        gpioTerminate();
        return 1;
    }

    // Perform high-precision measurement
    if (ioctl(i2c_fd, I2C_RDWR, 0xFD) < 0) {
        fprintf(stderr, "Error: Failed to perform high-precision measurement\n");
        gpioTerminate();
        return 1;
    }

    // Wait for at least 8.5 ms for conversion
    if (ioctl(i2c_fd, I2C_RDWR, 0xFD) < 0) {
        fprintf(stderr, "Error: Failed to wait for conversion\n");
        gpioTerminate();
        return 1;
