    buffer[3] = (char)((buffer[3] << 8) | buffer[4]);
    buffer[4] = (char)((buffer[4] << 8) | buffer[5]);

    float temperature = -45 + 175 * (buffer[2] / 65535.0);
    float humidity = -6 + 125 * (buffer[3] / 65535.0);

