#include <stdint.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDRESS 0x48

// Global variables
uint16_t i2c_buf[BUFFER_SIZE];
size_t i2c_buf_size = 0;
size_t i2c_buf_index = 0;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Check if I2C is available
    if (gpioI2CSetup(I2C_BUS_NUM) < 0) {
        fprintf(stderr, "Failed to set up I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open the I2C device
    gpioI2COpenDevice(I2C_BUS_NUM, I2C_ADDRESS);

    // Initialize circular buffer
    for (size_t i = 0; i < BUFFER_SIZE; i++) {
        i2c_buf[i] = 0;
    }

    // Start the timer for reading temperature
    gpioSetPWMFrequency(I2C_BUS_NUM, PWM_FREQ_HZ);
    gpioPWMOutput(I2C_BUS_NUM, TEMP_PIN);
    gpioPWMStart(I2C_BUS_NUM, TEMP_PIN);

    // Main loop
    while (1) {
        // Wait for 5 seconds
        gpioSleep(5000);

        // Read temperature from the TMP117
        if (gpioI2CReadReg16(I2C_BUS_NUM, TEMP_REG_ID, &i2c_buf[i2c_buf_index]) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        // Convert temperature to °C
        float temperature = i2c_buf[i2c_buf_index] / 0.0078125;

        // Store the temperature reading in the circular buffer
        i2c_buf_index = (i2c_buf_index + 1) % BUFFER_SIZE;
        if (i2c_buf_index == 0) {
            i2c_buf_index = BUFFER_SIZE - 1;
        }

        // Write the temperature to the binary file
        FILE *file = fopen("temperature_log.dat", "ab");
        if (file == NULL) {
            fprintf(stderr, "Failed to open temperature_log.dat\n");
            continue;
        }

        fprintf(file, "%f\n", temperature);
        fclose(file);

        // Flush the buffer to the file and release resources
        gpioPWMStop(I2C_BUS_NUM, TEMP_PIN);
        gpioI2CCloseDevice(I2C_BUS_NUM, I2C_ADDRESS);
        gpioTerminate();

        // Exit the program
        return 0;
    }
}

