#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <stdlib.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_SLAVE_ADDR 0x40

int main() {
    int i2c_fd;
    int gpio_fd;
    int ret;
    char *mag_temp_log_file = "mag_temp_log.csv";

    // Initialize pigpio
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpio_set_mode(GPIO_UNUSED) < 0) {
        fprintf(stderr, "Failed to set GPIO as unused\n");
        return 1;
    }

    if (gpio_set_dir(GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO as output\n");
        return 1;
    }

    if (gpio_set_value(GPIO_OUTPUT, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO to 0\n");
        return 1;
    }

    if (gpio_set_mode(GPIO_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO as input\n");
        return 1;
    }

    if (gpio_set_value(GPIO_INPUT, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO to 1\n");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = pigpio_open_i2c(I2C_BUS_NUM, I2C_SLAVE_ADDR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Open log file
    if ((fp = fopen(mag_temp_log_file, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Initialize variables
    float raw_value = 0.0;
    float field_gauss = 0.0;
    float temp_celsius = 0.0;
    char *log_entry = "NaN,NaN,NaN,NaN";

    // Loop forever
    while (1) {
        // Read sensor values
        ret = pigpio_read_i2c_reg16(i2c_fd, 0x00, &raw_value);
        if (ret < 0) {
            fprintf(stderr, "Failed to read raw value from sensor\n");
            continue;
        }

        field_gauss = raw_value * 0.1;
        temp_celsius = raw_value * 0.01 - 25.0;

        // Log data
        fprintf(fp, "%f,%f,%f,%f\n", field_gauss, temp_celsius, field_gauss, temp_celsius);

        // Write log entry
        fprintf(fp, "%s,%,%,%.2f\n", log_entry, field_gauss, temp_celsius);

        // Clear log entry
        memset(log_entry, ' ', sizeof(log_entry));
    }

    // Close I2C bus
    pigpio_close_i2c(i2c_fd);

    // Close log file
    fclose(fp);

    // Gracefully terminate pigpio
    pigpio_exit();

    return 0;
}

