#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_SCL_PIN 3
#define I2C_SDA_PIN 2

#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

void log_error(const char* message, int timestamp) {
    time_t now = time(NULL);
    char timestamp_str[30];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&now));

    char* log_message = malloc(strlen(message) + strlen(timestamp_str) + 2);
    sprintf(log_message, "%s, %s, %s\n", message, timestamp_str, CRC_8_TABLE[CRC_POLYNOMIAL & 0xFF]);

    FILE* log_file = fopen("sht31d_data.log", "a");
    if (log_file) {
        fputs(log_message, log_file);
        fclose(log_file);
    }

    free(log_message);
}

int main() {
    int i2c_fd;
    int ret;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio", get_last_error());
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = pigpio_open(I2C_BUS_NUM)) < 0) {
        log_error("Failed to open I2C bus", get_last_error());
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    if ((ret = pigpio_set_mode(i2c_fd, I2C_BUS_NUM, I2C_SDA_PIN, I2C_SCL_PIN)) < 0) {
        log_error("Failed to set I2C device mode", get_last_error());
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE* log_file = fopen("sht31d_data.log", "w");
    if (!log_file) {
        log_error("Failed to open log file", get_last_error());
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (pigpio_set_slave(i2c_fd, 0x44) < 0) {
        log_error("Failed to set I2C slave address", get_last_error());
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Perform single-shot, clock-stretching-enabled measurement
    if (pigpio_start_measurement(i2c_fd) < 0) {
        log_error("Failed to start measurement", get_last_error());
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Wait at least 15 ms
    sleep(15);

    // Read 6 bytes: 2 bytes temperature, 1 CRC, and 2 bytes humidity
    uint16_t temp_raw, crc_raw;
    uint16_t hum_raw;

    if (pigpio_read_reg16(i2c_fd, 0x3E, &temp_raw) < 0) {
        log_error("Failed to read temperature register", get_last_error());
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (pigpio_read_reg16(i2c_fd, 0x3F, &crc_raw) < 0) {
        log_error("Failed to read CRC register", get_last_error());
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (pigpio_read_reg16(i2c_fd, 0x3E, &hum_raw) < 0) {
        log_error("Failed to read humidity register", get_last_error());
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Validate each CRC-8
    uint8_t crc_expected = CRC_8_TABLE[CRC_POLYNOMIAL & 0xFF] ^ CRC_INITIAL_VALUE;

    if (crc_raw != crc_expected) {
        log_error("CRC-8 validation failed", get_last_error());
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Convert raw values
    float temperature = -45 + 175 * temp_raw / 65535.0;
    float humidity = 100 * hum_raw / 65535.0;

    // Log the readings
    char timestamp_str[30];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&now));

    char* log_message = malloc(strlen("Temperature: ") + strlen(timestamp_str) + strlen("Humidity: ") + 2);
    sprintf(log_message, "Temperature: %.2f C, Humidity: %.2f%%", temperature, humidity);

    if (log_file) {
        fputs(log_message, log_file);
        fclose(log_file);
    }

    free(log_message);

    // Close I2C handle
    if (pigpio_stop_measurement(i2c_fd) < 0) {
        log_error("Failed to stop measurement", get_last_error());
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Close log file
    if (fclose(log_file) < 0) {
        log_error("Failed to close log file", get_last_error());
        gpioTerminate();
        return 1;
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

