#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define I2C_BUS_1 1
#define I2C_ADDR_SLAVE 0x64
#define I2C_ADDR_SENSOR 0x65

