void log_message(const char *message) {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    char timestamp[80];
    snprintf(timestamp, sizeof(timestamp), "%s %s %d\n",
             ctime_r(&now.tv_sec, timestamp, NULL),
             ctime_r(&now.tv_sec, &now.tv_nsec, timestamp),
             now.tv_nsec / 1000000);
    fprintf(stderr, "%s\n", timestamp);
}

int main() {
