        log_message("Failed to open I2C bus");
        return 1;
    }

    if ((rc = gpiod_i2c_set_slave_addr(i2c_fd, I2C_I2C_SLAVE_ADDR)) < 0) {
        log_message("Failed to set I2C slave address");
        goto cleanup;
    }

    if ((rc = gpiod_i2c_set_function(i2c_fd, GPIGPIO_FUNCTION_I2C)) < 0) {
        log_message("Failed to set I2C function");
        goto cleanup;
    }

    if ((rc = gpiod_i2c_set_output_min(i2c_fd, I2C_OUTPUT_MIN)) < 0) {
        log_message("Failed to set I2C output min");
        goto cleanup;
