#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x25

int main() {
    int rc;
    int i;
    int16_t pressure, temperature;
    uint8_t crc8;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_rdwr_ioctl_data crc_data;
    char log_file[128];
    FILE *log_fp;

    // Initialize I2C bus
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        return 1;
    }

    // Open log file
    snprintf(log_file, sizeof(log_file), "airflow.log");
    log_fp = fopen(log_file, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set I2C address
    if (ioctl(I2C_BUS_NUM, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInit() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set I2C speed
    if (gpioSetSpeed(1000) < 0) {
        fprintf(stderr, "Failed to set I2C speed\n");
        return 1;
    }

    // Set GPIO for Sensirion SDP810-500Pa sensor
    if (gpioSetMode(GPIO_SDP810_500_PA, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO for Sensirion SDP810-500Pa sensor\n");
        return 1;
    }

    // Set sensor address
    if (gpioSetAddress(I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set sensor address\n");
        return 1;
    }

    // Set differential pressure command
    if (gpioSetValue(GPIO_SDP810_500_PA, 0) < 0) {
        fprintf(stderr, "Failed to set differential pressure command\n");
        return 1;
    }

    // Set first measurement delay
    if (gpioSetValue(GPIO_SDP810_500_PA, 1) < 0) {
        fprintf(stderr, "Failed to set first measurement delay\n");
        return 1;
    }

    // Wait for 45 ms
    if (gpioDelay(45) < 0) {
        fprintf(stderr, "Failed to wait for 45 ms\n");
        return 1;
    }

    // Send command 0x362F
    if (gpioSetValue(GPIO_SDP810_500_PA, 1) < 0) {
        fprintf(stderr, "Failed to send command 0x362F\n");
        return 1;
    }

    // Wait for CRC8 byte
    if (gpioDelay(1) < 0) {
        fprintf(stderr, "Failed to wait for CRC8 byte\n");
        return 1;
    }

    // Read 9 bytes containing 3 words
    if (gpioSetValue(GPIO_SDP810_500_PA, 1) < 0) {
        fprintf(stderr, "Failed to send command 0x362F\n");
        return 1;
    }

    // Read pressure, temperature, and status
    if (gpioReadReg16(GPIO_SDP810_500_PA, GPIO_SDP810_500_PA_SDP_P_ADDR) < 0) {
        fprintf(stderr, "Failed to read pressure\n");
        return 1;
    }
    pressure = gpioReadReg16(GPIO_SDP810_500_PA, GPIO_SDP810_500_PA_SDP_P_DATA);

    if (gpioReadReg16(GPIO_SDP810_500_PA, GPIO_SDP810_500_PA_SDP_T_ADDR) < 0) {
        fprintf(stderr, "Failed to read temperature\n");
        return 1;
    }
    temperature = gpioReadReg16(GPIO_SDP810_500_PA, GPIO_SDP810_500_PA_SDP_T_DATA);

    if (gpioReadReg8(GPIO_SDP810_500_PA, GPIO_SDP810_500_PA_SDP_C_ADDR) < 0) {
        fprintf(stderr, "Failed to read CRC8\n");
        return 1;
    }
    crc8 = gpioReadReg8(GPIO_SDP810_500_PA, GPIO_SDP810_500_PA_SDP_C_DATA);

    // Validate CRC8
    if (crc8 != 0x31) {
        fprintf(stderr, "CRC8 mismatch\n");
        return 1;
    }

    // Convert raw pressure and temperature
    pressure = (pressure * 60) / 10;
    temperature = (temperature * 200) / 10;

    // Log the data
