            exit(EXIT_FAILURE);
        }

        // Combine the MSB and LSB, right-shift the result by 4 bits, and convert to Celsius
        temperature = (i2c_msgs[0].msg[0] << 8) | i2c_msgs[0].msg[1];
        celsius_temperature = (temperature >> 4) * 0.0625;

        // Check if the temperature exceeds the hysteresis threshold
        if (celsius_temperature > hysteresis_threshold) {
            led_gpio_value = 1;
        } else {
            led_gpio_value = 0;
        }

        // Set the LED GPIO value
        ret = gpiod_set_value(LED_GPIO_NUMBER, led_gpio_value);
