            perror("Failed to set LED GPIO value");
            exit(EXIT_FAILURE);
        }

        // Check for repeated I2C failures
        if (ret < 0) {
            perror("Failed to set LED GPIO value");
            exit(EXIT_FAILURE);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Release all libgpiod resources
    gpiod_term();

    return 0;
}

