    struct i2c_rdwr_ioctl_data data;
    struct i2c_rdwr_ioctl_data_setup setup;
    struct timespec start_time, end_time;
    char timestamp[32];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C bus address
    if ((i2c_addr = i2cSetClockSpeed(fd, 100000)) < 0) {
        fprintf(stderr, "Error: Failed to set I2C clock speed\n");
        goto close_fd;
    }

    // Open I2C device file
    if ((i2c_fd = i2cOpen(i2c_addr)) < 0) {
        fprintf(stderr, "Error: Failed to open I2C device file\n");
        goto close_fd;
    }

    // Set I2C device file descriptor
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error: Failed to set I2C device file descriptor\n");
        goto close_i2c_fd;
    }

    // Set up I2C communication
    memset(&data, 0, sizeof(data));
    memset(&setup, 0, sizeof(setup));
    setup.length = 2;
    setup.addr = I2C_ADDRESS;
    setup.flags = 0;
    setup.timeout = 20000;
    data.flags = 0;
    data.timeout = 20000;
    data.rdwr_data = (void *)pressure_data;
    data.wr_data_ptr = pressure_data;
    data.rd_data_ptr = pressure_data;
    data.timeout_usecs = 0;
    data.io_timeout_usecs = 20000;
    data.io_flags = 0;
    data.io_flags |= I2C_M_RD;
    data.io_flags |= I2C_M_WR;

    // Send continuous-measurement command
    if (ioctl(i2c_fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "Error: Failed to send continuous-measurement command\n");
        goto close_i2c_fd;
    }

    // Wait at least 45 ms
    start_time.tv_sec = 0;
    start_time.tv_nsec = 1000000;
    nanosleep(&start_time, &end_time);

    // Read 9 bytes: 2 bytes differential pressure plus 1 CRC byte, 2 bytes temperature plus 1 CRC byte, and 3 bytes of scale-factor data
    if (ioctl(i2c_fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "Error: Failed to read 9 bytes\n");
        goto close_i2c_fd;
    }

    // Validate CRC-8 for pressure and temperature readings
    if (crc8(0, pressure_data, 2) != crc8(0, pressure_data + 2, 2)) {
