        fprintf(stderr, "Error: CRC-8 validation failed for temperature reading\n");
        goto close_i2c_fd;
    }

    // Convert raw differential pressure by dividing by the scale factor
    pressure_raw = *(int *)pressure_data;
    scale_factor = 0x8000; // Scale factor from Sensirion SDP800-500Pa datasheet
    pressure_raw /= scale_factor;

    // Convert raw temperature by dividing by 200
    temperature_raw = *(int *)temperature_data;
    temperature_raw /= 200;

    // Log each reading with a timestamp
    snprintf(timestamp, sizeof(timestamp), "%.2f", (double)get_monotonic_time() * 1000);
    printf("Pressure: %.2f, Temperature: %.2f, Scale Factor: %d\n", pressure_raw, temperature_raw, scale_factor);
    printf("Flow Data: %s\n", timestamp);

    // Release resources
    close(i2c_fd);
    gpioTerminate();

close_i2c_fd:
    i2cClose(i2c_fd);

close_fd:
    close(fd);
    gpioTerminate();

    return 0;
}

