#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <stdlib.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x40

int main() {
    int i2c_fd;
    int result;
    int i2c_addr = I2C_ADDR;
    int i2c_timeout = 20000;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = pigpioOpen(I2C_BUS_NUM)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C bus speed
    if (gpioSetSpeed(I2C_BUS_NUM, 100000) < 0) {
        fprintf(stderr, "Failed to set I2C bus speed\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set I2C address
    if (gpioSetMode(I2C_BUS_NUM, I2C_MODE_I2C) < 0) {
        fprintf(stderr, "Failed to set I2C mode\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(I2C_BUS_NUM, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure HDC1080 sensor
    if (gpioSetResolution(I2C_BUS_NUM, I2C_ADDR, 14, 14) < 0) {
        fprintf(stderr, "Failed to set resolution\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set I2C timeout
    if (gpioSetTimeout(i2c_timeout) < 0) {
        fprintf(stderr, "Failed to set I2C timeout\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open I2C handle
    if ((result = pigpioOpenI2C(i2c_fd, I2C_BUS_NUM)) < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Wait for sensor to be present
    if (gpioWaitForTrig(I2C_BUS_NUM, I2C_ADDR, I2C_TRIG_START) < 0) {
        fprintf(stderr, "Failed to wait for sensor presence\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Read temperature and humidity
    uint16_t raw_temp, raw_humidity;
    if (gpioReadReg16(I2C_BUS_NUM, I2C_ADDR, 0x02, &raw_temp) < 0) {
        fprintf(stderr, "Failed to read temperature register\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioReadReg16(I2C_BUS_NUM, I2C_ADDR, 0x03, &raw_humidity) < 0) {
        fprintf(stderr, "Failed to read humidity register\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Convert raw values
    float temperature = (raw_temp / 65536.0) * 165.0 - 40.0;
    float humidity = (raw_humidity / 65536.0) * 100.0;

    // Log the valid reading
    char timestamp[50];
    time_t now = time(NULL);
    struct tm *ltm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);

    FILE *log_file = fopen("enviro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(log_file);

    // Close I2C handle
    if (pigpioCloseI2C(i2c_fd) < 0) {
        fprintf(stderr, "Failed to close I2C handle\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Close pigpio
    gpioTerminate();

    return 0;
