#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x44
#define SENSOR_COMMAND 0xE0
#define SENSOR_DATA_LENGTH 3
#define CRC8_POLYNOMIAL 0x31

int main() {
    int i2c_fd;
    int sensor_fd;
    int i2c_gpio_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    uint8_t sensor_data[SENSOR_DATA_LENGTH];
    uint8_t crc8_calculated;
    uint8_t crc8_expected;
    char temperature_log_filename[128] = "temperature_log.txt";
    FILE *temperature_log;
    struct sigaction sa;
    int sigint_received = 0;

    // Open the I2C adapter
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) == -1) {
        perror("Error opening I2C adapter");
        exit(EXIT_FAILURE);
    }

    // Set the slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) == -1) {
        perror("Error setting I2C slave address");
        exit(EXIT_FAILURE);
    }

    // Open the GPIO file descriptor for the Sensirion sensor
    if ((i2c_gpio_fd = open("/dev/gpiochip0", O_RDWR)) == -1) {
        perror("Error opening GPIO file descriptor");
        exit(EXIT_FAILURE);
    }

    // Open the log file
    if ((temperature_log = fopen(temperature_log_filename, "w")) == NULL) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    // Set up the sigaction structure
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_SIGINFO;

    // Install the sigint handler
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error installing sigint handler");
        exit(EXIT_FAILURE);
    }

    // Install the sigterm handler
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error installing sigterm handler");
        exit(EXIT_FAILURE);
    }

    // Infinite loop
    while (1) {
        // Read data from the sensor
        if (read(sensor_fd, sensor_data, SENSOR_DATA_LENGTH) != SENSOR_DATA_LENGTH) {
            perror("Error reading sensor data");
            exit(EXIT_FAILURE);
        }

        // Calculate the CRC8
        crc8_expected = 0x31;
        crc8_calculated = calculate_crc8(sensor_data, SENSOR_DATA_LENGTH, crc8_expected);

        // Check if the calculated CRC8 matches the expected value
        if (crc8_calculated != crc8_expected) {
            fprintf(stderr, "CRC8 mismatch detected. Expected: %02X, Calculated: %02X\n", crc8_expected, crc8_calculated);
            continue;
        }

        // Convert the raw ticks to Celsius
        float temperature = -45 + 175 * sensor_data[0] / 65535.0;

        // Log the temperature with an ISO-8601 timestamp
        fprintf(temperature_log, "%sT%s, %.2f\n", ctime(&(time(NULL)), NULL), ctime(&(time(&(sensor_data[0]))), NULL), temperature);

        // Close the log file
        fclose(temperature_log);
    }

    // Clean up
    close(i2c_gpio_fd);
    close(sensor_fd);
    close(i2c_fd);

    // Restore the original signal handlers
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Exit
    return 0;
}

// SIGINT handler
void sigint_handler(int sig) {
    sigint_received = 1;
}

// Calculate the CRC8
uint8_t calculate_crc8(uint8_t *data, int data_length, uint8_t expected_crc) {
    uint8_t crc = 0;
    for (int i = 0; i < data_length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

