#include <linux/i2c-dev.h>

#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDRESS 0x62

// Function prototypes
void init_pigpio();
void open_i2c_bus();
void send_command(int fd, uint16_t address, uint16_t command);
void read_data(int fd, uint16_t address);
void write_to_csv(const char* filename, const char* data);
void log_error(const char* message, const char* timestamp);

// Global variables
volatile sig_atomic_t running;
pthread_t logging_thread;
pthread_mutex_t buffer_mutex;
pthread_cond_t buffer_cond;

// Thread-safe circular buffer
typedef struct {
    uint16_t timestamp;
    uint16_t data[100];
} CircularBuffer;

CircularBuffer buffer;
int buffer_size = 0;
int buffer_index = 0;

// Function to initialize pigpio
void init_pigpio() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        exit(1);
    }
}

// Function to open I2C bus
void open_i2c_bus() {
    int i2c_fd = i2c_open(I2C_BUS_NUM);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }
    struct i2c_rdwr_ioctl_data data;
    data.flags = 0;
    data.timeout = 100;
    if (ioctl(i2c_fd, I2C_RDWR, &data) < 0) {
        perror("Failed to set I2C bus mode");
        exit(1);
    }
}

// Function to send command to Sensirion SCD40 CO2 sensor
void send_command(int fd, uint16_t address, uint16_t command) {
    if (write(fd, &command, sizeof(command)) != sizeof(command)) {
        log_error("Failed to send command to SCD40", __func__, strerror(errno));
        exit(1);
    }
}

// Function to read data from Sensirion SCD40 CO2 sensor
void read_data(int fd, uint16_t address) {
    uint16_t data[9];
    if (read(fd, data, sizeof(data)) != sizeof(data)) {
        log_error("Failed to read data from SCD40", __func__, strerror(errno));
        exit(1);
    }
    if (data[0] != 0x21B1) {
        log_error("Invalid command received from SCD40", __func__, data);
        exit(1);
    }
    if (data[1] != 0xE000) {
        log_error("Invalid command received from SCD40", __func__, data);
        exit(1);
    }
    if (data[2] != 0x00) {
        log_error("Invalid command received from SCD40", __func__, data);
        exit(1);
    }
    if (data[3] != 0x00) {
        log_error("Invalid command received from SCD40", __func__, data);
        exit(1);
    }
    if (data[4] != 0x00) {
        log_error("Invalid command received from SCD40", __func__, data);
        exit(1);
    }
    if (data[5] != 0x00) {
        log_error("Invalid command received from SCD40", __func__, data);
        exit(1);
    }
    if (data[6] != 0x00) {
        log_error("Invalid command received from SCD40", __func__, data);
        exit(1);
    }
    if (data[7] != 0x00) {
        log_error("Invalid command received from SCD40", __func__, data);
        exit(1);
    }
    if (data[8] != 0x00) {
        log_error("Invalid command received from SCD40", __func__, data);
        exit(1);
    }
}

// Function to write to a CSV file
void write_to_csv(const char* filename, const char* data) {
    FILE* file = fopen(filename, "a");
    if (file == NULL) {
        log_error("Failed to open CSV file", __func__, strerror(errno));
        exit(1);
    }
    fprintf(file, "%s,%s\n", data, data);
    fclose(file);
}

// Function to log errors with timestamps
void log_error(const char* message, const char* timestamp) {
    char log_message[100];
    strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S", localtime());
    log_message[strlen(log_message) - 1] = '\0';
    log_message[strlen(log_message) + 1] = '\n';
    log_message[strlen(log_message)] = '\0';
    log_error(log_message, timestamp);
}

int main() {
    init_pigpio();
    open_i2c_bus();

    pthread_mutex_init(&buffer_mutex, NULL);
    pthread_cond_init(&buffer_cond, NULL);

    CircularBuffer buffer;
    buffer_size = 0;
    buffer_index = 0;

    running = 1;

    while (running) {
        pthread_mutex_lock(&buffer_mutex);

        if (buffer_index >= buffer_size) {
            buffer_index = 0;
        }

        if (buffer_size > 0) {
            CircularBuffer* buffer_ptr = &buffer;
            buffer_ptr->timestamp = i2c_rdwr_start_trans(I2C_BUS_NUM, I2C_ADDRESS, &buffer_ptr->data[buffer_index], 1);
            pthread_mutex_unlock(&buffer_mutex);

            if (buffer_ptr->timestamp == 0) {
                pthread_mutex_lock(&buffer_mutex);
                buffer_index = (buffer_index + 1) % buffer_size;
                pthread_mutex_unlock(&buffer_mutex);
            }
        } else {
            pthread_mutex_lock(&buffer_mutex);
            buffer_index = 0;
            pthread_mutex_unlock(&buffer_mutex);
        }

        pthread_cond_wait(&buffer_cond, &buffer_mutex);

        pthread_mutex_lock(&buffer_mutex);

        if (buffer_index < buffer_size) {
            CircularBuffer* buffer_ptr = &buffer;
            buffer_ptr->timestamp = i2c_rdwr_stop_trans(I2C_BUS_NUM, I2C_ADDRESS);
            pthread_mutex_unlock(&buffer_mutex);

            if (buffer_ptr->timestamp == 0) {
                buffer_index++;
            }
        } else {
            pthread_mutex_unlock(&buffer_mutex);
        }

        pthread_cond_signal(&buffer_cond);
    }

    pthread_mutex_destroy(&buffer_mutex);
    pthread_cond_destroy(&buffer_cond);

    close_i2c_handle();
    gpioTerminate();

    return 0;
}

