#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDRESS 0x63

int main() {
    int i, ret;
    int i2c_fd;
    uint8_t buffer[6];
    uint16_t pressure, temperature;
    char log_file[128];
    char *log_message;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C bus speed
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error: Failed to set I2C bus speed\n");
        goto error_close_i2c;
    }

    // Verify sensor identity
    if (read_WHO_AM_I(i2c_fd) != 0x08) {
        fprintf(stderr, "Error: Failed to verify sensor identity\n");
        goto error_close_i2c;
    }

    // Read calibration coefficients
    if (i2cReadI2CBlockData(i2c_fd, 0x05, buffer, 6) < 0) {
        fprintf(stderr, "Error: Failed to read calibration coefficients\n");
        goto error_close_i2c;
    }

    // Loop
    while (1) {
        // Trigger measurement
        write(0, 0x00, 1);
        sleep(10);

        // Read data
        if (i2cReadI2CBlockData(i2c_fd, 0x00, buffer, 6) < 0) {
            fprintf(stderr, "Error: Failed to read data\n");
            continue;
        }

        // Convert data to pressure and temperature
        pressure = (buffer[0] << 8) | buffer[1];
        temperature = (buffer[2] << 8) | buffer[3];

        // Log data
        snprintf(log_message, sizeof(log_message), "%.6f,%.2f\n", pressure / 100.0, temperature);
        log_file[0] = '\0';
        strcat(log_file, log_message);
        if ((log_message = fopen(log_file, "a")) == NULL) {
            fprintf(stderr, "Error: Failed to open log file\n");
            continue;
        }
        fputs(log_message, log_file);
        fclose(log_file);

        // Print data
        printf("%.6f,%.2f\n", pressure / 100.0, temperature);

        // Wait 5 seconds
        sleep(5);
    }

error_close_i2c:
    close(i2c_fd);
    gpioTerminate();
    return 1;
}

