        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C bus speed
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error: Failed to set I2C bus speed\n");
        goto error_close_i2c;
    }

    // Verify sensor identity
    if (read_WHO_AM_I(i2c_fd) != 0x08) {
        fprintf(stderr, "Error: Failed to verify sensor identity\n");
        goto error_close_i2c;
    }

    // Read calibration coefficients
