        fprintf(stderr, "Error: Failed to read calibration coefficients\n");
        goto error_close_i2c;
    }

    // Loop
    while (1) {
        // Trigger measurement
        write(0, 0x00, 1);
        sleep(10);

        // Read data
        if (i2cReadI2CBlockData(i2c_fd, 0x00, buffer, 6) < 0) {
            fprintf(stderr, "Error: Failed to read data\n");
            continue;
        }

        // Convert data to pressure and temperature
        pressure = (buffer[0] << 8) | buffer[1];
        temperature = (buffer[2] << 8) | buffer[3];

        // Log data
        snprintf(log_message, sizeof(log_message), "%.6f,%.2f\n", pressure / 100.0, temperature);
        log_file[0] = '\0';
        strcat(log_file, log_message);
        if ((log_message = fopen(log_file, "a")) == NULL) {
            fprintf(stderr, "Error: Failed to open log file\n");
            continue;
        }
        fputs(log_message, log_file);
        fclose(log_file);

        // Print data
        printf("%.6f,%.2f\n", pressure / 100.0, temperature);

        // Wait 5 seconds
        sleep(5);
    }

error_close_i2c:
    close(i2c_fd);
    gpioTerminate();
    return 1;
}
