#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDRESS 0x44

int main() {
    int ret;
    int i;
    int retryCount = 3;
    int i2c_fd;
    char i2c_buf[6];
    char *html_content = "<html><body><h1>Temperature and Humidity</h1><p>Current Temperature: <span id='temperature'>-</span></p><p>Current Humidity: <span id='humidity'>-</span></p></body></html>";

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = pigpio_open(I2C_BUS_NUM)) < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C speed to 100kHz
    if (pigpio_set_speed(i2c_fd, 100000) < 0) {
        fprintf(stderr, "Error: Failed to set I2C speed\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C address of Sensirion SHT40 sensor
    if (pigpio_set_mode(i2c_fd, I2C_ADDR_MODE_7BIT) < 0) {
        fprintf(stderr, "Error: Failed to set I2C address mode\n");
        gpioTerminate();
        return 1;
    }
    if (pigpio_set_address(i2c_fd, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error: Failed to set I2C address\n");
        gpioTerminate();
        return 1;
    }

    // Set up the I2C communication
    if (pigpio_set_mode(i2c_fd, I2C_MODE_MASTER) < 0) {
        fprintf(stderr, "Error: Failed to set I2C mode\n");
        gpioTerminate();
        return 1;
    }

    // Send measurement command to the Sensirion SHT40 sensor
    if (pigpio_write(i2c_fd, 0xFD, 1) < 0) {
        fprintf(stderr, "Error: Failed to send measurement command\n");
        gpioTerminate();
        return 1;
    }

    // Wait for at least 10 ms
    if (pigpio_delay(10) < 0) {
        fprintf(stderr, "Error: Failed to wait for 10 ms\n");
        gpioTerminate();
        return 1;
    }

    // Read 6 bytes from the sensor
    if (pigpio_read(i2c_fd, i2c_buf, 6) < 0) {
        fprintf(stderr, "Error: Failed to read 6 bytes from sensor\n");
        gpioTerminate();
        return 1;
    }

    // Convert raw data to temperature and humidity
    int raw_T = i2c_buf[0] << 8 | i2c_buf[1];
    int raw_RH = i2c_buf[2] << 8 | i2c_buf[3];
    float T = -45 + 175 * (raw_T / 65535);
    float RH = -6 + 125 * (raw_RH / 65535);

    // Clamp humidity to 0-100%
    if (RH < 0) {
        RH = 0;
    } else if (RH > 100) {
        RH = 100;
    }

    // Display temperature and humidity on the web page
    printf("<h1>Temperature and Humidity</h1><p>Current Temperature: <span id='temperature'>%d</span></p><p>Current Humidity: <span id='humidity'>%d</span></p>\n", T, RH);

    // Close I2C bus
    if (pigpio_close(i2c_fd) < 0) {
        fprintf(stderr, "Error: Failed to close I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Clean up
    gpioTerminate();

    return 0;
}

