#include <time.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x48

int main() {
    int i2c_fd;
    int err;
    int gpio_num;
    int i2c_addr;
    uint16_t data;
    struct i2c_rdwr_ioctl_data data_wr;
    struct i2c_rdwr_ioctl_data data_rd;
    char filename[32];
    time_t now;
    struct tm tm;
    char timestamp[32];
    double temperature;

    // Initialize pigpio
    if (gpio_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    // Set I2C bus number and address
    if (pi_set_bus_num(I2C_BUS_NUM) < 0) {
        fprintf(stderr, "Error: Failed to set I2C bus number\n");
        return 1;
    }
    if (pi_set_addr(I2C_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C address\n");
        return 1;
    }

    // Open I2C file descriptor
    if ((i2c_fd = pi_open_i2c_device()) < 0) {
        fprintf(stderr, "Error: Failed to open I2C device\n");
        return 1;
    }

    // Get current time
    now = time(NULL);
    tm = *localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Log each reading to a timestamped CSV file
    sprintf(filename, "temperature_log_%s.csv", timestamp);
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open CSV file\n");
        return 1;
    }

    // Read temperature from TMP102 sensor
    if (pi_i2c_read_reg(i2c_fd, 0x00, &data, 1) < 0) {
        fprintf(stderr, "Error: Failed to read temperature from TMP102\n");
        fclose(fp);
        return 1;
    }
    data >>= 4;
    temperature = (double)(data & 0x3FF) * 0.0625;

    // Log the reading
    fprintf(fp, "%s,%f\n", timestamp, temperature);

    // Close the CSV file
    fclose(fp);

    // Close I2C file descriptor
    pi_close_i2c_device(i2c_fd);

    // Terminate pigpio
    pi_exit();

    return 0;
}

