#include <errno.h>

#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x40
#define HTTP_PORT 80

int main() {
    int sockfd, client_fd, rc;
    struct sockaddr_in serv_addr, cli_addr;
    socklen_t cli_len = sizeof(cli_addr);
    char buffer[256];
    char *message = "{\"humidity\": %d}";
    int i;

    // Initialize I2C bus
    if (gpiod_init() < 0) {
        syslog(LOG_ERR, "Failed to initialize I2C bus");
        return 1;
    }

    // Open I2C device file
    if ((sockfd = open(I2C_BUS, O_RDWR)) < 0) {
        syslog(LOG_ERR, "Failed to open I2C device file");
        gpiod_exit();
        return 1;
    }

    // Set I2C device address
    if (ioctl(sockfd, I2C_SLAVE, I2C_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C device address");
        close(sockfd);
        gpiod_exit();
        return 1;
    }

    // Create socket for HTTP POST
    if ((client_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        syslog(LOG_ERR, "Failed to create socket");
        close(sockfd);
        gpiod_exit();
        return 1;
    }

    // Set socket options
    if (setsockopt(client_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &1, sizeof(int)) < 0) {
        syslog(LOG_ERR, "Failed to set socket options");
        close(sockfd);
        close(client_fd);
        gpiod_exit();
        return 1;
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(HTTP_PORT);

    if (bind(client_fd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        syslog(LOG_ERR, "Failed to bind socket");
        close(sockfd);
        close(client_fd);
        gpiod_exit();
        return 1;
    }

    if (listen(client_fd, 3) < 0) {
        syslog(LOG_ERR, "Failed to listen on socket");
        close(sockfd);
        close(client_fd);
        gpiod_exit();
        return 1;
    }

    while (1) {
        // Read data from HTU21D sensor
        if (read(sockfd, &buffer, sizeof(buffer)) < 0) {
            syslog(LOG_ERR, "Failed to read from sensor");
            close(client_fd);
            gpiod_exit();
            return 1;
        }

        // Parse JSON message
        for (i = 0; i < strlen(buffer); i++) {
            if (buffer[i] == '{') {
                break;
            }
        }

        if (i == strlen(buffer)) {
            syslog(LOG_ERR, "Failed to parse JSON message");
            close(client_fd);
            gpiod_exit();
            return 1;
        }

        // Extract humidity value
        int humidity = atoi(buffer + i);

        // Send POST request
        if (send(client_fd, message, strlen(message), 0) < 0) {
            syslog(LOG_ERR, "Failed to send POST request");
            close(client_fd);
            gpiod_exit();
            return 1;
        }

        // Receive response
        if (recv(client_fd, buffer, sizeof(buffer)) < 0) {
            syslog(LOG_ERR, "Failed to receive response");
            close(client_fd);
            gpiod_exit();
            return 1;
        }

        // Close socket and I2C device
        close(client_fd);
        close(sockfd);
        gpiod_exit();
    }

    return 0;
}

