#define IN1_GPIO_PIN 23
#define IN2_GPIO_PIN 24

int main() {
    int fd, i2c_fd, gpio_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_request gpio_request;
    struct gpio_direction gpio_direction;
    struct gpio_int_event gpio_int_event;
    struct gpio_event gpio_event;
    struct gpio_event gpio_event_mask;
    struct i2c_msg i2c_msgs[2];
    int ret;

    // Open GPIO and I2C file descriptors
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening i2c-1 device");
        exit(EXIT_FAILURE);
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening i2c-1 device");
        exit(EXIT_FAILURE);
    }

    // Open GPIO file descriptor
    gpio_fd = open("/sys/class/gpio/gpio17/gpio", O_RDWR);
    if (gpio_fd < 0) {
        perror("Error opening GPIO file descriptor");
        exit(EXIT_FAILURE);
    }

    // Set the GPIO direction to output
    gpio_direction.mode = GPIO_MODE_OUTPUT;
    gpio_direction.pull_up_down = GPIO_PUD_UP;
    gpio_direction.value = 0;
    ret = ioctl(gpio_fd, GPIO_SET_DIRECTION, &gpio_direction);
    if (ret < 0) {
        perror("Error setting GPIO direction");
        exit(EXIT_FAILURE);
    }

    // Set the GPIO as an active-low digital output
    gpio_request.gpio_num = 17;
    gpio_request.direction = GPIO_OUT;
    gpio_request.value = 0;
    ret = ioctl(gpio_fd, GPIO_SET_LEVEL, &gpio_request);
    if (ret < 0) {
        perror("Error setting GPIO as active-low digital output");
        exit(EXIT_FAILURE);
    }

    // Open the L298N motor driver board file descriptor
    gpio_request.gpio_num = 22;
    gpio_request.direction = GPIO_OUT;
    gpio_request.value = 0;
    ret = ioctl(gpio_fd, GPIO_SET_LEVEL, &gpio_request);
    if (ret < 0) {
        perror("Error setting GPIO as output");
        exit(EXIT_FAILURE);
    }

    gpio_request.gpio_num = 23;
    gpio_request.direction = GPIO_IN;
    gpio_request.value = 0;
    ret = ioctl(gpio_fd, GPIO_SET_LEVEL, &gpio_request);
    if (ret < 0) {
        perror("Error setting GPIO as input");
        exit(EXIT_FAILURE);
    }

    gpio_request.gpio_num = 24;
    gpio_request.direction = GPIO_OUT;
    gpio_request.value = 1;
    ret = ioctl(gpio_fd, GPIO_SET_LEVEL, &gpio_request);
    if (ret < 0) {
        perror("Error setting GPIO as output");
        exit(EXIT_FAILURE);
    }

    // Wait for the YL-83 sensor to be triggered
    while (1) {
        // Poll the GPIO line
        ret = ioctl(fd, FBIOGET_LINE(i2c_fd), &i2c_msgs[0].len);
        if (ret < 0) {
            perror("Error polling GPIO line");
            exit(EXIT_FAILURE);
        }

        if (i2c_msgs[0].len == 0) {
            break;
        }

        // Check the GPIO line value
        if (i2c_msgs[0].buf[0] & 0x80) {
            printf("Rain detected!\n");
            // Close the window
            ret = ioctl(ENA_GPIO_PIN, GPIO_CLR_LINE, ENA_GPIO_PIN);
            if (ret < 0) {
                perror("Error closing window");
                exit(EXIT_FAILURE);
            }

            ret = ioctl(IN1_GPIO_PIN, GPIO_CLR_LINE, IN1_GPIO_PIN);
            if (ret < 0) {
                perror("Error closing window");
                exit(EXIT_FAILURE);
            }

            ret = ioctl(IN2_GPIO_PIN, GPIO_CLR_LINE, IN2_GPIO_PIN);
            if (ret < 0) {
                perror("Error closing window");
                exit(EXIT_FAILURE);
            }

            // Wait for 5 seconds
            sleep(5);

            // Stop the motor
            ret = ioctl(ENA_GPIO_PIN, GPIO_SET_LINE, ENA_GPIO_PIN);
            if (ret < 0) {
                perror("Error stopping motor");
                exit(EXIT_FAILURE);
            }

            ret = ioctl(IN1_GPIO_PIN, GPIO_SET_LINE, IN1_GPIO_PIN);
            if (ret < 0) {
                perror("Error stopping motor");
                exit(EXIT_FAILURE);
            }

            ret = ioctl(IN2_GPIO_PIN, GPIO_SET_LINE, IN2_GPIO_PIN);
            if (ret < 0) {
                perror("Error stopping motor");
                exit(EXIT_FAILURE);
            }
        }
    }

    // Close the I2C file descriptor
    close(i2c_fd);

    // Close the GPIO file descriptor
    close(gpio_fd);

    // Close the i2c-1 device file descriptor
    close(fd);

    return 0;
