#define FAN_PWM_FREQ 1000 // 1 kHz
#define FAN_PWM_RAMP_MIN 0 // 0°C
#define FAN_PWM_RAMP_MAX 255 // 100°C

int main() {
    int fd;
    struct spi_ioc_transfer transfer;
    char buffer[MAX_BUFFER_SIZE];
    struct spi_ioc_data data;
    int ret;

