    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    // Open SPI channel 0 at 500 kHz, mode 0
    if ((fd = spiOpen(0, 0)) < 0) {
        fprintf(stderr, "Error opening SPI channel\n");
        return 1;
    }

    // Set up SPI transfer parameters
    memset(&transfer, 0, sizeof(transfer));
    transfer.len = sizeof(buffer);
    transfer.tx_buf = (void*)buffer;
    transfer.rx_buf = (void*)&buffer[1];
    transfer.speed_hz = 500000; // 500 kHz
    transfer.mode = SPI_MODE_0;
    transfer.bits_per_word = 8;
    transfer.cs_change = 1;

    // Set up SPI transfer data
    data.tx_buf = (void*)&transfer;
    data.rx_buf = (void*)&transfer.rx_buf[1];
    data.len = sizeof(transfer.rx_buf);
    data.speed_hz = 500000; // 500 kHz
    data.cs_change = 1;

    // Set up MAX31855 registers
    if (ioctl(fd, SPI_IOC_MESSAGE_OUT, &data) < 0) {
        fprintf(stderr, "Error setting up MAX31855 registers\n");
        return 1;
    }

    // Set up fan PWM duty cycle
    int fan_duty_cycle = 0;

    while (1) {
        // Read temperature from MAX31855
        if (ioctl(fd, SPI_IOC_MESSAGE_OUT, &data) < 0) {
            fprintf(stderr, "Error reading temperature from MAX31855\n");
            continue;
        }

        // Extract signed 14-bit thermocouple temperature
        int temperature = (data.tx_buf[0] << 8) | data.tx_buf[1];

        // Check MAX31855 fault bits
        if ((data.rx_buf[16] & 0x8000) != 0) {
            fprintf(stderr, "MAX31855 fault detected: %s\n", data.rx_buf + 16);
            continue;
        }

        // Check fault type bits
        if ((data.rx_buf[16] & 0x0F00) != 0) {
            fprintf(stderr, "MAX31855 fault type detected: %s\n", data.rx_buf + 16);
            continue;
        }

        // Check fault bits
