    char *error_log_filename = rtd_log_filename;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open SPI device file descriptor
    if ((fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device file descriptor: %s\n", strerror(errno));
        gpiod_exit();
        return 1;
    }

    // Open chip-select line
    if ((cs_gpio_fd = gpiod_chip_select_open(MAX31865_CS_GPIO_NUMBER)) < 0) {
        fprintf(stderr, "Failed to open chip-select line: %s\n", strerror(errno));
        close(fd);
        gpiod_exit();
        return 1;
    }

    // Open SPI device file descriptor
    if ((spi = spi_open(fd)) < 0) {
        fprintf(stderr, "Failed to open SPI device file descriptor: %s\n", strerror(errno));
        gpiod_chip_select_close(cs_gpio_fd);
        gpiod_exit();
        return 1;
    }

    // Open chip-select line
    if ((cs_line = gpiod_chip_select_open(MAX31865_CS_GPIO_NUMBER)) < 0) {
        fprintf(stderr, "Failed to open chip-select line: %s\n", strerror(errno));
        spi_close(spi);
        gpiod_chip_select_close(cs_gpio_fd);
        gpiod_exit();
        return 1;
    }

    // Open log file
    if ((fp = fopen(error_log_filename, "w")) < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_chip_select_close(cs_gpio_fd);
