#define BME280_CSV_FILENAME "bme280_log.csv"

void log_timestamp(const char *format, struct timespec *ts) {
    char timestamp[80];
    struct tm tm = {0};
    time_t t = ts->tv_sec;
    struct tm *local_tm = localtime(&t);
    strftime(timestamp, sizeof(timestamp), format, local_tm);
    printf("%s, %s\n", timestamp, local_tm->tm_mday);
}

int main() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_rdwr_ioctl_data *i2c_rdwr_data;
    struct i2c_msg i2c_msgs[2];
    struct i2c_client *client;
    struct i2c_adapter *adapter;
    struct i2c_board_info board_info = {
        .type = I2C_BOARD_INFO_ONE_I2C,
        .address = BME280_I2C_ADDR,
        .flags = I2C_CLIENT_TOKEN_I2C,
    };
    struct timespec ts;
    struct stat log_file_stat;
    char log_file_name[64] = BME280_CSV_FILENAME;

    // Initialize I2C bus
    if (i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        return 1;
    }

    // Open the I2C bus
    adapter = i2c_adapter_new(BME280_I2C_BUS_NUM);
    if (adapter == NULL) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }
    client = i2c_new_client_adapt(&adapter->adap, &board_info);
    if (client == NULL) {
        fprintf(stderr, "Failed to create I2C client\n");
        return 1;
    }

    // Check BME280 chip ID
    if (i2c_check_id(client, BME280_CHIP_ID) < 0) {
        fprintf(stderr, "BME280 chip ID not found\n");
        return 1;
    }

    // Open log file
    if (stat(log_file_name, &log_file_stat) == -1) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }
    if ((log_fd = open(log_file_name, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)) < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up I2C message structure
    i2c_msgs[0].addr = BME280_I2C_ADDR;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 2;
    i2c_msgs[0].buf = (void *)&board_info;

    // Log data to CSV file
    while (1) {
        // Get current timestamp
        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
            fprintf(stderr, "Failed to get current timestamp\n");
            return 1;
        }

        // Log timestamp, temperature, humidity, and pressure
        log_timestamp(BME280_TIMESTAMP_FORMAT, &ts);
        log_timestamp(BME280_TIMESTAMP_FORMAT, &ts);
        log_timestamp(BME280_TIMESTAMP_FORMAT, &ts);
        log_timestamp(BME280_TIMESTAMP_FORMAT, &ts);

        // Write data to log file
        if (i2c_write(client, i2c_msgs, 2) < 0) {
            fprintf(stderr, "Failed to write data to log file\n");
            return 1;
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close log file
    if (close(log_fd) < 0) {
        fprintf(stderr, "Failed to close log file\n");
        return 1;
    }

    // Release I2C resources
    i2c_unregister_board(&board_info);
    i2c_adapter_del(adapter);
    i2c_new_client_adapt(&adapter->adap, &board_info);

    return 0;
}

