#include <string.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>

#include <pigpio.h>

#define FAN_GPIO 18
#define FAN_PWM_FILE "/sys/class/gpio/gpio18/value"
#define FAN_LOG_FILE "fan_log.txt"
#define FAN_FREQ 25000
#define FAN_MIN_TEMP 40
#define FAN_MAX_TEMP 70

int main() {
    int fd, ret;
    char buffer[32];
    struct itimerspec timer;
    struct timeval tv;
    struct stat fan_log_stat;
    char fan_log_file[128];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    // Open the log file
    snprintf(fan_log_file, sizeof(fan_log_file), "%s/fan_log.txt", getenv("HOME"));
    if ((fd = open(fan_log_file, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up the PWM duty cycle range
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set PWM mode\n");
        goto cleanup;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, FAN_FREQ) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency\n");
        goto cleanup;
    }

    if (gpioSetPWMrange(FAN_GPIO, PI_OUTPUT, FAN_MIN_TEMP, FAN_MAX_TEMP) < 0) {
        fprintf(stderr, "Error: Failed to set PWM range\n");
        goto cleanup;
    }

    // Set up the timer for logging temperature
    timer.it_value.tv_sec = 5;
    timer.it_value.tv_usec = 0;
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_usec = 0;

    if (timer.it_value.tv_sec > timer.it_interval.tv_sec) {
        tv.tv_sec = timer.it_value.tv_sec - timer.it_interval.tv_sec;
        tv.tv_usec = timer.it_interval.tv_usec;
    } else {
        tv.tv_sec = timer.it_interval.tv_sec;
        tv.tv_usec = timer.it_value.tv_usec;
    }

    ret = ioctl(fd, PI_GET_TIME, &timer);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to get timer value\n");
        goto cleanup;
    }

    // Main loop
    while (1) {
        // Read the CPU temperature
        if (get_cpu_temperature(&tv) < 0) {
            fprintf(stderr, "Error: Failed to get CPU temperature\n");
            goto cleanup;
        }

        // Map the temperature to duty cycle
        int duty_cycle = map_temperature_to_duty_cycle(tv.tv_sec);

        // Log the temperature, duty cycle, and timestamp
        snprintf(buffer, sizeof(buffer), "Temperature: %d°C, Duty Cycle: %d%%\n",
                 tv.tv_sec, duty_cycle);
        if (write(fd, buffer, strlen(buffer)) < 0) {
            fprintf(stderr, "Error: Failed to write to log file\n");
            goto cleanup;
        }

        // Log the fan speed
        snprintf(buffer, sizeof(buffer), "Fan Speed: %d%%\n", duty_cycle);
        if (write(fd, buffer, strlen(buffer)) < 0) {
            fprintf(stderr, "Error: Failed to write to log file\n");
            goto cleanup;
        }

        // Wait for the next PWM cycle
        ret = usec_to_sigs(timer.it_value.tv_usec);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to wait for PWM cycle\n");
            goto cleanup;
        }
    }

cleanup:
    gpioTerminate();
    return 0;
}

