#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define BMP180_I2C_ADDR 0x77
#define BMP180_DATA_LEN 3
#define BMP180_TIMESTAMP_LEN 8
#define BMP180_PRESSURE_LEN 4

int main() {
    int i2c_fd;
    int bmp180_fd;
    int ret;
    int debounce_timer;
    struct bmp180_data bmp180_data;
    struct bmp180_raw_data raw_data;
    struct bmp180_compensation_data compensation_data;
    char log_file_name[] = "pressure_log.txt";
    char log_buffer[BMP180_DATA_LEN];
    time_t last_log_time;
    int log_enabled = 1;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C file descriptor
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C device file\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C speed to 100 kHz
    if (ioctl(i2c_fd, PI_SET_SPEED, 100000) < 0) {
        fprintf(stderr, "Failed to set I2C speed\n");
        goto error_open_i2c;
    }

    // Open BMP180 sensor
    if ((bmp180_fd = open("/dev/bmp180", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open BMP180 sensor device file\n");
        goto error_open_bmp180;
    }

    // Set I2C address of the BMP180 sensor
    if (ioctl(bmp180_fd, PI_SET_ADDRESS, BMP180_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address of the BMP180 sensor\n");
        goto error_open_bmp180;
    }

    // Read BMP180 calibration data
    if (ioctl(bmp180_fd, PI_GET_CALIBRATION, &bmp180_data) < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        goto error_read_calibration;
    }

    // Compute pressure from raw data using Bosch compensation formulas
    if (compute_pressure(&bmp180_data, &raw_data) < 0) {
        fprintf(stderr, "Failed to compute pressure from raw data\n");
        goto error_compute_pressure;
    }

    // Set up debouncing timer
    debounce_timer = 200;
    if (debounce_timer > 0) {
        if (timerCreate(&debounce_timer, 0, &debounce_timer_id) < 0) {
            fprintf(stderr, "Failed to create debounce timer\n");
            goto error_timer_create;
        }
    }

    // Main loop
    while (1) {
        // Read raw data from the BMP180 sensor
        if (ioctl(bmp180_fd, PI_GET_RAW_DATA, &raw_data) < 0) {
            fprintf(stderr, "Failed to read raw data from the BMP180 sensor\n");
            goto error_read_raw_data;
        }

        // Check if the falling-edge detection on GPIO27 has occurred
        if (gpioRead(27) == 1) {
            // Debounce the falling-edge detection
            if (debounce_timer > 0) {
                if (timerExpire(&debounce_timer_id) == 0) {
                    // Toggle log_enabled
                    log_enabled = !log_enabled;
                }
            }

            // Toggle data logging
            if (log_enabled) {
                // Write a new log line to the file
                if (write(1, log_buffer, BMP180_DATA_LEN) != BMP180_DATA_LEN) {
                    fprintf(stderr, "Failed to write log line to file\n");
                    goto error_write_log_line;
                }

                // Update timestamp and pressure in the log file
                time_t current_time = time(NULL);
                struct tm *current_time_tm = localtime(&current_time);
                char log_line[BMP180_DATA_LEN + BMP180_TIMESTAMP_LEN + BMP180_PRESSURE_LEN];
                strftime(log_line, BMP180_DATA_LEN + BMP180_TIMESTAMP_LEN + BMP180_PRESSURE_LEN, "%Y-%m-%d %H:%M:%S", current_time_tm);
                strncat(log_line, log_buffer, BMP180_DATA_LEN);
                strncat(log_line, log_buffer, BMP180_TIMESTAMP_LEN);
                strncat(log_line, log_buffer, BMP180_PRESSURE_LEN);

                // Write the log line to the file
                if (write(1, log_line, BMP180_DATA_LEN + BMP180_TIMESTAMP_LEN + BMP180_PRESSURE_LEN) != BMP180_DATA_LEN + BMP180_TIMESTAMP_LEN + BMP180_PRESSURE_LEN) {
                    fprintf(stderr, "Failed to write log line to file\n");
                    goto error_write_log_line;
                }
            }
        }

        // Sleep for 2 seconds
        sleep(2);
    }

error_write_log_line:
    if (write(1, log_buffer, BMP180_DATA_LEN) != BMP180_DATA_LEN) {
        fprintf(stderr, "Failed to write log line to file\n");
    }

error_write_log_file:
    if (close(1) < 0) {
        fprintf(stderr, "Failed to close log file\n");
    }

error_timer_create:
    if (timerDelete(&debounce_timer_id) < 0) {
        fprintf(stderr, "Failed to delete debounce timer\n");
    }

error_read_raw_data:
    if (close(bmp180_fd) < 0) {
        fprintf(stderr, "Failed to close BMP180 sensor device file\n");
    }

error_read_calibration:
    if (close(i2c_fd) < 0) {
        fprintf(stderr, "Failed to close I2C device file\n");
    }

error_open_bmp180:
    if (close(bmp180_fd) < 0) {
        fprintf(stderr, "Failed to close BMP180 sensor device file\n");
    }

error_open_i2c:
    if (close(i2c_fd) < 0) {
        fprintf(stderr, "Failed to close I2C device file\n");
    }

error_init_pigpio:
    gpioTerminate();

error_main:
    return 1;
}

