#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>

#define RGB_RED   17
#define RGB_GREEN 18
#define RGB_BLUE  27
#define RGB_COMMON 3.3

volatile sig_atomic_t stop = 0;

void error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    exit(1);
}

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int gpio = 0;
    int pwm_red = 0;
    int pwm_green = 0;
    int pwm_blue = 0;
    int temperature = 0;
    int r, g, b;

    if (gpioInitialise() < 0) {
        error("Failed to initialize GPIO.");
        return 1;
    }

    gpio = pigpio_get_gpio();
    if (gpio < 0) {
        error("Failed to get GPIO.");
        return 1;
    }

    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        error("Failed to set output mode.");
        return 1;
    }

    if (gpioSetPWMfrequency(gpio, 100) < 0) {
        error("Failed to set PWM frequency.");
        return 1;
    }

    if (gpioSetPWMrange(gpio, 255) < 0) {
        error("Failed to set PWM range.");
        return 1;
    }

    if (gpioOpen(gpio, O_RDWR) < 0) {
        error("Failed to open GPIO.");
        return 1;
    }

    if (gpioSetMode(gpio, PI_INPUT) < 0) {
        error("Failed to set input mode.");
        return 1;
    }

    if (gpioRead(gpio) < 0) {
        error("Failed to read GPIO.");
        return 1;
    }

    while (!stop) {
        if (gpioRead(gpio) == 0) {
            temperature = (int)((float)read_file("/sys/class/thermal/thermal_zone0/temp") / 1000.0);

            if (temperature < 40000) {
                r = 255;
                g = 0;
                b = 0;
            } else if (temperature >= 40000 && temperature < 59999) {
                r = 0;
                g = 255;
                b = 0;
            } else {
                r = 255;
                g = 0;
                b = 0;
            }

            if (gpioSetPWM(gpio, RGB_COMMON, r, g, b) < 0) {
                error("Failed to set PWM duty.");
                return 1;
            }

            if (gpioRead(gpio) == 0) {
                gpioTerminate();
                return 0;
            }
        }

        if (gpioRead(gpio) == 1) {
            gpioTerminate();
            return 0;
        }

        if (gpioRead(gpio) == 2) {
            gpioSetPWM(gpio, RGB_COMMON, 0, 0, 0);
            gpioSetPWM(gpio, RGB_RED, 255, 0, 0);
            gpioSetPWM(gpio, RGB_GREEN, 0, 255, 0);
            gpioSetPWM(gpio, RGB_BLUE, 0, 0, 255);
            gpioSetMode(gpio, PI_OUTPUT);
            gpioDelay(10);
            gpioSetMode(gpio, PI_INPUT);
        }

        gpioDelay(50);
    }

    gpioTerminate();
    return 0;
}

