            fprintf(stderr, "Error: Failed to set I2C function\n");
            gpioTerminate();
            return 1;
        }

        // Print timestamp and pressure
        if (pigpio_set_oversampling(bmp_sensor, oversample_count) < 0) {
            fprintf(stderr, "Error: Failed to set oversampling count\n");
            gpioTerminate();
            return 1;
        }

        if (pigpio_set_delay(bmp_sensor, oversample_delay_ms) < 0) {
            fprintf(stderr, "Error: Failed to set delay\n");
            gpioTerminate();
            return 1;
        }

        if (pigpio_set_function(bmp_sensor, GPIO_FUNC_GPIO) < 0) {
            fprintf(stderr, "Error: Failed to set I2C function\n");
            gpioTerminate();
            return 1;
        }

        if (pigpio_set_oversampling(bmp_sensor, 1) < 0) {
            fprintf(stderr, "Error: Failed to set oversampling count\n");
            gpioTerminate();
            return 1;
        }

        if (pigpio_set_delay(bmp_sensor, 1) < 0) {
            fprintf(stderr, "Error: Failed to set delay\n");
            gpioTerminate();
            return 1;
        }

        if (pigpio_set_function(bmp_sensor, GPIO_FUNC_GPIO) < 0) {
            fprintf(stderr, "Error: Failed to set I2C function\n");
            gpioTerminate();
            return 1;
        }

        // Log pressure
        if (logging_enabled == 1) {
            if (pigpio_set_file(1, "pressure_log.txt") < 0) {
                fprintf(stderr, "Error: Failed to open logging file\n");
                gpioTerminate();
                return 1;
            }

            if (pigpio_write(1, &pressure_log_data, sizeof(pressure_log_data)) < 0) {
                fprintf(stderr, "Error: Failed to write to logging file\n");
                gpioTerminate();
                return 1;
            }
        }

        // Toggle logging
        if (logging_enabled == 1) {
            gpioWrite(4, 1);
            gpioDelay(BETA_SAMPLE_DELAY_MS);
            gpioWrite(4, 0);
            gpioDelay(BETA_SAMPLE_DELAY_MS);
        }
    }

    // Cleanup
    gpioTerminate();
    return 0;
}
