#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define MAX_STATE 3
#define MAX_SPEEDS 5

int main() {
    int fd, i, ret, fan_state, fan_speed, log_fd;
    char buffer[16];
    struct i2c_msg msg[2];
    struct i2c_rdwr_ioctl_data data;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_event event;
    struct timespec start_time, end_time;
    unsigned long long elapsed_time;
    char log_file[128];

    // Initialize GPIO and sysfs
    if (gpio_init() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    if (i2c_init() < 0) {
        perror("Failed to initialize I2C");
        exit(EXIT_FAILURE);
    }

    // Open sysfs file for thermal management
    if ((fd = open("/sys/class/thermal/thermal_zone0/temp", O_RDONLY)) < 0) {
        perror("Failed to open thermal_zone0/temp");
        exit(EXIT_FAILURE);
    }

    // Open sysfs file for cooling device
    if ((fd = open("/sys/class/thermal/cooling_device0/cur_state", O_RDWR)) < 0) {
        perror("Failed to open cooling_device0/cur_state");
        exit(EXIT_FAILURE);
    }

    // Open log file
    if ((log_fd = open("/var/log/fan_control.log", O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Initialize cooling device
    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        perror("Failed to read cooling device");
        exit(EXIT_FAILURE);
    }

    if (data.state < MAX_STATE) {
        fan_state = data.state;
    } else {
        fan_state = MAX_STATE;
    }

    // Initialize fan speed map
    for (int i = 0; i < MAX_SPEEDS; i++) {
        fan_speed = (MAX_STATE - data.state) * (MAX_SPEEDS - i) / MAX_STATE + i;
        snprintf(buffer, sizeof(buffer), "%d", fan_speed);
        if (write(log_fd, buffer, strlen(buffer)) < 0) {
            perror("Failed to log fan speed");
            exit(EXIT_FAILURE);
        }
    }

    // Start fan control loop
    while (1) {
        // Read CPU temperature
        if (read(fd, &temp, sizeof(temp)) < 0) {
            perror("Failed to read CPU temperature");
            exit(EXIT_FAILURE);
        }

        // Calculate fan speed based on temperature
        fan_speed = (temp - 45) * (MAX_SPEEDS - data.state) / (MAX_STATE - data.state);
        fan_speed = (fan_speed + data.state) / 2;

        // Check if fan state should be changed
        if (fan_speed != data.state) {
            data.state = fan_speed;
            data.state = (data.state + 1) % MAX_STATE;

            // Log fan speed change
            if (write(log_fd, buffer, strlen(buffer)) < 0) {
                perror("Failed to log fan speed change");
                exit(EXIT_FAILURE);
            }

            // Log shutdown
            snprintf(log_file, sizeof(log_file), "/var/log/fan_control.log", "Shutdown: Fan state changed to %d", data.state);
            if (write(log_fd, log_file, strlen(log_file)) < 0) {
                perror("Failed to log shutdown");
                exit(EXIT_FAILURE);
            }

            // Stop fan
            if (ioctl(fd, I2C_RDWR, &data) < 0) {
                perror("Failed to stop fan");
                exit(EXIT_FAILURE);
            }

            // Exit program
            exit(EXIT_SUCCESS);
        }

        // Wait for 5 seconds
        nanosleep(&start_time, &end_time);
    }

    // Cleanup
    close(fd);
    close(log_fd);
    gpio_exit();
    return 0;
}

