#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/input.h>
#include <linux/gpio.h>
#include <linux/pigpio.h>

#define PWM_FREQUENCY 25000
#define PWM_PERIOD (1000000 / PWM_FREQUENCY)

int main() {
    int fd, gpioHandle, fanHandle;
    struct gpio_desc gpioDesc;
    struct input_dev inputDev;
    struct timespec ts;
    int temperature, dutyCycle;
    char filename[100];
    char *logFile = "cooling_log.csv";

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    // Open GPIO 18 (physical pin 12)
    gpioHandle = gpioOpen(12);
    if (gpioHandle < 0) {
        fprintf(stderr, "Error: Failed to open GPIO 18\n");
        gpioInitialise();
        return 1;
    }

    // Open fan control file
    snprintf(filename, sizeof(filename), "/sys/class/gpio/gpio18/value");
    fanHandle = open(filename, O_RDWR);
    if (fanHandle < 0) {
        fprintf(stderr, "Error: Failed to open fan control file\n");
        gpioClose(gpioHandle);
        gpioInitialise();
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(gpioHandle, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency\n");
        goto error_close_fan;
    }

    // Set PWM duty cycle
    dutyCycle = 0;
    if (gpioSetPWM(gpioHandle, PWM_FREQUENCY, PWM_PERIOD, &dutyCycle) < 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle\n");
        goto error_close_fan;
    }

    // Set up GPIO input
    gpioDesc.mode = GPIO_MODE_OUTPUT_PPM;
    gpioDesc.pull = GPIO_NOPULL;
    gpioDesc.type = GPIO_TYPE_PPM;
    gpioDesc.frequency = PWM_FREQUENCY;
    gpioDesc.zero_level = 0;
    gpioDesc.high_level = 1;
    gpioDesc.polarity = GPIO_POLARITY_LOW;
    gpioDesc.timeout_usec = 0;

    if (gpioOpenPwm(gpioHandle, &gpioDesc) < 0) {
        fprintf(stderr, "Error: Failed to open PWM channel\n");
        goto error_close_fan;
    }

    // Read temperature from /sys/class/thermal/thermal_zone0/temp
    if (readTemperature(&temperature) < 0) {
        fprintf(stderr, "Error: Failed to read temperature\n");
        goto error_close_gpio;
    }

    // Map duty cycle based on temperature
    if (mapDutyCycle(temperature) < 0) {
        fprintf(stderr, "Error: Failed to map duty cycle\n");
        goto error_close_gpio;
    }

    // Logging loop
    while (1) {
        // Read temperature and PWM duty cycle
        if (readTemperature(&temperature) < 0) {
            fprintf(stderr, "Error: Failed to read temperature\n");
            break;
        }

        if (readPwmDutyCycle(dutyCycle) < 0) {
            fprintf(stderr, "Error: Failed to read PWM duty cycle\n");
            break;
        }

        // Log data to file
        snprintf(filename, sizeof(filename), "cooling_log.csv");
        FILE *logFile = fopen(filename, "a");
        if (logFile == NULL) {
            fprintf(stderr, "Error: Failed to open log file\n");
            break;
        }

        ts.tv_sec = 0;
        ts.tv_nsec = 1000000000;
        if (fprintf(logFile, "%d,%d,%d\n", temperature, dutyCycle, (int)((100.0 * dutyCycle) / (temperature < 40 ? 40 : temperature > 70 ? 70 : temperature)))) < 0) {
            fprintf(stderr, "Error: Failed to write to log file\n");
            break;
        }

        fclose(logFile);
    }

    // Close GPIO and PWM channels
    gpioClose(gpioHandle);
    gpioSetPWMfrequency(gpioHandle, PWM_FREQUENCY);

error_close_gpio:
    gpioClose(gpioHandle);

error_close_fan:
    gpioClose(fanHandle);

error_close:
    gpioInitialise();
    return 1;
}

