    }

    // Open I2C bus
    if ((i2c_fd = i2cOpen(I2C_BUS_NUM)) < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C speed to 100kHz
    if (gpioSetSpeed(I2C_BUS_NUM, 100000) < 0) {
        fprintf(stderr, "Error setting I2C speed\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
