#include <fcntl.h>
#include <linux/i2c-gpio.h>

#define I2C_BUS_NUM 1
#define ADPD144RI_ADDRESS 0x39

int main() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    int red_threshold = 2000;
    int ir_threshold = 2000;
    int log_file_fd;
    char log_file_path[128] = "adpd144ri_log.txt";

    // Initialize GPIO and I2C
    gpio_init();
    i2c_fd = i2c_open(I2C_BUS_NUM);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Open log file
    log_file_fd = open(log_file_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_file_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Initialize ADPD144RI sensor
    if (adpd144ri_init() < 0) {
        fprintf(stderr, "Failed to initialize ADPD144RI sensor\n");
        return 1;
    }

    // Trigger LED on GPIO 17 (active-high)
    gpio_set_level(17, 1);

    // Loop to read and log data every 100 ms
    while (1) {
        // Read 16-bit red and IR data from FIFO data register
        if (adpd144ri_read_fifo_data(ADPD144RI_ADDRESS, &i2c_msgs[0].buf, &i2c_msgs[0].len) < 0) {
            fprintf(stderr, "Failed to read data from FIFO\n");
            return 1;
        }

        // Check for sensor absent condition
        if (i2c_msgs[0].len != 2) {
            fprintf(stderr, "Sensor absent condition detected\n");
            return 1;
        }

        // Check if red and IR data exceed threshold
        if (i2c_msgs[0].buf[0] > red_threshold || i2c_msgs[0].buf[1] > ir_threshold) {
            // Trigger LED on GPIO 17 (active-high)
            gpio_set_level(17, 1);
        } else {
            // Trigger LED on GPIO 17 (active-low)
            gpio_set_level(17, 0);
        }

        // Log timestamped readings to adpd144ri_log.txt
        struct timeval tv;
        gettimeofday(&tv, NULL);
        char timestamp[32];
        snprintf(timestamp, sizeof(timestamp), "%d-%02d-%02d %d:%02d:%02d.%03d",
                 tv.tv_sec, tv.tv_usec / 1000, tv.tv_usec % 1000, tv.tv_hour, tv.tv_min, tv.tv_sec, tv.tv_usec % 1000000);
        char log_line[128];
        snprintf(log_line, sizeof(log_line), "%.2f,%.2f,%.2f\n", (double)i2c_msgs[0].buf[0]/(1<<16), (double)i2c_msgs[0].buf[1]/(1<<16), timestamp);
        write(log_file_fd, log_line, strlen(log_line));

        // Wait for 100 ms
        usleep(100000);
    }

    // Clean up
    close(log_file_fd);
    close(i2c_fd);
    gpio_cleanup();

    return 0;
}

