#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/input.h>

#define RPM_LOG_FILE "rpm_log.txt"
#define PULSE_THRESHOLD 10

pthread_mutex_t pulse_counter_mutex;

int gpio_num = 18;
int sensor_pin = 12;

int main(int argc, char *argv[]) {
    if (gpio_init() != 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpio_set_mode(gpio_num, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    if (gpio_pull_up_enable(gpio_num) != 0) {
        fprintf(stderr, "Failed to enable pull-up on GPIO\n");
        return 1;
    }

    if (gpio_open_nonblock(gpio_num, &gpio_events) != 0) {
        fprintf(stderr, "Failed to open GPIO events\n");
        return 1;
    }

    gpio_event_type_t events = GPIO_EVENT_RISING_EDGE;
    if (gpio_event_type_set(gpio_num, events) != 0) {
        fprintf(stderr, "Failed to set event type\n");
        return 1;
    }

    gpio_event_type_t edge_type = GPIO_EVENT_FALLING_EDGE;
    if (gpio_event_type_set(gpio_num, edge_type) != 0) {
        fprintf(stderr, "Failed to set event type\n");
        return 1;
    }

    gpio_event_type_t edge_clear_type = GPIO_EVENT_RISING_EDGE;
    if (gpio_event_type_set(gpio_num, edge_clear_type) != 0) {
        fprintf(stderr, "Failed to set event type\n");
        return 1;
    }

    struct gpio_event event;
    while (1) {
        if (gpio_wait_event_nonblock(gpio_num, &event, 1, 1000) != 0) {
            fprintf(stderr, "Failed to wait for event\n");
            return 1;
        }

        if (event.type == GPIO_EVENT_RISING_EDGE) {
            if (pulse_count_increment() != 0) {
                fprintf(stderr, "Failed to increment pulse counter\n");
                return 1;
            }
        }

        if (event.type == GPIO_EVENT_FALLING_EDGE) {
            if (pulse_count_decrement() != 0) {
                fprintf(stderr, "Failed to decrement pulse counter\n");
                return 1;
            }
        }

        if (event.type == GPIO_EVENT_RISING_EDGE && pulse_count_get() > PULSE_THRESHOLD) {
            float rpm = (float) pulse_count_get() / (1.0 / (1.0 / 60.0));
            if (rpm > 0.0) {
                fprintf(stderr, "RPM: %.2f\n", rpm);
            }
        }
    }

    return 0;
}

int pulse_count_increment() {
    int count = 0;
    int previous_count = 0;

    while (1) {
        gpio_event_t event;
        if (gpio_wait_event_nonblock(gpio_num, &event, 1, 1000) != 0) {
            fprintf(stderr, "Failed to wait for event\n");
            return -1;
        }

        if (event.type == GPIO_EVENT_RISING_EDGE) {
            if (previous_count == 0) {
                previous_count = count;
            }
            count++;
        }

        if (event.type == GPIO_EVENT_FALLING_EDGE) {
            if (previous_count != 0) {
                float delta_time = (float) gpio_get_time_usec() / 1000000.0;
                float delta_count = (float) count - previous_count;
                float rpm = (float) delta_count / delta_time;
                if (rpm > 0.0) {
                    fprintf(stderr, "RPM: %.2f\n", rpm);
                    return count;
                }
            }
            previous_count = 0;
        }
    }
}

int pulse_count_decrement() {
    int count = 0;
    int previous_count = 0;

    while (1) {
        gpio_event_t event;
        if (gpio_wait_event_nonblock(gpio_num, &event, 1, 1000) != 0) {
            fprintf(stderr, "Failed to wait for event\n");
            return -1;
        }

        if (event.type == GPIO_EVENT_RISING_EDGE) {
            if (previous_count == 0) {
                previous_count = count;
            }
            count--;
        }

        if (event.type == GPIO_EVENT_FALLING_EDGE) {
            if (previous_count != 0) {
                float delta_time = (float) gpio_get_time_usec() / 1000000.0;
                float delta_count = (float) count - previous_count;
                float rpm = (float) delta_count / delta_time;
                if (rpm < 0.0) {
