#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <linux/i2c.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x39
#define LED_GPIO 17

int main() {
    int i2c_fd, gpio_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    struct gpio_request gpio_req;
    uint8_t adpd144ri_data[8];
    uint8_t adpd144ri_red_data[8];
    uint8_t adpd144ri_ir_data[8];
    int threshold = 2000;
    int i, j, count = 0;
    int log_file_fd;
    struct timeval start_time, end_time;
    char timestamp[80];
    char log_line[100];
    FILE *log_fp;

    // Initialize I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Open GPIO line for LED
    if ((gpio_fd = open("/dev/gpiomem", O_RDWR)) < 0) {
        perror("Error opening GPIO line");
        exit(EXIT_FAILURE);
    }

    // Set GPIO 17 as an output
    if (ioctl(gpio_fd, GPIO_SET_DIR, GPIO_OUTPUT) < 0) {
        perror("Error setting GPIO 17 as output");
        exit(EXIT_FAILURE);
    }

    // Set GPIO 17 as a GPIO line
    if (ioctl(gpio_fd, GPIO_SET_VALUE, GPIO_17) < 0) {
        perror("Error setting GPIO 17 as GPIO line");
        exit(EXIT_FAILURE);
    }

    // Open log file
    if ((log_file_fd = open("adpd144ri_log.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    // Set up I2C communication
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        exit(EXIT_FAILURE);
    }

    // Read PART_ID register
    if (ioctl(i2c_fd, I2C_RDWR, I2C_RD_PART_ID) < 0) {
        perror("Error reading PART_ID register");
        exit(EXIT_FAILURE);
    }

    // Read red and IR channel data from FIFO data registers
    if (ioctl(i2c_fd, I2C_RDWR, I2C_FIFO_READ(0)) < 0) {
        perror("Error reading red and IR channel data from FIFO");
        exit(EXIT_FAILURE);
    }

    // Log timestamped readings to log file
    log_fp = fopen("adpd144ri_log.txt", "a");
    if (log_fp == NULL) {
        perror("Error opening log file for writing");
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < 8; i++) {
        timestamp[0] = '\0';
        gettimeofday(&start_time, NULL);
        // Read data from FIFO
        if (ioctl(i2c_fd, I2C_RDWR, I2C_FIFO_READ(i)) < 0) {
            perror("Error reading data from FIFO");
            exit(EXIT_FAILURE);
        }
        timestamp[strlen(timestamp)] = '\0';
        gettimeofday(&end_time, NULL);
        time_diff(&end_time, &start_time);
        strftime(timestamp + strlen(timestamp), sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &end_time);
        log_fp << timestamp << "," << timestamp << "," << adpd144ri_data[i] << "\n";
        count++;
    }

    // Close log file
    fclose(log_fp);

    // Clean up I2C bus
    close(i2c_fd);

    // Clean up GPIO lines
    close(gpio_fd);

    // Clean up log file
    unlink("adpd144ri_log.txt");

    // Clean up I2C bus
    return 0;
}

