#define GAIN_PIN 18
#define MAX9814_OUT_PIN 17
#define GAIN_PIN_NAME "gpio-17"
#define AUDIO_LOG_FILE "audio_log.txt"

int main() {
    int fd, gain_fd, audio_fd;
    struct gpiod_event event;
    struct gpiod_event_attr attr;
    char filename[128];
    char buffer[1024];
    int peak_count = 0;
    int peak_time = 0;
    struct timespec start_time, end_time;
    int level = 1;
    int i = 0;
    int exit_flag = 0;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open gain and audio files
    gain_fd = open(GAIN_PIN_NAME, O_RDWR);
    if (gain_fd < 0) {
        fprintf(stderr, "Failed to open gain file: %s\n", GAIN_PIN_NAME);
        gpiod_exit();
        return 1;
    }
    audio_fd = open(AUDIO_LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (audio_fd < 0) {
        fprintf(stderr, "Failed to open audio log file: %s\n", AUDIO_LOG_FILE);
        close(gain_fd);
        gpiod_exit();
        return 1;
    }

    // Set gain to 60dB
    if (gpiod_set_line_level(gain_fd, GAIN_PIN, GAIN_PIN_NAME, GAIN_PIN_NAME, 60) < 0) {
        fprintf(stderr, "Failed to set gain to 60dB\n");
        close(gain_fd);
        close(audio_fd);
        gpiod_exit();
        return 1;
    }

    // Set up the event for detecting rising edges
    if (gpiod_event_request(gain_fd, GAIN_PIN, GAIN_PIN_NAME, &event, 1, 0) < 0) {
        fprintf(stderr, "Failed to request event for rising edges\n");
        close(gain_fd);
        close(audio_fd);
        gpiod_exit();
        return 1;
    }

    // Loop indefinitely
    while (1) {
        // Read the digital input pin
        if (gpiod_read(gain_fd, GAIN_PIN, GAIN_PIN_NAME, &event) < 0) {
            fprintf(stderr, "Failed to read digital input pin\n");
            close(gain_fd);
            close(audio_fd);
            gpiod_exit();
            return 1;
        }

        // Check if a rising edge has been detected
        if (event.state == 1) {
            // Log the peak event
            if (write(audio_fd, buffer, 1024) < 0) {
                fprintf(stderr, "Failed to write to audio log file\n");
                close(gain_fd);
                close(audio_fd);
                gpiod_exit();
                return 1;
            }

            // Increment peak count and timestamp
            peak_count++;
            gettimeofday(&start_time, NULL);
            peak_time = start_time.tv_sec;
        }

        // Check if the peak count has reached the desired threshold
        if (peak_count >= 10) {
            // Log the peak event
            if (write(audio_fd, buffer, 1024) < 0) {
                fprintf(stderr, "Failed to write to audio log file\n");
                close(gain_fd);
                close(audio_fd);
                gpiod_exit();
                return 1;
            }

            // Reset peak count and timestamp
            peak_count = 0;
            gettimeofday(&start_time, NULL);
        }

        // Wait for 10 ms
        usleep(10000);
    }

    // Clean up
    close(gain_fd);
    close(audio_fd);
    gpiod_exit();

    return 0;
}

