        fprintf(stderr, "Failed to set gain to 60dB\n");
        close(gain_fd);
        close(audio_fd);
        gpiod_exit();
        return 1;
    }

    // Set up the event for detecting rising edges
    if (gpiod_event_request(gain_fd, GAIN_PIN, GAIN_PIN_NAME, &event, 1, 0) < 0) {
        fprintf(stderr, "Failed to request event for rising edges\n");
        close(gain_fd);
        close(audio_fd);
        gpiod_exit();
        return 1;
    }

    // Loop indefinitely
    while (1) {
        // Read the digital input pin
        if (gpiod_read(gain_fd, GAIN_PIN, GAIN_PIN_NAME, &event) < 0) {
            fprintf(stderr, "Failed to read digital input pin\n");
            close(gain_fd);
            close(audio_fd);
            gpiod_exit();
            return 1;
        }

        // Check if a rising edge has been detected
        if (event.state == 1) {
            // Log the peak event
            if (write(audio_fd, buffer, 1024) < 0) {
                fprintf(stderr, "Failed to write to audio log file\n");
                close(gain_fd);
                close(audio_fd);
                gpiod_exit();
                return 1;
            }

            // Increment peak count and timestamp
            peak_count++;
            gettimeofday(&start_time, NULL);
            peak_time = start_time.tv_sec;
        }

        // Check if the peak count has reached the desired threshold
        if (peak_count >= 10) {
            // Log the peak event
            if (write(audio_fd, buffer, 1024) < 0) {
                fprintf(stderr, "Failed to write to audio log file\n");
                close(gain_fd);
                close(audio_fd);
                gpiod_exit();
                return 1;
            }

            // Reset peak count and timestamp
            peak_count = 0;
            gettimeofday(&start_time, NULL);
        }

        // Wait for 10 ms
        usleep(10000);
    }

    // Clean up
    close(gain_fd);
    close(audio_fd);
    gpiod_exit();

    return 0;
}
