#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define I2C_BUS_1 1
#define I2C_ADDRESS 0x70

int main() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    uint8_t i2c_buf[7];
    int ret;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    // Set I2C bus
    if (gpioSetBrightness(0, 0) < 0) {
        fprintf(stderr, "Error: Failed to set I2C bus\n");
        gpioTerminate();
        return 1;
    }
    gpioSetMode(I2C_BUS_1, PI_MODE_I2C);

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error: Failed to set I2C address\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up I2C messages
    i2c_msgs[0].addr = I2C_ADDRESS;
    i2c_msgs[0].flags = 0;
    i2c_msgs[1].addr = I2C_ADDRESS;
    i2c_msgs[1].flags = I2C_RD;

    // Read 7 bytes from the sensor
    if (ioctl(i2c_fd, I2C_RDWR, i2c_msgs) < 0) {
        fprintf(stderr, "Error: Failed to read from sensor\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Process sensor data
    for (int i = 0; i < 2; i++) {
        if (i2c_msgs[i].flags & I2C_ERR) {
            fprintf(stderr, "Error: I2C error during read\n");
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        if (i2c_msgs[i].flags & I2C_REP) {
            if (i2c_msgs[i].buf == NULL) {
                fprintf(stderr, "Error: I2C buffer is NULL\n");
                close(i2c_fd);
                gpioTerminate();
                return 1;
            }

            // Extract TVOC and eCO2 values
            uint8_t tvoc_byte = i2c_msgs[i].buf[1];
            uint8_t e_co2_byte = i2c_msgs[i].buf[2];

            // Compute IAQ index
            int tvoc = (tvoc_byte >> 1) & 0x7F;
            int e_co2 = (e_co2_byte >> 4) & 0x3F;

            // Log values
            char timestamp[50];
            struct tm tm;
            time_t now = time(NULL);
            localtime_r(&now, &tm);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

            FILE *log_file = fopen("air_quality_log.csv", "a");
            if (log_file == NULL) {
                fprintf(stderr, "Error: Failed to open log file\n");
                close(i2c_fd);
                gpioTerminate();
                return 1;
            }

            fprintf(log_file, "%s,%,%.2f,%.2f\n", timestamp, tvoc, e_co2);

            fclose(log_file);
        }
    }

    // Close I2C bus
    if (ioctl(i2c_fd, I2C_RDWR, NULL) < 0) {
        fprintf(stderr, "Error: Failed to close I2C bus\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

