#include <errno.h>
#include <sys/ioctl.h>
#include <linux/input.h>

#include <gpiod.h>

#define GPIO_FILE "/dev/gpiochip0"
#define TOUCH_LINE "ttp223_tamper"

int main() {
    int chip_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_event event;
    struct timespec start_time, end_time;
    int touch_count = 0;
    int intr_count = 0;
    int intr_threshold_ms = 5000; // 5 seconds
    int intr_interval_ms = 100; // poll every 100 ms
    int exit_code = 0;

    // Open gpiochip0 by name
    chip_fd = gpiod_open(GPIO_FILE, GPIDO_READ);
    if (chip_fd < 0) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Request the line as input with the consumer label "ttp223_tamper"
    line = gpiod_request_line(chip_fd, TOUCH_LINE, GPIDO_INPUT, "ttp223_tamper");
    if (line == NULL) {
        fprintf(stderr, "Failed to request line %s: %s\n", TOUCH_LINE, gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Initialize the chip
    if (gpiod_init(chip_fd) < 0) {
        fprintf(stderr, "Failed to initialize chip: %s\n", gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set the line to active-high
    if (gpiod_line_direction(chip_fd, line, GPIDO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set line %s direction to output: %s\n", TOUCH_LINE, gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set the line to active-high
    if (gpiod_line_active_high(chip_fd, line) < 0) {
        fprintf(stderr, "Failed to set line %s active-high: %s\n", TOUCH_LINE, gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set the line to open-drain
    if (gpiod_line_mode(chip_fd, line, GPIDO_OPEN_DRAIN) < 0) {
        fprintf(stderr, "Failed to set line %s mode to open-drain: %s\n", TOUCH_LINE, gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set the line to pull-up
    if (gpiod_line_pull_up_down(chip_fd, line, GPIDO_PULL_UP) < 0) {
        fprintf(stderr, "Failed to set line %s pull-up: %s\n", TOUCH_LINE, gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set the line to interrupt-driven
    if (gpiod_line_interrupt_enable(chip_fd, line, GPIDO_INTERRUPT_EDGE_FALLING) < 0) {
        fprintf(stderr, "Failed to set line %s interrupt-driven edge falling: %s\n", TOUCH_LINE, gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set the line to active-high
    if (gpiod_line_active_high(chip_fd, line) < 0) {
        fprintf(stderr, "Failed to set line %s active-high: %s\n", TOUCH_LINE, gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set the line to open-drain
    if (gpiod_line_mode(chip_fd, line, GPIDO_OPEN_DRAIN) < 0) {
        fprintf(stderr, "Failed to set line %s mode to open-drain: %s\n", TOUCH_LINE, gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set the line to pull-up
    if (gpiod_line_pull_up_down(chip_fd, line, GPIDO_PULL_UP) < 0) {
        fprintf(stderr, "Failed to set line %s pull-up: %s\n", TOUCH_LINE, gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set the line to interrupt-driven
    if (gpiod_line_interrupt_enable(chip_fd, line, GPIDO_INTERRUPT_EDGE_FALLING) < 0) {
        fprintf(stderr, "Failed to set line %s interrupt-driven edge falling: %s\n", TOUCH_LINE, gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set the line to active-high
    if (gpiod_line_active_high(chip_fd, line) < 0) {
        fprintf(stderr, "Failed to set line %s active-high: %s\n", TOUCH_LINE, gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set the line to open-drain
    if (gpiod_line_mode(chip_fd, line, GPIDO_OPEN_DRAIN) < 0) {
        fprintf(stderr, "Failed to set line %s mode to open-drain: %s\n", TOUCH_LINE, gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set the line to pull-up
    if (gpiod_line_pull_up_down(chip_fd, line, GPIDO_PULL_UP) < 0) {
        fprintf(stderr, "Failed to set line %s pull-up: %s\n", TOUCH_LINE, gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set the line to interrupt-driven
    if (gpiod_line_interrupt_enable(chip_fd, line, GPIDO_INTERRUPT_EDGE_FALLING) < 0) {
        fprintf(stderr, "Failed to set line %s interrupt-driven edge falling: %s\n", TOUCH_LINE, gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Poll the line every 100 ms
    while (1) {
        struct timespec start, end;
        int ret;

        // Get the current time
        if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
            fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }

        // Wait for the line to change state
        ret = gpiod_event_wait(chip_fd, line, &event, 1000);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for line %s state change: %s\n", TOUCH_LINE, gpiod_strerror(errno));
            exit(EXIT_FAILURE);
        }

        // Check if the line is still touched
        if (event.value == 1) {
            // Print intrusion alert
            printf("Intrusion detected!\n");
            touch_count++;

            // Reset the timer
            end_time.tv_sec = start_time.tv_sec;
            end_time.tv_nsec = start_time.tv_nsec;
            ret = clock_gettime(CLOCK_MONOTONIC, &end);
            if (ret < 0) {
                fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
                exit(EXIT_FAILURE);
            }

            // Check if the sensor has been touched for more than 5 seconds
            if (end_time.tv_sec - start_time.tv_sec > 5) {
                // Print intrusion alert
                printf("Intrusion detected! Sensor has been touched for more than 5 seconds.\n");
                exit(EXIT_SUCCESS);
            }
        }

        // Check if the line is released
        if (event.value == 0) {
