#define KY_026_GPIO_PIN 20
#define KY_026_LOG_FILE "flame_log.txt"
#define KY_026_LOG_FORMAT "%Y-%m-%dT%H:%M:%S"

int main() {
    int fd;
    struct gpiod_device *device;
    struct gpiod_event_attr attr;
    struct gpiod_event_info info;
    char buffer[32];
    char *timestamp;
    int ret;

    // Open GPIO chip
    fd = gpiod_open(GPIO_FILENAME, GPIDO_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(fd));
        return 1;
    }

    // Initialize KY-026 Flame Sensor
    device = gpiod_get_device(fd);
    if (device == NULL) {
        fprintf(stderr, "Failed to get device: %s\n", gpiod_strerror(fd));
        gpiod_close(fd);
        return 1;
    }

    // Set KY-026 Flame Sensor as output
    ret = gpiod_set_direction(device, GPIO_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set direction: %s\n", gpiod_strerror(ret));
        gpiod_close(fd);
        gpiod_unregister_device(device);
        return 1;
    }

    // Set KY-026 Flame Sensor to trigger on GPIO 20
    ret = gpiod_set_event_detect(device, GPIO_20, GPIDO_FALLING_EDGE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set event detect: %s\n", gpiod_strerror(ret));
        gpiod_close(fd);
        gpiod_unregister_device(device);
        return 1;
    }

    // Set KY-026 Flame Sensor to trigger every 100 milliseconds
    ret = gpiod_set_event_rate(device, 100);
    if (ret < 0) {
        fprintf(stderr, "Failed to set event rate: %s\n", gpiod_strerror(ret));
        gpiod_close(fd);
        gpiod_unregister_device(device);
        return 1;
    }

    // Wait for flame detection or 100 milliseconds
    while (1) {
        // Read KY-026 Flame Sensor state
        ret = gpiod_get_event_state(device, GPIO_20, &info);
        if (ret < 0) {
            fprintf(stderr, "Failed to get event state: %s\n", gpiod_strerror(ret));
            continue;
        }

        // Check if flame is detected
        if (info.state == 1) {
            timestamp = strftime(buffer, sizeof(buffer), KY_026_LOG_FORMAT, time(NULL));
            fprintf(stderr, "Flame detected at: %s\n", timestamp);
            // Log state transition to 'flame_log.txt'
            FILE *log_file = fopen(KY_026_LOG_FILE, "a");
            if (log_file == NULL) {
                fprintf(stderr, "Failed to open log file: %s\n", KY_026_LOG_FILE);
                continue;
            }
            fprintf(log_file, "%s\n", timestamp);
            fclose(log_file);
        }

        // Wait for 100 milliseconds
        usleep(100000);
    }

    // Clean up GPIO resources
    gpiod_unregister_device(device);
    gpiod_close(fd);

    return 0;
}

