#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDRESS 0x44

int main() {
    int i2c_fd;
    int result;
    uint16_t data;
    char filename[20];
    struct i2c_rdwr_ioctl_data data_rdwr;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_rdwr_ioctl_data *data_ptr;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio library\n");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = pigpio_open_i2c(I2C_BUS_NUM, I2C_ADDRESS)) < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        return 1;
    }

    // Create log file
    snprintf(filename, sizeof(filename), "light_data.txt");
    FILE *log_file = fopen(filename, "w");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    // Configure sensor for continuous conversion mode
    if (pigpio_set_mode(i2c_fd, I2C_MODE_CONT) < 0) {
        fprintf(stderr, "Error setting continuous conversion mode\n");
        return 1;
    }

    // Set conversion time to 100 ms
    if (pigpio_set_conversion_time(i2c_fd, 100) < 0) {
        fprintf(stderr, "Error setting conversion time\n");
        return 1;
    }

    // Set full-scale range
    if (pigpio_set_fullscale(i2c_fd, I2C_FS_16BIT) < 0) {
        fprintf(stderr, "Error setting full-scale range\n");
        return 1;
    }

    // Start reading data
    while (1) {
        // Wait for sensor to complete conversion
        if (pigpio_wait_for_completion(i2c_fd, I2C_TIMEOUT_MS) < 0) {
            fprintf(stderr, "Error waiting for conversion completion\n");
            continue;
        }

        // Read data from sensor
        if (pigpio_read_i2c_reg16(i2c_fd, I2C_RESULT_REG, &data) < 0) {
            fprintf(stderr, "Error reading data from sensor\n");
            continue;
        }

        // Unpack exponent and mantissa
        data_ptr = &data;
        data.wr_buf = &data_rdwr;
        data.wr_len = sizeof(data_rdwr);
        data_rdwr.wr_buf = &data_rdwr;
        data_rdwr.wr_len = sizeof(data_rdwr);

        // Compute lux
        uint16_t lux = 0;
        for (int i = 0; i < 16; i++) {
            lux += (data_ptr->data >> (12 - i)) & 0x3FF;
        }

        // Log data
        fprintf(log_file, "%.6f\n", 0.01 * 2.0 * pow(2.0, (float)lux / 4096.0));

        // Close log file
        fclose(log_file);
    }

    // Cleanup
    pigpio_exit();
    pigpio_unexport();

    return 0;
}

