#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/stat.h>

#include <pigpio.h>

#define GPIO_DIR_IN 2
#define GPIO_PULL_DOWN 1
#define GPIO_PULL_UP 0

int main() {
    int fd, gpio, i, ret;
    char buffer[16];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    // Verify pigpio initialization
    if (gpioIsInitialised() == 0) {
        fprintf(stderr, "Error: pigpio not initialized\n");
        return 1;
    }

    // Open GPIO file
    fd = open("/dev/gpiomem", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO file\n");
        return 1;
    }

    // Set all GPIOs as input with pull-down resistor
    for (gpio = 2; gpio <= 9; gpio++) {
        ret = gpioSetMode(gpio, GPIO_DIR_IN | GPIO_PULL_DOWN);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d as input with pull-down resistor\n", gpio);
            return 1;
        }
    }

    // Install signal handlers
    signal(SIGINT, sigintHandler);
    signal(SIGTERM, sigtermHandler);

    // Main loop
    while (1) {
        // Wait 100 ms
        gpioDelay(100000);

        // Poll and log state of all 8 channels
        for (gpio = 2; gpio <= 9; gpio++) {
            ret = gpioRead(gpio, buffer, 16);
            if (ret < 0) {
                fprintf(stderr, "Error: Failed to read GPIO %d\n", gpio);
                return 1;
            }

            for (i = 0; i < 16; i++) {
                if (buffer[i] & (1 << (7 - (gpio - 2)))) {
                    printf("[+%d ms] CH%d=1\n", gpio - 2, (7 - (gpio - 2)) + i);
                } else {
                    printf("[-%d ms] CH%d=0\n", gpio - 2, (7 - (gpio - 2)) + i);
                }
            }
        }
    }

    // Cleanup
    gpioTerminate();
    return 0;
}

// Signal handlers
void sigintHandler(int signum) {
    printf("[+%d ms] SIGINT received\n", getpid());
}

void sigtermHandler(int signum) {
    printf("[+%d ms] SIGTERM received\n", getpid());
    exit(0);
}

