#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define GPIO_DIR_OUT  (1 << 4)  // BCM GPIO 4 (GPIO 4)
#define GPIO_DIR_IN   (1 << 5)  // BCM GPIO 5 (GPIO 5)

int main() {
    int fd;
    int gpio_fd;
    int pigpio_initialized = 0;
    int pigpio_error = 0;
    int sensor_state_h = 0;
    int sensor_state_l = 0;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio library\n");
        return 1;
    }

    // Check if pigpio is properly initialized
    if (gpioIsInitialized() == 0) {
        fprintf(stderr, "pigpio library not properly initialized\n");
        return 1;
    }

    // Open GPIO file descriptors
    if ((fd = open("/dev/gpiomem", O_RDWR)) < 0) {
        fprintf(stderr, "Error opening GPIO file descriptor\n");
        return 1;
    }

    if ((gpio_fd = open("/dev/gpiochip0", O_RDWR)) < 0) {
        fprintf(stderr, "Error opening GPIO chip file descriptor\n");
        return 1;
    }

    // Set GPIO direction to OUT
    if (gpioSetMode(gpio_fd, GPIO_DIR_OUT) < 0) {
        fprintf(stderr, "Error setting GPIO direction to OUT\n");
        return 1;
    }

    // Set GPIO 4 and 5 as output
    if (gpioSetLine(gpio_fd, GPIO_DIR_OUT, GPIO_OUTPUT, GPIO_OUTPUT_LEVEL_HIGH) < 0) {
        fprintf(stderr, "Error setting GPIO 4 as output\n");
        return 1;
    }

    if (gpioSetLine(gpio_fd, GPIO_DIR_OUT, GPIO_OUTPUT, GPIO_OUTPUT_LEVEL_LOW) < 0) {
        fprintf(stderr, "Error setting GPIO 5 as output\n");
        return 1;
    }

    // Set pull-up resistors
    if (gpioSetPullUpDrain(gpio_fd, GPIO_PULLUP_ENABLE, GPIO_PULLUP_ENABLE) < 0) {
        fprintf(stderr, "Error setting pull-up resistors\n");
        return 1;
    }

    // Set GPIO 4 and 5 as input
    if (gpioSetLine(gpio_fd, GPIO_DIR_IN, GPIO_INPUT, GPIO_INPUT_PULLUP) < 0) {
        fprintf(stderr, "Error setting GPIO 4 as input\n");
        return 1;
    }

    if (gpioSetLine(gpio_fd, GPIO_DIR_IN, GPIO_INPUT, GPIO_INPUT_PULLUP) < 0) {
        fprintf(stderr, "Error setting GPIO 5 as input\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sig_handler);

    // Read sensor states every 500 ms
    while (1) {
        sensor_state_h = pigpio_getDigitalIn(gpio_fd, GPIO_MAGNETIC_H);
        sensor_state_l = pigpio_getDigitalIn(gpio_fd, GPIO_MAGNETIC_L);

        printf("Sensor H: %d, Sensor L: %d\n", sensor_state_h, sensor_state_l);

        // Wait for 500 ms
        sleep(0.5);
    }

    // Clean up
    close(fd);
    close(gpio_fd);
    gpioTerminate();

    return 0;
}
