#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define BCM_GPIO 4
#define BCM_PIN 7

int main() {
    int ret;
    int gpio_fd;
    int tilt_sensor_gpio;
    struct gpio_desc *desc;
    char *banner = "Tilt Sensor Monitor\n";

    // Initialize pigpio library
    if ((ret = gpioInitialise()) != 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", gpioErrorStr(ret));
        return 1;
    }

    // Get GPIO file descriptor
    gpio_fd = gpioOpen(BCM_GPIO);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error opening GPIO file descriptor: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Get GPIO descriptor for the tilt sensor
    desc = gpioGetDesc(gpio_fd);
    if (desc == NULL) {
        fprintf(stderr, "Error getting GPIO descriptor: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set the tilt sensor as a digital input with the internal pull-up resistor enabled
    if (gpioSetMode(desc, BCM_GPIO_IN) < 0) {
        fprintf(stderr, "Error setting mode for the tilt sensor: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Enable the internal pull-up resistor for the tilt sensor
    if (gpioSetPullUpDrain(desc, BCM_GPIO_PUD_UP) < 0) {
        fprintf(stderr, "Error enabling pull-up resistor for the tilt sensor: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Poll the sensor every 100 ms
    while (1) {
        if (gpioRead(desc, BCM_GPIO) < 0) {
            fprintf(stderr, "Error reading from GPIO: %s\n", strerror(errno));
            gpioTerminate();
            return 1;
        }

        if (desc->state == 0) {
            printf("Tilted\n");
        } else {
            printf("Not Tilted\n");
        }

        // Flush stdout after each log line
        fflush(stdout);

        // Wait for a signal to exit
        if (gpioWaitSignal(gpio_fd, SIGINT) < 0) {
            fprintf(stderr, "Error waiting for SIGINT: %s\n", strerror(errno));
            gpioTerminate();
            return 1;
        }
    }

    gpioTerminate();
    return 0;
}

