        return 1;
    }

    if (gpio_pull_up_enable(gpio_num) < 0) {
        fprintf(stderr, "Error enabling pull-up resistor\n");
        gpio_exit();
        return 1;
    }

    fd = open("/dev/pigpio", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening pigpio device\n");
