    if (driver_version < PIGPIO_VERSION_MAJOR || (driver_version == PIGPIO_VERSION_MAJOR && driver_version < PIGPIO_VERSION_MINOR)) {
        fprintf(stderr, "Incompatible pigpio version\n");
        goto exit;
    }

    if (gpio_export(gpio_num) < 0) {
        fprintf(stderr, "Error exporting GPIO\n");
        goto exit;
    }

