#define LED_GPIO_PIN 25
#define LED_GPIO_RESISTOR 220
#define SENSOR_1_GPIO_PIN 23
#define SENSOR_2_GPIO_PIN 24

int main() {
    int err, gpio;
    int sensor_1_value, sensor_2_value;

    // Initialize pigpio library
    if (gpio_init() < 0) {
        fprintf(stderr, "Error initializing pigpio library\n");
        return 1;
    }

    if (gpio_set_mode(SENSOR_1_GPIO_PIN, PI_OUT) < 0 ||
        gpio_set_mode(SENSOR_2_GPIO_PIN, PI_OUT) < 0) {
        fprintf(stderr, "Error setting GPIO modes\n");
        return 1;
    }

    if (gpio_open_nonblock(SENSOR_1_GPIO_PIN, &gpio) < 0 ||
        gpio_open_nonblock(SENSOR_2_GPIO_PIN, &gpio) < 0) {
        fprintf(stderr, "Error opening GPIO pins\n");
        return 1;
    }

    if (gpio_set_level(SENSOR_1_GPIO_PIN, 1) < 0) {
        fprintf(stderr, "Error setting sensor 1 output to HIGH\n");
        return 1;
    }

    if (gpio_set_level(SENSOR_2_GPIO_PIN, 1) < 0) {
        fprintf(stderr, "Error setting sensor 2 output to HIGH\n");
        return 1;
    }

    while (1) {
        sensor_1_value = gpio_read(SENSOR_1_GPIO_PIN);
        sensor_2_value = gpio_read(SENSOR_2_GPIO_PIN);

        if (sensor_1_value == 0 && sensor_2_value == 0) {
            gpio_set_level(LED_GPIO_PIN, 1);
        } else {
            gpio_set_level(LED_GPIO_PIN, 0);
        }

        usleep(100 * 1000); // 100 ms
    }

    gpio_close(gpio);
    gpio_uninstall_callback(gpio);
    gpio_exit();

    return 0;
}

