#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define SENSOR_PIN 23
#define ALERT_FILE "flood_log.txt"
#define MAX_RETRIES 60

int gpio_fd;
int sensor_pin;

void init_gpio() {
    if (gpio_init() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    gpio_set_mode(gpio_fd, GPIO_IN);
    gpio_set_pull_up_down(gpio_fd, GPIO_PUD_UP);
    gpio_open(gpio_fd);

    gpio_request_irq(gpio_fd, SENSOR_PIN, GPIO_INTR_DISABLED, gpio_callback, NULL);
}

void cleanup_gpio() {
    gpio_close(gpio_fd);
    gpio_unrequest_irq(gpio_fd, SENSOR_PIN);
    gpio_release(gpio_fd);
    gpio_exit(gpio_fd);
}

void read_sensor() {
    int retries = MAX_RETRIES;
    while (retries > 0) {
        if (gpio_read(gpio_fd) == GPIO_PIN_HIGH) {
            printf("Water detected at %s\n", ctime(&(time(NULL)));
            fprintf(ALERT_FILE, "Water detected at %s\n", ctime(&(time(NULL)));
            return;
        }

        retries--;
        usleep(2 * 1000 * 1000); // Wait for 2 seconds
    }

    printf("Failed to detect water after %d attempts\n", retries);
}

int main() {
    init_gpio();

    while (1) {
        read_sensor();
        usleep(2 * 1000 * 1000); // Wait for 2 seconds
    }

    cleanup_gpio();
    return 0;
}

