#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <gpiod.h>

#define TOUCH_SENSOR_PATH "/dev/i2c-1"
#define LED_GPIO_PATH "/sys/class/gpio/gpio18/value"

int main() {
    int gpio_fd, touch_fd, syslog_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpiod_line_request line_request;
    struct gpiod_event event;
    int touch_status = 0;
    int syslog_level = LOG_INFO;

    // Open syslog
    syslog_fd = openlog("touch_sensor_app", syslog_level, LOG_DAEMON);
    if (syslog_fd == -1) {
        perror("Failed to open syslog");
        exit(EXIT_FAILURE);
    }

    // Open GPIO
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd == -1) {
        perror("Failed to open GPIO");
        exit(EXIT_FAILURE);
    }

    // Open touch sensor
    if (ioctl(gpio_fd, GPIOC_GET_LINE_RES, &line_request) < 0) {
        perror("Failed to get line request");
        exit(EXIT_FAILURE);
    }

    // Open syslog for touch sensor
    if (syslog(syslog_fd, "Touch sensor opened successfully") < 0) {
        perror("Failed to open syslog for touch sensor");
        exit(EXIT_FAILURE);
    }

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        perror("Failed to initialize libgpiod");
        exit(EXIT_FAILURE);
    }

    // Initialize LED
    if (ioctl(18, GPIO_SET_VALUE, 1) < 0) {
        perror("Failed to set LED GPIO to high");
        exit(EXIT_FAILURE);
    }

    // Initialize syslog for LED
    if (syslog(syslog_fd, "LED initialized successfully") < 0) {
        perror("Failed to open syslog for LED");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read touch sensor
        if (ioctl(touch_fd, TOUCH_SENSOR_READ, &i2c_data) < 0) {
            perror("Failed to read touch sensor");
            exit(EXIT_FAILURE);
        }

        // Check if touch sensor is actively touched
        if (i2c_data.touched) {
            // Illuminate LED
            if (ioctl(18, GPIO_SET_VALUE, 1) < 0) {
                perror("Failed to set LED GPIO to high");
                exit(EXIT_FAILURE);
            }

            // Log touch event
            char buffer[50];
            sprintf(buffer, "Touched sensor at %d", i2c_data.address);
            syslog(syslog_fd, "%s", buffer);
        }

        // Wait 50 ms
        sleep(50);

        // Read touch sensor again
        if (ioctl(touch_fd, TOUCH_SENSOR_READ, &i2c_data) < 0) {
            perror("Failed to read touch sensor");
            exit(EXIT_FAILURE);
        }

        // Check if touch sensor is still actively touched
        if (i2c_data.touched) {
            // Unilluminate LED
            if (ioctl(18, GPIO_SET_VALUE, 0) < 0) {
                perror("Failed to set LED GPIO to low");
                exit(EXIT_FAILURE);
            }

            // Log touch event
            sprintf(buffer, "Released sensor at %d", i2c_data.address);
            syslog(syslog_fd, "%s", buffer);
        }
    }

    // Cleanup
    gpiod_exit();
    close(syslog_fd);
    close(gpio_fd);
    close(touch_fd);
    return 0;
}

