#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define LED_GPIO 18
#define LED_PIN 12

int main() {
    int chip_fd, line_fd, line_num;
    struct gpiod_event event;
    struct gpiod_event_attr attr;
    int debounce_ms = 50;
    int debounce_count = 0;
    int touch_detected = 0;

    // Initialize LED line as output
    if (gpio_request_line(LED_GPIO, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to request GPIO %d line\n", LED_GPIO);
        return 1;
    }

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open the chip
    if (gpiod_chip_open(GPIDO_CHIP_LINE, &chip_fd) < 0) {
        fprintf(stderr, "Failed to open chip\n");
        return 1;
    }

    // Open the line
    if (gpiod_line_request(chip_fd, LED_GPIO, LED_PIN, GPIDO_LINE_IN, &line_fd) < 0) {
        fprintf(stderr, "Failed to request line\n");
        return 1;
    }

    // Set debounce attribute
    attr.event_mask = GPIDO_EVENT_LINE_EDGE;
    attr.debounce_time = debounce_ms;
    attr.debounce_count = debounce_count;

