#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_DIR 17
#define GPIO_INH_VALUE 0

int main() {
    int fd, ret;
    struct gpio_value value;
    char log_file_name[] = "/var/log/rain_events.log";

    // Initialize pigpio library
    if (gpio_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    // Open log file
    if ((fd = open(log_file_name, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        fprintf(stderr, "Error: Failed to open log file\n");
        return 1;
    }

    // Set up GPIO 17 as an input with internal pull-up resistor enabled
    if (gpio_set_mode(GPIO_DIR, GPIO_IN) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO 17 as input with internal pull-up resistor\n");
        return 1;
    }

    // Set GPIO 17 to input with internal pull-up resistor
    if (gpio_set_pull_up_en(GPIO_DIR, GPIO_INH_VALUE) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO 17 to input with internal pull-up resistor\n");
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Main loop
    while (1) {
        // Poll the sensor
        ret = gpio_get_value(GPIO_DIR, &value);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to read sensor value\n");
            break;
        }

        // Log state transition
        if (value.value == GPIO_INH_VALUE) {
            char timestamp[50];
            struct tm tm;
            time_t now = time(NULL);
            char *log_message = "Rain Detected";

            // Get current time
            localtime_r(&now, &tm);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

            // Write log entry
            if (open(log_file_name, O_WRONLY | O_CREAT | O_TRUNC, 0644) < 0) {
                fprintf(stderr, "Error: Failed to open log file\n");
                break;
            }
            if (write(fileno(log_file_name), timestamp, strlen(timestamp)) < 0) {
                fprintf(stderr, "Error: Failed to write log entry\n");
                break;
            }
            if (write(fileno(log_file_name), log_message, strlen(log_message)) < 0) {
                fprintf(stderr, "Error: Failed to write log entry\n");
                break;
            }
            if (close(fileno(log_file_name)) < 0) {
                fprintf(stderr, "Error: Failed to close log file\n");
                break;
            }
        }

        // Wait for 500 ms
        sleep(0.5);
    }

    // Clean up
    gpio_exit();
    return 0;
}

// Signal handler for SIGINT and SIGTERM
void sig_handler(int signum) {
    printf("Received signal %d, exiting gracefully...\n", signum);
    close(fileno(log_file_name));
    unlink(log_file_name);
    gpio_exit();
}

