#include <time.h>
#include <pigpio.h>

#define DRV5032_PULL_UP_PIN 17
#define DRV5032_PULL_DOWN_PIN 18
#define RPM_THRESHOLD 100

int gpio_open(int pin);
void gpio_close(int pin);
int gpio_read(int pin);
void gpio_write(int pin, int value);
int gpio_ioctl(int file, int request, void *arg);

int main() {
    int fd, gpio_fd;
    struct gpio_desc gpio_desc;
    struct timespec start_time, end_time;
    int rpm, debounce_count = 0;
    char timestamp[80];
    char sensor1_state, sensor2_state;
    char log_file[80];
    FILE *log_fp;

    gpio_fd = gpio_open(DRV5032_PULL_UP_PIN);
    if (gpio_fd < 0) {
        perror("gpio_open");
        exit(EXIT_FAILURE);
    }

    gpio_desc.gpio_dir = PI_OUTPUT;
    gpio_desc.gpio_value = 0;
    gpio_desc.gpio_pin = DRV5032_PULL_UP_PIN;
    gpio_desc.gpio_edge = PI_FALLING;
    gpio_desc.gpio_type = PI_OUTPUT;

    if (gpio_ioctl(gpio_fd, GPIO_SET_DIRECTION, &gpio_desc) < 0) {
        perror("gpio_ioctl");
        exit(EXIT_FAILURE);
    }

    gpio_desc.gpio_value = 1;
    gpio_ioctl(gpio_fd, GPIO_SET_VALUE, &gpio_desc);

    fd = open("shaft_log.txt", O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    log_fp = fopen(log_file, "a");
    if (log_fp == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    gpio_desc.gpio_dir = PI_INPUT;
    gpio_desc.gpio_value = 0;
    gpio_desc.gpio_pin = DRV5032_PULL_DOWN_PIN;
    gpio_desc.gpio_edge = PI_FALLING;
    gpio_desc.gpio_type = PI_INPUT;

    if (gpio_ioctl(gpio_fd, GPIO_SET_DIRECTION, &gpio_desc) < 0) {
        perror("gpio_ioctl");
        exit(EXIT_FAILURE);
    }

    gpio_desc.gpio_value = 1;
    gpio_ioctl(gpio_fd, GPIO_SET_VALUE, &gpio_desc);

    while (1) {
        struct timespec start, stop;
        int rpm_count;

        if (gpio_read(DRV5032_PULL_UP_PIN) == 1) {
            debounce_count = 0;
        } else {
            debounce_count++;
        }

        if (debounce_count >= 5) {
            debounce_count = 0;
        }

        if (gpio_read(DRV5032_PULL_DOWN_PIN) == 1) {
            rpm_count++;
        } else {
            rpm_count = 0;
        }

        if (rpm_count > RPM_THRESHOLD) {
            rpm = rpm_count;
            break;
        }

        if (rpm > 0) {
            rpm_count = 0;
            snprintf(timestamp, sizeof(timestamp), "%s", ctime(&start_time.tv_sec));
            snprintf(log_file, sizeof(log_file), "%.2f,%.2f,%.2f\n", start_time.tv_sec, timestamp, sensor1_state, sensor2_state);
            fprintf(log_fp, "%s\n", log_file);
        }

        nanosleep(&start, &stop);
    }

    gpio_close(gpio_fd);
    close(fd);
    fclose(log_fp);

    return 0;
}

