    int fd;
    struct gpio_desc gpio_desc;

    fd = open("/dev/gpiomem", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    gpio_desc.gpio_dir = PI_OUTPUT;
    gpio_desc.gpio_value = 0;
