    if (ioctl(gpio_open(pin), GPIO_GET_VALUE, &gpio_desc) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    return gpio_desc.gpio_value;
}

void gpio_write(int pin, int value) {
    struct gpio_desc gpio_desc;

    gpio_desc.gpio_dir = PI_OUTPUT;
    gpio_desc.gpio_value = value;
    gpio_desc.gpio_pin = pin;

    if (ioctl(gpio_open(pin), GPIO_SET_VALUE, &gpio_desc) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
}

int gpio_ioctl(int file, int request, void *arg) {
    int ret;

    ret = ioctl(file, request, arg);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    return ret;
}

