#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x28

int main() {
    int i2c_fd;
    char log_file_name[] = "biometric_log.txt";
    char log_file_path[128] = "";

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    if (gpioI2CReadReg16(i2c_fd, I2C_ADDR, 0x00) != 0x4142) {
        fprintf(stderr, "Sensor not found at address 0x%02x\n", I2C_ADDR);
        goto cleanup;
    }

    // Configure sensor for continuous measurement
    if (gpioI2CWriteReg16(i2c_fd, I2C_ADDR, 0x30, 0x03) < 0) {
        fprintf(stderr, "Failed to configure sensor for continuous measurement\n");
        goto cleanup;
    }

    // Loop to read and log data
    while (1) {
        // Read heart rate data
        uint16_t heart_rate_data;
        if (gpioI2CReadReg16(i2c_fd, I2C_ADDR, 0x02, &heart_rate_data) < 0) {
            fprintf(stderr, "Failed to read heart rate data\n");
            goto cleanup;
        }

        // Read SpO2 data
        uint16_t sp02_data;
        if (gpioI2CReadReg16(i2c_fd, I2C_ADDR, 0x04, &sp02_data) < 0) {
            fprintf(stderr, "Failed to read SpO2 data\n");
            goto cleanup;
        }

        // Log data with timestamp
        char log_message[128];
        snprintf(log_message, sizeof(log_message), "%.4s, Heart Rate: %.0f BPM, SpO2: %.0f%%",
                 asctime(localtime(&(time(NULL)))), heart_rate_data, sp02_data);

        // Append log message to file
        if (open(log_file_path, O_WRONLY | O_APPEND | O_CREAT, 0644) < 0) {
            fprintf(stderr, "Failed to open log file\n");
