#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDRESS 0x1D
#define SDA_GPIO_NUM 2
#define SCL_GPIO_NUM 3

#define LED_GPIO_NUM 17

#define I2C_TIMEOUT_MS 1000

#define VIBRATION_THRESHOLD 500
#define VIBRATION_LOG_FILE "seismic_events.log"

int main() {
    int ret;
    int i;
    int retryCount = 3;
    int logFileHandle;
    struct i2c_rdwr_ioctl_data i2cData;
    struct i2c_msg i2cMsg[2];
    uint8_t buffer[6];
    uint16_t data;
    char logMessage[128];
    char logTimestamp[32];

    gpio_init();
    gpio_set_mode(LED_GPIO_NUM, GPIO_OUTPUT);

    logFileHandle = open(VIBRATION_LOG_FILE, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (logFileHandle < 0) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Initialize pigpio library
        if (gpio_init() < 0) {
            perror("Error initializing pigpio library");
            exit(EXIT_FAILURE);
        }

        // Set up I2C bus
        if (gpio_set_mode(I2C_BUS_NUM, GPIO_MODE_I2C) < 0) {
            perror("Error setting up I2C bus");
            exit(EXIT_FAILURE);
        }

        if (gpio_set_sda_function(I2C_BUS_NUM, GPIO_FUN_I2C) < 0) {
            perror("Error setting up I2C SDA function");
            exit(EXIT_FAILURE);
        }

        if (gpio_set_scl_function(I2C_BUS_NUM, GPIO_FUN_I2C) < 0) {
            perror("Error setting up I2C SCL function");
            exit(EXIT_FAILURE);
        }

        // Set I2C address and read CTRL1
        if (gpio_set_function(I2C_BUS_NUM, I2C_ADDRESS, GPIO_MODE_I2C) < 0) {
            perror("Error setting I2C address");
            exit(EXIT_FAILURE);
        }

        if (gpio_write(I2C_BUS_NUM, I2C_ADDRESS, 0) < 0) {
            perror("Error writing I2C address");
            exit(EXIT_FAILURE);
        }

        if (gpio_write(I2C_BUS_NUM, I2C_ADDRESS, I2C_ADDRESS) < 0) {
            perror("Error writing I2C address");
            exit(EXIT_FAILURE);
        }

        if (gpio_set_function(I2C_BUS_NUM, I2C_ADDRESS, GPIO_MODE_OUTPUT) < 0) {
            perror("Error setting I2C address as output");
            exit(EXIT_FAILURE);
        }

        if (gpio_write(I2C_BUS_NUM, I2C_ADDRESS, 0) < 0) {
            perror("Error writing I2C address");
            exit(EXIT_FAILURE);
        }

        if (gpio_write(I2C_BUS_NUM, I2C_ADDRESS, I2C_ADDRESS) < 0) {
            perror("Error writing I2C address");
            exit(EXIT_FAILURE);
        }

        if (gpio_set_function(I2C_BUS_NUM, I2C_ADDRESS, GPIO_MODE_INPUT) < 0) {
            perror("Error setting I2C address as input");
            exit(EXIT_FAILURE);
        }

        if (gpio_read(I2C_BUS_NUM, I2C_ADDRESS, &data, 1) < 0) {
            perror("Error reading I2C address");
            exit(EXIT_FAILURE);
        }

        if (data != I2C_ADDRESS) {
            printf("Error: I2C address not detected\n");
            exit(EXIT_FAILURE);
        }

        // Read CTRL1
        if (gpio_read(I2C_BUS_NUM, I2C_ADDRESS, &data, 1) < 0) {
            perror("Error reading CTRL1");
            exit(EXIT_FAILURE);
        }

        if (data & 0x20) {
            printf("Error: CTRL1 power-down bit set\n");
            exit(EXIT_FAILURE);
        }

        // Read CTRL2
        if (gpio_read(I2C_BUS_NUM, I2C_ADDRESS, &data, 1) < 0) {
            perror("Error reading CTRL2");
            exit(EXIT_FAILURE);
        }

        if (data & 0x40) {
            printf("Error: CTRL2 vibration detection enabled\n");
            exit(EXIT_FAILURE);
        }

        // Read 3-axis acceleration registers
        if (gpio_read(I2C_BUS_NUM, I2C_ADDRESS, &data, 6) < 0) {
            perror("Error reading acceleration registers");
            exit(EXIT_FAILURE);
        }

        // Compute Euclidean vibration magnitude
        for (i = 0; i < 6; i++) {
            if (data[i] < 0) {
                printf("Error: Invalid acceleration data\n");
                exit(EXIT_FAILURE);
            }

            if (data[i] > VIBRATION_THRESHOLD) {
                printf("Threshold exceeded: %f g\n", data[i] / VIBRATION_THRESHOLD);

                // Log threshold-exceeding event
                snprintf(logMessage, sizeof(logMessage), "Threshold exceeded: %f g", data[i] / VIBRATION_THRESHOLD);
                snprintf(logTimestamp, sizeof(logTimestamp), "%s", get_iso8601_timestamp());

                if (logMessage[0] == '\0') {
                    logMessage[1] = '\0';
                }

                if (write(logFileHandle, logMessage, strlen(logMessage) + 1) < 0) {
                    perror("Error writing log message");
                    exit(EXIT_FAILURE);
                }

                // Turn on LED
                gpio_set_value(LED_GPIO_NUM, 1);
                usleep(1000);
                gpio_set_value(LED_GPIO_NUM, 0);
            }
        }

        // Release resources
        gpio_set_function(I2C_BUS_NUM, I2C_ADDRESS, GPIO_MODE_INPUT);
        gpio_release(I2C_BUS_NUM);
        gpio_release(LED_GPIO_NUM);

        gpio_exit();
    }

    return 0;
}

