#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <sys/syslog.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <gpiod.h>

#define SENSOR_COUNT 5
#define LINE_COUNT_MIN 3
#define LINE_COUNT_MAX 4

int main() {
    int chip_fd, line_fd[SENSOR_COUNT];
    struct gpiod_chip *chip;
    int sensor_id;
    int line_id;
    int line_status;
    struct gpiod_line *line;
    struct timespec start_time;
    struct timespec end_time;
    char log_file[128];
    char line_events_log[128];
    char timestamp[128];
    char sensor_id_str[16];
    char sensor_pin_str[4];
    char event_line[256];

    // Initialize syslog
    openlog("flame_monitor", LOG_PID | LOG_PERROR, LOG_USER);

    // Initialize sensor IDs
    snprintf(sensor_id_str, sizeof(sensor_id_str), "sensor_%d", SENSOR_COUNT);
    snprintf(sensor_pin_str, sizeof(sensor_pin_str), "%d", SENSOR_COUNT);

    // Initialize line IDs
    snprintf(line_events_log, sizeof(line_events_log), "/var/log/flame_events.log");
    snprintf(timestamp, sizeof(timestamp), "%s", ctime(&time(NULL)));

