#include <fcntl.h>
#include <gpiod.h>

#define TOUCH_SENSOR_GPIO_PINS 5
#define TOUCH_SENSOR_GPIO_PIN_STR "5"
#define TOUCH_SENSOR_GPIO_PIN_NUM 5

int main() {
    int gpio_fd;
    struct gpiod_line_bulk lines[1];
    struct gpiod_line_info line_info[1];
    struct timespec start_time, end_time;
    int touch_detected = 0;
    int touch_released = 0;
    int error = 0;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Error initializing libgpiod: %s\n", gpiod_strerror(errno));
        return 1;
    }

    // Open GPIO chip
    if ((gpio_fd = gpiod_open(GPIDO_CHIP_LINE, GPIDO_READ | GPIDO_WRITE)) < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_strerror(errno));
        gpiod_exit();
        return 1;
    }

    // Set up GPIO lines
    if (gpiod_set_line_config(gpio_fd, TOUCH_SENSOR_GPIO_PINS, GPIDO_LINE_IN, 1, GPIDO_PULL_UP) < 0) {
        fprintf(stderr, "Error setting up GPIO lines: %s\n", gpiod_strerror(errno));
        gpiod_close(gpio_fd);
        gpiod_exit();
        return 1;
    }

    // Set up bulk line request
    if (gpiod_bulk_line_request(gpio_fd, TOUCH_SENSOR_GPIO_PINS, 1, lines, 1, &line_info[0]) < 0) {
        fprintf(stderr, "Error setting up bulk line request: %s\n", gpiod_strerror(errno));
        gpiod_close(gpio_fd);
        gpiod_exit();
        return 1;
    }

    // Start reading touch states
    while (1) {
        // Get current time
        if (clock_gettime(CLOCK_MONOTONIC, &start_time) < 0) {
            fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
            gpiod_close(gpio_fd);
            gpiod_exit();
            return 1;
        }

        // Poll GPIO lines
        if (gpiod_poll(gpio_fd, 1, &end_time, NULL) < 0) {
            fprintf(stderr, "Error polling GPIO lines: %s\n", strerror(errno));
            gpiod_close(gpio_fd);
            gpiod_exit();
            return 1;
        }

        // Check if any touch events occurred
        if (end_time.tv_sec > start_time.tv_sec) {
            if (lines[0].state == GPIDO_LINE_STATE_LOW) {
                touch_detected = 1;
            } else {
                touch_released = 1;
            }
        }

        // Log touch events
        if (touch_detected || touch_released) {
            printf("[%s] %s\n", isoc_date_time(start_time), lines[0].name);
            start_time.tv_sec = end_time.tv_sec;
            start_time.tv_nsec = end_time.tv_nsec;
            if (touch_detected) {
                printf("Touch detected\n");
            } else {
                printf("Touch released\n");
            }
            touch_detected = 0;
            touch_released = 0;
        }
    }

    // Clean up
    gpiod_close(gpio_fd);
    gpiod_exit();

    return 0;
}

