    int i;
    int log_fd;
    struct i2c_rdwr_ioctl_data data;
    uint16_t config_reg;
    uint16_t lux_reg;
    uint16_t brightness_reg;
    uint16_t error_code;
    uint16_t raw_lux;
    float lux;
    int brightness;
    int exit_flag = 0;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    if ((rc = pigpio_i2c_open(I2C_BUS_NUM, I2C_ADDR, &data)) < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }

    // Configure sensor
    if (pigpio_ioctl(data.fd, PI_I2C_SENSOR_CONFIG_WRITE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to configure sensor\n");
        exit(EXIT_FAILURE);
    }
    config_reg = 0x00;
    if (pigpio_ioctl(data.fd, PI_I2C_SENSOR_CONFIG_WRITE, config_reg) < 0) {
        fprintf(stderr, "Error: Failed to configure sensor\n");
        exit(EXIT_FAILURE);
    }
    config_reg = 0x00;
