        exit(EXIT_FAILURE);
    }
    config_reg = 0x00;
    if (pigpio_ioctl(data.fd, PI_I2C_SENSOR_CONFIG_WRITE, config_reg) < 0) {
        fprintf(stderr, "Error: Failed to configure sensor\n");
        exit(EXIT_FAILURE);
    }

    // Open I2C log file
    if ((log_fd = open("grow_log.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        fprintf(stderr, "Error: Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    // Set up PWM
    if (pigpio_ioctl(data.fd, PI_I2C_PWM_SET_PERIOD, 1000) < 0) {
        fprintf(stderr, "Error: Failed to set PWM period\n");
        exit(EXIT_FAILURE);
    }
    if (pigpio_ioctl(data.fd, PI_I2C_PWM_SET_AMPLITUDE, 100) < 0) {
        fprintf(stderr, "Error: Failed to set PWM amplitude\n");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!exit_flag) {
        // Read ALS register
        if (pigpio_ioctl(data.fd, PI_I2C_SENSOR_READ, 0, &raw_lux) < 0) {
            fprintf(stderr, "Error: Failed to read ALS register\n");
            exit(EXIT_FAILURE);
        }

        // Convert raw_lux to lux
        lux = raw_lux * 0.0576;

        // Check if lux is within the required range
        if (lux < 100) {
            brightness = 100;
        } else if (lux < 500) {
            brightness = 75;
        } else if (lux < 1000) {
            brightness = 50;
        } else {
            brightness = 25;
        }

        // Set LED brightness
        if (pigpio_ioctl(data.fd, PI_I2C_PWM_SET_BRIGHTNESS, brightness) < 0) {
