            exit(EXIT_FAILURE);
        }
        if (pigpio_ioctl(data.fd, PI_I2C_SENSOR_READ, 0, &error_code) < 0) {
            fprintf(stderr, "Error: Failed to read error code\n");
            exit(EXIT_FAILURE);
        }
        if (pigpio_ioctl(data.fd, PI_I2C_SENSOR_READ, 0, &brightness_reg) < 0) {
            fprintf(stderr, "Error: Failed to read brightness register\n");
            exit(EXIT_FAILURE);
        }

        // Log data
        if (pigpio_ioctl(data.fd, PI_I2C_SENSOR_WRITE, 0, &lux_reg) < 0) {
            fprintf(stderr, "Error: Failed to write lux register\n");
            exit(EXIT_FAILURE);
        }
        if (pigpio_ioctl(data.fd, PI_I2C_SENSOR_WRITE, 0, &error_code) < 0) {
            fprintf(stderr, "Error: Failed to write error code\n");
            exit(EXIT_FAILURE);
        }
        if (pigpio_ioctl(data.fd, PI_I2C_SENSOR_WRITE, 0, &brightness_reg) < 0) {
            fprintf(stderr, "Error: Failed to write brightness register\n");
            exit(EXIT_FAILURE);
        }

        // Wait for 1 second
        if (pigpio_ioctl(data.fd, PI_I2C_SENSOR_READ, 0, &lux_reg) < 0) {
            fprintf(stderr, "Error: Failed to read lux register\n");
            exit(EXIT_FAILURE);
        }

        // Wait for 1 second
        if (pigpio_usleep(1000000) < 0) {
            fprintf(stderr, "Error: Failed to sleep\n");
            exit(EXIT_FAILURE);
        }
    }

    // Close I2C log file
    if (close(log_fd) < 0) {
        fprintf(stderr, "Error: Failed to close log file\n");
        exit(EXIT_FAILURE);
    }

    // Close I2C
    if (pigpio_i2c_close(data.fd) < 0) {
        fprintf(stderr, "Error: Failed to close I2C\n");
        exit(EXIT_FAILURE);
    }

    // Close PWM
    if (pigpio_ioctl(data.fd, PI_I2C_PWM_CLOSE, 0) < 0) {
        fprintf(stderr, "Error: Failed to close PWM\n");
        exit(EXIT_FAILURE);
    }

    // Terminate pigpio
    pigpio_exit(0);

    return 0;
}
