    gpioSetMode(2, PI_MODE_IN);
    gpioSetMode(3, PI_MODE_IN);
    gpioSetMode(4, PI_MODE_IN);
    gpioSetMode(5, PI_MODE_IN);
    gpioSetMode(6, PI_MODE_IN);
    gpioSetMode(7, PI_MODE_IN);
