#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>

#define KY026_GPIO_PIN 4
#define KY026_DO_PIN 17

int main() {
    int fd;
    int ret;
    struct gpiod_event_data event_data;
    struct gpiod_event_data *event_data_ptr;
    struct timespec start_time, end_time;
    char log_file_name[] = "fire_events.log";

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    // Open log file
    fd = open(log_file_name, O_APPEND | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    // Set up GPIO
    if (gpioSetMode(KY026_GPIO_PIN, PI_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return 1;
    }

    if (gpioSetLevel(KY026_GPIO_PIN, 0) < 0) {
        fprintf(stderr, "Error setting GPIO level\n");
        return 1;
    }

    // Set up event
    event_data_ptr = &event_data;
    event_data.flags = GPIGPIO_EVENT_DATA_FLAGS_LEVEL | GPIGPIO_EVENT_DATA_FLAGS_EDGE;
    event_data.gpio_num = KY026_GPIO_PIN;
    event_data.event_type = GPIGPIO_EVENT_TYPE_LEVEL_EDGE;
    event_data.callback = NULL;
    event_data.user_data = NULL;

    // Set up GPIO polling
    gpioSetPwmRange(KY026_GPIO_PIN, 0, 255);
    gpioSetPwmPeriod(KY026_GPIO_PIN, 500);
    gpioSetPwmValue(KY026_GPIO_PIN, 0);

    // Main loop
    while (1) {
        // Poll the sensor
        ret = gpioPollEventData(KY026_GPIO_PIN, event_data_ptr, &event_data, 100);
        if (ret < 0) {
            fprintf(stderr, "Error polling sensor\n");
            continue;
        }

        // Check if a flame is detected
        if (event_data_ptr->level == 0) {
            // Trigger alert
            gpioSetLevel(KY026_GPIO_PIN, 1);
            sleep(1);
            gpioSetLevel(KY026_GPIO_PIN, 0);
        }

        // Log the reading
        struct timespec now;
        gettimeofday(&now, NULL);
        char log_message[50];
        sprintf(log_message, "Sensor reading: %lu\n", (unsigned long)now.tv_sec);
        write(fd, log_message, strlen(log_message));

        // Release resources
        gpioReleaseEventData(event_data_ptr);
        gpioTerminate();
        close(fd);
    }

    return 0;
}

