#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define TOUCH_SENSOR_GPIO_PIN 7
#define TOUCH_SENSOR_LINE_NAME "/dev/gpiochip0"
#define TOUCH_SENSOR_LINE_PATH "/sys/class/gpio/gpiochip0/gpio7"
#define TOUCH_SENSOR_LINE_PULLDOWN "/sys/class/gpio/gpiochip0/gpio7/value"

int main() {
    int chip_fd, line_fd, log_fd;
    struct gpiod_event event;
    char line_path[128];
    char log_file_path[128];
    char log_message[128];
    int debounce_interval = 50;
    int press_count = 0;
    int release_count = 0;
    int exit_status = 0;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %s\n", gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Open GPIO line and debounce
    chip_fd = gpiod_chip_open(0);
    if (chip_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }
    line_fd = gpiod_line_open(chip_fd, TOUCH_SENSOR_LINE_NAME);
    if (line_fd < 0) {
        fprintf(stderr, "Failed to open GPIO line: %s\n", gpiod_strerror(errno));
        gpiod_line_close(chip_fd, line_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    snprintf(log_file_path, sizeof(log_file_path), "touch_log.txt");
    log_fd = open(log_file_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_close(chip_fd, line_fd);
        gpiod_chip_close(chip_fd);
        exit(EXIT_FAILURE);
    }

    // Loop to read and process touch events
    while (1) {
        // Read the debounce interval
        if (gpiod_event_read(line_fd, &event, sizeof(event)) < 0) {
            fprintf(stderr, "Failed to read debounce interval: %s\n", gpiod_strerror(errno));
            exit(EXIT_FAILURE);
        }

        // Read the touch sensor state
        if (gpiod_event_read(line_fd, &event, sizeof(event)) < 0) {
            fprintf(stderr, "Failed to read touch sensor state: %s\n", gpiod_strerror(errno));
            exit(EXIT_FAILURE);
        }

        // Check if the touch event is a press or release
        if (event.type == GPIO_EVENT_PRESS) {
            press_count++;
            if (press_count > 1) {
                // Debounce
                usleep(debounce_interval * 1000);
            }
        } else if (event.type == GPIO_EVENT_RELEASE) {
            release_count++;
            if (release_count > 1) {
                // Debounce
                usleep(debounce_interval * 1000);
            }
        }

        // Append the touch event to the log file
        if (write(log_fd, "Touch Detected\n", strlen("Touch Detected\n")) < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }

        // Print the touch event to stderr
        fprintf(stderr, "Touch Detected at %s\n", ctime(&event.timestamp));

        // Release the GPIO line and close the log file
        gpiod_line_release(line_fd);
        close(log_fd);
        gpiod_chip_close(chip_fd);
        exit(EXIT_SUCCESS);
    }

    // Cleanup
    gpiod_chip_close(chip_fd);
    gpiod_line_close(line_fd);
    gpiod_init();
    return 0;
}

