#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>

#define LED_GPIO 17
#define LED_PIN 11

int main() {
    int fd;
    int gpio_fd;
    int ret;
    int debounce_time = 200;
    int debounce_count = 0;
    struct timespec ts;
    char touch_log_filename[] = "touch_log.txt";
    FILE *touch_log_file;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    if (gpioSetMode(4, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO4 as input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO17 as output\n");
        gpioTerminate();
        return 1;
    }

    if ((fd = open(touch_log_filename, O_CREAT | O_WRONLY | O_APPEND, 0644)) < 0) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    if ((touch_log_file = fopen(touch_log_filename, "a")) == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        if (gpioRead(4) == 3) { // Check for touch
            if (debounce_count == 0) {
                ts.tv_sec = 0;
                ts.tv_nsec = debounce_time * 1000000;
                while (nanosleep(&ts, NULL) == -1 && errno == EINTR) {
                    // Do nothing, continue with the next iteration
                }
                debounce_count++;
            } else {
                debounce_count = 0;
            }
        }

        if (gpioRead(17) == 0) { // Check for LED state
            if (gpioRead(17) == 0) {
                gpioWrite(LED_GPIO, 0); // Toggle LED
                fprintf(touch_log_file, "Touched at %s\n", ctime(NULL));
                fflush(touch_log_file);
            } else {
                gpioWrite(LED_GPIO, 1); // Set LED state
            }
        }

        usleep(debounce_time * 1000); // Wait for debounce time
    }

    gpioTerminate();
    close(fd);
    close(touch_log_file);

    return 0;
}

