        sensor_gpio = BCM2708_GPIO_BASE + sensor_pin;
        err = gpioWrite(sensor_gpio, 1);
        if (err < 0) {
            fprintf(stderr, "Failed to reset sensor state for sensor 2\n");
            continue;
