        sensor_pin = (TMAG5110A1_SENSOR_GPIO_27 << 1) | 0; // GPIO27 for sensor 3
        sensor_gpio = BCM2708_GPIO_BASE + sensor_pin;
        err = gpioWrite(sensor_gpio, 0);
        if (err < 0) {
            fprintf(stderr, "Failed to reset sensor state for sensor 3\n");
            continue;
        }

        // Wait for next iteration
        usleep(1000 * 1000);
    }

    // Cleanup
    gpioTerminate();
    gpioUninitialize();

    return 0;
}

