#include <linux/gpio.h>

#define KY_026_DO_PIN 17
#define KY_026_DO_LINE "/dev/gpiochip0"
#define KY_026_DO_LINE_NAME "gpiochip0"

int main() {
    int fd, gpio_fd, log_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_event event;
    struct timespec ts;
    char buffer[32];
    char *log_file = "flame_log.txt";

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open GPIO chip and line
    if ((fd = gpiod_open(KY_026_DO_LINE_NAME, GPIDX_GPIO, &chip, &line)) < 0) {
        fprintf(stderr, "Failed to open GPIO line: %s\n", gpiod_error(fd));
        gpiod_close(chip);
        gpiod_uninit();
        return 1;
    }

    // Set line as input with internal pull-up
    if (gpiod_line_get_config(line, GPIDX_GPIO, GPIDX_INPUT | GPIDX_PULLUP) < 0) {
        fprintf(stderr, "Failed to set line configuration: %s\n", gpiod_error(fd));
        gpiod_close(chip);
        gpiod_uninit();
        return 1;
    }

    // Poll the line every 100 ms
    while (1) {
        if (gpiod_event_wait(chip, line, &event, 100) < 0) {
            fprintf(stderr, "Failed to wait for event: %s\n", gpiod_error(fd));
            break;
        }

        // Check for falling edge
        if (event.type == GPIDX_EVENT_GPIO_FALLING_EDGE) {
            // Print 'FLAME DETECTED' to console
            printf("FLAME DETECTED\n");

            // Append timestamp and 'FLAME DETECTED' to 'flame_log.txt'
            if (open(log_file, O_APPEND | O_CREAT, 0644) < 0) {
                fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
                break;
            }

            if (write(log_fd, "FLAME DETECTED\n", 13) < 0) {
                fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
                break;
            }

            close(log_fd);
        }

        // Release GPIO line and close chip
        if (gpiod_line_release(line) < 0) {
            fprintf(stderr, "Failed to release line: %s\n", gpiod_error(fd));
            break;
        }

        if (gpiod_close(chip) < 0) {
            fprintf(stderr, "Failed to close GPIO chip: %s\n", gpiod_error(fd));
            break;
        }

        usleep(100000);  // Wait for 100 ms
    }

    // Clean up
    gpiod_uninit();
    gpiod_close(chip);
    close(fd);
    unlink(log_file);

    return 0;
}

