#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define LED_GPIO_NUMBER 22
#define SENSOR1_GPIO_NUMBER 17
#define SENSOR2_GPIO_NUMBER 27

int main() {
    int chip_fd, log_fd, sensor1_fd, sensor2_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *sensor1, *sensor2;
    struct gpiod_line_config sensor1_config, sensor2_config;
    struct gpiod_line_state sensor1_state, sensor2_state;
    struct gpiod_line_state led_state;
    int log_file_fd;
    struct timespec start_time, end_time;
    char timestamp[80];
    char log_line[100];

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open GPIO chip
    chip_fd = gpiod_chip_by_name("gpiochip0");
    if (chip_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_error_name(gpiod_get_error()));
        gpiod_exit();
        return 1;
    }

    // Open sensor lines
    sensor1_fd = gpiod_line_by_chip(chip_fd, SENSOR1_GPIO_NUMBER, &sensor1_config);
    if (sensor1_fd < 0) {
        fprintf(stderr, "Failed to open sensor1 line: %s\n", gpiod_error_name(gpiod_get_error()));
        gpiod_line_close(sensor1_fd);
        gpiod_exit();
        return 1;
    }

    sensor2_fd = gpiod_line_by_chip(chip_fd, SENSOR2_GPIO_NUMBER, &sensor2_config);
    if (sensor2_fd < 0) {
        fprintf(stderr, "Failed to open sensor2 line: %s\n", gpiod_error_name(gpiod_get_error()));
        gpiod_line_close(sensor2_fd);
        gpiod_line_close(sensor1_fd);
        gpiod_exit();
        return 1;
    }

    // Set sensor lines to active-low
    if (gpiod_line_set_direction(sensor1_fd, GPID_DIR_IN) < 0 ||
        gpiod_line_set_direction(sensor2_fd, GPID_DIR_IN) < 0) {
        fprintf(stderr, "Failed to set sensor lines to active-low: %s\n", gpiod_error_name(gpiod_get_error()));
        gpiod_line_close(sensor1_fd);
        gpiod_line_close(sensor2_fd);
        gpiod_exit();
        return 1;
    }

    // Set sensor lines to low
    if (gpiod_line_set_value(sensor1_fd, 0) < 0 ||
        gpiod_line_set_value(sensor2_fd, 0) < 0) {
        fprintf(stderr, "Failed to set sensor lines to low: %s\n", gpiod_error_name(gpiod_get_error()));
        gpiod_line_close(sensor1_fd);
        gpiod_line_close(sensor2_fd);
        gpiod_exit();
        return 1;
    }

    // Log sensor readings to 'obstacle_log.csv'
    log_file_fd = open("obstacle_log.csv", O_CREAT | O_TRUNC | O_WRONLY, 0644);
    if (log_file_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_close(sensor1_fd);
        gpiod_line_close(sensor2_fd);
        gpiod_exit();
        return 1;
    }

    while (1) {
        // Read sensor data
        if (gpiod_line_read(sensor1_fd, &sensor1_state) < 0) {
            fprintf(stderr, "Failed to read sensor1 state: %s\n", gpiod_error_name(gpiod_get_error()));
            gpiod_line_close(sensor1_fd);
            gpiod_line_close(sensor2_fd);
            gpiod_exit();
            return 1;
        }

        if (gpiod_line_read(sensor2_fd, &sensor2_state) < 0) {
            fprintf(stderr, "Failed to read sensor2 state: %s\n", gpiod_error_name(gpiod_get_error()));
            gpiod_line_close(sensor1_fd);
            gpiod_line_close(sensor2_fd);
            gpiod_exit();
            return 1;
        }

        // Check if both sensors read 0
        if (sensor1_state.value == 0 && sensor2_state.value == 0) {
            // Log the sensor readings
            snprintf(timestamp, sizeof(timestamp), "%s", get_timestamp());
            snprintf(log_line, sizeof(log_line), "%.2f,%.2f,0,1,1\n", timestamp, sensor1_state.value, sensor2_state.value, 1);
            if (write(log_file_fd, log_line, strlen(log_line)) < 0) {
                fprintf(stderr, "Failed to write log line to file: %s\n", strerror(errno));
                gpiod_line_close(sensor1_fd);
                gpiod_line_close(sensor2_fd);
                gpiod_exit();
                return 1;
            }
        }

        // Wait for 100 ms
        nanosleep(&start_time, &end_time);
    }

    // Clean up
    gpiod_line_close(sensor1_fd);
    gpiod_line_close(sensor2_fd);
    gpiod_line_close(sensor1_config.line);
    gpiod_line_close(sensor2_config.line);
    gpiod_exit();
    return 0;
}

