#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x49

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[2];
    int rc;

    // Initialize I2C bus
    if (ioctl(fd = open("/dev/i2c-1", O_RDWR), I2C_RDWR, I2C_SLAVE) < 0) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C address");
        exit(EXIT_FAILURE);
    }

    // Set I2C transfer mode to I2C_MODE_I2C
    if (ioctl(fd, I2C_SLAVE, I2C_MODE_I2C) < 0) {
        perror("Error setting I2C transfer mode");
        exit(EXIT_FAILURE);
    }

    // Read the ALS visible data registers
    msg[0].addr = I2C_ADDR;
    msg[0].flags = 0;
    msg[0].len = 2;
    msg[0].buf = &data.msg[0];
    msg[0].len = 2;
    msg[0].func = I2C_FUNC_RECV;

    data.msg[0] = 0x24;
    data.msg[1] = 0x25;

    if (ioctl(fd, I2C_RDWR, I2C_RD_BYTE) < 0) {
        perror("Error reading data registers");
        exit(EXIT_FAILURE);
    }

    // Combine the LSB and MSB values into a 16-bit value
    data.data[0] = (data.msg[0] << 8) | data.msg[1];
    data.data[1] = (data.msg[0] >> 8) & 0xFF;
    data.data[2] = (data.msg[1] >> 8) & 0xFF;

    // Log the sensor values
    printf("Sensor Data: 0x%04x, 0x%04x\n", data.data[0], data.data[1]);

    // Clean up resources
    close(fd);

    return 0;
}

