#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define GPIO_DIR_IN 0
#define GPIO_DIR_OUT 1

int main() {
    int chip_fd, gpio_fd, line_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *lines[3];
    int i, ret;

    // Initialize libgpiod
    if ((ret = gpiod_init()) != 0) {
        fprintf(stderr, "Error initializing libgpiod: %s\n", gpiod_strerror(ret));
        return 1;
    }

    // Open the gpiochip device
    if ((chip_fd = gpiod_open(GPIOD_CHIP_DEFAULT)) < 0) {
        fprintf(stderr, "Error opening gpiochip device: %s\n", gpiod_strerror(errno));
        gpiod_exit();
        return 1;
    }

    // Open the lines
    if ((gpio_fd = gpiod_line_request_input(chip_fd, GPIO_DIR_IN, 2, &lines[0])) < 0) {
        fprintf(stderr, "Error opening line 2 (left): %s\n", gpiod_strerror(errno));
        gpiod_line_release(lines[0]);
        gpiod_close(gpio_fd);
        gpiod_exit();
        return 1;
    }
    if ((gpio_fd = gpiod_line_request_input(chip_fd, GPIO_DIR_IN, 3, &lines[1])) < 0) {
        fprintf(stderr, "Error opening line 3 (middle): %s\n", gpiod_strerror(errno));
        gpiod_line_release(lines[0]);
        gpiod_line_release(lines[1]);
        gpiod_close(gpio_fd);
        gpiod_exit();
        return 1;
    }
    if ((gpio_fd = gpiod_line_request_input(chip_fd, GPIO_DIR_IN, 4, &lines[2])) < 0) {
        fprintf(stderr, "Error opening line 4 (right): %s\n", gpiod_strerror(errno));
        gpiod_line_release(lines[0]);
        gpiod_line_release(lines[1]);
        gpiod_close(gpio_fd);
        gpiod_exit();
        return 1;
    }

    // Poll the lines every 100 ms
    while (1) {
        for (i = 0; i < 3; i++) {
            if (lines[i] != NULL) {
                int sensor_value;
                if ((ret = gpiod_line_read(lines[i], &sensor_value, 1)) < 0) {
                    fprintf(stderr, "Error reading sensor value: %s\n", gpiod_strerror(errno));
                    gpiod_line_release(lines[i]);
                    gpiod_close(gpio_fd);
                    gpiod_exit();
                    return 1;
                }
                printf("L:%d\n", sensor_value);
            }
        }
        sleep(100);
    }

    // Clean up
    for (i = 0; i < 3; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    gpiod_close(gpio_fd);
    gpiod_exit();

    return 0;
