            close(fd);
            pigpio_exit();
            return 1;
        }
        if ((ret = pigpio_set_pwm(LED_GREEN, 255, 0)) != 0) {
            syslog(LOG_ERR, "Error setting PWM duty-cycle for GPIO %d: %s", LED_GREEN, pigpio_error_str(ret));
            munmap(gpio_map, RPI_GPIO_SIZE);
            close(fd);
            pigpio_exit();
