            syslog(LOG_ERR, "Error setting PWM duty-cycle for GPIO %d: %s", LED_GREEN, pigpio_error_str(ret));
            munmap(gpio_map, RPI_GPIO_SIZE);
            close(fd);
            pigpio_exit();
            return 1;
        }
        if ((ret = pigpio_set_pwm(LED_BLUE, 0, 0)) != 0) {
            syslog(LOG_ERR, "Error setting PWM duty-cycle for GPIO %d: %s", LED_BLUE, pigpio_error_str(ret));
            munmap(gpio_map, RPI_GPIO_SIZE);
            close(fd);
            pigpio_exit();
            return 1;
        }

        // Release syslog resources
        syslog(LOG_INFO, "Fading between random hues every 5 seconds");

        // Wait for SIGINT or SIGTERM to gracefully shut down
        struct sigaction sa;
        sa.sa_handler = SIGINT;
        sa.sa_flags = SA_RESTART;
        sigaction(SIGINT, &sa, NULL);
        sa.sa_handler = SIGTERM;
        sigaction(SIGTERM, &sa, NULL);

        // Wait for SIGINT or SIGTERM to exit
        while (1) {
            if (sigwaitinfo(&sa, NULL) == -1) {
                syslog(LOG_ERR, "Error waiting for signal: %s", strerror(errno));
                break;
            }
        }

        // Release PWM and PIGPIO resources
        if ((ret = pigpio_set_pwm(LED_RED, 255, 0)) != 0) {
            syslog(LOG_ERR, "Error setting PWM duty-cycle for GPIO %d: %s", LED_RED, pigpio_error_str(ret));
            munmap(gpio_map, RPI_GPIO_SIZE);
            close(fd);
            pigpio_exit();
            return 1;
        }
        if ((ret = pigpio_set_pwm(LED_GREEN, 255, 0)) != 0) {
            syslog(LOG_ERR, "Error setting PWM duty-cycle for GPIO %d: %s", LED_GREEN, pigpio_error_str(ret));
            munmap(gpio_map, RPI_GPIO_SIZE);
            close(fd);
            pigpio_exit();
            return 1;
        }
        if ((ret = pigpio_set_pwm(LED_BLUE, 255, 0)) != 0) {
            syslog(LOG_ERR, "Error setting PWM duty-cycle for GPIO %d: %s", LED_BLUE, pigpio_error_str(ret));
            munmap(gpio_map, RPI_GPIO_SIZE);
            close(fd);
            pigpio_exit();
            return 1;
        }

        // Release syslog resources
        syslog(LOG_INFO, "Gracefully shutting down");
    }

    // Release PWM and PIGPIO resources
    if ((ret = pigpio_set_pwm(LED_RED, 0, 0)) != 0) {
        syslog(LOG_ERR, "Error setting PWM duty-cycle for GPIO %d: %s", LED_RED, pigpio_error_str(ret));
        munmap(gpio_map, RPI_GPIO_SIZE);
    }
    if ((ret = pigpio_set_pwm(LED_GREEN, 0, 0)) != 0) {
        syslog(LOG_ERR, "Error setting PWM duty-cycle for GPIO %d: %s", LED_GREEN, pigpio_error_str(ret));
        munmap(gpio_map, RPI_GPIO_SIZE);
    }
    if ((ret = pigpio_set_pwm(LED_BLUE, 0, 0)) != 0) {
        syslog(LOG_ERR, "Error setting PWM duty-cycle for GPIO %d: %s", LED_BLUE, pigpio_error_str(ret));
        munmap(gpio_map, RPI_GPIO_SIZE);
    }

    // Close syslog resources
    syslog(LOG_INFO, "Exiting");
    pigpio_exit();

