#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi-dev.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define APA102_LED_FRAME_SIZE 4

int main() {
    int fd_i2c, fd_spi, fd_gpio;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct spi_device *spi_dev;
    struct gpio *gpio_dev;
    uint16_t lux;
    uint8_t led_data[APA102_LED_FRAME_SIZE];
    uint8_t led_frame[APA102_LED_FRAME_SIZE];
    uint8_t end_frame[4] = {0xE0, 0, 0, 0};

    // Initialize I2C and SPI devices
    fd_i2c = open(I2C_BUS, O_RDWR);
    if (fd_i2c < 0) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    fd_spi = open(SPI_DEVICE, O_RDWR);
    if (fd_spi < 0) {
        perror("Error opening SPI device");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO for SPI chip select
    gpio_dev = gpio_open(0);
    if (gpio_dev == NULL) {
        perror("Error opening GPIO");
        exit(EXIT_FAILURE);
    }

    gpio_set_mode(gpio_dev, GPIO_OUTPUT);
    gpio_set_direction(gpio_dev, GPIO_OUT);

    // Initialize I2C device
    if (ioctl(fd_i2c, I2C_SLAVE, 0x23) < 0) {
        perror("Error setting I2C device address");
        exit(EXIT_FAILURE);
    }

    // Initialize SPI device
    spi_dev = spi_open(fd_spi);
    if (spi_dev == NULL) {
        perror("Error opening SPI device");
        exit(EXIT_FAILURE);
    }

    // Set SPI clock speed
    if (spi_set_max_speed_hz(spi_dev, 1000000) < 0) {
        perror("Error setting SPI clock speed");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO for BH1750
    gpio_set_mode(gpio_dev, GPIO_OUTPUT);
    gpio_set_direction(gpio_dev, GPIO_OUT);
    gpio_set_value(gpio_dev, 0);

    // Initialize I2C device for BH1750
    if (ioctl(fd_i2c, I2C_SLAVE, 0x20) < 0) {
        perror("Error setting I2C device address");
        exit(EXIT_FAILURE);
    }

    // Set I2C device to One-Time High-Resolution mode
    if (ioctl(fd_i2c, I2C_RDWR, 0x00) < 0) {
        perror("Error setting I2C device to OTHRR mode");
        exit(EXIT_FAILURE);
    }

    // Wait approximately 120 ms for conversion to complete
    gpio_set_value(gpio_dev, 1);
    sleep(120);
    gpio_set_value(gpio_dev, 0);

    // Read 2-byte result from BH1750
    if (ioctl(fd_i2c, I2C_RDWR, 0x21) < 0) {
        perror("Error reading BH1750 conversion result");
        exit(EXIT_FAILURE);
    }

    // Convert raw value to lux
    lux = (uint16_t)((0x3F00 & i2c_data.wr_reg) >> 8);

    // Map lux range [10, 300] to APA102's 5-bit global brightness [0, 31]
    lux = (lux - 10) * 31 / 300 + 0x10;

    // Send APA102 frame
    for (int i = 0; i < APA102_LED_FRAME_SIZE; i++) {
        led_data[i] = (uint8_t)((lux * 0x100) >> 8);
        led_frame[i] = 0xE0 | (led_data[i] >> 4) | (led_data[i] & 0x0F);
    }

    // Send APA102 end frame
    memcpy(led_frame + 32, end_frame, 4);

    // Send APA102 frame via SPI
    if (spi_write(spi_dev, (uint8_t *)&led_frame, APA102_LED_FRAME_SIZE) < 0) {
        perror("Error sending APA102 frame via SPI");
        exit(EXIT_FAILURE);
    }

    // Close all file descriptors
    close(fd_i2c);
    close(fd_spi);
    gpio_close(gpio_dev);
    spi_close(spi_dev);

    return 0;
}

