#define I2C_READ(fd, reg) ioctl(fd, I2C_RDWR, reg)
#define I2C_WRITE(fd, reg, data) ioctl(fd, I2C_WRONLY, reg)

#define I2C_READ_BYTE(fd) I2C_READ(fd, 0)
#define I2C_WRITE_BYTE(fd, data) I2C_WRITE(fd, data)

#define I2C_READ_WORD(fd) I2C_READ(fd, 0)
