#include <gpiod.h>

#define BUZZER_PIN 17
#define LED_PIN 18

void error_exit(const char *message) {
    printf("Error: %s\n", message);
    exit(1);
}

void self_test() {
    gpio_line_t line;
    struct gpiod_event event;
    int fd;

    line = gpiod_line_request(GPIO_LINE_4);
    if (line == -1) {
        error_exit("Failed to request GPIO line.");
    }

    fd = gpiod_event_write(line, GPIGPIO_EVENT_LOW);
    if (fd == -1) {
        error_exit("Failed to write event to GPIO line.");
    }

    event.type = GPIGPIO_EVENT_LOW;
    event.value = 0;
    event.flags = 0;

    fd = gpiod_event_write(line, &event);
    if (fd == -1) {
        error_exit("Failed to write event to GPIO line.");
    }

    event.type = GPIGPIO_EVENT_HIGH;
    event.value = 0;
    event.flags = 0;

    fd = gpiod_event_write(line, &event);
    if (fd == -1) {
        error_exit("Failed to write event to GPIO line.");
    }

    gpiod_event_release(fd);
    gpiod_line_release(line);
}

void activate_buzzer() {
    int fd;
    fd = open("/dev/pigpio", O_RDWR);
    if (fd == -1) {
        error_exit("Failed to open pigpio device.");
    }

    if (ioctl(fd, PI_SET_BOARD_SPEED, 1000000) == -1) {
        error_exit("Failed to set pigpio board speed.");
    }

    if (ioctl(fd, PI_SET_MODE, PI_MODE_OUTPUT) == -1) {
        error_exit("Failed to set pigpio output mode.");
    }

    if (ioctl(fd, PI_SET_DIGITAL_PIN, GPIO_4) == -1) {
        error_exit("Failed to set pigpio digital pin.");
    }

    if (ioctl(fd, PI_WRITE, 1) == -1) {
        error_exit("Failed to write to pigpio.");
    }

    close(fd);
}

