#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/input.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

#define I2C_ADDR 0x23
#define I2C_BUS "/dev/i2c-1"
#define LED_GPIO 17

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[2];
    struct i2c_rdwr_ioctl_data_setup setup;
    struct gpiod_value_range value;
    int ret;

    // Initialize GPIO and I2C
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (i2cInitialize() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return 1;
    }

    // Open I2C file descriptor
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    // Set up I2C communication
    memset(&data, 0, sizeof(data));
    data.flags = 0;
    data.msgs = msg;
    data.nmsgs = 2;
    data.msg = msg;

    // Set up GPIO
    memset(&value, 0, sizeof(value));
    value.value = 0;
    ret = gpiodSetValue(LED_GPIO, value);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO value\n");
        return 1;
    }

    // Set up circular buffer for storing I2C readings
    int bufferSize = 60;
    int buffer = malloc(bufferSize * sizeof(uint16_t));
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for buffer\n");
        return 1;
    }

    // Set up circular buffer for storing average lux readings
    int bufferSize2 = 60;
    int buffer2 = malloc(bufferSize2 * sizeof(float));
    if (buffer2 == NULL) {
        fprintf(stderr, "Failed to allocate memory for buffer2\n");
        return 1;
    }

    // Set up average lux conversion factor
    float luxFactor = 1.2;

    // Set up I2C communication loop
    while (1) {
        // Read I2C data
        ret = i2cTransfer(fd, &data, 2, NULL, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to read I2C data\n");
            continue;
        }

        // Skip reading if I2C read fails
        if (ret < 2) {
            continue;
        }

        // Convert raw value to lux
        uint16_t raw = data.msg[1].wValue;
        float lux = (float)raw / luxFactor;

        // Store the last 60 lux readings in the circular buffer
        if (buffer != NULL) {
            buffer[bufferSize - 1] = raw;
        }

        // Compute average lux
        float sum = 0.0f;
        for (int i = 0; i < bufferSize; i++) {
            sum += buffer[i];
        }
        float avg_lux = sum / bufferSize;

        // Compute average lux rate
        float rate = 0.0f;
        if (avg_lux > 1000) {
            rate = (float)1000 / avg_lux;
        } else if (avg_lux < 0.5) {
            rate = (float)0.5 / avg_lux;
        } else {
            rate = (float)1.0 / avg_lux;
        }

        // Set GPIO output based on average lux rate
        if (rate >= 0.5) {
            gpioSetValue(LED_GPIO, 1);
        } else if (rate <= 0.5) {
            gpioSetValue(LED_GPIO, 0);
        }

        // Blink the LED at a rate proportional to the average lux
        gpioDelay(1);
        gpioSetValue(LED_GPIO, 1 - (rate * 0.5));
        gpioDelay(1);

        // Sleep for 1 second
        sleep(1);

        // Release I2C file descriptor
        ret = i2cRelease(fd);
        if (ret < 0) {
            fprintf(stderr, "Failed to release I2C file descriptor\n");
            return 1;
        }

        // Release GPIO
        ret = gpiodRelease(LED_GPIO);
        if (ret < 0) {
            fprintf(stderr, "Failed to release GPIO\n");
            return 1;
        }
    }

    // Clean up
    free(buffer);
    free(buffer2);
    i2cTerminate();
    gpioTerminate();

    return 0;
}

