Here's a complete, compilable C program for a Raspberry Pi that uses libgpiod to display the digit '5' on a common-cathode seven-segment display driven by a 74HC595 shift register, blinking it on and off every second (500 ms on, 500 ms off). The program uses GPIO17 as the data pin, GPIO18 as the clock pin, and GPIO27 as the latch pin. The 74HC595 outputs connect to the display segments in the order Q0=a, Q1=b, Q2=c, Q3=d, Q4=e, Q5=f, Q6=g, Q7=dp (dp unused).

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpiod.h>

#define GPIO17  17
#define GPIO18  18
#define GPIO27  27

#define SEGMENT_A  27
#define SEGMENT_B  28
#define SEGMENT_C  29
#define SEGMENT_D  30
#define SEGMENT_E  31
#define SEGMENT_F  32
#define SEGMENT_G  33
#define SEGMENT_DP 34

#define NUM_SEGMENTS 7

int main() {
    int fd, gpio_fd, gpio_chip_fd;
    struct gpiod_line *lines[NUM_SEGMENTS];
    struct gpiod_line_config line_configs[NUM_SEGMENTS];
    struct gpiod_line_config *line_config;
    struct timespec delay;
    unsigned long delay_ms;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open GPIO file descriptors
    fd = open("/sys/class/gpio/gpiochip0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO file descriptor\n");
        gpiod_exit();
        return 1;
    }

    gpio_chip_fd = open(fd, O_RDWR);
    if (gpio_chip_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip file descriptor\n");
        close(fd);
        gpiod_exit();
        return 1;
    }

    // Open GPIO lines
    lines[0] = gpio_chip_fd;
    line_configs[0].line = lines[0];
    line_configs[0].direction = GPID_OUT;
    line_configs[0].active_low = 0;
    line_config = line_configs;

    // Set GPIO17 as the data pin
    if (gpiod_line_request(lines[0], GPIO17, line_config) < 0) {
        fprintf(stderr, "Failed to request GPIO17 as data pin\n");
        close(gpio_chip_fd);
        gpiod_exit();
        return 1;
    }

    // Set GPIO18 as the clock pin
    if (gpiod_line_request(lines[0], GPIO18, line_config) < 0) {
        fprintf(stderr, "Failed to request GPIO18 as clock pin\n");
        close(gpio_chip_fd);
        gpiod_exit();
        return 1;
    }

    // Set GPIO27 as the latch pin
    if (gpiod_line_request(lines[0], GPIO27, line_config) < 0) {
        fprintf(stderr, "Failed to request GPIO27 as latch pin\n");
        close(gpio_chip_fd);
        gpiod_exit();
        return 1;
    }

    // Set all three lines as outputs
    if (gpiod_line_config_set(lines[0], line_config) < 0) {
        fprintf(stderr, "Failed to set GPIO17, GPIO18, and GPIO27 as outputs\n");
        close(gpio_chip_fd);
        gpiod_exit();
        return 1;
    }

    // Set the delay time for the shift-out function
    delay.tv_sec = 0;
    delay.tv_nsec = 500000;

    // Loop to blink the digit indefinitely
    while (1) {
        // Set the digit to '5'
        if (gpiod_line_config_set(lines[0], line_config) < 0) {
            fprintf(stderr, "Failed to set GPIO17 as data pin\n");
            close(gpio_chip_fd);
            gpiod_exit();
            return 1;
        }

        // Send 8 bits MSB-first
        for (int i = 0; i < 8; i++) {
            if (gpiod_line_config_set(lines[0], line_config) < 0) {
                fprintf(stderr, "Failed to set GPIO17 as data pin\n");
                close(gpio_chip_fd);
                gpiod_exit();
                return 1;
            }

            // Send the 8-bit value
            unsigned long value = (i & 0x80) ? 0xFFFFFFFF : 0x00FFFFFF;
            if (gpiod_line_config_set(lines[0], line_config) < 0) {
                fprintf(stderr, "Failed to set GPIO17 as data pin\n");
                close(gpio_chip_fd);
                gpiod_exit();
                return 1;
            }

            // Send the value MSB-first
            for (int j = 0; j < 8; j++) {
                if (gpiod_line_config_set(lines[0], line_config) < 0) {
                    fprintf(stderr, "Failed to set GPIO17 as data pin\n");
                    close(gpio_chip_fd);
                    gpiod_exit();
                    return 1;
                }

