#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define LED_GPIO_PIN 17
#define LED_GPIO_LINE 0
#define BUTTON_GPIO_PIN 18
#define BUTTON_GPIO_LINE 12

int main() {
    int chip_fd, line_fd, gpio_fd;
    struct gpiod_line_info line_info;
    struct gpiod_event_info event_info;
    char line_name[32];
    char button_name[32];
    int timeout_ms = 1000;
    int led_state = 0;
    int button_pressed = 0;
    int exit_flag = 0;

    // Open GPIO chip
    if ((chip_fd = gpiod_chip_open(0)) < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Request LED line as output initially low
    if (gpiod_line_request(chip_fd, LED_GPIO_LINE, GPIDIO_OUTPUT | GPIDIO_LOW, line_name, sizeof(line_name), &line_info) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", gpiod_strerror(errno));
        gpiod_chip_close(chip_fd);
        exit(EXIT_FAILURE);
    }

    // Request button as input with internal pull-up and falling-edge event detection
    if (gpiod_line_request(chip_fd, BUTTON_GPIO_LINE, GPIDIO_INPUT | GPIDIO_PULLUP | GPIDIO_FALLINGEDGE, button_name, sizeof(button_name), &line_info) < 0) {
        fprintf(stderr, "Failed to request button line as input: %s\n", gpiod_strerror(errno));
        gpiod_chip_close(chip_fd);
        exit(EXIT_FAILURE);
    }

    // Loop to toggle LED and monitor button events
    while (!exit_flag) {
        // Toggle LED state
        led_state = !led_state;
        gpio_fd = gpiod_line_get(chip_fd, line_info.line_index);
        if (gpio_fd < 0) {
            fprintf(stderr, "Failed to get GPIO line: %s\n", gpiod_strerror(errno));
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_event_wait(chip_fd, gpio_fd, line_info.line_index, GPIDIO_EVENT_FALLINGEDGE, timeout_ms, &event_info) < 0) {
            fprintf(stderr, "Failed to wait for falling edge event: %s\n", gpiod_strerror(errno));
            exit(EXIT_FAILURE);
        }

        if (event_info.event_type == GPIDIO_EVENT_FALLINGEDGE) {
            button_pressed = 1;
        }

        // Print message on falling edge
        if (button_pressed) {
            printf("Button pressed, LED will turn off...\n");
            led_state = 0;
        }

        // Toggle LED state
        gpio_fd = gpiod_line_get(chip_fd, line_info.line_index);
        if (gpio_fd < 0) {
            fprintf(stderr, "Failed to get GPIO line: %s\n", gpiod_strerror(errno));
            exit(EXIT_FAILURE);
        }

        if (led_state) {
            gpio_fd = gpiod_line_get(chip_fd, line_info.line_index);
            if (gpio_fd < 0) {
                fprintf(stderr, "Failed to get GPIO line: %s\n", gpiod_strerror(errno));
                exit(EXIT_FAILURE);
            }

            if (gpiod_line_set(chip_fd, line_info.line_index, GPIDIO_OUTPUT | GPIDIO_HIGH) < 0) {
                fprintf(stderr, "Failed to set LED line to high: %s\n", gpiod_strerror(errno));
                exit(EXIT_FAILURE);
            }

            usleep(1000); // Wait for 1 second

            gpio_fd = gpiod_line_get(chip_fd, line_info.line_index);
            if (gpio_fd < 0) {
                fprintf(stderr, "Failed to get GPIO line: %s\n", gpiod_strerror(errno));
                exit(EXIT_FAILURE);
            }

            if (gpiod_line_set(chip_fd, line_info.line_index, GPIDIO_INPUT) < 0) {
                fprintf(stderr, "Failed to set LED line to input: %s\n", gpiod_strerror(errno));
                exit(EXIT_FAILURE);
            }

            gpio_fd = gpiod_line_get(chip_fd, line_info.line_index);
            if (gpio_fd < 0) {
                fprintf(stderr, "Failed to get GPIO line: %s\n", gpiod_strerror(errno));
                exit(EXIT_FAILURE);
            }

            if (gpiod_line_set(chip_fd, line_info.line_index, GPIDIO_OUTPUT | GPIDIO_LOW) < 0) {
                fprintf(stderr, "Failed to set LED line to low: %s\n", gpiod_strerror(errno));
                exit(EXIT_FAILURE);
            }

            exit_flag = 1;
        }
    }

    // Close GPIO chip and release resources
    gpiod_chip_close(chip_fd);

    return 0;
