    int line_fd;
    int gpio_direction_value;
    int gpio_value;
    int error;

    // Open gpiochip0 device
    chip_fd = open("/dev/gpiochip0", O_RDWR);
    if (chip_fd < 0) {
        perror("Failed to open gpiochip0 device");
        exit(EXIT_FAILURE);
    }

    // Check if gpiochip0 device is found
    if (ioctl(chip_fd, GPIOC_GET_LINE_STATE, &line_fd) < 0) {
        perror("Failed to get gpiochip0 line state");
        exit(EXIT_FAILURE);
    }

    // Check if line is busy
    if (line_fd != -1) {
        perror("Failed to get gpiochip0 line status");
        exit(EXIT_FAILURE);
    }

    // Open GPIO lines
    gpio_direction_value = GPIO_OUTPUT;
    gpio_value = 0;

    // Configure GPIO24 as output initially low
    error = ioctl(chip_fd, GPIOC_SET_LINE_STATE, line_fd, gpio_direction_value, gpio_value);
    if (error < 0) {
        perror("Failed to set GPIO24 direction");
        exit(EXIT_FAILURE);
    }

    // Configure GPIO22 as input with internal pull-down
    error = ioctl(chip_fd, GPIOC_SET_LINE_STATE, line_fd, gpio_direction_value, gpio_value);
    if (error < 0) {
        perror("Failed to set GPIO22 direction");
        exit(EXIT_FAILURE);
    }

    // Set GPIO24 as output and GPIO22 as input
    error = ioctl(chip_fd, GPIOC_SET_LINE_STATE, line_fd, gpio_direction_value, gpio_value);
    if (error < 0) {
        perror("Failed to set GPIO24 and GPIO22 direction");
        exit(EXIT_FAILURE);
    }

    // Monitor the button
    while (1) {
        gpio_value = 0;
        error = ioctl(chip_fd, GPIOC_GET_LINE_STATE, line_fd, gpio_direction_value, &gpio_value);
        if (error < 0) {
            perror("Failed to get GPIO22 value");
            exit(EXIT_FAILURE);
        }

        if (gpio_value == 1) {
            // LED on
            error = ioctl(chip_fd, GPIOC_SET_LINE_STATE, line_fd, gpio_direction_value, gpio_value);
            if (error < 0) {
                perror("Failed to turn LED on");
                exit(EXIT_FAILURE);
            }
            usleep(500 * 1000); // 500 ms on
        } else {
            // LED off
            error = ioctl(chip_fd, GPIOC_SET_LINE_STATE, line_fd, gpio_direction_value, gpio_value);
            if (error < 0) {
                perror("Failed to turn LED off");
                exit(EXIT_FAILURE);
            }
            usleep(500 * 1000); // 500 ms off
        }

        // Wait for button release
        usleep(BUTTON_RESISTOR_VALUE * 1000); // 1 second
    }

    // Release resources
    close(chip_fd);
    close(line_fd);

    return 0;
}

