#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDRESS 0x39

int main() {
    int fd;
    int ret;
    int i;
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    uint16_t reg_addr;
    uint16_t reg_data;
    uint8_t data[2];
    uint16_t als_data;
    uint16_t r_data;
    uint16_t g_data;
    uint16_t b_data;
    char csv_file_name[] = "color_log.csv";
    FILE *csv_file;
    char *error_message = "I2C communication error: ";

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "%s: Failed to initialize pigpio library.\n", error_message);
        return 1;
    }

    // Open I2C bus
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "%s: Failed to open I2C bus.\n", error_message);
        gpioTerminate();
        return 1;
    }

    // Set I2C bus speed to 100 kHz
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "%s: Failed to set I2C bus speed.\n", error_message);
        close(fd);
        gpioTerminate();
        return 1;
    }

