#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define LED_GPIO 17

int main() {
    int fd;
    int i;
    int16_t data[6];
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_rdwr_ioctl_data_setup setup;
    int16_t devid;
    int16_t accel_data[6];
    int16_t accel_data_sum = 0;
    int16_t accel_threshold = 2;
    int16_t accel_direction = 0;
    int16_t accel_gx, accel_gy, accel_gz;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up I2C bus 1
    if (piSetupI2C() < 0) {
        fprintf(stderr, "Error: Failed to set up I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Set up LED
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Check DEVID register
    if (piI2CReadReg16(I2C_DEV_ADDR, 0x00, &devid) < 0) {
        fprintf(stderr, "Error: Failed to read DEVID register\n");
        gpioTerminate();
        return 1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Error: DEVID register does not read 0xE5\n");
        gpioTerminate();
        return 1;
    }

    // Set full-resolution, ±2g range
    if (piI2CRewriteReg16(I2C_DEV_ADDR, 0x32, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to reconfigure sensor\n");
        gpioTerminate();
        return 1;
    }

    // Start reading data
    while (1) {
        // Read data from sensor
        if (piI2CReadReg16(I2C_DEV_ADDR, 0x32, data, 6) < 0) {
            fprintf(stderr, "Error: Failed to read data from sensor\n");
            gpioTerminate();
            return 1;
        }

        // Calculate sum of data
        for (i = 0; i < 6; i++) {
            accel_data_sum += data[i];
        }

        // Check if acceleration exceeds threshold
        if (abs(accel_data_sum) > accel_threshold) {
            if (accel_direction == 0) {
                gpioSetValue(LED_GPIO, 1);
            } else {
                gpioSetValue(LED_GPIO, 0);
            }
            accel_direction = -accel_direction;
        }

        // Log data
        sprintf(accel_log, "%.3f,%.3f,%.3f\n", data[0]/16.0, data[1]/16.0, data[2]/16.0);
        FILE *log_file = fopen("accel_log.txt", "a");
        if (log_file) {
            fprintf(log_file, accel_log);
            fclose(log_file);
        }

        // Wait for 100 ms
        usleep(100000);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

