    if (pigpio_set_mode(i2c_fd, I2C_MODE_I2C) < 0) {
        printf("Error: Failed to set up I2C communication.\n");
        return 1;
    }

    // Set up GPIO for I2C communication
    if (pigpio_set_mode(gpio_fd, GPIO_MODE_I2C) < 0) {
        printf("Error: Failed to set up GPIO for I2C communication.\n");
        return 1;
    }

