    if (pigpio_set_slave(i2c_fd, I2C_ADDR_GY_51_LSM303DLHC) < 0) {
        printf("Error: Failed to set up I2C slave address.\n");
        return 1;
    }

    // Set up I2C write function
    if (pigpio_write(i2c_fd, 0, 0, sizeof(gy_data), &gy_data) < 0) {
        printf("Error: Failed to write data to I2C device.\n");
        return 1;
    }

    // Set up I2C write function
    if (pigpio_write(i2c_fd, 0, 0, sizeof(mag_data), &mag_data) < 0) {
        printf("Error: Failed to write data to I2C device.\n");
        return 1;
