        printf("Error: Failed to read data from I2C device.\n");
        return 1;
    }

    // Set up I2C read function
    if (pigpio_read(i2c_fd, 0, 0, sizeof(mag_data), &mag_data) < 0) {
        printf("Error: Failed to read data from I2C device.\n");
        return 1;
    }

    // Calculate heading
    float heading_rad = atan2(mag_data[1], mag_data[0]);
    heading_rad = heading_rad * 180 / M_PI;

    // Convert heading to degrees
    if (heading_rad < -M_PI_2)
        heading_rad += M_PI_2;
    else if (heading_rad > M_PI_2)
        heading_rad -= M_PI_2;

    // Format heading string
    snprintf(heading_str, 50, "%.2f", heading_rad);

    // Log heading
    fprintf(log_file, "%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", heading_str, gy_data[0], gy_data[1], gy_data[2], mag_data[0], mag_data[1], mag_data[2]);

    // Close log file
    fclose(log_file);

    // Close I2C handles
    pigpio_close(i2c_fd);
    pigpio_close(gpio_fd);

    // Graceful shutdown
    signal(SIGINT, graceful_shutdown);
    signal(SIGTERM, graceful_shutdown);

    return 0;
}

