#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#include <pigpio.h>

#define CE_GPIO_NUM 8
#define SPI_CHANNEL_0 0
#define SPI_MODE_3 (1 << 5)
#define SPI_CPOL_1 (1 << 6)
#define SPI_CPHA_1 (1 << 7)
#define SPI_FLAGS_0b11000000000 (1 << 9) | (1 << 10) | (1 << 8)

#define ADIS16488A_ADDRESS 0x1A
#define ADIS16488A_GYRO_X_REG 0x04
#define ADIS16488A_GYRO_Y_REG 0x06
#define ADIS16488A_GYRO_Z_REG 0x08
#define ADIS16488A_ACCEL_X_REG 0x0A
#define ADIS16488A_ACCEL_Y_REG 0x0C
#define ADIS16488A_ACCEL_Z_REG 0x0E

#define SAMPLE_INTERVAL 100
#define SAMPLE_PERIOD 10

int main() {
    int fd;
    int gpioHandle;
    int spiHandle;
    int csvHandle;
    int sampleCount = 0;
    int sampleInterval = 0;
    int sampleDelay = 0;
    int runningFlag = 0;
    char timestamp[32];
    float gyroSensitivity[3] = {0.005, 0.005, 0.005};
    float accelSensitivity[3] = {0.00025, 0.00025, 0.00025};
    uint16_t gyroData[2];
    uint16_t accelData[3];
    uint8_t adisData[2];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    if (spiOpen(CE_GPIO_NUM, SPI_CHANNEL_0, SPI_MODE_3, SPI_CPOL_1, SPI_CPHA_1, SPI_FLAGS_0b11000000000) < 0) {
        fprintf(stderr, "Failed to open SPI channel.\n");
        gpioTerminate();
        return 1;
    }

    if (fopen("imu_data.csv", "w") == NULL) {
        fprintf(stderr, "Failed to open CSV file for logging.\n");
        spiClose();
        gpioTerminate();
        return 1;
    }

    csvHandle = fileno(stdout);

    while (1) {
        if (runningFlag) {
            sampleDelay = millis() % SAMPLE_PERIOD;
            if (sampleDelay > 0) {
                sampleCount++;
                if (sampleCount % sampleInterval == 0) {
                    if (readGyroData() && readAccelData()) {
                        convertSensitivity();
                        logSample();
                    }
                }
            }
        }

        if (gpioRead(CE_GPIO_NUM) & 1) {
            runningFlag = 0;
        }

        if (sampleDelay == 0) {
            gpioDelay(sampleInterval);
        }

        if (runningFlag) {
            gpioDelay(sampleDelay);
        }
    }

    spiClose();
    gpioTerminate();
    fclose(csvHandle);

    return 0;
