int gpioInitialise() {
    int ret;
    ret = pigpio_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %d\n", ret);
        return ret;
    }

    ret = pigpio_set_mode(CE_GPIO_NUM, PI_MODE_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %d\n", ret);
        return ret;
    }

    ret = pigpio_set_dir(CE_GPIO_NUM, PI_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO direction: %d\n", ret);
        return ret;
    }

    ret = pigpio_set_value(CE_GPIO_NUM, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO value: %d\n", ret);
        return ret;
    }

    return 0;
}

int spiOpen(int cePin, int channel, int mode, int polarity, int phase, int flags) {
    int ret;
    struct spi_device *spi_device;

    ret = pigpio_spi_open(CE_GPIO_NUM, &spi_device, channel, mode, polarity, phase, flags);
    if (ret < 0) {
        fprintf(stderr, "Failed to open SPI device: %d\n", ret);
        return ret;
    }

    ret = pigpio_spi_xfer(spi_device, CE_GPIO_NUM, CE_GPIO_NUM, SPI_FLAGS_0b11000000000, ADIS16488A_ADDRESS, ADIS16488A_GYRO_X_REG, adisData, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read data from SPI device: %d\n", ret);
        return ret;
    }

    ret = pigpio_spi_xfer(spi_device, CE_GPIO_NUM, CE_GPIO_NUM, SPI_FLAGS_0b11000000000, ADIS16488A_ADDRESS, ADIS16488A_GYRO_Y_REG, adisData, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read data from SPI device: %d\n", ret);
        return ret;
    }

    ret = pigpio_spi_xfer(spi_device, CE_GPIO_NUM, CE_GPIO_NUM, SPI_FLAGS_0b11000000000, ADIS16488A_ADDRESS, ADIS16488A_GYRO_Z_REG, adisData, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read data from SPI device: %d\n", ret);
        return ret;
    }

    ret = pigpio_spi_xfer(spi_device, CE_GPIO_NUM, CE_GPIO_NUM, SPI_FLAGS_0b11000000000, ADIS16488A_ADDRESS, ADIS16488A_ACCEL_X_REG, adisData, 3);
    if (ret < 0) {
        fprintf(stderr, "Failed to read data from SPI device: %d\n", ret);
        return ret;
    }

    ret = pigpio_spi_xfer(spi_device, CE_GPIO_NUM, CE_GPIO_NUM, SPI_FLAGS_0b11000000000, ADIS16488A_ADDRESS, ADIS16488A_ACCEL_Y_REG, adisData, 3);
    if (ret < 0) {
        fprintf(stderr, "Failed to read data from SPI device: %d\n", ret);
        return ret;
    }

    ret = pigpio_spi_xfer(spi_device, CE_GPIO_NUM, CE_GPIO_NUM, SPI_FLAGS_0b11000000000, ADIS16488A_ADDRESS, ADIS16488A_ACCEL_Z_REG, adisData, 3);
    if (ret < 0) {
        fprintf(stderr, "Failed to read data from SPI device: %d\n", ret);
        return ret;
    }

    return 0;
}

int readGyroData() {
    int ret;
    uint16_t data[2];

    ret = pigpio_spi_xfer(spiHandle, CE_GPIO_NUM, CE_GPIO_NUM, SPI_FLAGS_0b11000000000, ADIS16488A_ADDRESS, ADIS16488A_GYRO_X_REG, data, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read data from SPI device: %d\n", ret);
        return ret;
    }

    gyroData[0] = (data[0] << 8) | data[1];
    gyroData[1] = (data[0] >> 8) & 0xFF;

    return 0;
}

int readAccelData() {
    int ret;
    uint16_t data[3];

