#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x68

int main() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    int retry_count = 0;

    // Open the I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) == -1) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("Error setting I2C address");
        exit(EXIT_FAILURE);
    }

    // Open the sensor device file
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        perror("Error opening sensor device file");
        exit(EXIT_FAILURE);
    }

    // Wake up the sensor
    if (ioctl(i2c_fd, I2C_WAKE, 0x00) == -1) {
        perror("Error waking up the sensor");
        exit(EXIT_FAILURE);
    }

    // Set the desired ranges
    if (ioctl(i2c_fd, I2C_SET_GAIN, 0x00) == -1) {
        perror("Error setting gain");
        exit(EXIT_FAILURE);
    }

    // Set the ranges to +-2g and +-250 dps
    if (ioctl(i2c_fd, I2C_SET_GYRO_RANGE, 0x1B) == -1) {
        perror("Error setting gyro range");
        exit(EXIT_FAILURE);
    }

    // Set the ranges to +-2g and +-250 dps
    if (ioctl(i2c_fd, I2C_SET_ACCEL_RANGE, 0x1C) == -1) {
        perror("Error setting accel range");
        exit(EXIT_FAILURE);
    }

    // Set the I2C file descriptor to non-blocking mode
    if (fcntl(i2c_fd, F_SETFL, O_NONBLOCK) == -1) {
        perror("Error setting non-blocking mode");
        exit(EXIT_FAILURE);
    }

    // Loop to read data
    while (1) {
        // Read raw accelerometer data from registers 0x3B-0x40
        if (ioctl(i2c_fd, I2C_RDWR, 0x3B) == -1) {
            perror("Error reading accelerometer data");
            exit(EXIT_FAILURE);
        }

        // Read raw gyroscope data from registers 0x43-0x48
        if (ioctl(i2c_fd, I2C_RDWR, 0x43) == -1) {
            perror("Error reading gyroscope data");
            exit(EXIT_FAILURE);
        }

        // Print the raw 16-bit signed values to the console
        for (int i = 0; i < 8; i++) {
            printf("Accelerometer: %d\n", (int)i2c_data.wr_data[i]);
        }
        for (int i = 0; i < 8; i++) {
            printf("Gyroscope: %d\n", (int)i2c_data.wr_data[i + 8]);
        }

        // Wait 50 ms
        sleep(50);
    }

    // Close the I2C file descriptor
    close(i2c_fd);

    // Close the I2C bus
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("Error closing I2C bus");
        exit(EXIT_FAILURE);
    }

    return 0;
}

