#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define I2C_BUS_NUM 1
#define LED_GPIO_LINE 17

#define I2C_ADDRESS 0x1D
#define I2C_TIMEOUT_MS 100

int main() {
    int i2c_fd;
    int gpio_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    struct i2c_msg i2c_msg;
    int ret;
    int threshold = 2.0;
    char buffer[2];
    char log_file_path[] = "/home/pi/impact_log.txt";
    struct timespec start_time, end_time;
    unsigned long long elapsed_time;

    // Initialize LED GPIO line
    if (ioctl(LED_GPIO_LINE, GPIO_SET_LEVEL, GPIO_HIGH) < 0) {
        perror("Failed to set LED GPIO line to high");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C bus address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }

    // Open LED GPIO line
    if ((gpio_fd = open("/dev/gpiochip0", O_RDWR)) < 0) {
        perror("Failed to open LED GPIO line");
        exit(EXIT_FAILURE);
    }

    // Set GPIO line as output
    if (ioctl(gpio_fd, GPIO_SET_LEVEL, GPIO_HIGH) < 0) {
        perror("Failed to set LED GPIO line to high");
        exit(EXIT_FAILURE);
    }

    // Check sensor's identity
    if (ioctl(i2c_fd, I2C_RDWR, I2C_WHO_AM_I) < 0) {
        perror("Failed to read WHO_AM_I register");
        exit(EXIT_FAILURE);
    }

    if (memcmp(buffer, "\x1A", 1) != 0) {
        printf("Sensor identity check failed. Exiting.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C communication
    memset(&i2c_msgs, 0, sizeof(i2c_msgs));
    i2c_msgs[0].addr = I2C_ADDRESS;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 2;
    i2c_msgs[0].buf = &i2c_msg;

    while (1) {
        // Poll sensor
        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_msgs[0]);
        if (ret < 0) {
            perror("Failed to read sensor data");
            exit(EXIT_FAILURE);
        }

        // Check if acceleration exceeds threshold
        if (buffer[0] > threshold && buffer[1] > threshold) {
            // Log the impact
            if (write(log_file_path, &buffer[0], 2) < 0) {
                perror("Failed to write to log file");
                exit(EXIT_FAILURE);
            }

            // Turn LED on
            if (ioctl(LED_GPIO_LINE, GPIO_SET_LEVEL, GPIO_HIGH) < 0) {
                perror("Failed to set LED GPIO line to high");
                exit(EXIT_FAILURE);
            }

            // Record timestamp
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }

        // Check if acceleration exceeds threshold
        if (buffer[0] < -threshold && buffer[1] < -threshold) {
            // Log the impact
            if (write(log_file_path, &buffer[0], 2) < 0) {
                perror("Failed to write to log file");
                exit(EXIT_FAILURE);
            }

            // Turn LED off
            if (ioctl(LED_GPIO_LINE, GPIO_SET_LEVEL, GPIO_LOW) < 0) {
                perror("Failed to set LED GPIO line to low");
                exit(EXIT_FAILURE);
            }

            // Record timestamp
            clock_gettime(CLOCK_MONOTONIC, &end_time);
            elapsed_time = (end_time.tv_sec - start_time.tv_sec) * 1000000 + (end_time.tv_nsec - start_time.tv_nsec);
            printf("Elapsed time: %llu ms\n", elapsed_time);
        }

        // Wait for 100 ms
        usleep(100000);
    }

    // Clean up
    close(i2c_fd);
    close(gpio_fd);
    return 0;
}

