#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define CE_GPIO_NUM 8
#define SPI_CHANNEL_0 0
#define WHO_AM_I_REGISTER 0x3F5A

int main() {
    int ret;
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_direction direction;
    struct gpiod_event event;
    struct timespec start_time, end_time;
    struct angular_rate angular_rate;
    char log_file_name[] = "gyro_log.csv";
    FILE *log_file;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO and SPI
    chip = gpiod_chip_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to find gpiochip0\n");
        return 1;
    }

    line = gpiod_line_by_name(chip, "gpio8");
    if (line == NULL) {
        fprintf(stderr, "Error: Failed to find gpio8\n");
        return 1;
    }

    direction = gpiod_direction_output;
    if (gpioSetLinePolarity(line, direction) < 0) {
        fprintf(stderr, "Error: Failed to set polarity for gpio8\n");
        return 1;
    }

    if (gpioOpen(line, O_RDWR) < 0) {
        fprintf(stderr, "Error: Failed to open gpio8\n");
        return 1;
    }

    // Set CE pin to output
    if (gpioSetLineValue(line, direction, 1) < 0) {
        fprintf(stderr, "Error: Failed to set CE pin to output\n");
        return 1;
    }

    // Set SPI mode and transfer parameters
    if (gpioSetSpeed(1000) < 0) {
        fprintf(stderr, "Error: Failed to set SPI speed to 1000 Hz\n");
        return 1;
    }

    if (gpioSetMode(CE_GPIO_NUM, direction) < 0) {
        fprintf(stderr, "Error: Failed to set CE pin direction\n");
        return 1;
    }

    // Set SPI transfer parameters
    if (gpioSetTransferType(SPI_CHANNEL_0, GPIGPIO_TRANSFER_SPI) < 0) {
        fprintf(stderr, "Error: Failed to set SPI transfer type\n");
        return 1;
    }

    if (gpioSetDataFormat(SPI_CHANNEL_0, GPIGPIO_DATA_16_BIT) < 0) {
        fprintf(stderr, "Error: Failed to set SPI data format\n");
        return 1;
    }

    if (gpioSetDataOrder(SPI_CHANNEL_0, GPIGPIO_DATA_MSB_FIRST) < 0) {
        fprintf(stderr, "Error: Failed to set SPI data order\n");
        return 1;
    }

    if (gpioSetClockPolarity(SPI_CHANNEL_0, GPIGPIO_CLOCK_CPOL_LOW) < 0) {
        fprintf(stderr, "Error: Failed to set SPI clock polarity\n");
        return 1;
    }

    if (gpioSetClockPhase(SPI_CHANNEL_0, GPIGPIO_CLOCK_CPHA_1) < 0) {
        fprintf(stderr, "Error: Failed to set SPI clock phase\n");
        return 1;
    }

    if (gpioSetDataSize(SPI_CHANNEL_0, GPIGPIO_DATA_16_BIT) < 0) {
        fprintf(stderr, "Error: Failed to set SPI data size\n");
        return 1;
    }

    // Set WHO_AM_I register value
    if (gpioSetRegister(CE_GPIO_NUM, 0x3F5A, 1) < 0) {
        fprintf(stderr, "Error: Failed to set WHO_AM_I register value\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read X_GYRO_OUT register
        if (gpioGetRegister(CE_GPIO_NUM, 0x14, 1, &ret) < 0) {
            fprintf(stderr, "Error: Failed to read X_GYRO_OUT register\n");
            return 1;
        }

        // Scale the value at 0.0305 deg/sec/LSB
        angular_rate.x = (ret >> 8) * 0.0305;
        angular_rate.y = (ret >> 9) * 0.0305;
        angular_rate.z = (ret >> 10) * 0.0305;

        // Log the angular rate
        if (fprintf(log_file, "%d,%f,%f,%f\n", (int)(ret >> 8), angular_rate.x, angular_rate.y, angular_rate.z) < 0) {
            fprintf(stderr, "Error: Failed to log angular rate\n");
            return 1;
        }

        // Sleep for 10 ms
        if (nanosleep(&start_time, &end_time) < 0) {
            fprintf(stderr, "Error: Failed to sleep for 10 ms\n");
            return 1;
        }
    }

    // Clean up
    gpioClose(line);
    gpioSetSpeed(1000);
    gpioSetMode(CE_GPIO_NUM, direction);
    gpioSetTransferType(SPI_CHANNEL_0, GPIGPIO_TRANSFER_SPI);
    gpioSetDataFormat(SPI_CHANNEL_0, GPIGPIO_DATA_16_BIT);
    gpioSetDataOrder(SPI_CHANNEL_0, GPIGPIO_DATA_MSB_FIRST);
    gpioSetClockPolarity(SPI_CHANNEL_0, GPIGPIO_CLOCK_CPOL_LOW);
    gpioSetClockPhase(SPI_CHANNEL_0, GPIGPIO_CLOCK_CPHA_1);
    gpioSetDataSize(SPI_CHANNEL_0, GPIGPIO_DATA_16_BIT);
    gpioSetRegister(CE_GPIO_NUM, 0x3F5A, 1);
    gpioTerminate();

    return 0;
}

