#include <gpiod.h>

#define KY026_DO_PIN 17
#define KY026_DO_NAME "gpio17"
#define KY026_DO_FILENAME "flame_events.log"

int main() {
    int fd;
    int ret;
    struct gpiod_event event;
    char *log_file = KY026_DO_NAME;
    int log_fd;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    // Open log file in append mode
    if ((log_fd = open(log_file, O_RDWR | O_CREAT, 0644)) < 0) {
        fprintf(stderr, "Error: Failed to open log file\n");
        return 1;
    }

    // Set the DO pin as an output with internal pull-up
    if (gpioSetMode(KY026_DO_NAME, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set DO pin as output\n");
        return 1;
    }
    if (gpioSetPulldown(KY026_DO_NAME) < 0) {
        fprintf(stderr, "Error: Failed to set DO pin as pull-down\n");
        return 1;
    }

    // Set the DO pin as an input
    if (gpioSetMode(KY026_DO_NAME, GPIO_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set DO pin as input\n");
        return 1;
    }

    // Initialize the file descriptor for the log file
    if (log_fd >= 0) {
        if (lseek(log_fd, 0, SEEK_END) < 0) {
            fprintf(stderr, "Error: Failed to seek to end of log file\n");
            return 1;
        }
        if (ftruncate(log_fd, 0) < 0) {
            fprintf(stderr, "Error: Failed to truncate log file\n");
            return 1;
        }
    }

    // Main loop
    while (1) {
        // Read the sensor's digital output
        ret = gpioRead(KY026_DO_NAME, &event, 1);
        if (ret < 0) {
            if (ret == PI_BAD_GPIO) {
                fprintf(stderr, "Error: Sensor read error: %s\n", gpioErrorName(ret));
            } else {
                fprintf(stderr, "Error: Failed to read sensor: %s\n", gpioErrorName(ret));
