int log_fd;

void init_i2c() {
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        exit(1);
    }
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        exit(1);
    }
}

void cleanup_gpio() {
    gpioTerminate();
}

void cleanup_i2c() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void log_entry(int raw_x, int raw_y, int raw_z) {
    char log_filename[128];
    snprintf(log_filename, sizeof(log_filename), "fall_log.txt", time(NULL));

    FILE *log_file = fopen(log_filename, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(1);
    }

    fprintf(log_file, "%.4X, %.4X, %.4X\n", raw_x, raw_y, raw_z);
    fclose(log_file);
}

void read_data_registers(int *registers) {
    if (ioctl(i2c_fd, I2C_RDWR, I2C_ADDR) < 0) {
        perror("Failed to read data registers");
        exit(1);
    }

    for (int i = 0; i < 6; i++) {
        if (ioctl(i2c_fd, I2C_RD, registers + i) < 0) {
            perror("Failed to read data register");
            exit(1);
        }
    }
}

void calculate_tilt_angle(int raw_x, int raw_y, int raw_z) {
    float x = (float) raw_x / 4096.0 * 2.0;
    float y = (float) raw_y / 4096.0 * 2.0;
    float z = (float) raw_z / 4096.0 * 2.0;

    float x_signed = x > 0 ? x : -x;
    float y_signed = y > 0 ? y : -y;
    float z_signed = z > 0 ? z : -z;

    float x_msb = x_signed > 0 ? x_signed : -x_signed;
    float y_msb = y_signed > 0 ? y_signed : -y_signed;
    float z_msb = z_signed > 0 ? z_signed : -z_signed;

    float x_lsb = x_signed < 0 ? -x_signed : x_signed;
    float y_lsb = y_signed < 0 ? -y_signed : y_signed;
    float z_lsb = z_signed < 0 ? -z_signed : z_signed;

    float x_angle = atan2(x_msb, x_lsb);
    float y_angle = atan2(y_msb, y_lsb);
    float z_angle = atan2(z_msb, z_lsb);

    float tilt_angle = fabsf(x_angle) + fabsf(y_angle) + fabsf(z_angle);

    if (tilt_angle > M_PI_2) {
        tilt_angle = M_PI_2 - tilt_angle;
    }
    else if (tilt_angle < -M_PI_2) {
        tilt_angle = -M_PI_2 + tilt_angle;
    }

    return tilt_angle;
}

int main() {
    init_i2c();
    init_gpio();

    init_log_file();

    init_i2c_fd();
    init_gpio_fd();

    init_data_registers();

    while (1) {
        int raw_x, raw_y, raw_z;
        read_data_registers(&raw_x);
        read_data_registers(&raw_y);
        read_data_registers(&raw_z);

        int tilt_angle = calculate_tilt_angle(raw_x, raw_y, raw_z);

        log_entry(raw_x, raw_y, raw_z);

        if (tilt_angle > M_PI_2) {
            tilt_angle = M_PI_2 - tilt_angle;
        }
        else if (tilt_angle < -M_PI_2) {
            tilt_angle = -M_PI_2 + tilt_angle;
        }

        if (tilt_angle > M_PI_4) {
            tilt_angle = M_PI_4 - tilt_angle;
        }
        else if (tilt_angle < -M_PI_4) {
            tilt_angle = -M_PI_4 + tilt_angle;
        }

        printf("Tilt angle: %.4f rad\n", tilt_angle);

        usleep(100000);
    }

    cleanup_i2c();
    cleanup_gpio();

    return 0;
}
