#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define E18_D80NK_GPIO_LINE "/sys/class/gpio/gpiochip4/gpio17"
#define E18_D80NK_LINE "/sys/class/gpio/gpio17"

int main() {
    int chip_fd, line_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec start_time, end_time;
    char line_value;

    // Open gpiochip4 for GPIO17
    chip_fd = gpiod_chip_open_by_name("gpiochip4");
    if (chip_fd < 0) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", gpiod_strerror(chip_fd));
        return 1;
    }

    // Request line for input direction
    line_fd = gpiod_line_open(chip_fd, E18_D80NK_LINE);
    if (line_fd < 0) {
        fprintf(stderr, "Failed to open line for input direction: %s\n", gpiod_strerror(line_fd));
        gpiod_chip_close(chip_fd);
        return 1;
    }

    // Request line for input direction
    if (gpiod_line_request_input(line_fd) < 0) {
        fprintf(stderr, "Failed to request input on line: %s\n", gpiod_strerror(line_fd));
        gpiod_line_close(line_fd);
        gpiod_chip_close(chip_fd);
        return 1;
    }

    // Poll the sensor every 1 second
    while (1) {
        // Read the line value
        if (gpiod_line_get_value(line_fd, &line_value) < 0) {
            fprintf(stderr, "Failed to read line value: %s\n", gpiod_strerror(line_fd));
            continue;
        }

        // Check if an obstacle is detected
        if (line_value == 0) {
            // Simulate self-parking sequence
            printf("Self-parking sequence started\n");
            sleep(1);
