                fprintf(stderr, "Error: Failed to read data.\n");
                return 1;
            }

            fprintf(stderr, "Accel X/Y/Z sensitivity: ");
            for (int i = 0; i < 3; i++) {
                fprintf(stderr, "%d ", data[i]);
            }
            fprintf(stderr, "\n");

            num_bytes = 12;
            if (ret != read(I2C_BUS_NUM, data, num_bytes)) {
                fprintf(stderr, "Error: Failed to read data.\n");
                return 1;
            }

            fprintf(stderr, "Accel sensitivity: ");
            for (int i = 0; i < 3; i++) {
                fprintf(stderr, "%d ", data[i]);
            }
            fprintf(stderr, "\n");

            fprintf(stderr, "mg/LSB\n");
            fprintf(stderr, "===================================================================\n");
        }
    }

    return 0;
