#include <sys/wait.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>

#define KY038_PIN 11
#define KY038_OUT_PIN 17

int main(int argc, char *argv[]) {
    int threshold;
    int high_count = 0;
    int window_start = 0;
    int window_end = 0;
    int alert_count = 0;
    int status_count = 0;
    int exit_status = 0;
    int error_code = 0;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    if (sscanf(argv[1], "%d", &threshold) != 1) {
        fprintf(stderr, "Invalid input: %s\n", argv[1]);
        return 1;
    }

    if (threshold <= 0) {
        fprintf(stderr, "Threshold must be a positive integer\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    gpioSetMode(KY038_PIN, PI_OUT);
    gpioSetMode(KY038_OUT_PIN, PI_OUT);

    while (1) {
        gpioSetLineState(KY038_PIN, PI_HIGH);
        gpioDelay(1);
        gpioSetLineState(KY038_PIN, PI_LOW);

        window_start = gpioGetLineState(KY038_PIN);
        window_end = gpioGetLineState(KY038_PIN);

        high_count++;

        if (window_end - window_start >= 5) {
            if (window_end - window_start > threshold) {
                printf("ALERT: High reading count exceeded threshold (%d vs %d)\n", high_count, threshold);
                alert_count++;
            } else {
                printf("STATUS: High reading count (%d) did not exceed threshold\n", high_count);
                status_count++;
            }
        }

        if (window_end - window_start >= 5) {
            gpioDelay(1000);
        }

        if (gpioGetState(KY038_OUT_PIN) == PI_HIGH) {
            exit_status = 0;
        }

        if (gpioGetState(KY038_OUT_PIN) == PI_LOW) {
            exit_status = 1;
        }

        if (exit_status == 0) {
            break;
        }

        if (gpioTerminate() < 0) {
            fprintf(stderr, "Failed to terminate pigpio: %s\n", strerror(errno));
            error_code = 1;
        }

        if (error_code != 0) {
            break;
        }

        if (waitpid(getpid(), &error_code, 0) < 0) {
            fprintf(stderr, "Failed to wait for child process: %s\n", strerror(errno));
            error_code = 1;
        }

        if (error_code != 0) {
            break;
        }

        if (exit_status == 0) {
            break;
        }

        if (kill(getpid(), SIGINT) < 0) {
            fprintf(stderr, "Failed to send SIGINT to parent process: %s\n", strerror(errno));
            error_code = 1;
        }

        if (error_code != 0) {
            break;
        }

        if (kill(getpid(), SIGTERM) < 0) {
            fprintf(stderr, "Failed to send SIGTERM to parent process: %s\n", strerror(errno));
            error_code = 1;
        }

        if (error_code != 0) {
            break;
        }

        if (waitpid(getpid(), &error_code, 0) < 0) {
            fprintf(stderr, "Failed to wait for child process: %s\n", strerror(errno));
            error_code = 1;
        }

        if (error_code != 0) {
            break;
        }
    }

    gpioTerminate();
    gpioInitialise();

    return 0;
}

