#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x23

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[2];
    int ret;

    // Open the I2C bus
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C address to 0x23
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }

    // Set the One-Time High-Resolution Mode 2 command (0x21)
    if (ioctl(fd, I2C_RDWR, 0x21) < 0) {
        perror("Failed to set One-Time High-Resolution Mode 2 command");
        exit(EXIT_FAILURE);
    }

    // Wait for the maximum conversion time of 180 ms
    struct timespec ts_start, ts_end;
    clock_gettime(CLOCK_MONOTONIC, &ts_start);

    // Read 2 bytes of data
    msg[0].addr = I2C_ADDR;
    msg[0].flags = 0;
    msg[0].len = 2;
    msg[1].addr = I2C_ADDR;
    msg[1].flags = 0;
    msg[1].len = 2;

    data.msgs = msg;
    data.nmsgs = 2;

    ret = ioctl(fd, I2C_RDWR, &data);
    if (ret < 0) {
        perror("Failed to read data from sensor");
        exit(EXIT_FAILURE);
    }

    // Calculate and log the illuminance in lux
    struct i2c_msg* msg_end = &msg[1];
    int raw_value = (int)((msg[0].data[0] << 8) | msg[0].data[1]);
    float lux = (float)((raw_value * 5) / 6);

    // Log the sensor readings to 'light_log.txt'
    FILE* log_file = fopen("light_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    char timestamp[80];
    struct timespec ts_end;
    clock_gettime(CLOCK_MONOTONIC, &ts_end);
    gettimeofday(&ts_start, NULL);
    gettimeofday(&ts_end, NULL);
    int elapsed_ms = (int)((ts_end.tv_sec - ts_start.tv_sec) * 1000 + (ts_end.tv_usec - ts_start.tv_usec) / 1000);
    sprintf(timestamp, "%s, Lux: %.2f\n", gmtime(&ts_start), lux);
    fprintf(log_file, "%s\n", timestamp);
    fprintf(log_file, "%s\n", timestamp);
    fprintf(log_file, "%s\n", timestamp);

    fclose(log_file);

    // Release resources
    close(fd);
    return 0;
}

