        gpiod_exit(gpiochip);
        return 1;
    }

    if ((line2 = gpiod_request_line(gpiochip, TIP120_PIN_2, GPIO_INPUT)) < 0) {
        fprintf(stderr, "Failed to request line 2: %s\n", strerror(errno));
        gpiod_release_line(gpiochip, line1);
        gpiod_exit(gpiochip);
        return 1;
    }

    // Set both lines to LOW
    if (gpio_direction_output(line1, 0) < 0) {
        fprintf(stderr, "Failed to set line 1 LOW: %s\n", strerror(errno));
