        gpiod_release_line(gpiochip, line2);
        gpiod_exit(gpiochip);
        return 1;
    }

    if (gpio_direction_output(line2, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set line 2 OUTPUT: %s\n", strerror(errno));
        gpiod_release_line(gpiochip, line1);
        gpiod_release_line(gpiochip, line2);
        gpiod_exit(gpiochip);
        return 1;
    }

