            gpiod_release_line(gpiochip, line1);
            gpiod_release_line(gpiochip, line2);
            gpiod_exit(gpiochip);
            return 1;
        }

        // De-energize solenoid 1 and energize solenoid 2 for 500 ms
        if (gpio_output_value(line1, 0) < 0) {
            fprintf(stderr, "Failed to set line 1 LOW: %s\n", strerror(errno));
            gpiod_release_line(gpiochip, line1);
