        if ((result = gpioRead(27, buffer, 10)) < 0) {
            fprintf(stderr, "Error: Failed to read from UART1\n");
            return 1;
        }
        if (result == 0) {
            fprintf(stderr, "Error: Timeout waiting for UART1 input\n");
            continue;
        }
        if (strcmp(buffer, EXPECTED_CODE) != 0) {
            fprintf(stderr, "Error: UART1 input does not match the expected code\n");
            continue;
