            timeout = 5;
        }

        // Unlock both doors simultaneously for 2 seconds
        if (gpioWrite(17, PI_HIGH) < 0 || gpioWrite(27, PI_HIGH) < 0) {
            fprintf(stderr, "Error: Failed to set GPIO17 and GPIO27 to HIGH\n");
            return 1;
        }
        if (gpioDelay(timeout) < 0) {
            fprintf(stderr, "Error: Failed to wait for timeout\n");
            return 1;
        }
        if (gpioWrite(17, PI_LOW) < 0 || gpioWrite(27, PI_LOW) < 0) {
            fprintf(stderr, "Error: Failed to set GPIO17 and GPIO27 to LOW\n");
            return 1;
        }

        // Cleanup
        gpioTerminate();
    }

    return 0;
