            // Log failsafe timeout
            syslog(LOG_WARNING, "PIR sensor reading HIGH for more than %d seconds", FAILSAFE_TIMEOUT_SEC);
            failsafe_triggered = 0;
        }

        // Check for shutdown
        if (relay_on && !motion_detected && failsafe_triggered) {
            // Log shutdown
            syslog(LOG_INFO, "Shutting down");
            goto close_gpio_lines;
        }

        // Wait for 50 ms
        usleep(50000);
    }

close_gpio_lines:
