        syslog(LOG_ERR, "Failed to release gpio lines: %s", strerror(errno));
    }

close_gpio_fd:
    // Close gpiochip
    ret = close(fd);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to close gpiochip: %s", strerror(errno));
    }

    return 0;
