#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define GPIO_DIR_IN 0
#define GPIO_DIR_OUT 1

int main() {
    int relays[4] = {18, 23, 24, 25};
    int i;

    // Initialize the GPIO chip
    int gpio_fd = gpiod_get_fd(0);
    if (gpio_fd < 0) {
        perror("Failed to get GPIO file descriptor");
        exit(EXIT_FAILURE);
    }

    // Set all relays to OUTPUT mode
    for (i = 0; i < 4; i++) {
        if (gpiod_set_direction(gpio_fd, relays[i], GPIO_DIR_OUT) < 0) {
            perror("Failed to set GPIO direction");
            exit(EXIT_FAILURE);
        }
    }

    // Set up the interval timing using clock_gettime(CLOCK_MONOTONIC)
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Toggle the relays based on the prime number intervals
    for (i = 0; i < 4; i++) {
        if (i % 2 == 0) {
            // Toggle relay 2, 3, 5, and 7 seconds
            struct timespec interval;
            interval.tv_sec = i * 7;
            interval.tv_nsec = 0;
            if (gpiod_set_value(gpio_fd, relays[i], GPIO_DIR_OUT, interval.tv_sec) < 0) {
                perror("Failed to set GPIO value");
                exit(EXIT_FAILURE);
            }
            sleep(interval.tv_sec);
        } else {
            // Toggle relay 1, 4, 6, and 8 seconds
            struct timespec interval;
            interval.tv_sec = i * 5;
            interval.tv_nsec = 0;
            if (gpiod_set_value(gpio_fd, relays[i], GPIO_DIR_OUT, interval.tv_sec) < 0) {
                perror("Failed to set GPIO value");
                exit(EXIT_FAILURE);
            }
            sleep(interval.tv_sec);
        }
    }

    // Set all relays back to INPUT mode
    for (i = 0; i < 4; i++) {
        if (gpiod_set_direction(gpio_fd, relays[i], GPIO_DIR_IN) < 0) {
            perror("Failed to set GPIO direction");
            exit(EXIT_FAILURE);
        }
    }

    // Clean up the GPIO chip
    if (gpiod_release_fd(gpio_fd) < 0) {
        perror("Failed to release GPIO file descriptor");
        exit(EXIT_FAILURE);
    }

    // Clean up the relays
    for (i = 0; i < 4; i++) {
        gpio_close(relays[i]);
    }

    // Clean up the program
    printf("Program terminated.\n");

    return 0;
}

