#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    int bytes_written;
    int threshold = 50.0;
    float sensitivity = 131.0;
    int16_t buffer[100];
    int i, j, count = 0;
    int exit_flag = 0;

    // Initialize I2C bus
    if (gpio_init() < 0) {
        printf("Error: Failed to initialize I2C bus.\n");
        return 1;
    }

    if (pi_open_i2c_bus() < 0) {
        printf("Error: Failed to open I2C bus.\n");
        return 1;
    }

    // Wake up the sensor
    if (pi_write_reg(I2C_ADDR, 0x6B, 0x00) < 0) {
        printf("Error: Failed to wake up sensor.\n");
        return 1;
    }

    // Verify the device
    if (pi_read_reg(I2C_ADDR, 0x75) != I2C_ADDR) {
        printf("Error: Failed to verify sensor.\n");
        return 1;
    }

    // Read gyroscope data
    if (pi_read_reg(I2C_ADDR, GYRO_XOUT_H) & 0xFF) {
        printf("Error: Failed to read X-axis data.\n");
        return 1;
    }
    if (pi_read_reg(I2C_ADDR, GYRO_YOUT_H) & 0xFF) {
        printf("Error: Failed to read Y-axis data.\n");
        return 1;
    }
    if (pi_read_reg(I2C_ADDR, GYRO_ZOUT_H) & 0xFF) {
        printf("Error: Failed to read Z-axis data.\n");
        return 1;
    }

    // Log data to buffer
    for (i = 0; i < 100; i++) {
        buffer[i] = (pi_read_reg(I2C_ADDR, GYRO_XOUT_H) & 0xFF) +
                    (pi_read_reg(I2C_ADDR, GYRO_YOUT_H) & 0xFF) * sensitivity +
                    (pi_read_reg(I2C_ADDR, GYRO_ZOUT_H) & 0xFF) * sensitivity;
        if (buffer[i] > threshold) {
            printf("Angular velocity: %.2f degrees/second\n", buffer[i]);
            count++;
        }
    }

    // Trigger callback function
    if (count >= 100) {
        for (i = 0; i < 100; i++) {
            if (buffer[i] > threshold) {
                printf("Angular velocity: %.2f degrees/second\n", buffer[i]);
                break;
            }
        }
    }

    // Clean up resources
    for (i = 0; i < 100; i++) {
        pi_write_reg(I2C_ADDR, GYRO_XOUT_L + (i * 2), buffer[i]);
    }
    pi_close_i2c_bus();

    return 0;
}

