    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    // Open serial port
    if ((fd = serOpenPort("/dev/serial0", 9600, SER_8N1, &port)) < 0) {
        fprintf(stderr, "Error opening serial port\n");
        return 1;
    }

    // Send 9-byte command
    serWrite(fd, ser_cmd, CO2_CMD_LEN);
    serWrite(fd, &port.baud_base, 1);
    serWrite(fd, &port.parity, 1);
    serWrite(fd, &port.data_bits, 1);
    serWrite(fd, &port.stop_bits, 1);
    serWrite(fd, &port.flow_control, 0);

    // Wait for response
    while (1) {
        if (serDataAvailable(fd) == 0) {
            if (timeout_ms == 0) {
                fprintf(stderr, "Timeout waiting for response\n");
                break;
