        fprintf(stderr, "Error writing to serial port\n");
    }
    if (serWrite(fd, &port.stop_bits, 1) < 0) {
        fprintf(stderr, "Error writing to serial port\n");
    }
    if (serWrite(fd, &port.flow_control, 0) < 0) {
        fprintf(stderr, "Error writing to serial port\n");
    }

    // Close log files
    if (unlink(co2_log_file) == -1) {
        fprintf(stderr, "Error deleting log file\n");
    }
    if (unlink(co2_error_log_file) == -1) {
        fprintf(stderr, "Error deleting error log file\n");
    }

