#include <linux/i2c.h>

#define GPIO_RED 17
#define GPIO_GREEN 27
#define GPIO_BLUE 22

#define I2C_BUS_1 1
#define I2C_ADDR 0x23

#define RELAY_RED GPIO_RED
#define RELAY_GREEN GPIO_GREEN
#define RELAY_BLUE GPIO_BLUE

#define RELAY_THRESHOLDS {50, 150, 150}

#define RELAY_LOG_FILE "lighting_log.txt"
#define RELAY_LOG_PREFIX "Relay "

int main() {
    int i2c_fd, relays[3];
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    int relays_absent = 0;
    int i, j;

    // Initialize GPIO and I2C
    gpio_init();
    i2c_init();

    // Open I2C bus
    if ((i2c_fd = i2c_open(I2C_BUS_1)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Open relay files
    if ((relays[0] = open(RELAY_LOG_PREFIX "relay_red.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("Failed to open relay file");
        exit(EXIT_FAILURE);
    }
    if ((relays[1] = open(RELAY_LOG_PREFIX "relay_green.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("Failed to open relay file");
        exit(EXIT_FAILURE);
    }
    if ((relays[2] = open(RELAY_LOG_PREFIX "relay_blue.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("Failed to open relay file");
        exit(EXIT_FAILURE);
    }

    // Wait for the first I2C conversion
    struct i2c_msg msg = {
        .addr = I2C_ADDR,
        .flags = 0,
        .len = 2,
        .buf = &i2c_msgs[0].buf,
    };
    if (i2c_transfer(i2c_fd, &msg, 1) < 0) {
        perror("Failed to wait for I2C conversion");
        exit(EXIT_FAILURE);
    }

    // Initialize BH1750 sensor
    if (i2c_smbus_write_byte_data(i2c_fd, 0x10, 0x00) < 0) {
        perror("Failed to set BH1750 to continuous high-resolution mode");
        exit(EXIT_FAILURE);
    }

    // Wait at least 120 ms for the first conversion
    if (i2c_transfer(i2c_fd, &msg, 1) < 0) {
        perror("Failed to wait for I2C conversion");
        exit(EXIT_FAILURE);
    }

    // Read the 2-byte lux value
    if (i2c_transfer(i2c_fd, &msg, 1) < 0) {
        perror("Failed to read lux value");
        exit(EXIT_FAILURE);
    }

    // Compute lux = raw / 1.2
    int raw = i2c_msgs[0].buf[1] << 8 | i2c_msgs[0].buf[0];
    float lux = raw / 1.2;

    // Log the lux value and relay states
    if (write(relays[0], &lux, sizeof(lux)) < 0) {
        perror("Failed to write lux value to relay file");
        exit(EXIT_FAILURE);
    }
    if (write(relays[1], &lux, sizeof(lux)) < 0) {
        perror("Failed to write lux value to relay file");
        exit(EXIT_FAILURE);
    }
    if (write(relays[2], &lux, sizeof(lux)) < 0) {
        perror("Failed to write lux value to relay file");
        exit(EXIT_FAILURE);
    }

    // Check every I2C and file I/O call
    if (i2c_transfer(i2c_fd, &msg, 1) < 0) {
        perror("Failed to transfer data");
        exit(EXIT_FAILURE);
    }

    // Release GPIO and I2C file descriptor
    gpio_free();
    i2c_close(i2c_fd);

    // Close relay files
    if (close(relays[0]) < 0) {
        perror("Failed to close relay file");
        exit(EXIT_FAILURE);
    }
    if (close(relays[1]) < 0) {
        perror("Failed to close relay file");
        exit(EXIT_FAILURE);
    }
    if (close(relays[2]) < 0) {
        perror("Failed to close relay file");
        exit(EXIT_FAILURE);
    }

    // Log the timestamp, lux value, and relay states
    if (write(relays_absent, &relays_absent, sizeof(relays_absent)) < 0) {
        perror("Failed to write relay states to log file");
        exit(EXIT_FAILURE);
    }

    // Wait for 1 second
    sleep(1);

    // Log the timestamp, lux value, and relay states
    if (write(relays_absent, &relays_absent, sizeof(relays_absent)) < 0) {
        perror("Failed to write relay states to log file");
        exit(EXIT_FAILURE);
    }

    return 0;
}

