#include <sys/types.h>
#include <sys/stat.h>

#include <pigpio.h>

#define I2C_ADDR 0x68
#define PWM_CHIP_ID 2
#define PWM_CHIP_NAME "pwmchip2"

int main() {
    int i2c_fd, pwm_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct pigpio *gpio;
    struct i2c_msg i2c_msgs[2];
    struct i2c_rdwr_ioctl_data pwm_data;
    struct timeval start_time, end_time;
    char log_file_name[] = "solar_tracker.log";
    char log_file_path[128];

    // Initialize I2C and PWM
    gpio = pigpio_init();
    if (gpio == NULL) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpio_open(gpio, "/dev/pigpio") < 0) {
        fprintf(stderr, "Failed to open pigpio\n");
        return 1;
    }

    if (gpio_set_mode(gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for PWM\n");
        return 1;
    }

    if (gpio_set_dir(gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set direction for PWM\n");
        return 1;
    }

    if (gpio_set_value(gpio, 0) < 0) {
        fprintf(stderr, "Failed to set PWM to 0\n");
        return 1;
    }

    if (gpio_set_mode(gpio, PI_SERVO) < 0) {
        fprintf(stderr, "Failed to set mode for servo\n");
        return 1;
    }

    if (gpio_set_pwm_range(gpio, 100, 2000) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        return 1;
    }

    if (gpio_set_pwm(gpio, PWM_CHIP_NAME, PWM_CHIP_ID, 0) < 0) {
        fprintf(stderr, "Failed to set PWM\n");
        return 1;
    }

    // Open I2C
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return 1;
    }

    // Read sensor data
    if (ioctl(i2c_fd, I2C_RDWR, &i2c_msgs[0]) < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return 1;
    }

    // Log sensor data
    log_file_path[0] = '\0';
    snprintf(log_file_path, sizeof(log_file_path), "solar_tracker.log");
    FILE *log_file = fopen(log_file_path, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    fprintf(log_file, "Timestamp,Pitch,Roll,Servo\n");

    // Calculate pitch, roll, and servo values
    float pitch = atan2(i2c_msgs[0].wr_data[1], i2c_msgs[0].wr_data[0]);
    float roll = atan2(i2c_msgs[0].wr_data[3], i2c_msgs[0].wr_data[2]);
    float servo_value = atan2(i2c_msgs[1].wr_data[3], i2c_msgs[1].wr_data[2]);

    // Log sensor data
    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n",
            getctime(), pitch, roll, servo_value);

    // Calculate servo position
    float servo_position = (servo_value - PI_MIN) / (PI_MAX - PI_MIN) * 100;

    // Set servo position
    if (gpio_set_value(gpio, 1) < 0) {
        fprintf(stderr, "Failed to set servo to position\n");
        return 1;
    }

    if (gpio_set_pwm(gpio, PWM_CHIP_NAME, PWM_CHIP_ID, servo_position) < 0) {
        fprintf(stderr, "Failed to set servo position\n");
        return 1;
    }

    // Release resources
    gpio_close(gpio);
    pigpio_exit();

    return 0;
}

