#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define BUZZER_PULSE_LENGTH 10 // in microseconds

int main() {
    int err, gpio, triggerPin, echoPin, buzzerPin, delayPin;
    struct gpio *gpioHandle;
    struct timespec startTime, endTime;
    struct timespec startPulseTime, endPulseTime;
    int distance, frequency;

    // Initialize pigpio library
    if (gpioSetMode(23, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 23 as output\n");
        return 1;
    }
    gpioHandle = gpioOpen(1);
    if (gpioHandle == NULL) {
        fprintf(stderr, "Failed to open GPIO\n");
        return 1;
    }

    if (gpioSetMode(18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 18 as output\n");
        gpioClose(gpioHandle);
        return 1;
    }
    gpioHandle = gpioOpen(2);
    if (gpioHandle == NULL) {
        fprintf(stderr, "Failed to open GPIO\n");
        gpioClose(gpioHandle);
        return 1;
    }

    if (gpioSetMode(24, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 24 as input\n");
        gpioClose(gpioHandle);
        gpioClose(2);
        return 1;
    }

    triggerPin = gpioGetLine(23);
    echoPin = gpioGetLine(24);
    buzzerPin = gpioGetLine(18);

    delayPin = gpioGetLine(29);

    if (gpioSetLevel(triggerPin, 1) < 0) {
        fprintf(stderr, "Failed to set trigger pin high\n");
        gpioClose(2);
        gpioClose(gpioHandle);
        return 1;
    }

    if (gpioSetLevel(echoPin, 0) < 0) {
        fprintf(stderr, "Failed to set echo pin low\n");
        gpioClose(2);
        gpioClose(gpioHandle);
        return 1;
    }

    if (gpioSetLevel(buzzerPin, 1) < 0) {
        fprintf(stderr, "Failed to set buzzer pin high\n");
        gpioClose(2);
        gpioClose(3);
        gpioClose(gpioHandle);
        return 1;
    }

    if (gpioSetLevel(delayPin, 1) < 0) {
        fprintf(stderr, "Failed to set delay pin high\n");
        gpioClose(2);
        gpioClose(3);
        gpioClose(4);
        gpioClose(gpioHandle);
        return 1;
    }

    if (gpioSetLevel(delayPin, 0) < 0) {
        fprintf(stderr, "Failed to set delay pin low\n");
        gpioClose(2);
        gpioClose(3);
        gpioClose(4);
        gpioClose(gpioHandle);
        return 1;
    }

    // Set initial delay time
    startTime.tv_sec = 0;
    startTime.tv_nsec = 1000000;
    endTime.tv_sec = 0;
    endTime.tv_nsec = 1000000;

    // Main loop
    while (1) {
        // Read the distance from the HC-SR04 sensor
        err = pigpio_getDistance(echoPin, &distance);
        if (err < 0) {
            fprintf(stderr, "Failed to read distance from echo pin\n");
            continue;
        }

        // Map the distance to frequency
        frequency = (int) (200 + (distance / 2) * (2000 - 200) / distance);

        // Check if the distance is valid (2 cm to 30 cm)
        if (distance < 2 || distance > 30) {
            fprintf(stderr, "Invalid distance: %d cm\n", distance);
            continue;
        }

        // Generate the trigger pulse
        gpioDelay(BUZZER_PULSE_LENGTH);
        gpioSetLevel(triggerPin, 1);
        gpioDelay(BUZZER_PULSE_LENGTH);
        gpioSetLevel(triggerPin, 0);

        // Read the echo pulse
        err = pigpio_getDistance(echoPin, &endTime.tv_sec);
        if (err < 0) {
            fprintf(stderr, "Failed to read echo pulse\n");
            continue;
        }

        // Calculate pulse width
        endPulseTime.tv_sec = endTime.tv_sec;
        endPulseTime.tv_nsec = endTime.tv_nsec;
        microseconds_to_timeval(&endPulseTime, &startPulseTime);
        endPulseTime.tv_sec -= startPulseTime.tv_sec;
        endPulseTime.tv_nsec -= startPulseTime.tv_nsec;
        pulseWidth = (int) (endPulseTime.tv_sec * 1000000 + endPulseTime.tv_nsec / 1000);

        // Check if the pulse width is valid
        if (pulseWidth < 10 || pulseWidth > BUZZER_PULSE_LENGTH * 2) {
            fprintf(stderr, "Invalid pulse width: %d us\n", pulseWidth);
            continue;
        }

        // Generate the 10 microsecond trigger pulse
        gpioDelay(10);
        gpioSetLevel(triggerPin, 1);
        gpioDelay(10);
        gpioSetLevel(triggerPin, 0);

        // Check if the buzzer is playing
        gpioRead(buzzerPin, &buzzerState);
        if (buzzerState == 0) {
            // Silence the buzzer
            gpioSetLevel(buzzerPin, 1);
            gpioDelay(100);
            gpioSetLevel(buzzerPin, 0);
        }

        // Check if the main loop should exit
        if (millis() - startTime.tv_sec > 60) {
            break;
        }
    }

    // Clean up
    gpioClose(2);
    gpioClose(3);
    gpioClose(4);
    gpioClose(gpioHandle);

    return 0;
}

