#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <pigpio.h>

#define LED_RED 17
#define LED_GREEN 22
#define LED_BLUE 27

int main() {
    int fd;
    int gpio_num_red = LED_RED;
    int gpio_num_green = LED_GREEN;
    int gpio_num_blue = LED_BLUE;
    int proximity_value = 0;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    if (gpioSetBrightness(255) < 0) {
        fprintf(stderr, "Error: Failed to set LED brightness to maximum\n");
        return 1;
    }

    if (gpioSetMode(gpio_num_red, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to output mode\n", gpio_num_red);
        return 1;
    }

    if (gpioSetMode(gpio_num_green, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to output mode\n", gpio_num_green);
        return 1;
    }

    if (gpioSetMode(gpio_num_blue, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to output mode\n", gpio_num_blue);
        return 1;
    }

    // Simulate proximity value over time
    while (1) {
        proximity_value = (int)(0.5 + 0.5 * sin(proximity_value * M_PI / 0.5));
        proximity_value = (int)(proximity_value * 255);

        if (gpioSetPWM(gpio_num_red, 0, proximity_value) < 0) {
            fprintf(stderr, "Error: Failed to set PWM for GPIO %d\n", gpio_num_red);
            return 1;
        }

        if (gpioSetPWM(gpio_num_green, 0, proximity_value) < 0) {
            fprintf(stderr, "Error: Failed to set PWM for GPIO %d\n", gpio_num_green);
            return 1;
        }

        if (gpioSetPWM(gpio_num_blue, 0, proximity_value) < 0) {
            fprintf(stderr, "Error: Failed to set PWM for GPIO %d\n", gpio_num_blue);
            return 1;
        }

        gpioDelay(1);
    }

    // Cleanup
    gpioTerminate();

    return 0;
}

