#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#include <linux/i2c.h>
#include <linux/i2c-dev.h>

#include <linux/gpio.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x68
#define PWR_MGMT_1_REG 0x6B
#define GYRO_DATA_REG 0x43
#define GYRO_DATA_LEN 2

int main() {
    int i2c_fd, gpio_fd, log_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_request gpio_req;
    struct i2c_msg i2c_msgs[2];
    int bytes_written;
    int i;

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Open GPIO for I2C communication
    if ((gpio_fd = open("/dev/gpiochip0", O_RDWR)) < 0) {
        perror("Error opening GPIO for I2C communication");
        exit(EXIT_FAILURE);
    }

    // Wake up MPU-6050 gyroscope
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error writing to PWR_MGMT_1");
        exit(EXIT_FAILURE);
    }

    // Write 0x00 to PWR_MGMT_1
    if (ioctl(i2c_fd, I2C_WR_MESSAGE_PRELIM, &gpio_req, sizeof(gpio_req)) < 0) {
        perror("Error writing to PWR_MGMT_1");
        exit(EXIT_FAILURE);
