    quit = 1;
}

int main(int argc, char *argv[]) {
    int fd, line;
    struct gpiod_event event;
    struct timespec ts;
    char filename[32];
    char line_state;
    int count = 0;
    int threshold = 3;
    int last_timestamp = 0;
    int last_event_type = 0;
    int events[5];
    int i;

    if (argc > 1) {
        if (sscanf(argv[1], "%d", &timeout_ms) != 1) {
            fprintf(stderr, "Invalid timeout value. Defaulting to 1000 ms.\n");
            timeout_ms = 1000;
        }
    } else {
        timeout_ms = 1000;
    }

    fd = gpiod_get_fd(VIBRATION_SENSOR_LINE);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO line for reading: %s\n", gpiod_error_name(errno));
        return 1;
    }

    line = gpiod_request_line(fd, VIBRATION_SENSOR_LINE);
    if (line < 0) {
        fprintf(stderr, "Failed to request line for reading: %s\n", gpiod_error_name(errno));
        gpiod_release_line(fd);
        return 1;
    }

    snprintf(filename, sizeof(filename), "/vibration_events.log");
    fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_release_line(line);
        gpiod_release_fd(fd);
        return 1;
    }

    while (!quit) {
        if (timeout_ms > 0) {
            if (nanosleep(&ts, NULL) != 0) {
                fprintf(stderr, "Failed to sleep for specified timeout: %s\n", strerror(errno));
                continue;
            }
        }

        line_state = gpiod_get_line_state(fd, VIBRATION_SENSOR_LINE);
        if (line_state == GPIO_LINE_STATE_LOW) {
            events[count] = 1;
            count++;
        } else {
            events[count] = 0;
            count--;
        }

        if (count >= threshold) {
            if (last_event_type == 0) {
                last_timestamp = ts.tv_sec;
                last_event_type = 1;
            } else if (last_event_type == 1 && ts.tv_sec - last_timestamp >= threshold) {
                if (events[0] == 1) {
                    printf("EARTHQUAKE ALERT: %s\n", ts.tv_sec == last_timestamp ? "NOW" : "AT %s\n", asctime(localtime(&ts.tv_sec)));
                }
                last_timestamp = ts.tv_sec;
                last_event_type = 0;
            }
        }

        if (write(fd, &events[0], sizeof(events[0]) > 0 ? sizeof(events[0]) : 0) < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            continue;
        }

        if (close(fd) < 0) {
            fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
            return 1;
        }

        if (close(fd) < 0) {
            fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
            return 1;
        }

        if (quit) {
            break;
        }
    }

    gpiod_release_line(line);
    gpiod_release_fd(fd);

    return 0;
}

