#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_ADDR 0x1E
#define SDA_PIN 3
#define SCL_PIN 5

int main() {
    int i2c_fd, csv_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    struct i2c_rdwr_ioctl_data csv_data;
    char header[] = "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n";
    char *log_file = "mag_log.csv";

    // Initialize I2C communication
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        perror("Error opening I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open CSV file for appending
    if ((csv_fd = open(log_file, O_WRONLY | O_CREAT | O_APPEND, 0644)) == -1) {
        perror("Error opening CSV file");
        close(i2c_fd);
        return 1;
    }

    // Configure continuous-conversion mode
    if (ioctl(i2c_fd, I2C_RDWR, 0x00) == -1) {
        perror("Error configuring I2C read/write mode");
        close(csv_fd);
        close(i2c_fd);
        return 1;
    }

    // Set output data rate to 15 Hz
    if (ioctl(i2c_fd, I2C_RDWR, 0x14) == -1) {
        perror("Error configuring I2C data rate");
        close(csv_fd);
        close(i2c_fd);
        return 1;
    }

    // Initialize magnetometer
    if (ioctl(i2c_fd, I2C_RDWR, I2C_ADDR) == -1) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        close(csv_fd);
        return 1;
    }

    // Perform hard-iron calibration
    if (ioctl(i2c_fd, I2C_RDWR, 0x03) == -1) {
        perror("Error performing hard-iron calibration");
        close(i2c_fd);
        close(csv_fd);
        return 1;
    }

    // Read data from magnetometer
    if (ioctl(i2c_fd, I2C_RDWR, 0x03) == -1) {
        perror("Error reading data from magnetometer");
        close(i2c_fd);
        close(csv_fd);
        return 1;
    }

    // Calculate and log data
    for (;;) {
        // Read data from magnetometer
        if (ioctl(i2c_fd, I2C_RDWR, 0x03) == -1) {
            perror("Error reading data from magnetometer");
            close(i2c_fd);
            close(csv_fd);
            return 1;
        }

        // Read data registers
        if (ioctl(i2c_fd, I2C_RDWR, 0x03) == -1) {
            perror("Error reading data registers");
            close(i2c_fd);
            close(csv_fd);
            return 1;
        }

        // Calculate X, Y, and Z values
        float x = (float) i2c_msgs[0].msg[0] << 8 | i2c_msgs[0].msg[1];
        float y = (float) i2c_msgs[1].msg[0] << 8 | i2c_msgs[1].msg[1];
        float z = (float) i2c_msgs[2].msg[0] << 8 | i2c_msgs[2].msg[1];

        // Apply hard-iron calibration offsets
        x_offset = 10;
        y_offset = -5;
        z_offset = 20;

        // Calculate calibrated X, Y, and Z values
        float calibrated_x = x + x_offset;
        float calibrated_y = y + y_offset;
        float calibrated_z = z + z_offset;

        // Calculate heading
        float heading = atan2f(calibrated_y, calibrated_x) * 180 / M_PI;

        // Append data to CSV file
        if (ioctl(csv_fd, I2C_RDWR, 0x00) == -1) {
            perror("Error writing to CSV file");
            close(i2c_fd);
            close(csv_fd);
            return 1;
        }

        if (printf("%s,%f,%f,%f,%d\n", header, calibrated_x, calibrated_y, calibrated_z, heading) == -1) {
            perror("Error writing to CSV file");
            close(i2c_fd);
            close(csv_fd);
            return 1;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C file descriptor and CSV file
    close(i2c_fd);
    close(csv_fd);

    return 0;
}

