    char json_buffer[256];
    char *timestamp = malloc(strlen(ctime(&(struct timeval){.tv_sec = time(NULL)})));
    snprintf(timestamp, 256, "%s", ctime(&(struct timeval){.tv_sec = time(NULL)}));

    if (state == 1) {
        snprintf(json_buffer, 256, "{\"timestamp\":\"%s\", \"relay_state\":\"ON\"}", timestamp);
    } else {
