        fprintf(stderr, "Error initialising pigpio: %s\n", strerror(ret));
        exit(EXIT_FAILURE);
    }

    gpioSetMode(RELAY_PIN, PI_OUT);
    gpioSetISRFunc(RELAY_PIN, relay_callback, NULL);

    gpioSetState(RELAY_PIN, 1);

