    if (relay_fd < 0) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    gpioSetState(TOUCH_PIN, 1);

    struct itimersoft *itimer;
    itimer = malloc(sizeof(struct itimersoft));
    if (getitimer(ITIMER_REAL, itimer) == -1) {
        fprintf(stderr, "Error getting timer: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    itimer->it_value.tv_sec = 200;
    itimer->it_interval.tv_sec = itimer->it_value.tv_sec;

    if (setitimer(ITIMER_REAL, itimer, NULL) == -1) {
        fprintf(stderr, "Error setting timer: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    while (1) {
        gpioSetState(RELAY_PIN, 1);
        gpioDelay(100);
        gpioSetState(RELAY_PIN, 0);
        gpioDelay(100);

        gpioSetState(TOUCH_PIN, 1);
        gpioDelay(100);
        gpioSetState(TOUCH_PIN, 0);

        gpioDelay(100);
    }

    gpioTerminate();

    return 0;
}

