#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <time.h>

#define GPIO_FILE "/dev/gpiochip0"
#define RELAY_GPIO_BASE 17
#define RELAY_GPIO_COUNT 4
#define MOISTURE_THRESHOLD 30

int main() {
    int fd;
    struct gpiod_chip_info chip_info;
    struct gpiod_line_config line_config;
    struct timespec start_time, end_time;
    int relay_num, moisture_level;
    char log_file[128];

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open gpiochip
    if (gpiod_open(GPIO_FILE, &fd) < 0) {
        fprintf(stderr, "Failed to open gpiochip\n");
        gpiod_exit();
        return 1;
    }

    // Request the four lines as outputs with inactive drive
    if (gpiod_request_lines(fd, RELAY_GPIO_BASE, RELAY_GPIO_COUNT, &chip_info, &line_config) < 0) {
        fprintf(stderr, "Failed to request gpio lines\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Simulate soil moisture
    srand(time(NULL));
    moisture_level = rand() % (100 - MOISTURE_THRESHOLD + 1) + MOISTURE_THRESHOLD;

    // Log every activation
    sprintf(log_file, "log_%d.txt", moisture_level);
    FILE *log_file_fp = fopen(log_file, "a");
    if (!log_file_fp) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Log activation
    fprintf(log_file_fp, "%.2f: Relay %d activated\n", (double)time(NULL) / 1000000.0, relay_num);

    // Activate relays
    for (relay_num = 0; relay_num < RELAY_GPIO_COUNT; relay_num++) {
        if (moisture_level < MOISTURE_THRESHOLD) {
            // Activate relay for 5 seconds
            if (gpiod_set_line_config(fd, RELAY_GPIO_BASE + relay_num, line_config) < 0) {
                fprintf(stderr, "Failed to set relay configuration\n");
                return 1;
            }
            if (gpiod_set_line_value(fd, RELAY_GPIO_BASE + relay_num, 1) < 0) {
                fprintf(stderr, "Failed to set relay value\n");
                return 1;
            }
            usleep(5000 * 1000); // 5 seconds in microseconds
            gpiod_set_line_value(fd, RELAY_GPIO_BASE + relay_num, 0);
            usleep(1000 * 1000); // 1 second in microseconds
        }
    }

    // Deactivate relays
    for (relay_num = 0; relay_num < RELAY_GPIO_COUNT; relay_num++) {
        gpiod_set_line_value(fd, RELAY_GPIO_BASE + relay_num, 1);
        usleep(1000 * 1000); // 1 second in microseconds
    }

    // Close log file
    fclose(log_file_fp);

    // Close gpiochip
    if (gpiod_close(fd) < 0) {
        fprintf(stderr, "Failed to close gpiochip\n");
        gpiod_exit();
        return 1;
    }

    // Release resources
    gpiod_exit();

    return 0;
}

