#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x68
#define GYRO_XOUT_H 0x43
#define PWR_MGMT_1 0x6B

int main() {
    int rc;
    int fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    struct i2c_rdwr_ioctl_data i2c_msgs_gyro[2];
    struct i2c_rdwr_ioctl_data i2c_msgs_log[2];
    struct timespec ts;
    char timestamp[32];
    char log_data[80];
    char log_header[16] = "timestamp,x,y,z\n";
    int i, j, k;
    float x, y, z;
    float sensitivity_factor = 131.0;

    // Initialize I2C bus
    if (gpio_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize I2C bus.\n");
        return 1;
    }

    if (pi_open_i2c_bus() < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus.\n");
        return 1;
    }

    // Wake up the MPU-6050 gyroscope
    if (pi_write_i2c_reg16(I2C_ADDR, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to wake up MPU-6050 gyroscope.\n");
        return 1;
    }

    // Read 6 bytes of gyroscope data
    if (pi_read_i2c_reg16(I2C_ADDR, GYRO_XOUT_H, i2c_msgs_gyro, 2) < 0) {
        fprintf(stderr, "Error: Failed to read gyroscope data.\n");
        return 1;
    }

    // Convert raw 16-bit values to degrees/second
    for (i = 0; i < 6; i++) {
        x += (i2c_msgs_gyro[i].buf[0] << 8) | i2c_msgs_gyro[i].buf[1];
        y += (i2c_msgs_gyro[i].buf[2] << 8) | i2c_msgs_gyro[i].buf[3];
        z += (i2c_msgs_gyro[i].buf[4] << 8) | i2c_msgs_gyro[i].buf[5];
    }

    // Log the data to gyro_log.txt
    if (pi_open_file_write(I2C_ADDR, "gyro_log.txt", &fd) < 0) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        return 1;
    }

    for (i = 0; i < 6; i++) {
        sprintf(timestamp, "%s%d", ts.tv_sec, ts.tv_nsec / 1000000);
        sprintf(log_data, "%s,%f,%f,%f\n", timestamp, x, y, z);
        if (pi_write_file(fd, log_data, strlen(log_data)) < 0) {
            fprintf(stderr, "Error: Failed to write log data to file.\n");
            return 1;
        }
    }

    // Close file descriptors
    if (pi_close_file(fd) < 0) {
        fprintf(stderr, "Error: Failed to close log file.\n");
        return 1;
    }

    // Release I2C bus
    if (pi_close_i2c_bus() < 0) {
        fprintf(stderr, "Error: Failed to close I2C bus.\n");
        return 1;
    }

    // Release GPIO resources
    gpio_exit();

    return 0;
}

