#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <linux/gpio.h>
#include <linux/delay.h>
#include <linux/time.h>

#define TRIG_GPIO 17
#define ECHO_GPIO 18
#define TRIG_GPIO_NAME "gpio17"
#define ECHO_GPIO_NAME "gpio18"
#define TRIG_GPIO_FILE "/dev/gpio"
#define ECHO_GPIO_FILE "/dev/gpio"
#define TRIG_GPIO_BIDIRECTIONAL GPIO_MODE_OUTPUT
#define ECHO_GPIO_BIDIRECTIONAL GPIO_MODE_INPUT
#define TRIG_GPIO_PULLUP GPIO_PULL_UP
#define ECHO_GPIO_PULLUP GPIO_PULL_UP
#define TRIG_GPIO_SPEED GPIO_SPEED_HZ_10
#define ECHO_GPIO_SPEED GPIO_SPEED_HZ_10
#define TRIG_TIMEOUT_US 50
#define ECHO_TIMEOUT_US 100
#define TRIG_MIN_GUARD_US 10
#define ECHO_MIN_GUARD_US 10
#define TRIG_MIN_DISTANCE_CM 0.1715

int main() {
    int trig_fd, echo_fd;
    struct i2c_msg i2c_msgs[2];
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_desc *gpio_desc;
    struct gpio_request gpio_req;
    struct gpio_event gpio_event;
    int ret;
    int distance_cm = 0;
    int log_fd;
    int log_file_open_result;
    int log_file_write_result;
    int log_file_close_result;
    int error_log_write_result;
    int error_log_close_result;
    int guard_us;
    int timeout_us;
    int pulse_width_us;
    int pulse_width_cm;
    int pulse_width_ratio;
    int pulse_width_ratio_cm;
    int pulse_width_ratio_cm_error;

    // Initialize GPIOs
    gpio_desc = gpio_request_by_name(TRIG_GPIO_NAME);
    gpio_req.gpio_request_type = GPIO_REQUEST_TYPE_OUTPUT;
    gpio_req.gpio_request_line = TRIG_GPIO;
    gpio_req.gpio_direction = TRIG_GPIO_BIDIRECTIONAL;
    gpio_req.gpio_value = 0;
    ret = gpio_request_by_name(TRIG_GPIO, &gpio_req);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO %s\n", TRIG_GPIO_NAME);
        return 1;
    }

    gpio_desc = gpio_request_by_name(ECHO_GPIO_NAME);
    gpio_req.gpio_request_type = GPIO_REQUEST_TYPE_INPUT;
    gpio_req.gpio_request_line = ECHO_GPIO;
    gpio_req.gpio_direction = ECHO_GPIO_BIDIRECTIONAL;
    ret = gpio_request_by_name(ECHO_GPIO, &gpio_req);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO %s\n", ECHO_GPIO_NAME);
        gpio_release(gpio_desc);
        return 1;
    }

    // Open log file
    log_file_open_result = open("distance_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_file_open_result == -1) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Open log file for appending
    log_file_close_result = open("distance_log.txt", O_APPEND | O_CREAT | O_TRUNC, 0644);
    if (log_file_close_result == -1) {
        fprintf(stderr, "Failed to open log file for appending\n");
        close(log_file_open_result);
        return 1;
    }

    // Log initialization
    log_file_write_result = write(log_file_open_result, "-1\n", 5);
    if (log_file_write_result == -1) {
        fprintf(stderr, "Failed to log initialization\n");
        close(log_file_open_result);
        close(log_file_close_result);
        return 1;
    }

    // Set up I2C communication
    i2c_msgs[0].addr = 0x1A;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 2;
    i2c_msgs[0].buf = (void *)&i2c_data;

    i2c_msgs[1].addr = 0x1B;
    i2c_msgs[1].flags = 0;
    i2c_msgs[1].len = 2;
    i2c_msgs[1].buf = (void *)&i2c_data;

    i2c_data.cmd = I2C_SLAVE_ADDRESS;
    i2c_data.data = 0;

    ret = i2c_transfer(i2c_fd, i2c_msgs, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to set up I2C communication\n");
        close(log_file_open_result);
        close(log_file_close_result);
        return 1;
    }

    // Set trigger pulse
    ret = gpio_request_by_name(TRIG_GPIO, &gpio_req);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO %s\n", TRIG_GPIO_NAME);
        close(log_file_open_result);
        close(log_file_close_result);
        return 1;
    }

    gpio_req.gpio_request_type = GPIO_REQUEST_TYPE_OUTPUT;
    gpio_req.gpio_request_line = TRIG_GPIO;
    gpio_req.gpio_direction = TRIG_GPIO_BIDIRECTIONAL;
    gpio_req.gpio_value = 1;
    ret = gpio_request_by_name(TRIG_GPIO, &gpio_req);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO %s\n", TRIG_GPIO_NAME);
        gpio_release(gpio_desc);
        close(log_file_open_result);
        close(log_file_close_result);
        return 1;
    }

    // Set echo pulse
    gpio_req.gpio_request_type = GPIO_REQUEST_TYPE_OUTPUT;
    gpio_req.gpio_request_line = ECHO_GPIO;
    gpio_req.gpio_direction = ECHO_GPIO_BIDIRECTIONAL;
    gpio_req.gpio_value = 0;
    ret = gpio_request_by_name(ECHO_GPIO, &gpio_req);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO %s\n", ECHO_GPIO_NAME);
        gpio_release(gpio_desc);
        close(log_file_open_result);
        close(log_file_close_result);
        return 1;
    }

    // Set pulse width
    ret = gpio_request_by_name(TRIG_GPIO, &gpio_req);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO %s\n", TRIG_GPIO_NAME);
        gpio_release(gpio_desc);
        close(log_file_open_result);
        close(log_file_close_result);
        return 1;
    }

    gpio_req.gpio_request_type = GPIO_REQUEST_TYPE_OUTPUT;
    gpio_req.gpio_request_line = ECHO_GPIO;
    gpio_req.gpio_direction = ECHO_GPIO_BIDIRECTIONAL;
    gpio_req.gpio_value = 1;
    ret = gpio_request_by_name(ECHO_GPIO, &gpio_req);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO %s\n", ECHO_GPIO_NAME);
        gpio_release(gpio_desc);
        close(log_file_open_result);
        close(log_file_close_result);
        return 1;
    }

    // Wait for rising edge
    timeout_us = TRIG_TIMEOUT_US;
    ret = usec_delay_ms(timeout_us);
    if (ret) {
        fprintf(stderr, "Failed to wait for rising edge\n");
        gpio_release(gpio_desc);
        close(log_file_open_result);
        close(log_file_close_result);
        return 1;
    }

    // Wait for falling edge
    timeout_us = TRIG_TIMEOUT_US;
    ret = usec_delay_ms(timeout_us);
    if (ret) {
        fprintf(stderr, "Failed to wait for falling edge\n");
        gpio_release(gpio_desc);
        close(log_file_open_result);
        close(log_file_close_result);
        return 1;
    }

    // Measure pulse width
    timeout_us = TRIG_TIMEOUT_US;
    ret = usec_delay_ms(timeout_us);
    if (ret) {
        fprintf(stderr, "Failed to measure pulse width\n");
        gpio_release(gpio_desc);
        close(log_file_open_result);
        close(log_file_close_result);
        return 1;
    }

    pulse_width_us = (i2c_msgs[0].buf->data >> 1) * 2;
    pulse_width_cm = pulse_width_us / 344.0;

    // Convert pulse width to distance
    distance_cm = pulse_width_cm * 0.01715;

    // Log distance
    log_file_write_result = write(log_file_open_result, &distance_cm, sizeof(distance_cm));
    if (log_file_write_result == -1) {
        fprintf(stderr, "Failed to log distance\n");
        close(log_file_open_result);
        close(log_file_close_result);
        return 1;
    }

    log_file_write_result = write(log_file_open_result, "-1\n", 5);
    if (log_file_write_result == -1) {
        fprintf(stderr, "Failed to log distance\n");
        close(log_file_open_result);
        close(log_file_close_result);
        return 1;
    }

    // Release resources
    gpio_release(gpio_desc);
    close(log_file_open_result);
    close(log_file_close_result);

    return 0;
}

