        close(log_file_open_result);
        close(log_file_close_result);
        return 1;
    }

    gpio_req.gpio_request_type = GPIO_REQUEST_TYPE_OUTPUT;
    gpio_req.gpio_request_line = ECHO_GPIO;
    gpio_req.gpio_direction = ECHO_GPIO_BIDIRECTIONAL;
    gpio_req.gpio_value = 1;
    ret = gpio_request_by_name(ECHO_GPIO, &gpio_req);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO %s\n", ECHO_GPIO_NAME);
        gpio_release(gpio_desc);
        close(log_file_open_result);
        close(log_file_close_result);
        return 1;
    }

    // Wait for rising edge
    timeout_us = TRIG_TIMEOUT_US;
    ret = usec_delay_ms(timeout_us);
    if (ret) {
        fprintf(stderr, "Failed to wait for rising edge\n");
        gpio_release(gpio_desc);
        close(log_file_open_result);
        close(log_file_close_result);
        return 1;
    }

    // Wait for falling edge
    timeout_us = TRIG_TIMEOUT_US;
    ret = usec_delay_ms(timeout_us);
    if (ret) {
        fprintf(stderr, "Failed to wait for falling edge\n");
        gpio_release(gpio_desc);
        close(log_file_open_result);
        close(log_file_close_result);
        return 1;
    }

    // Measure pulse width
    timeout_us = TRIG_TIMEOUT_US;
    ret = usec_delay_ms(timeout_us);
    if (ret) {
        fprintf(stderr, "Failed to measure pulse width\n");
        gpio_release(gpio_desc);
        close(log_file_open_result);
        close(log_file_close_result);
        return 1;
    }

    pulse_width_us = (i2c_msgs[0].buf->data >> 1) * 2;
    pulse_width_cm = pulse_width_us / 344.0;

    // Convert pulse width to distance
    distance_cm = pulse_width_cm * 0.01715;

    // Log distance
    log_file_write_result = write(log_file_open_result, &distance_cm, sizeof(distance_cm));
    if (log_file_write_result == -1) {
        fprintf(stderr, "Failed to log distance\n");
        close(log_file_open_result);
        close(log_file_close_result);
        return 1;
    }

    log_file_write_result = write(log_file_open_result, "-1\n", 5);
    if (log_file_write_result == -1) {
        fprintf(stderr, "Failed to log distance\n");
        close(log_file_open_result);
        close(log_file_close_result);
        return 1;
    }

    // Release resources
    gpio_release(gpio_desc);
    close(log_file_open_result);
    close(log_file_close_result);

    return 0;
}
