#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x68

int main() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    int ret;

    // Initialize i2c_fd
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) == -1) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Wake up the sensor from sleep
    if (ioctl(i2c_fd, I2C_SLEEP, 0) == -1) {
        perror("Error waking up sensor");
        exit(EXIT_FAILURE);
    }

    // Set gyroscope full-scale range to ±250 dps
    if (ioctl(i2c_fd, I2C_SET_GAIN, 0x1B) == -1) {
        perror("Error setting gyroscope gain");
        exit(EXIT_FAILURE);
    }

    // Read 6 bytes of gyroscope data
    if (ioctl(i2c_fd, I2C_RDWR, I2C_ADDR) == -1) {
        perror("Error reading I2C device");
        exit(EXIT_FAILURE);
    }

    // Read data from MPU-6050
    i2c_msgs[0].addr = I2C_ADDR;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 6;
    i2c_msgs[0].buf = (void *)&i2c_data.data;

    i2c_msgs[1].addr = I2C_ADDR;
    i2c_msgs[1].flags = I2C_RECV_FLAG;
    i2c_msgs[1].len = 6;
    i2c_msgs[1].buf = (void *)&i2c_data.data;

    if (ioctl(i2c_fd, I2C_RDWR, I2C_ADDR) == -1) {
        perror("Error reading I2C device");
        exit(EXIT_FAILURE);
    }

    // Convert raw 16-bit big-endian values to degrees/second
    for (int i = 0; i < 6; i++) {
        int raw_data = i2c_msgs[1].buf[i];
        int degrees_per_second = (raw_data >> 4) * 131.0;
        printf("x: %d, y: %d, z: %d\n", degrees_per_second, degrees_per_second, degrees_per_second);
    }

    // Close the i2c_fd
    if (close(i2c_fd) == -1) {
        perror("Error closing I2C device");
        exit(EXIT_FAILURE);
    }

    return 0;
}

