#define RELAY_PIN_COUNT (sizeof(RELAY_PIN_NAMES) / sizeof(RELAY_PIN_NAMES[0]))

int main() {
    int chip_fd;
    struct gpiod_chip_info chip_info;
    struct gpiod_line_config line_config;
    struct timespec start_time;
    char watering_log_filename[] = "watering_log.txt";
    FILE *watering_log_file;
    int i, relay_pin_count = RELAY_PIN_COUNT;

    // Open the gpiochip0
    if ((chip_fd = open(GPIO_FILE, O_RDWR)) == -1) {
        perror("Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    // Request all four lines as outputs with active-low semantics
    if (ioctl(chip_fd, GPIGPIO_CHIP_GET_LINE_CONFIG, &line_config) == -1) {
        perror("Failed to request lines for output");
        exit(EXIT_FAILURE);
    }
    line_config.line_config.direction = GPIGPIO_DIRECTION_OUTPUT;
    line_config.line_config.active_low = 1;

    if (ioctl(chip_fd, GPIGPIO_CHIP_SET_LINE_CONFIG, &line_config) == -1) {
        perror("Failed to set line configuration");
        exit(EXIT_FAILURE);
    }

    // Set all lines HIGH (inactive) at startup
    for (i = 0; i < relay_pin_count; i++) {
        if (ioctl(chip_fd, GPIGPIO_CHIP_GET_LINE_BY_NAME, RELAY_PIN_NAMES[i]) == -1) {
            perror("Failed to get line number");
            exit(EXIT_FAILURE);
        }
        if (ioctl(chip_fd, GPIGPIO_CHIP_SET_LINE_LEVEL, RELAY_PIN_NAMES[i], GPIO_LEVEL_HIGH) == -1) {
            perror("Failed to set line level");
            exit(EXIT_FAILURE);
        }
    }

    // Simulate an automated plant watering system
    while (1) {
        // Get current time
        gettimeofday(&start_time, NULL);

        // Simulate watering cycle
        printf("Watering cycle started at %s\n", ctime(&start_time.tv_sec));

        // Wait for 86400 seconds (24 hours)
        sleep(86400);
    }

    // Close the gpiochip0
    close(chip_fd);

    return 0;
}

