#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define RELAY_GPIO_17 17
#define RELAY_GPIO_18 18
#define RELAY_GPIO_27 27
#define RELAY_GPIO_22 22

#define RELAY_PWM_FREQ 1000
#define RELAY_DUTY_CYCLE_MIN 0
#define RELAY_DUTY_CYCLE_MAX 255

#define LOG_FILE "smart_lighting.log"

int main() {
    int ret;
    int relays[4] = {RELAY_GPIO_17, RELAY_GPIO_18, RELAY_GPIO_27, RELAY_GPIO_22};
    int i;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (gpioSetMode(relays, 4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for relays\n");
        return 1;
    }

    for (i = 0; i < 4; i++) {
        if (gpioSetPWM(relays[i], RELAY_PWM_FREQ, RELAY_DUTY_CYCLE_MIN, RELAY_DUTY_CYCLE_MAX) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for relay %d\n", i + 1);
            return 1;
        }
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    struct tm now = {0};
    time_t t = time(NULL);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &now);

    fprintf(log_file, "Sunrise effect started at %s\n", timestamp);

    for (i = 0; i < 60; i++) {
        for (int j = 0; j < 4; j++) {
            gpioWrite(relays[j], (i * 255) / 60);
            usleep(1000);
        }

        for (i = 0; i < 4; i++) {
            gpioWrite(relays[i], 0);
            gpioDelay(1000);
        }

        fprintf(log_file, "Sunrise effect ended at %s\n", timestamp);
        fflush(log_file);

        sleep(1);
    }

    gpioTerminate();

    fclose(log_file);
    return 0;
}

