};

int i2c_init(struct i2c_data *i2c_data) {
    int ret;

    ret = pigpio_init();
    if (ret != 0) {
        printf("Error initializing pigpio: %d\n", ret);
        return -1;
    }

    ret = pigpio_set_mode(GPIO_OUTPUT_DIGITAL, GPIO_OUTPUT_LEVEL_HIGH);
    if (ret != 0) {
        printf("Error setting GPIO17 to high: %d\n", ret);
        return -1;
