void i2c_read_data(struct i2c_data *i2c_data) {
    int ret;
    uint8_t data[2];

    ret = pigpio_i2c_read(i2c_data->i2c_fd, MPU_6050_WHO_AM_I_REG, data, 2);
    if (ret != 2) {
        printf("Error reading MPU-6050 WHO_AM_I register: %d\n", ret);
        return;
    }

    if (memcmp(data, MPU_6050_WHO_AM_I_DEFAULT, 2) != 0) {
        printf("Error: MPU-6050 WHO_AM_I register does not read 0x68\n");
        return;
    }
}

void i2c_write_data(struct i2c_data *i2c_data) {
    int ret;
    uint8_t data[2];

    data[0] = 0x00;
    data[1] = 0x00;

    ret = pigpio_i2c_write(i2c_data->i2c_fd, MPU_6050_PWR_MGMT_1_REG, data, 2);
    if (ret != 2) {
        printf("Error writing PWR_MGMT_1 register: %d\n", ret);
        return;
    }

    data[0] = 0x07;
    data[1] = 0x00;

    ret = pigpio_i2c_write(i2c_data->i2c_fd, MPU_6050_SMPLRT_DIV_REG, data, 2);
    if (ret != 2) {
        printf("Error writing SMPLRT_DIV register: %d\n", ret);
        return;
    }

    data[0] = 0x00;
    data[1] = 0x7F;

    ret = pigpio_i2c_write(i2c_data->i2c_fd, MPU_6050_GYRO_CONFIG_REG, data, 2);
    if (ret != 2) {
        printf("Error writing GYRO_CONFIG register: %d\n", ret);
        return;
    }

    data[0] = 0x1B;
    data[1] = 0x00;

    ret = pigpio_i2c_write(i2c_data->i2c_fd, MPU_6050_GYRO_XOUT_H_REG, data, 2);
    if (ret != 2) {
        printf("Error writing GYRO_XOUT_H register: %d\n", ret);
        return;
    }

