#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define I2C_DEVICE_PATH "/dev/i2c-1"
#define I2C_BUS_NUM 1
#define I2C_ADDR 0x5A

#define LED_GPIO 17

int main() {
    int i2c_fd, log_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    unsigned char ambient_light, proximity;
    struct timespec start_time, end_time;
    char log_file_path[128] = "biometric_log.txt";

    // Initialize I2C file descriptor
    if ((i2c_fd = open(I2C_DEVICE_PATH, O_RDWR | O_NONBLOCK)) == -1) {
        perror("Error opening I2C device");
        exit(EXIT_FAILURE);
    }

    // Open log file
    if ((log_fd = open(log_file_path, O_APPEND | O_CREAT | O_TRUNC, 0644)) == -1) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    // Set GPIO17 high to simulate presence-detected LED
    gpio_set_level(LED_GPIO, 1);

    // Set up I2C communication
    i2c_msgs[0].addr = I2C_ADDR;
    i2c_msgs[0].flags = 0;
    i2c_msgs[1].addr = I2C_ADDR;
    i2c_msgs[1].flags = I2C_M_RD;

    // Set up I2C communication parameters
    i2c_data.msgs = i2c_msgs;
    i2c_data.nmsgs = 2;
    i2c_data.timeout_ms = 10;
    i2c_data.retries = 3;

    // Set up GPIO17
    gpio_set_direction(LED_GPIO, GPIO_OUT);

    // Set up SIGINT/SIGTERM signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Start I2C communication loop
    while (1) {
        // Read ambient light value
        if (ioctl(i2c_fd, I2C_RDWR, &i2c_msgs[0].buf) == -1) {
            perror("Error reading ambient light value");
            continue;
        }
        ambient_light = i2c_msgs[0].buf[0];

        // Read proximity value
        if (ioctl(i2c_fd, I2C_RDWR, &i2c_msgs[1].buf) == -1) {
            perror("Error reading proximity value");
            continue;
        }
        proximity = i2c_msgs[1].buf[0];

        // Log the readings
        log_time();
        printf("%.2f,AmbientLight:%.2X,Proximity:%.2X\n", get_time(), ambient_light, proximity);

        // Check if proximity value exceeds 100
        if (proximity > 100) {
            gpio_set_level(LED_GPIO, 1);
        } else {
            gpio_set_level(LED_GPIO, 0);
        }

        // Wait for next reading
        nanosleep(&start_time, &end_time);
    }

    // Clean up
    close(i2c_fd);
    close(log_fd);
    gpio_set_direction(LED_GPIO, GPIO_IN);
    return 0;
}

// SIGINT/SIGTERM signal handlers
void sigint_handler(int signum) {
    printf("Received SIGINT/SIGTERM signal, cleaning up...\n");
    close(i2c_fd);
    close(log_fd);
    gpio_set_level(LED_GPIO, 0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM signal, cleaning up...\n");
    close(i2c_fd);
    close(log_fd);
    gpio_set_direction(LED_GPIO, GPIO_IN);
}

// Helper function to log the current time
void log_time() {
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);
    printf("%.2f, ", current_time.tv_sec);
}

