#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <string.h>
#include <signal.h>
#include <sys/time.h>

#include <pigpio.h>

#define CE0_GPIO_PIN 8
#define CE0_GPIO_OUTPUT_PIN 17
#define CE0_SPI_CHANNEL 0

#define ADXRS290_X_REGISTER_ADDRESS 0x02
#define ADXRS290_Y_REGISTER_ADDRESS 0x04

#define SENSITIVITY 200

int main() {
    int ret;
    int retryCount = 0;
    int sampleInterval = 10; // in milliseconds
    struct timespec startTime, endTime;
    struct sigaction sa;

    // Initialize SPI
    gpioInitialise();
    retryCount = 0;
    while (retryCount < 3) {
        if (spiOpen(CE0_SPI_CHANNEL, 0) < 0) {
            retryCount++;
            continue;
        }
        break;
    }

    // Initialize GPIO
    gpioInitialise();
    gpioSetMode(CE0_GPIO_OUTPUT_PIN, PI_OUTPUT);
    gpioWrite(CE0_GPIO_OUTPUT_PIN, 0);

    // Set up the gyro data logging file
    FILE *file = fopen("gyro_data.csv", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open gyro_data.csv\n");
        return 1;
    }

    // Set up the signal handler
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    // Set up the timer for 100 Hz sampling
    struct itimerspec timer;
    timer.it_value.tv_sec = 1 / (1000.0 / 100.0);
    timer.it_value.tv_nsec = 0;
    timer.it_interval.tv_sec = 1 / (1000.0 / 100.0);
    timer.it_interval.tv_nsec = 0;

    // Main loop
    while (1) {
        // Wait for 100 ms
        nanosleep(&timer, NULL);

        // Read the gyro data
        uint16_t rawX, rawY;
        retryCount = 0;
        while (retryCount < 3) {
            if (spiXfer(CE0_SPI_CHANNEL, CE0_GPIO_OUTPUT_PIN, CE0_GPIO_INPUT, 2, &rawX, &rawY, 1) < 0) {
                retryCount++;
                continue;
            }
            break;
        }

        // Log the data
        fprintf(file, "%.6f, %d, %d\n", (double) (rawX >> 8) / SENSITIVITY, (double) rawY / SENSITIVITY, 0);

        // Reset the timer
        nanosleep(&timer, NULL);
    }

    // Clean up
    fclose(file);
    gpioTerminate();
    gpioInitialise();

    return 0;
}

// SIGINT handler
void sigint_handler(int signum) {
    printf("Received SIGINT signal\n");
    fprintf(stderr, "Exiting...\n");
    exit(0);
}

