    int fadeDuration = 0;
    int i, j, k;
    int lampStatus[GPIO_NUM_LAMPS];
    int totalLamps = GPIO_NUM_LAMPS;
    int fadeInterval = 0;
    int fadeStep = 0;
    int fadeState = 1;
    int fadeStartTime = 0;
    int fadeEndTime = 0;
    int fadeComplete = 0;
    int lampState[GPIO_NUM_LAMPS];

    if (argc != 2) {
        printf("Usage: %s <fade_duration>\n", argv[0]);
        return 1;
    }

    if (sscanf(argv[1], "%d", &fadeDuration) != 1) {
        printf("Invalid duration format. Expected an integer between 1 and 3600.\n");
        return 1;
    }

    if (fadeDuration < 1 || fadeDuration > 3600) {
        printf("Duration must be an integer between 1 and 3600.\n");
        return 1;
    }

    gpioInit();

    for (i = 0; i < totalLamps; i++) {
        lampStatus[i] = 0;
        lampState[i] = 1;
    }

    for (i = 0; i < totalLamps; i++) {
        gpioSetMode(i + GPIO_NUM_PINS, GPIO_OUTPUT);
        lampState[i] = 1;
    }

    printf("Initializing pigpio...\n");
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio.\n");
        return 1;
    }

    printf("Starting...\n");

    for (i = 0; i < totalLamps; i++) {
        lampStatus[i] = 1;
        gpioSetPWMfrequency(i + GPIO_NUM_PINS, 100);
        gpioSetPWMrange(i + GPIO_NUM_PINS, 0, 255);
        gpioSetPWM(i + GPIO_NUM_PINS, 0);
        fadeInterval = (1000 / (fadeDuration / 1000)) + 1;
        fadeStartTime = 0;
        fadeEndTime = 0;
        fadeComplete = 0;
    }

    while (!fadeComplete) {
        for (i = 0; i < totalLamps; i++) {
            if (lampStatus[i] == 1) {
                fadeInterval--;
                if (fadeInterval == 0) {
                    fadeComplete = 1;
                    break;
                }
                gpioSetPWM(i + GPIO_NUM_PINS, fadeStep);
                gpioDelay(fadeInterval);
                fadeStep++;
                if (fadeStep > 255) {
                    fadeStep = 0;
                }
            }
        }

        for (i = 0; i < totalLamps; i++) {
            if (lampStatus[i] == 1) {
                gpioDelay(fadeInterval);
                lampStatus[i] = 0;
            }
        }

        printf("Lamps are fading...\n");

        for (i = 0; i < totalLamps; i++) {
            if (lampStatus[i] == 1) {
                printf("Lamp %d is fading...\n", i + 1);
                printf("Current PWM duty cycle: %d\n", gpioGetPWM(i + GPIO_NUM_PINS));
            }
        }

        printf("Lamps are now off.\n");
    }

    gpioTerminate();

    return 0;
}

