#include <fcntl.h>
#include <gpiod.h>

#define RELAY_PIN_RED 17
#define RELAY_PIN_YELLOW 22
#define RELAY_PIN_GREEN 23
#define RELAY_PIN_YELLOW_3 3

int main() {
    int fd, gpio_fd;
    struct gpiod_line *line;
    struct gpiod_line_config line_config;
    struct gpiod_event event;
    int state = 0;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open the GPIO chip
    if ((fd = gpiod_chip_open("/dev/gpiochip0")) < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpiod_exit();
        return 1;
    }

    // Open the line for the traffic light
    if ((gpio_fd = gpiod_line_open(fd, RELAY_PIN_RED)) < 0) {
        fprintf(stderr, "Failed to open line for relay red\n");
        gpiod_line_close(gpio_fd);
        gpiod_chip_close(fd);
        gpiod_exit();
        return 1;
    }

    // Configure the line for active-low operation
    line_config.direction = GPIGPIO_DIRECTION_IN;
    line_config.edge = GPIGPIO_EDGE_LOW;

    if (gpiod_line_config(gpio_fd, &line_config) < 0) {
        fprintf(stderr, "Failed to configure line for active-low operation\n");
        gpiod_line_close(gpio_fd);
        gpiod_chip_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set up the event for the line
    event.type = GPIGPIO_EVENT_LINE;
    event.line = gpio_fd;
    event.event = GPIGPIO_EVENT_LINE_LOW;

    // Wait for the line to go LOW
    if (gpiod_event_wait(gpio_fd, &event, 1) < 0) {
        fprintf(stderr, "Failed to wait for line to go LOW\n");
        gpiod_line_close(gpio_fd);
        gpiod_chip_close(fd);
        gpiod_exit();
        return 1;
    }

    // Cycle through the states
    while (1) {
        // Red state
        printf("Red state\n");
        state = 0;
        if (gpiod_line_write(gpio_fd, state) < 0) {
            fprintf(stderr, "Failed to write to line\n");
            gpiod_line_close(gpio_fd);
            gpiod_chip_close(fd);
            gpiod_exit();
            return 1;
        }

        // Yellow state
