#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_DIR_OUT 17
#define GPIO_DIR_IN 27

int main() {
    int ret;
    int log_fd;
    char log_file[128] = "dispense_log.txt";

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Open log file
    if ((log_fd = open(log_file, O_CREAT | O_WRONLY | O_TRUNC, 0644)) < 0) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 and GPIO27 as outputs
    if ((ret = gpioSetMode(GPIO_DIR_OUT, GPIO_DIR_OUT)) < 0) {
        fprintf(stderr, "Error setting GPIO17 and GPIO27 as outputs: %s\n", strerror(errno));
        goto error_log_file;
    }

    // Set GPIO17 and GPIO27 as outputs
    if ((ret = gpioSetMode(GPIO_DIR_OUT, GPIO_DIR_OUT)) < 0) {
        fprintf(stderr, "Error setting GPIO17 and GPIO27 as outputs: %s\n", strerror(errno));
        goto error_gpio_set_mode;
    }

    // Dispense cycle
    gpioDelay(500); // Dispense duration for solenoid 1
    gpioDelay(500); // Dispense duration for solenoid 2
    gpioDelay(500); // Dispense duration for deactivation

    // Deactivate both solenoids
    gpioDelay(500); // Deactivate solenoid 1
    gpioDelay(500); // Deactivate solenoid 2
    gpioDelay(500); // Deactivate both solenoids

    // Close log file
    if (close(log_fd) < 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        goto error_close_log_file;
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;

error_close_log_file:
    close(log_fd);
error_gpio_set_mode:
    gpioSetMode(GPIO_DIR_OUT, GPIO_DIR_IN);
error_log_file:
    close(log_fd);
error_initialise:
    gpioTerminate();
    return 1;
}

