    ret = init_sensors();
    if (ret) {
        fprintf(stderr, "Error initializing ultrasonic sensor: %s\n", strerror(ret));
        cleanup_i2c();
        close_log_file(log_fd);
        cleanup_pigpio();
        return 1;
    }

    // Initialize PID controller
    pid = pid_open(MOTOR_SPEED_MIN, MOTOR_SPEED_MAX, PID_Kp, PID_Ki, PID_Kd);
    if (!pid) {
        fprintf(stderr, "Error initializing PID controller: %s\n", strerror(errno));
        cleanup_sensors();
        cleanup_i2c();
        close_log_file(log_fd);
        cleanup_pigpio();
        return 1;
    }

