        ControlData control_data;
        ret = read_sensors(&control_data);
        if (ret) {
            fprintf(stderr, "Error reading control data from sensors: %s\n", strerror(ret));
            control_pid(NULL, NULL);
            continue;
        }

        // Calculate motor speeds
        int motor_a_speed = control_data.tilt_error * MOTOR_SPEED_MAX / TILT_ERROR_MAX + control_data.distance * MOTOR_SPEED_MAX / SENSOR_DISTANCE_THRESHOLD;
