        fprintf(stderr, "Error setting GPIO mode\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetBrightness(0) < 0) {
        fprintf(stderr, "Error setting GPIO brightness\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        exit(EXIT_FAILURE);
    }

    if (gpioGetState(TOUCH_SENSOR_PIN) != PI_ACTIVE) {
        fprintf(stderr, "Error: Touched sensor not detected\n");
        exit(EXIT_FAILURE);
    }

    printf("Press Ctrl+C to exit\n");

    while (1) {
        // Wait for touch or release of touch sensor
        if (gpioGetState(TOUCH_SENSOR_PIN) == PI_ACTIVE) {
            // Touched sensor detected, toggle relay state
            relayState = !relayState;
            gpioSetValue(RELAY_PIN, relayState);

            // Debounce the touch
            if (debounce(RELAY_PIN, TOUCH_SENSOR_PIN, debounceDelay) == 1) {
                printf("Touched sensor detected, relay state changed\n");
            }
        }

        // Wait for 50 ms before detecting the next touch
        sleep(50);
    }

    // Clean up resources
    gpioTerminate();
    pigpio_shutdown();

    return 0;
}

// Debounce function
int debounce(int pin, int touchSensor, int debounceDelay) {
    int previousState = gpioGetState(pin);
    int currentState = gpioGetState(touchSensor);

    if (currentState == previousState) {
        return 0; // No touch detected
    }

    if (currentState == PI_ACTIVE) {
        // Debounce delay
        if (currentState == previousState) {
            return 0; // No touch detected
        }
    }

    int debouncedState = previousState;
    previousState = currentState;

    return debouncedState;
}

