#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define RELAY_PIN_1 11
#define RELAY_PIN_2 13
#define RELAY_PIN_3 15
#define RELAY_PIN_4 17

int main() {
    int chip_fd;
    struct gpiod_chip *chip;
    int relays[4] = {RELAY_PIN_1, RELAY_PIN_2, RELAY_PIN_3, RELAY_PIN_4};
    int phase = 0;
    int brightness = 0;
    int brightness_increase_time = 3600; // 1 hour
    int brightness_decrease_time = 21600; // 6 hours
    int brightness_increase_duty_cycle = 0;
    int brightness_decrease_duty_cycle = 0;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %s\n", gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Open the chip by its name
    chip_fd = gpiod_chip_open_by_name("gpiochip");
    if (chip_fd < 0) {
        fprintf(stderr, "Failed to open the chip: %s\n", gpiod_chip_error_name(chip_fd));
        exit(EXIT_FAILURE);
    }

    // Request output on all relays
    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_output(chip_fd, relays[i], GPIDO_OUTPUT) < 0) {
            fprintf(stderr, "Failed to request output on relay %d: %s\n", relays[i], gpiod_line_error_name(relays[i]));
            exit(EXIT_FAILURE);
        }
    }

    // Set initial phase, brightness, and duty cycles
    phase = 0;
    brightness = 0;
    brightness_increase_duty_cycle = brightness_decrease_duty_cycle = 100;

    // Main loop
    while (1) {
        // Update brightness based on the current phase
        if (phase == 0) {
            brightness += brightness_increase_duty_cycle / 4;
        } else if (phase == 1) {
            brightness += brightness_decrease_duty_cycle / 4;
        } else if (phase == 2) {
            brightness -= brightness_increase_duty_cycle / 4;
        } else {
            brightness -= brightness_decrease_duty_cycle / 4;
        }

        // Update brightness and duty cycles for all relays
        for (int i = 0; i < 4; i++) {
            brightness_increase_duty_cycle += brightness_increase_duty_cycle / 4;
            brightness_decrease_duty_cycle += brightness_decrease_duty_cycle / 4;

            if (brightness_increase_duty_cycle < 0) {
                brightness_increase_duty_cycle = 0;
            } else if (brightness_increase_duty_cycle > 100) {
                brightness_increase_duty_cycle = 100;
            }

            if (brightness_decrease_duty_cycle < 0) {
                brightness_decrease_duty_cycle = 0;
            } else if (brightness_decrease_duty_cycle > 100) {
                brightness_decrease_duty_cycle = 100;
            }

            if (gpiod_line_set_value(chip_fd, relays[i], brightness_increase_duty_cycle) < 0) {
                fprintf(stderr, "Failed to set brightness on relay %d: %s\n", relays[i], gpiod_line_error_name(relays[i]));
                exit(EXIT_FAILURE);
            }

            if (gpiod_line_set_value(chip_fd, relays[i], brightness_decrease_duty_cycle) < 0) {
                fprintf(stderr, "Failed to set brightness on relay %d: %s\n", relays[i], gpiod_line_error_name(relays[i]));
                exit(EXIT_FAILURE);
            }
        }

        // Wait for 1 hour
        sleep(3600);

        // Cycle through the phases
        phase = (phase + 1) % 4;
    }

    // Clean up
    for (int i = 0; i < 4; i++) {
        if (gpiod_line_release(chip_fd, relays[i]) < 0) {
            fprintf(stderr, "Failed to release relay %d: %s\n", relays[i], gpiod_line_error_name(relays[i]));
            exit(EXIT_FAILURE);
        }
    }

    // Close the chip
    if (gpiod_chip_close(chip_fd) < 0) {
        fprintf(stderr, "Failed to close the chip: %s\n", gpiod_chip_error_name(chip_fd));
        exit(EXIT_FAILURE);
    }

    // Clean up libgpiod
    gpiod_exit();

    return 0;
}

