            FILE *log_file = fopen("freefall.log", "a");
            if (log_file == NULL) {
                fprintf(stderr, "Error opening log file\n");
                return 1;
            }

            fprintf(log_file, "%.3f, %.3f, %.3f\n", g_x, g_y, g_z);
            fclose(log_file);
        }

        // Wait for 100 ms
        usleep(100000);
    }

    // Check for freefall event every 100 ms
    while (1) {
        // Wait for I2C read
        if (ioctl(fd, I2C_RDWR, I2C_ADDR) < 0) {
            fprintf(stderr, "Error reading I2C device\n");
            gpioTerminate();
            return 1;
        }

        // Wait for data
        if (ioctl(fd, I2C_RDWR, I2C_ADDR) < 0) {
            fprintf(stderr, "Error reading I2C device\n");
            gpioTerminate();
            return 1;
        }

        // Check for freefall event
        if (g_x < -0.2 || g_y < -0.2 || g_z < -0.2) {
            // Log freefall event
            char timestamp[20];
            char x_str[10];
            char y_str[10];
            char z_str[10];
            sprintf(timestamp, "%s", ctime(&(i2c_data.buf[6])));
            sprintf(x_str, "%0.3f", g_x);
            sprintf(y_str, "%0.3f", g_y);
            sprintf(z_str, "%0.3f", g_z);
            printf("Freefall detected at %s, X: %s, Y: %s, Z: %s\n", timestamp, x_str, y_str, z_str);

            // Log data to file
            FILE *log_file = fopen("freefall.log", "a");
            if (log_file == NULL) {
                fprintf(stderr, "Error opening log file\n");
                return 1;
            }

            fprintf(log_file, "%.3f, %.3f, %.3f\n", g_x, g_y, g_z);
            fclose(log_file);
        }

        // Wait for 100 ms
        usleep(100000);
    }

    // Close I2C handle
    if (ioctl(fd, I2C_RDWR, I2C_ADDR) < 0) {
        fprintf(stderr, "Error closing I2C handle\n");
        gpioTerminate();
        return 1;
    }

    // Release resources
    gpioTerminate();

    return 0;
}
