int main(int argc, char *argv[]) {
    int fd, ret;
    int i2c_fd;
    int gpio_fd;
    int buzzer_gpio;
    int i2c_retries = 3;
    int freefall_threshold = 100;
    int impact_threshold = 200;
    int i;

    // Initialize pigpio
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpio_exit();
        return 1;
    }

    if ((i2c_fd = ioctl(fd, PI_I2C_OPEN)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        close(fd);
        gpio_exit();
        return 1;
    }

    // Open GPIO
    if ((gpio_fd = open("/dev/gpiochip0", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open GPIO: %s\n", strerror(errno));
        close(i2c_fd);
        ioctl(i2c_fd, PI_I2C_CLOSE);
        gpio_exit();
        return 1;
    }

    // Configure LIS3DH
    if (pi_set_device(i2c_fd, I2C_BUS_NUM, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set device: %s\n", strerror(errno));
        close(gpio_fd);
        close(i2c_fd);
        gpio_exit();
        return 1;
    }

    if (pi_set_mode(gpio_fd, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode: %s\n", strerror(errno));
        close(gpio_fd);
        close(i2c_fd);
        pi_exit();
        return 1;
    }

    if (pi_set_direction(gpio_fd, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set direction: %s\n", strerror(errno));
        close(gpio_fd);
        close(i2c_fd);
        pi_exit();
        return 1;
    }

    if (pi_set_pull_up_down(gpio_fd, GPIO_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up/down: %s\n", strerror(errno));
        close(gpio_fd);
        close(i2c_fd);
        pi_exit();
        return 1;
    }

    if (pi_set_interrupt_mode(gpio_fd, GPIO_INT_FALLING) < 0) {
        fprintf(stderr, "Failed to set interrupt mode: %s\n", strerror(errno));
        close(gpio_fd);
        close(i2c_fd);
        pi_exit();
        return 1;
    }

    // Set buzzer GPIO
    if (pi_set_pin(gpio_fd, 17) < 0) {
        fprintf(stderr, "Failed to set buzzer GPIO: %s\n", strerror(errno));
        close(gpio_fd);
        close(i2c_fd);
        pi_exit();
        return 1;
    }

    // Open buzzer GPIO
    if ((buzzer_gpio = open("/dev/gpiochip0", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open buzzer GPIO: %s\n", strerror(errno));
        close(gpio_fd);
        close(i2c_fd);
        pi_exit();
        return 1;
    }

    // Set buzzer GPIO as output
    if (pi_set_direction(buzzer_gpio, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer direction: %s\n", strerror(errno));
        close(buzzer_gpio);
        close(gpio_fd);
        close(i2c_fd);
        pi_exit();
        return 1;
    }

