#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

#define I2C_ADDRESS 0x18
#define THRESHOLD 2.0

int main(int argc, char *argv[]) {
    int i2c_fd;
    int result;
    int threshold;
    int log_file_fd;
    char log_file_path[128] = "/var/log/high_acceleration.log";

    // Check command line arguments
    if (argc < 2) {
        printf("Usage: %s [-a <address>] [-t <threshold>] [-h]\n", argv[0]);
        return 1;
    }

    // Parse command line arguments
    int opt;
    while ((opt = getopt(argc, argv, "a:t:h")) != -1) {
        switch (opt) {
            case 'a':
                I2C_ADDRESS = atoi(optarg);
                break;
            case 't':
                threshold = atof(optarg);
                break;
            case 'h':
                return 0;
            default:
                return 1;
        }
    }

    // Check I2C address range
    if (I2C_ADDRESS < 0x08 || I2C_ADDRESS > 0x77) {
        printf("Invalid I2C address: 0x%02x\n", I2C_ADDRESS);
        return 1;
    }

    // Check threshold range
    if (threshold < 0.0 || threshold > 2.0) {
        printf("Invalid threshold: %f\n", threshold);
        return 1;
    }

    // Open I2C
    if ((i2c_fd = i2cOpen(I2C_ADDRESS)) < 0) {
        printf("Failed to open I2C at address 0x%02x: %s\n", I2C_ADDRESS, strerror(errno));
        return 1;
    }

    // Configure sensor
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        printf("Failed to set I2C slave address: %s\n", strerror(errno));
        return 1;
    }

    // Set CTRL_REG1 and CTRL_REG4
    if (ioctl(i2c_fd, I2C_RDWR, 0x57) < 0 || ioctl(i2c_fd, I2C_RDWR, 0x88) < 0) {
        printf("Failed to set CTRL_REG1 and CTRL_REG4: %s\n", strerror(errno));
        return 1;
    }

    // Set data rate
    if (ioctl(i2c_fd, I2C_RDWR, 0x3A) < 0 || ioctl(i2c_fd, I2C_RDWR, 0x01) < 0) {
        printf("Failed to set data rate: %s\n", strerror(errno));
        return 1;
    }

    // Set high-resolution mode
    if (ioctl(i2c_fd, I2C_RDWR, 0x3C) < 0 || ioctl(i2c_fd, I2C_RDWR, 0x01) < 0) {
        printf("Failed to set high-resolution mode: %s\n", strerror(errno));
        return 1;
    }

    // Set ±2g range
