            snprintf(log_message, sizeof(log_message), "High acceleration detected at X: %d, Y: %d, Z: %d, g: %.2f\n",
                     raw_data & 0x1F, (raw_data >> 5) & 0x1F, (raw_data >> 6) & 0x1F, g);
            if (write(log_file_fd, log_message, strlen(log_message)) < 0) {
                printf("Failed to write to log file: %s\n", strerror(errno));
