    // Close I2C
    if (ioctl(i2c_fd, I2C_RDWR, 0) < 0) {
        printf("Failed to close I2C: %s\n", strerror(errno));
        return 1;
    }

    // Terminate pigpio
    if (pigpio_exit() < 0) {
        printf("Failed to terminate pigpio: %s\n", strerror(errno));
        return 1;
    }

