#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define LED_PIN 22
#define ALERT_PIN 22
#define BUZZER_PIN 27

int main() {
    int fd, gpio_fd;
    struct gpiod_line_info line_info;
    struct gpiod_event_info event_info;
    int center_sensor_reading = 0;
    int alert_count = 0;
    int alert_duration = 2;
    int line_following_direction = 0;
    int line_following_stop = 0;
    struct timespec start_time, end_time;
    int sensor_absent = 0;
    int bus_error = 0;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open GPIO file descriptor
    fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO file descriptor\n");
        gpiod_exit();
        return 1;
    }

    // Open alert LED and buzzer
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO file descriptor\n");
        close(fd);
        gpiod_exit();
        return 1;
    }

    if (ioctl(gpio_fd, GPIGPIO_LINE_GET, GPIO4) < 0) {
        fprintf(stderr, "Failed to get line for left sensor\n");
        close(fd);
        close(gpio_fd);
        gpiod_exit();
        return 1;
    }

    if (ioctl(gpio_fd, GPIGPIO_LINE_GET, GPIO17) < 0) {
        fprintf(stderr, "Failed to get line for center sensor\n");
        close(fd);
        close(gpio_fd);
        gpiod_exit();
        return 1;
    }

    if (ioctl(gpio_fd, GPIGPIO_LINE_GET, GPIO27) < 0) {
        fprintf(stderr, "Failed to get line for right sensor\n");
        close(fd);
        close(gpio_fd);
        gpiod_exit();
        return 1;
    }

    // Set up the line-following logic
    while (1) {
        // Poll the sensors
        memset(&line_info, 0, sizeof(line_info));
        memset(&event_info, 0, sizeof(event_info));

        if (ioctl(fd, GPIGPIO_LINE_READ, &line_info) < 0) {
            fprintf(stderr, "Failed to read line sensor\n");
            close(fd);
            close(gpio_fd);
            gpiod_exit();
            return 1;
        }

        if (line_info.state == GPIGPIO_LINE_DETECTED) {
            center_sensor_reading = line_info.value;
            if (center_sensor_reading == 1) {
                line_following_direction = 1;
            } else {
                line_following_direction = 0;
            }
        }

        if (ioctl(fd, GPIGPIO_LINE_READ, &event_info) < 0) {
            fprintf(stderr, "Failed to read line sensor\n");
            close(fd);
            close(gpio_fd);
            gpiod_exit();
            return 1;
        }

        if (event_info.state == GPIGPIO_LINE_DETECTED) {
            if (line_following_direction == 1) {
                if (center_sensor_reading == 1) {
                    line_following_stop = 1;
                }
            } else if (line_following_direction == 0) {
                if (center_sensor_reading == 1) {
                    line_following_stop = 1;
                }
            }
        }

        // Check for sensor absence
        if (event_info.state == GPIGPIO_LINE_ABSENT) {
            sensor_absent = 1;
        }

        // Check for bus error
        if (event_info.state == GPIGPIO_BUS_ERROR) {
            bus_error = 1;
        }

        // Check for alert
        if (line_following_stop == 1) {
            if (alert_count == 0) {
                // Drive LED HIGH for 2 seconds
                if (ioctl(LED_PIN, 1) < 0) {
                    fprintf(stderr, "Failed to drive LED HIGH\n");
                    close(fd);
                    close(gpio_fd);
                    gpiod_exit();
                    return 1;
                }

                // Wait for 2 seconds
                clock_gettime(CLOCK_MONOTONIC, &start_time);
                while (clock_gettime(CLOCK_MONOTONIC, &end_time) < start_time + 2);

                if (ioctl(LED_PIN, 0) < 0) {
                    fprintf(stderr, "Failed to drive LED LOW\n");
                    close(fd);
                    close(gpio_fd);
                    gpiod_exit();
                    return 1;
                }

                // Reset alert count
                alert_count = 0;
            } else {
                // Wait for 5 readings
                for (int i = 0; i < 5; i++) {
                    if (center_sensor_reading == 1) {
                        break;
                    }
                    if (ioctl(fd, GPIGPIO_LINE_READ, &event_info) < 0) {
                        fprintf(stderr, "Failed to read line sensor\n");
                        close(fd);
                        close(gpio_fd);
                        gpiod_exit();
                        return 1;
                    }
                }

                // Reset alert count
                alert_count = 0;
            }
        }

        // Check for alert duration
        if (alert_count == 5) {
            // Drive GPIO22 HIGH for 2 seconds
            if (ioctl(GPIO22, 1) < 0) {
                fprintf(stderr, "Failed to drive GPIO22 HIGH\n");
                close(fd);
                close(gpio_fd);
                gpiod_exit();
                return 1;
            }

            // Wait for 2 seconds
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            while (clock_gettime(CLOCK_MONOTONIC, &end_time) < start_time + 2);

            if (ioctl(GPIO22, 0) < 0) {
                fprintf(stderr, "Failed to drive GPIO22 LOW\n");
                close(fd);
                close(gpio_fd);
                gpiod_exit();
                return 1;
            }

            // Reset alert count
            alert_count = 0;
        }

        // Check for sensor-absent errors
        if (sensor_absent == 1) {
            fprintf(stderr, "Sensor-absent error\n");
            close(fd);
            close(gpio_fd);
            gpiod_exit();
            return 1;
        }

        // Check for bus-error
        if (bus_error == 1) {
            fprintf(stderr, "Bus-error error\n");
            close(fd);
            close(gpio_fd);
            gpiod_exit();
            return 1;
        }

        // Wait for 10 ms
        usleep(10000);
    }

    // Clean up
    close(fd);
    close(gpio_fd);
    gpiod_exit();

    return 0;
}

