#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define RELAY_PORT 5000
#define RELAY_DEVICE "/dev/gpiomem"
#define RELAY_CHANNEL 18
#define RELAY_LOG_FILE "relay_log.txt"

int main(int argc, char *argv[]) {
    int sock;
    struct sockaddr_in addr;
    char buffer[256];
    char *command;
    char *command_ptr;
    char *log_file_path = RELAY_LOG_FILE;
    int log_file_fd;
    int relay_status = 0;
    int exit_gracefully = 0;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio library\n");
        exit(EXIT_FAILURE);
    }

    // Open log file
    if ((log_file_fd = open(log_file_path, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        fprintf(stderr, "Error opening log file\n");
        exit(EXIT_FAILURE);
    }

    // Open relay log file
    if ((log_file_fd = open(RELAY_LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        fprintf(stderr, "Error opening relay log file\n");
        exit(EXIT_FAILURE);
    }

    // Initialize socket
    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        fprintf(stderr, "Error creating socket\n");
        exit(EXIT_FAILURE);
    }

    // Set socket options
    if (setsockopt(sock, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &1, sizeof(int)) < 0) {
        fprintf(stderr, "Error setting socket options\n");
        exit(EXIT_FAILURE);
    }

    // Set relay channel
    if (gpioSetMode(RELAY_CHANNEL, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting relay channel mode\n");
        exit(EXIT_FAILURE);
    }

    // Set relay state
    if (gpioWrite(RELAY_CHANNEL, relay_status) < 0) {
        fprintf(stderr, "Error setting relay state\n");
        exit(EXIT_FAILURE);
    }

    // Bind socket to port
    if (bind(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error binding socket to port\n");
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(sock, 3) < 0) {
        fprintf(stderr, "Error listening for incoming connections\n");
        exit(EXIT_FAILURE);
    }

    // Accept incoming connection
    if ((addr.sin_addr.s_addr = htonl(INADDR_ANY)) == 0) {
        fprintf(stderr, "Error setting socket address\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Accept incoming connection
        if ((sock = accept(sock, (struct sockaddr *)&addr, (socklen_t*)&addrlen)) < 0) {
            fprintf(stderr, "Error accepting connection\n");
            exit(EXIT_FAILURE);
        }

        // Log activation
        if (logMessage("Activated relay", log_file_fd) < 0) {
            fprintf(stderr, "Error logging activation\n");
            exit(EXIT_FAILURE);
        }

        // Process incoming command
        if (getCommand(sock, &command, &command_ptr) < 0) {
            fprintf(stderr, "Error parsing command\n");
            exit(EXIT_FAILURE);
        }

        // Log deactivation
        if (logMessage("Deactivated relay", log_file_fd) < 0) {
            fprintf(stderr, "Error logging deactivation\n");
            exit(EXIT_FAILURE);
        }

        // Check if command is valid
        if (strcmp(command, "ON") == 0 || strcmp(command, "OFF") == 0) {
            relay_status = (strcmp(command, "ON") == 0) ? 1 : 0;
            if (gpioWrite(RELAY_CHANNEL, relay_status) < 0) {
                fprintf(stderr, "Error setting relay state\n");
                exit(EXIT_FAILURE);
            }
        }

        // Close socket and log file
        close(sock);
        close(log_file_fd);

        // Turn off relay
        if (gpioWrite(RELAY_CHANNEL, relay_status) < 0) {
            fprintf(stderr, "Error turning off relay\n");
            exit(EXIT_FAILURE);
        }

        // Graceful shutdown
        if (gpioTerminate() < 0) {
            fprintf(stderr, "Error terminating pigpio\n");
            exit(EXIT_FAILURE);
        }

        // Exit gracefully
        exit_gracefully = 1;
    }

    // Cleanup
    close(sock);
    close(log_file_fd);
    gpioTerminate();

    return 0;
}

