    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio library");
        exit(1);
    }

    // Set up syslog
    syslog_fd = openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);
    if (syslog_fd == -1) {
        syslog(LOG_ERR, "Failed to open syslog");
        exit(1);
    }

