    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(IN1, PI_INPUT);
    gpioSetMode(IN2, PI_INPUT);

    // Set up motor
    gpioWrite(ENA, PI_HIGH);
    gpioWrite(IN1, PI_HIGH);
    gpioWrite(IN2, PI_LOW);

    // Main loop
    while (1) {
        // Check if rain is detected
        if (gpioRead(GPIO_17) == 0) {
            rain_detected = 1;
        } else {
            rain_detected = 0;
        }

        // Check if dry for at least 3 consecutive polls
        if (previous_dry_count >= 3 && previous_poll_time + 200 < time(NULL)) {
            gpioDelay(200);
            previous_poll_time = time(NULL);
        } else {
            previous_dry_count = 0;
        }

        // Check if motor should run
        if (rain_detected && !motor_running) {
            gpioWrite(ENA, PI_HIGH);
            gpioWrite(IN1, PI_HIGH);
            gpioWrite(IN2, PI_LOW);
            motor_running = 1;
            gpioDelay(5000);
            gpioWrite(ENA, PI_LOW);
            gpioWrite(IN1, PI_LOW);
            gpioWrite(IN2, PI_LOW);
        }

        // Check if motor should stop
        if (!rain_detected && motor_running) {
            gpioWrite(ENA, PI_LOW);
            gpioWrite(IN1, PI_LOW);
            gpioWrite(IN2, PI_LOW);
            motor_running = 0;
        }

        // Log events
        if (rain_detected) {
            syslog(LOG_INFO, "Rain detected");
        } else {
            syslog(LOG_INFO, "No rain detected");
        }

        if (motor_running) {
            syslog(LOG_INFO, "Motor started");
        } else {
            syslog(LOG_INFO, "Motor stopped");
        }

        // Wait for user input to exit
        if (getchar() == 'q') {
            break;
        }

        // Wait for SIGINT or SIGTERM
        if (kill(getpid(), SIGINT) == -1 || kill(getpid(), SIGTERM) == -1) {
            syslog(LOG_ERR, "Failed to send SIGINT or SIGTERM");
        }
    }

    // Clean up
    gpioTerminate();
    closelog();

    return 0;
}

