#include <linux/input.h>

#include <pigpio.h>

#define GPIO_PULSE_WIDTH 2000
#define GPIO_RELEASE_DELAY 100

int main() {
    int servo_fd, button_fd, gpio_fd;
    struct input_event event;
    struct input_dev *input_dev;
    int button_pressed = 0;
    int button_debounce_timer = 0;
    int servo_locked = 0;
    int servo_unlocked = 0;
    int exit_flag = 0;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open GPIO file descriptors
    servo_fd = open("/dev/gpiomem", O_RDWR);
    if (servo_fd < 0) {
        fprintf(stderr, "Failed to open /dev/gpiomem\n");
        return 1;
    }

    button_fd = open("/dev/input/event0", O_RDONLY);
    if (button_fd < 0) {
        fprintf(stderr, "Failed to open /dev/input/event0\n");
        return 1;
    }

    // Set up GPIO file descriptors
    if (gpioSetMode(servo_fd, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    if (gpioSetPwmFrequency(servo_fd, 100) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return 1;
    }

    if (gpioSetPwmRange(servo_fd, GPIO_PULSE_WIDTH) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        return 1;
    }

    if (gpioSetServoPwm(servo_fd, GPIO_PULSE_WIDTH) < 0) {
        fprintf(stderr, "Failed to set servo PWM\n");
        return 1;
    }

    if (gpioSetServoPwm(servo_fd, GPIO_RELEASE_DELAY) < 0) {
        fprintf(stderr, "Failed to set servo PWM release delay\n");
        return 1;
    }

    // Set up button file descriptors
    if (gpioSetMode(button_fd, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    if (gpioGetValue(button_fd) == 1) {
        button_pressed = 1;
    }

    // Set up debouncing
    gpioSetDebounce(button_fd, GPIO_DEBOUNCE_INTERNAL);

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (!exit_flag) {
        // Check if button is pressed
        if (button_pressed) {
            // Check if button is released
            if (gpioGetValue(button_fd) == 0) {
                // Lock the servo
                gpioSetServoPwm(servo_fd, GPIO_PULSE_WIDTH);
                servo_locked = 1;
                printf("Locking servo\n");
            } else {
                // Unlock the servo
                gpioSetServoPwm(servo_fd, GPIO_RELEASE_DELAY);
                servo_unlocked = 1;
                printf("Unlocking servo\n");
            }

            // Wait for debounce
            button_debounce_timer = 0;
            while (gpioGetValue(button_fd) == 1 && button_debounce_timer++ < GPIO_DEBOUNCE_INTERNAL) {
                usleep(100);
            }

            button_debounce_timer = 0;
        }

        // Poll the servo
        if (gpioGetValue(servo_fd) == 1) {
            if (servo_locked) {
                // Release the servo
                gpioSetServoPwm(servo_fd, GPIO_RELEASE_DELAY);
                servo_unlocked = 0;
                printf("Releasing servo\n");
            } else {
                // Lock the servo
                gpioSetServoPwm(servo_fd, GPIO_PULSE_WIDTH);
                servo_locked = 1;
                printf("Locking servo\n");
            }
        }

        // Wait for a short time
        usleep(1000);
    }

    // Clean up
    gpioTerminate();

    return 0;
}

// Signal handler for SIGINT and SIGTERM
void sigint_handler(int signum) {
    exit_flag = 1;
}

// Signal handler for SIGINT and SIGTERM
void sigterm_handler(int signum) {
    exit_flag = 1;
}

