#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <stdlib.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define ELECTRODE_COUNT 12
#define RELAY_OFF 0
#define RELAY_ON 1

int main() {
    int fd;
    int ret;
    int i;
    int touchStatus;
    int electrodeStates[ELECTRODE_COUNT];

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up I2C bus 1
    if (piI2cSetup(1) < 0) {
        fprintf(stderr, "Error: Failed to set up I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Perform a soft-reset of the MPR121
    if (piSetResistance(0, 0) < 0) {
        fprintf(stderr, "Error: Failed to perform soft-reset\n");
        gpioTerminate();
        return 1;
    }

    // Configure baseline filtering, debounce, FFI/SFI/CDT, and auto-config
    if (piSetConfig(0x00, 0x0C, 0x0C, 0x0C, 0x0C, 0x0C, 0x0C, 0x0C, 0x0C, 0x0C, 0x0C, 0x0C, 0x0C, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to configure MPR121\n");
        gpioTerminate();
        return 1;
    }

    // Enable exactly 12 electrodes
    if (piSetConfig(0x7B, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to enable electrodes\n");
        gpioTerminate();
        return 1;
    }

    // Set the relay to a known OFF state
    if (piSetDigital(RELAY_GPIO, RELAY_OFF) < 0) {
        fprintf(stderr, "Error: Failed to set relay to OFF state\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the touch sensor
    if (piSetResistance(0, 0) < 0) {
        fprintf(stderr, "Error: Failed to set up touch sensor\n");
        gpioTerminate();
        return 1;
    }

    // Wait for the sensor to be available
    while (piI2cRead(0x5A, &touchStatus, 1) < 0) {
        if (errno == EAGAIN) {
            continue;
        } else {
            fprintf(stderr, "Error: Failed to read touch status\n");
            gpioTerminate();
            return 1;
        }
    }

    // Toggle the relay only on a fresh touch of electrode 0
    if (touchStatus & 0x04) {
        if (piSetDigital(RELAY_GPIO, RELAY_ON) < 0) {
            fprintf(stderr, "Error: Failed to set relay to ON state\n");
            gpioTerminate();
            return 1;
        }
    }

    // Set up a 200 ms debounce
    if (piSetDebounce(0x5B, 200) < 0) {
        fprintf(stderr, "Error: Failed to set debounce\n");
        gpioTerminate();
        return 1;
    }

    // Toggle the relay only on a fresh touch of electrode 0
    if (touchStatus & 0x04) {
        if (piSetDigital(RELAY_GPIO, RELAY_ON) < 0) {
            fprintf(stderr, "Error: Failed to set relay to ON state\n");
            gpioTerminate();
            return 1;
        }
    }

    // Wait for the relay to toggle
    while (piGetDigital(RELAY_GPIO) == RELAY_ON) {
        if (piPollForDigital(RELAY_GPIO, 1, 100) < 0) {
            fprintf(stderr, "Error: Failed to poll for relay toggle\n");
            gpioTerminate();
            return 1;
        }
    }

    // Set the relay to a known OFF state
    if (piSetDigital(RELAY_GPIO, RELAY_OFF) < 0) {
        fprintf(stderr, "Error: Failed to set relay to OFF state\n");
        gpioTerminate();
        return 1;
    }

    // Clean up resources
    piTerminate();

    return 0;
}

