        if (piSetDigital(RELAY_GPIO, RELAY_ON) < 0) {
            fprintf(stderr, "Error: Failed to set relay to ON state\n");
            gpioTerminate();
            return 1;
        }
    }

    // Set up a 200 ms debounce
    if (piSetDebounce(0x5B, 200) < 0) {
        fprintf(stderr, "Error: Failed to set debounce\n");
        gpioTerminate();
        return 1;
    }

    // Toggle the relay only on a fresh touch of electrode 0
    if (touchStatus & 0x04) {
        if (piSetDigital(RELAY_GPIO, RELAY_ON) < 0) {
            fprintf(stderr, "Error: Failed to set relay to ON state\n");
            gpioTerminate();
            return 1;
        }
    }

    // Wait for the relay to toggle
    while (piGetDigital(RELAY_GPIO) == RELAY_ON) {
        if (piPollForDigital(RELAY_GPIO, 1, 100) < 0) {
            fprintf(stderr, "Error: Failed to poll for relay toggle\n");
            gpioTerminate();
            return 1;
        }
    }

    // Set the relay to a known OFF state
    if (piSetDigital(RELAY_GPIO, RELAY_OFF) < 0) {
        fprintf(stderr, "Error: Failed to set relay to OFF state\n");
        gpioTerminate();
        return 1;
    }

    // Clean up resources
    piTerminate();

    return 0;
}
