#define BH1750_I2C_ADDR 0x23
#define BH1750_ONE_TIME_MODE 0x20
#define BH1750_RES_16B 0x00
#define BH1750_RES_8B  0x01

int i2c_fd;

void i2c_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    if (gpioSetMode(GPIO_NUM_23, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 23 mode\n");
        exit(1);
    }

    if (gpioSetPulseWidth(GPIO_NUM_23, 0, 0, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO 23 pulse width\n");
        exit(1);
    }

    if (gpioOpenI2C(2, &i2c_fd) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(1);
    }

    if (ioctl(i2c_fd, PI_I2C_SLAVE, BH1750_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        exit(1);
    }
}

void i2c_deinit() {
    gpioTerminate();
    gpioClose(i2c_fd);
}

int i2c_read_raw(uint16_t addr, uint8_t *data, int len) {
    int ret;
    if ((ret = ioctl(i2c_fd, PI_I2C_READ, data, len, addr)) < 0) {
        fprintf(stderr, "Failed to read data from I2C device\n");
        exit(1);
    }
    return ret;
}

void i2c_read_lux(uint16_t addr, uint16_t *lux) {
    uint16_t raw;
    if ((raw = i2c_read_raw(addr, &raw, sizeof(raw))) < 0) {
        fprintf(stderr, "Failed to read raw data from I2C device\n");
        exit(1);
    }

    *lux = raw / 1.2;
}

void i2c_write_byte(uint16_t addr, uint8_t data) {
    if (ioctl(i2c_fd, PI_I2C_WRITE_BYTE, &data) < 0) {
        fprintf(stderr, "Failed to write byte to I2C device\n");
        exit(1);
    }
}

void i2c_log_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

int main() {
    i2c_init();

    while (1) {
        uint16_t lux;
        if (i2c_read_lux(BH1750_I2C_ADDR, &lux) < 0) {
            i2c_log_error("Failed to read lux value\n");
            continue;
        }

        if (lux < 150) {
            gpioWrite(GPIO_NUM_23, 1);
        } else {
            gpioWrite(GPIO_NUM_23, 0);
        }

        sleep(2);
    }

    i2c_deinit();
    return 0;
}

