#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/gpiod.h>

#define PWM_FREQUENCY 50
#define PULSE_WIDTH_MIN 500
#define PULSE_WIDTH_MAX 2500

int main() {
    int fd, ioctl_fd;
    struct gpiod_channel_param param;
    struct gpiod_channel_state state;
    int servo_pins[] = {7, 8, 9, 10, 11};
    int i;

    // Initialize pigpio library
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open GPIO file descriptors
    for (i = 0; i < 5; i++) {
        fd = open("/dev/gpiochip0", O_RDWR);
        if (fd < 0) {
            fprintf(stderr, "Failed to open GPIO file descriptor\n");
            gpio_exit();
            return 1;
        }

        ioctl_fd = open("/dev/gpiochip0/gpiochip0", O_RDWR);
        if (ioctl_fd < 0) {
            fprintf(stderr, "Failed to open ioctl file descriptor\n");
            close(fd);
            gpio_exit();
            return 1;
        }

        // Set GPIO direction and PWM frequency
        param.gpiod_channel = servo_pins[i];
        param.direction = GPID_OUTPUT;
        param.pwm_freq = PWM_FREQUENCY;
        param.pwm_range = PWM_FREQUENCY;
        if (ioctl(ioctl_fd, GPIO_SET_PARAM, &param) < 0) {
            fprintf(stderr, "Failed to set PWM frequency\n");
            close(fd);
            close(ioctl_fd);
            gpio_exit();
            return 1;
        }

        // Set servo pulse width
        param.gpiod_channel = servo_pins[i];
        param.value = (servo_pins[i] - PULSE_WIDTH_MIN) / (PULSE_WIDTH_MAX - PULSE_WIDTH_MIN) * (PWM_FREQUENCY / 50) + PULSE_WIDTH_MIN;
        if (ioctl(ioctl_fd, GPIO_SET_VALUE, &param) < 0) {
            fprintf(stderr, "Failed to set servo pulse width\n");
            close(fd);
            close(ioctl_fd);
            gpio_exit();
            return 1;
        }
    }

    // Hold the signals for 3 seconds
    for (i = 0; i < 3; i++) {
        usleep(3000000);
    }

    // Release the library resources
    gpio_exit();

    return 0;
}

