#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <math.h>

#define DRV8833_MOTOR_A_PIN 17
#define DRV8833_MOTOR_B_PIN 22
#define DRV8833_ENCODER_A_PIN 4
#define DRV8833_ENCODER_B_PIN 6
#define DRV8833_PWM_FREQUENCY 10000
#define DRV8833_PWM_PERIOD 100
#define DRV8833_PWM_DUTY_CYCLE 0.5
#define DRV8833_MAX_PWM_VALUE 255
#define DRV8833_MIN_PWM_VALUE 0

volatile uint32_t motor_a_count = 0;
volatile uint32_t motor_b_count = 0;
volatile uint32_t encoder_a_count = 0;
volatile uint32_t encoder_b_count = 0;

bool init_pigpio() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return false;
    }
    return true;
}

void cleanup_pigpio() {
    gpioTerminate();
}

bool init_encoder() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize encoder pins\n");
        return false;
    }
    gpioSetMode(DRV8833_ENCODER_A_PIN, PI_GPIO_OUTPUT);
    gpioSetMode(DRV8833_ENCODER_B_PIN, PI_GPIO_OUTPUT);
    gpioSetMode(DRV8833_MOTOR_A_PIN, PI_GPIO_OUTPUT);
    gpioSetMode(DRV8833_MOTOR_B_PIN, PI_GPIO_OUTPUT);
    gpioSetPolarity(DRV8833_ENCODER_A_PIN, PI_HIGH);
    gpioSetPolarity(DRV8833_ENCODER_B_PIN, PI_HIGH);
    gpioSetPwmFrequency(DRV8833_MOTOR_A_PIN, DRV8833_PWM_FREQUENCY);
    gpioSetPwmFrequency(DRV8833_MOTOR_B_PIN, DRV8833_PWM_FREQUENCY);
    gpioSetPwmRange(DRV8833_MOTOR_A_PIN, DRV8833_MIN_PWM_VALUE, DRV8833_MAX_PWM_VALUE);
    gpioSetPwmRange(DRV8833_MOTOR_B_PIN, DRV8833_MIN_PWM_VALUE, DRV8833_MAX_PWM_VALUE);
    gpioSetPwmDutyCycle(DRV8833_MOTOR_A_PIN, DRV8833_PWM_DUTY_CYCLE);
    gpioSetPwmDutyCycle(DRV8833_MOTOR_B_PIN, DRV8833_PWM_DUTY_CYCLE);
    return true;
}

void cleanup_encoder() {
    gpioSetPwmFrequency(DRV8833_ENCODER_A_PIN, 0);
    gpioSetPwmFrequency(DRV8833_ENCODER_B_PIN, 0);
    gpioSetPwmRange(DRV8833_ENCODER_A_PIN, 0);
    gpioSetPwmRange(DRV8833_ENCODER_B_PIN, 0);
    gpioSetPwmDutyCycle(DRV8833_ENCODER_A_PIN, 0);
    gpioSetPwmDutyCycle(DRV8833_ENCODER_B_PIN, 0);
}

void stop_motors() {
    gpioSetPwmDutyCycle(DRV8833_MOTOR_A_PIN, DRV8833_MIN_PWM_VALUE);
    gpioSetPwmDutyCycle(DRV8833_MOTOR_B_PIN, DRV8833_MIN_PWM_VALUE);
}

void update_encoder_counts() {
    uint32_t count_a = gpioGetPulseWidth(DRV8833_ENCODER_A_PIN);
    uint32_t count_b = gpioGetPulseWidth(DRV8833_ENCODER_B_PIN);
    motor_a_count += count_a - motor_a_count;
    motor_b_count += count_b - motor_b_count;
}

void update_motor_speed() {
    float target_speed = 50.0;
    float current_speed = motor_a_count / DRV8833_ENCODER_COUNTS_PER_REV * DRV8833_MAX_PWM_VALUE;
    float pwm_duty_cycle = target_speed - current_speed;
    if (pwm_duty_cycle < 0) {
        pwm_duty_cycle = 0;
    } else if (pwm_duty_cycle > 255) {
        pwm_duty_cycle = 255;
    }
    gpioSetPwmDutyCycle(DRV8833_MOTOR_A_PIN, pwm_duty_cycle);
    gpioSetPwmDutyCycle(DRV8833_MOTOR_B_PIN, pwm_duty_cycle);
}

void update_encoder_ticks() {
    encoder_a_count += DRV8833_ENCODER_COUNTS_PER_REV;
    encoder_b_count += DRV8833_ENCODER_COUNTS_PER_REV;
}

void update_pi_controller_values() {
    float error = 0.0;
    float integral_term = 0.0;
    float derivative_term = 0.0;
    float output = 0.0;

    error = motor_a_count - motor_b_count;
    integral_term += error * DRV8833_PID_INTEGRAL_GAIN;
    derivative_term = error - integral_term / DRV8833_PID_DERIVATIVE_GAIN;

    output = DRV8833_PWM_FREQUENCY * (derivative_term + integral_term);
    output = (output > DRV8833_MAX_PWM_VALUE) ? DRV8833_MAX_PWM_VALUE : output;
    output = (output < DRV8833_MIN_PWM_VALUE) ? DRV8833_MIN_PWM_VALUE : output;

    gpioSetPwmDutyCycle(DRV8833_MOTOR_A_PIN, output);
    gpioSetPwmDutyCycle(DRV8833_MOTOR_B_PIN, output);
}

void main() {
    if (!init_pigpio()) {
        printf("Failed to initialize pigpio\n");
        return;
    }

    if (!init_encoder()) {
        printf("Failed to initialize encoder pins\n");
        cleanup_pigpio();
        return;
    }

    while (true) {
        update_encoder_ticks();
        update_pi_controller_values();
        update_motor_speed();

        printf("Encoder A: %u\n", encoder_a_count);
        printf("Encoder B: %u\n", encoder_b_count);

        printf("Motor A RPM: %.2f\n", motor_a_count / DRV8833_ENCODER_COUNTS_PER_REV * DRV8833_MAX_PWM_VALUE);
        printf("Motor B RPM: %.2f\n", motor_b_count / DRV8833_ENCODER_COUNTS_PER_REV * DRV8833_MAX_PWM_VALUE);

        printf("PWM duty cycle for motor A: %u\n", (int)gpioGetPwmDutyCycle(DRV8833_MOTOR_A_PIN));
        printf("PWM duty cycle for motor B: %u\n", (int)gpioGetPwmDutyCycle(DRV8833_MOTOR_B_PIN));

        sleep(1);
    }
}

