#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/input.h>
#include <linux/gpio.h>

#define RELAY_PIN 17
#define TOUCH_SENSOR_PIN 4
#define DEBOUNCE_TIMEOUT 50

int main(int argc, char *argv[]) {
    int rc;
    struct gpio *gpio;
    struct gpio_desc desc;
    struct input_dev *input_dev;
    struct input_absinfo abs_info;
    char buffer[32];
    char *debounce_time_str;
    int debounce_time;

    if (argc < 2) {
        printf("Usage: %s <debounce_time_ms>\n", argv[0]);
        return 1;
    }

    debounce_time_str = argv[1];
    debounce_time = atoi(debounce_time_str);

    if (debounce_time < 1 || debounce_time > 1000) {
        printf("Invalid debounce time. Please enter a value between 1 and 1000 ms.\n");
        return 1;
    }

    if ((rc = gpioInitialise()) != 0) {
        printf("Failed to initialize pigpio: %s\n", gpioErrorStr(rc));
        return 1;
    }

    gpio = gpioOpen(RELAY_PIN);
    if (!gpio) {
        printf("Failed to open GPIO %d: %s\n", RELAY_PIN, gpioErrorStr(rc));
        return 1;
    }

    memset(&desc, 0, sizeof(desc));
    desc.flags = GPIOF_IN;
    desc.type = GPIO_TYPE_DIGITAL;
    desc.dir = GPIO_DIR_IN;
    desc.value = 0;
    desc.debounce_time = debounce_time;

    if ((rc = gpioSetMode(gpio, desc)) != 0) {
        printf("Failed to set GPIO mode: %s\n", gpioErrorStr(rc));
        gpioClose(gpio);
        return 1;
    }

    if ((rc = gpioSetValue(gpio, 1)) != 0) {
        printf("Failed to set GPIO value: %s\n", gpioErrorStr(rc));
        gpioClose(gpio);
        return 1;
    }

    if ((rc = gpioGetValue(gpio, &desc.value)) != 0) {
        printf("Failed to get GPIO value: %s\n", gpioErrorStr(rc));
        gpioClose(gpio);
        return 1;
    }

    if (desc.value == 0) {
        printf("Touch sensor is not connected or not grounded.\n");
        gpioClose(gpio);
        return 1;
    }

    input_dev = gpioGetInputDev(gpio);
    if (!input_dev) {
        printf("Failed to get input device: %s\n", gpioErrorStr(rc));
        gpioClose(gpio);
        return 1;
    }

    if ((rc = input_dev_setup(input_dev)) != 0) {
        printf("Failed to setup input device: %s\n", gpioErrorStr(rc));
        gpioClose(gpio);
        return 1;
    }

    if ((rc = input_dev_register(input_dev)) != 0) {
        printf("Failed to register input device: %s\n", gpioErrorStr(rc));
        input_dev_unregister(input_dev);
        gpioClose(gpio);
        return 1;
    }

    input_dev_release(input_dev);

    while (1) {
        if (input_dev_read(input_dev, &abs_info) == 0) {
            if (abs_info.absmin == abs_info.absmax) {
                if (desc.value == 0) {
                    gpioWrite(gpio, 1);
                    printf("Relay: ON\n");
                    sleep(1);
                    gpioWrite(gpio, 0);
                    printf("Relay: OFF\n");
                }
            } else {
                if (desc.value == 1) {
                    gpioWrite(gpio, 1);
                    printf("Relay: ON\n");
                    sleep(1);
                    gpioWrite(gpio, 0);
                    printf("Relay: OFF\n");
                }
            }
        }

        sleep(DEBOUNCE_TIMEOUT);
    }

    gpioClose(gpio);
    input_dev_unregister(input_dev);
    input_dev_release(input_dev);

    return 0;
}

