#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/input.h>
#include <linux/uinput.h>
#include <pigpio.h>

#define PULSE_WIDTH_MIN 500
#define PULSE_WIDTH_MAX 2500

int main() {
    int fd;
    int angle = 90;
    int pulseWidth = 1500;
    int angleClamped = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    fd = open("/dev/input/event0", O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open input device.\n");
        return 1;
    }

    struct input_event event;
    while (1) {
        if (read(fd, &event, sizeof(event)) != sizeof(event)) {
            fprintf(stderr, "Failed to read input event.\n");
            return 1;
        }

        if (event.type == 1 && event.code == 6) {
            if (event.value == 1) {
                angle++;
                if (angle > 180) {
                    angle = 180;
                }
            } else if (event.value == 0) {
                angle--;
                if (angle < 0) {
                    angle = 0;
                }
            }
        }

        if (angle != angleClamped) {
            pulseWidth = angleClamped * (PULSE_WIDTH_MAX - PULSE_WIDTH_MIN) / 180 + PULSE_WIDTH_MIN;
            if (pulseWidth < 500) {
                pulseWidth = 500;
            } else if (pulseWidth > 2500) {
                pulseWidth = 2500;
            }

            if (gpioSetPWMfrequency(18, 50) < 0) {
                fprintf(stderr, "Failed to set PWM frequency.\n");
                return 1;
            }

            if (gpioSetPWM(18, pulseWidth) < 0) {
                fprintf(stderr, "Failed to set PWM.\n");
                return 1;
            }

            gpioDelay(20); // Wait for PWM to start

            if (gpioPulseWidth(18, pulseWidth) < 0) {
                fprintf(stderr, "Failed to set pulse width.\n");
                return 1;
            }

            gpioDelay(20); // Wait for PWM to settle

            if (gpioGetPWM(18, &pulseWidth) < 0) {
                fprintf(stderr, "Failed to get pulse width.\n");
                return 1;
            }

            if (pulseWidth != angleClamped * (PULSE_WIDTH_MAX - PULSE_WIDTH_MIN) / 180 + PULSE_WIDTH_MIN) {
                fprintf(stderr, "Angle does not match the calculated value.\n");
                return 1;
            }

            angleClamped = angle;
            printf("Angle: %d\n", angle);
        }

        if (read(fd, &event, sizeof(event)) != sizeof(event)) {
            fprintf(stderr, "Failed to read input event.\n");
            return 1;
        }
    }

    gpioTerminate();
    close(fd);
    return 0;
}

