#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stddef.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <linux/i2c.h>
#include <linux/delay.h>
#include <linux/time.h>

#define A3144_GPIO_PIN 17
#define A3144_I2C_ADDR 0x1A

int main() {
    int chip_fd;
    struct gpiod_chip_info chip_info;
    struct gpiod_line_request_info line_info;
    struct timespec start_time, end_time;
    struct i2c_msg i2c_msgs[2];
    uint16_t i2c_data;
    int ret;

    // Initialize libgpiod
    if (gpiod_chip_open(&chip_fd, A3144_GPIO_PIN, &chip_info) < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_get_errmsg(chip_fd));
        return 1;
    }

    // Request input on GPIO 17 with internal pull-up
    if (gpiod_line_request_input_flags(chip_fd, A3144_GPIO_PIN, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request input on GPIO 17: %s\n", gpiod_get_errmsg(chip_fd));
        gpiod_chip_close(chip_fd);
        return 1;
    }

    // Set up debounce window
    line_info.flags = GPIOD_LINE_EVENT_WAIT_MODE_EDGE | GPIOD_LINE_EVENT_WAIT_TIME_2MS;
    line_info.debounce_window_usec = 2000;

    // Wait for the rising edge of the A3144 Hall-effect sensor
    if (gpiod_line_event_wait(chip_fd, A3144_GPIO_PIN, &line_info, &start_time) < 0) {
        fprintf(stderr, "Failed to wait for the rising edge of GPIO 17: %s\n", gpiod_get_errmsg(chip_fd));
        gpiod_chip_close(chip_fd);
        return 1;
    }

    // Wait for the falling edge of the A3144 Hall-effect sensor
    if (gpiod_line_event_wait(chip_fd, A3144_GPIO_PIN, &line_info, &end_time) < 0) {
        fprintf(stderr, "Failed to wait for the falling edge of GPIO 17: %s\n", gpiod_get_errmsg(chip_fd));
        gpiod_chip_close(chip_fd);
        return 1;
    }

    // Calculate RPM
    double pulse_count = (double) (end_time.tv_sec - start_time.tv_sec) * (double) (1000000000.0 / HZ);
    int rpm = (int) (pulse_count / 5.0) * 60.0;

    // Append RPM to motor_rpm.log
    FILE *log_file = fopen("motor_rpm.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open motor_rpm.log: %s\n", strerror(errno));
        gpiod_chip_close(chip_fd);
        return 1;
    }

    fprintf(log_file, "%.2f,%.0f\n", rpm, rpm);
    fclose(log_file);

    // Print RPM to stdout
    printf("Current RPM: %.2f\n", rpm);

    // Close GPIO line and chip
    gpiod_line_release(chip_fd, A3144_GPIO_PIN);
    gpiod_chip_close(chip_fd);

    return 0;
}

