#define RELAY_PIN 17
#define TOUCH_SENSOR_PIN 4

volatile sig_atomic_t touch_high_time_start = 0;
volatile sig_atomic_t touch_high_time_end = 0;
volatile sig_atomic_t relay_state = 1;

int main() {
    int err;
    int relay_fd;
    int touch_sensor_fd;
    struct gpio *gpio;

    // Initialize pigpio library
    if ((err = gpioInitialise()) != 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", gpioErrorStr(err));
        exit(EXIT_FAILURE);
    }

    // Set GPIO mode for touch sensor and relay
    if ((err = gpioSetMode(TOUCH_SENSOR_PIN, PI_OUTPUT)) != 0) {
        fprintf(stderr, "Error setting GPIO mode for touch sensor: %s\n", gpioErrorStr(err));
        exit(EXIT_FAILURE);
    }
    if ((err = gpioSetMode(RELAY_PIN, PI_OUTPUT)) != 0) {
        fprintf(stderr, "Error setting GPIO mode for relay: %s\n", gpioErrorStr(err));
        exit(EXIT_FAILURE);
    }

    // Open GPIO file descriptors
    if ((touch_sensor_fd = open("/dev/gpiogpio0", O_RDWR)) < 0) {
        fprintf(stderr, "Error opening GPIO file descriptor: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    if ((relay_fd = open("/dev/gpiogpio0", O_WRONLY)) < 0) {
        fprintf(stderr, "Error opening relay file descriptor: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    if ((gpio = gpioOpen(touch_sensor_fd)) == NULL) {
        fprintf(stderr, "Error opening GPIO: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        // Read touch sensor state
        if ((err = gpioRead(touch_sensor_fd, &touch_high_time_start)) != 0) {
            fprintf(stderr, "Error reading touch sensor state: %s\n", gpioErrorStr(err));
            exit(EXIT_FAILURE);
        }

        // Check if touch is HIGH
        if (touch_high_time_start > touch_high_time_end) {
            if (relay_state == 1) {
                gpioWrite(relay_fd, 0);
            }
            relay_state = 1 - relay_state;
            if (relay_state) {
                gpioWrite(relay_fd, 1);
            }
        }

        // Check if touch is LOW for more than 10 seconds
        if (touch_high_time_end > 10) {
            gpioWrite(relay_fd, 0);
            touch_high_time_start = touch_high_time_end;
            relay_state = 1;
        }

        // Wait 50 ms before reading again
        sleep(50);
    }

    // Cleanup
    gpioClose(gpio);
    close(touch_sensor_fd);
    close(relay_fd);
    gpioTerminate();

    return 0;
}

// Signal handlers
void sigint_handler(int signum) {
    printf("Received SIGINT signal\n");
    exit(EXIT_SUCCESS);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM signal\n");
    exit(EXIT_SUCCESS);
}

