#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/input.h>
#include <linux/uaccess.h>
#include <linux/time.h>
#include <linux/gpio.h>
#include <linux/spi/spi.h>

#define GPIO_LOCK_PIN 17
#define GPIO_READER_PIN 27
#define TIMESTAMP_FORMAT "%Y-%m-%dT%H:%M:%S"

int gpioInitialise() {
    int fd;
    int ret;

    fd = gpioOpen(GPIO_LOCK_PIN);
    if (fd < 0) {
        perror("Failed to open GPIO lock pin");
        return -1;
    }

    ret = gpioSetMode(fd, GPIO_OUTPUT);
    if (ret < 0) {
        perror("Failed to set GPIO pin mode");
        gpioClose(fd);
        return -1;
    }

    ret = gpioWrite(fd, GPIO_LOCK_PIN, GPIO_PIN_LOW);
    if (ret < 0) {
        perror("Failed to set GPIO pin to low");
        gpioClose(fd);
        return -1;
    }

    ret = gpioDelay(50);
    if (ret < 0) {
        perror("Failed to delay");
        gpioClose(fd);
        return -1;
    }

    ret = gpioWrite(fd, GPIO_LOCK_PIN, GPIO_PIN_HIGH);
    if (ret < 0) {
        perror("Failed to set GPIO pin to high");
        gpioClose(fd);
        return -1;
    }

    return 0;
}

int spiOpen() {
    int fd;
    int ret;

    fd = spiOpen(0);
    if (fd < 0) {
        perror("Failed to open SPI bus");
        return -1;
    }

    ret = spiSetBitOrder(fd, SPI_LSBFIRST);
    if (ret < 0) {
        perror("Failed to set SPI bit order");
        spiClose(fd);
        return -1;
    }

    ret = spiSetDataMode(fd, SPI_MODE_0);
    if (ret < 0) {
        perror("Failed to set SPI data mode");
        spiClose(fd);
        return -1;
    }

    ret = spiSetClockDivider(fd, SPI_CLOCK_DIVIDER_FREQ_HZ(1));
    if (ret < 0) {
        perror("Failed to set SPI clock divider");
        spiClose(fd);
        return -1;
    }

    ret = spiOpenClient(fd, 0);
    if (ret < 0) {
        perror("Failed to open SPI client");
        spiClose(fd);
        return -1;
    }

    return 0;
}

int spiXfer(int fd, const void *txdata, size_t len) {
    int ret;
    int tx_buf[2];
    int rx_buf[2];

    tx_buf[0] = (uint8_t)(len & 0xFF);
    tx_buf[1] = (uint8_t)((len >> 8) & 0xFF);

    ret = spiWrite(fd, tx_buf, 2);
    if (ret < 0) {
        perror("Failed to write to SPI client");
        return -1;
    }

    ret = spiRead(fd, rx_buf, 2);
    if (ret < 0) {
        perror("Failed to read from SPI client");
        return -1;
    }

    return 0;
}

int gpioWrite(int fd, int pin, int value) {
    int ret;

    ret = ioctl(fd, GPIO_IOC_WBITS, GPIO_PIN_SET_LOW);
    if (ret < 0) {
        perror("Failed to set GPIO pin to low");
        return -1;
    }

    ret = ioctl(fd, GPIO_IOC_WBITS, GPIO_PIN_HIGH);
    if (ret < 0) {
        perror("Failed to set GPIO pin to high");
        return -1;
    }

    return 0;
}

void gpioTerminate() {
    gpioClose(GPIO_LOCK_PIN);
    gpioClose(GPIO_READER_PIN);
}

int main() {
    int fd;
    int ret;
    struct input_event event;
    struct input_dev *input_dev;
    char buffer[10];

    if (gpioInitialise() < 0) {
        perror("Failed to initialise GPIO");
        return -1;
    }

    fd = spiOpen();
    if (fd < 0) {
        perror("Failed to open SPI bus");
        gpioTerminate();
        return -1;
    }

    ret = spiXfer(fd, (const void *)&event, sizeof(event));
    if (ret < 0) {
        perror("Failed to read from SPI client");
        gpioTerminate();
        return -1;
    }

    input_dev = input_register_device(fd, "gpio_reader", 0);
    if (input_dev == NULL) {
        perror("Failed to register input device");
        gpioTerminate();
        return -1;
    }

    input_set_abs_value(input_dev, GPIO_READER_PIN, event.code.abs);

    gpioWrite(fd, GPIO_READER_PIN, event.code.value);

    gpioTerminate();

    return 0;
}

