#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/input.h>
#include <pigpio.h>

#define RELAY_GPIO 18
#define RELAY_PIN 17
#define LOG_FILE "door_events.log"
#define DELAY_MS 50
#define RATE_LIMIT_MS 2000

int main() {
    int ret;
    int fd;
    struct input_event event;
    struct timespec ts_start, ts_end;
    char log_file[128];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed with error code %d\n", gpioGetError());
        return 1;
    }

    // Open log file
    snprintf(log_file, sizeof(log_file), "%s", LOG_FILE);
    fd = open(log_file, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", log_file);
        return 1;
    }

    // Set up rate limiting
    int prev_motion_time = 0;
    int prev_motion_count = 0;
    int rate_limit_count = 0;

    // Main loop
    while (1) {
        // Poll for motion events
        ret = gpioRead(RELAY_GPIO, &event, 1);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to read from GPIO: %s\n", strerror(errno));
            return 1;
        }

        // Check if motion is detected
        if (event.type == INPUT_MOUSE) {
            if (event.code == BTN_0) {
                // Unlock the door
                unlock_door();

                // Log the event
                struct timespec ts;
                gettimeofday(&ts, NULL);
                ts_start = ts;
                ret = write(fd, &event, sizeof(event));
                if (ret < 0) {
                    fprintf(stderr, "Error: Failed to log motion event: %s\n", strerror(errno));
                    return 1;
                }
                ts_end = ts;
                int elapsed_ms = (int)(ts_end.tv_sec - ts_start.tv_sec) * 1000 + (int)(ts_end.tv_nsec - ts_start.tv_nsec) / 1000000;
                printf("Motion detected at %d.%03d\n", elapsed_ms, prev_motion_count);
                prev_motion_count++;

                // Reset rate limit
                prev_motion_time = 0;
            }
        }

        // Check rate limit
        if (prev_motion_time > 0) {
            if (millis() - prev_motion_time >= RATE_LIMIT_MS) {
                rate_limit_count = 0;
            } else {
                rate_limit_count++;
            }
            if (rate_limit_count >= 2) {
                sleep(1000);
                rate_limit_count = 0;
            }
        }

        // Check if motion is still detected
        if (event.type == INPUT_MOUSE && event.code == BTN_0) {
            prev_motion_time = millis();
        }

        // Release relay
        gpioWrite(RELAY_GPIO, GPIO_UNUSED);
    }

    // Cleanup
    gpioTerminate();
    close(fd);
    return 0;
}

