#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/gpiod.h>

#define SELENOID_PIN 27
#define THRESHOLD 10.0

int main() {
    int error;
    struct gpiod_event_data event_data;
    struct gpiod_event event;
    char calibration_file[256] = "calibration.txt";
    char scale[10] = "1.0";
    char offset[10] = "0.0";
    char weight_log_file[256] = "weight_log.txt";
    FILE *weight_log;
    int i, j, k, timeout;
    struct timespec start_time, end_time;
    struct timespec start_calibration_time, end_calibration_time;
    double scale_factor, offset;

    // Initialize pigpio with error checking
    if ((error = gpiod_init(4, GPIDO_MODE_OUTPUT)) < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", gpio_strerror(error));
        return 1;
    }

    if ((error = gpiod_set_dir(4, GPIDO_OUTPUT)) < 0) {
        fprintf(stderr, "Error setting output direction for GPIO4: %s\n", gpio_strerror(error));
        gpiod_exit(4);
        return 1;
    }

    if ((error = gpiod_set_value(4, 1)) < 0) {
        fprintf(stderr, "Error setting GPIO4 to high: %s\n", gpio_strerror(error));
        gpiod_exit(4);
        return 1;
    }

    // Load calibration data from calibration.txt or use defaults
    if (access(calibration_file, F_OK) == -1) {
        FILE *fp = fopen(calibration_file, "r");
        if (fp) {
            fgets(calibration_file, sizeof(calibration_file), fp);
            fclose(fp);
        } else {
            fprintf(stderr, "Error opening calibration file: %s\n", calibration_file);
            return 1;
        }
    }

    // Read calibration data
    sscanf(calibration_file, "scale=%s offset=%s", scale, offset);
    sscanf(scale, "%f", &scale_factor);
    sscanf(offset, "%f", &offset);

    // Perform one-time startup calibration
    for (i = 0; i < 100; i++) {
        // Reset the load cell
        error = gpiod_set_value(4, 0);
        if (error < 0) {
            fprintf(stderr, "Error resetting load cell: %s\n", gpio_strerror(error));
            return 1;
        }

        // Wait for the load cell to settle
        timeout = 0.5;
        do {
            error = gpiod_get_value(4, &value);
            if (error < 0) {
                fprintf(stderr, "Error reading value from load cell: %s\n", gpio_strerror(error));
                return 1;
            }
        } while (value == 0);

        // Read the raw value from the load cell
        error = gpiod_get_event_data(4, &event_data);
        if (error < 0) {
            fprintf(stderr, "Error reading event data: %s\n", gpio_strerror(error));
            return 1;
        }

        // Calculate the offset
        event_data.value = event_data.value * scale_factor + offset;

        // Log the reading with a timestamp
        time_t now = time(NULL);
        struct tm *ltm = localtime(&now);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);
        fprintf(weight_log, "%.3f,%.3f,%.3f\n", event_data.value, timestamp, event_data.value);

        // Wait for the next iteration
        sleep(0.5);
    }

    // Save calibration data back to calibration.txt
    FILE *fp = fopen(calibration_file, "w");
    if (fp) {
        fprintf(fp, "scale=%s offset=%s\n", scale, offset);
        fclose(fp);
    } else {
        fprintf(stderr, "Error opening calibration file for writing: %s\n", calibration_file);
        return 1;
    }

    // Perform the weight reading loop
    while (1) {
        // Wait for the next iteration
        sleep(0.5);

        // Read the raw value from the load cell
        error = gpiod_get_event_data(4, &event_data);
        if (error < 0) {
            fprintf(stderr, "Error reading event data: %s\n", gpio_strerror(error));
            return 1;
        }

        // Calculate the weight
        event_data.value = event_data.value * scale_factor + offset;

        // Check if the weight exceeds the threshold
        if (event_data.value > THRESHOLD) {
            // Drive the solenoid pin high to engage the lock
            error = gpiod_set_value(27, 1);
            if (error < 0) {
                fprintf(stderr, "Error setting solenoid pin high: %s\n", gpio_strerror(error));
                return 1;
            }
        } else {
            // Drive the solenoid pin low to release the lock
            error = gpiod_set_value(27, 0);
            if (error < 0) {
                fprintf(stderr, "Error setting solenoid pin low: %s\n", gpio_strerror(error));
                return 1;
            }
        }

        // Log the reading with a timestamp
        time_t now = time(NULL);
        struct tm *ltm = localtime(&now);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);
        fprintf(weight_log, "%.3f,%.3f,%.3f\n", event_data.value, timestamp, event_data.value);
    }

    // Cleanup
    gpiod_exit(4);
    return 0;
}

