#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <syslog.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_PWM_FILE "/sys/class/gpio/gpio27/pwm"
#define GPIO_PWM_PERIOD 1000000
#define GPIO_PWM_FREQ 1000

int main() {
    int fd, ret;
    int rainSensorPin = 4;
    int motorDriverPin1 = 17;
    int motorDriverPin2 = 18;
    int pwmEnablePin = 27;
    int pwmHandle;
    int motorRunning = 0;
    int motorStopTime = 0;
    struct timespec stopTime;
    struct timespec startTime;
    struct timespec lastReadTime;
    int rainCount = 0;
    int rainThreshold = 3;
    int logFileDescriptor;
    char logFilePath[128];

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        exit(EXIT_FAILURE);
    }

    // Set up the GPIO pins
    if (gpioSetMode(rainSensorPin, PI_OUT) < 0) {
        perror("Failed to set GPIO pin as output");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPwmFrequency(pwmEnablePin, GPIO_PWM_FREQ) < 0) {
        perror("Failed to set PWM frequency");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPwm(pwmEnablePin, 0, GPIO_PWM_PERIOD) < 0) {
        perror("Failed to set PWM duty cycle");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPwm(pwmEnablePin, 0, GPIO_PWM_PERIOD / 2) < 0) {
        perror("Failed to set PWM duty cycle");
        exit(EXIT_FAILURE);
    }

    // Set up the motor driver pins
    if (gpioSetMode(motorDriverPin1, PI_OUT) < 0) {
        perror("Failed to set GPIO pin as output");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(motorDriverPin2, PI_OUT) < 0) {
        perror("Failed to set GPIO pin as output");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPwmFrequency(pwmEnablePin, GPIO_PWM_FREQ) < 0) {
        perror("Failed to set PWM frequency");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPwm(pwmEnablePin, 0, GPIO_PWM_PERIOD) < 0) {
        perror("Failed to set PWM duty cycle");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPwm(pwmEnablePin, 0, GPIO_PWM_PERIOD / 2) < 0) {
        perror("Failed to set PWM duty cycle");
        exit(EXIT_FAILURE);
    }

    // Set up syslog
    if (syslog(LOG_DAEMON | LOG_NOTIFY, "Window control started") < 0) {
        perror("Failed to set up syslog");
        exit(EXIT_FAILURE);
    }

    // Set up log file
    snprintf(logFilePath, sizeof(logFilePath), "/var/log/window_control.log");
    logFileDescriptor = open(logFilePath, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (logFileDescriptor < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read the rain sensor
        if (readRainSensor() < 0) {
            perror("Failed to read rain sensor");
            exit(EXIT_FAILURE);
        }

        // Check if the rain threshold has been met
        if (rainCount >= rainThreshold) {
            // Close the window
            closeWindow();

            // Log the rain event
            logRainEvent();

            // Wait for 60 seconds before checking again
            sleep(60);
        } else {
            // Wait for 5 seconds before checking again
            sleep(5);
        }
    }

    // Stop the motor
    stopMotor();

    // Release GPIO resources
    gpioRelease();

    // Close the log file
    close(logFileDescriptor);

    // Exit
    return 0;
}

// Function to read the rain sensor
int readRainSensor() {
    int ret;
    struct timespec start, stop;

    // Wait for the sensor to settle
    if (nanosleep(&start, &stop) < 0) {
        perror("Failed to wait for sensor to settle");
        exit(EXIT_FAILURE);
    }

    // Read the sensor value
    ret = read(GPIO_PWM_FILE, &stopTime, sizeof(stopTime));
    if (ret < 0) {
        perror("Failed to read PWM file");
        exit(EXIT_FAILURE);
    }

    // Wait for the sensor to settle again
    if (nanosleep(&stop, &start) < 0) {
        perror("Failed to wait for sensor to settle");
        exit(EXIT_FAILURE);
    }

    // Check the sensor value
    if (stopTime.tv_sec == 0 && stopTime.tv_nsec >= 1000000) {
        return 1; // Rain detected
    }

    return 0; // Rain not detected
}

// Function to close the window
void closeWindow() {
    // Close the motor
    closeMotor();

    // Close the log file
    close(logFileDescriptor);

    // Stop syslog
    syslog(LOG_NOTIFY, "Window control stopped");
}

// Function to stop the motor
void stopMotor() {
    if (gpioSetPwm(pwmEnablePin, 0, 0) < 0) {
        perror("Failed to set PWM duty cycle to 0");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPwm(pwmEnablePin, 0, 0) < 0) {
        perror("Failed to set PWM duty cycle to 0");
        exit(EXIT_FAILURE);
    }

    // Wait for the motor to stop
    sleep(1);
}

// Function to release GPIO resources
void gpioRelease() {
    if (gpioUnsetMode(motorDriverPin1) < 0) {
        perror("Failed to set GPIO mode to INPUT");
        exit(EXIT_FAILURE);
    }

    if (gpioUnsetMode(motorDriverPin2) < 0) {
        perror("Failed to set GPIO mode to INPUT");
        exit(EXIT_FAILURE);
    }

    if (gpioUnsetPwm(pwmEnablePin) < 0) {
        perror("Failed to set GPIO PWM to 0");
        exit(EXIT_FAILURE);
    }
}

// Function to log the rain event
void logRainEvent() {
    struct timespec now;

    // Get the current time
    if (clock_gettime(CLOCK_MONOTONIC, &now) < 0) {
        perror("Failed to get current time");
        exit(EXIT_FAILURE);
    }

    // Log the rain event
    char logMessage[128];
    snprintf(logMessage, sizeof(logMessage), "Rain detected at %s", ctime(&now.tv_sec));
    if (syslog(LOG_DAEMON | LOG_NOTIFY, logMessage) < 0) {
        perror("Failed to log rain event");
        exit(EXIT_FAILURE);
    }
}

