#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLK_PIN 17
#define HX711_DATA_GPIO_NUM 29
#define HX711_CLK_GPIO_NUM 27
#define CALIBRATION_THRESHOLD 5.0

int calibration_factor = 1;

int main() {
    int ret;
    int file_handle;
    char calibration_file[128];
    char security_log_file[128];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    // Open calibration file
    snprintf(calibration_file, sizeof(calibration_file), "/tmp/calibration.txt");
    file_handle = open(calibration_file, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (file_handle < 0) {
        fprintf(stderr, "Error: Failed to open calibration file\n");
        return 1;
    }

    // Open security log file
    snprintf(security_log_file, sizeof(security_log_file), "/var/log/security.log");
    file_handle = open(security_log_file, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file_handle < 0) {
        fprintf(stderr, "Error: Failed to open security log file\n");
        return 1;
    }

    // Initialize HX711
    if (hx711Initialize() < 0) {
        fprintf(stderr, "Error: HX711 initialization failed\n");
        return 1;
    }

    // Set up GPIOs
    gpioSetMode(HX711_DATA_GPIO_NUM, PI_OUTPUT);
    gpioSetMode(HX711_CLK_GPIO_NUM, PI_OUTPUT);

    // Set up solenoid lock GPIO
    gpioSetMode(GPIO27, PI_OUTPUT);

    // Set up calibration threshold
    calibration_factor = CALIBRATION_THRESHOLD;

    // Main loop
    while (1) {
        // Read weight from HX711
        int raw_weight = hx711ReadRaw(HX711_DATA_PIN, HX711_CLK_PIN);

        // Check for HX711 communication timeout
        if (raw_weight > 100) {
            fprintf(stderr, "Error: HX711 communication timeout\n");
            continue;
        }

        // Check if weight exceeds calibration threshold
        if (raw_weight > calibration_factor * 1000) {
            // Log the event
            char timestamp[32];
            time_t now = time(NULL);
            struct tm *ltm = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);
            char log_message[128];
            snprintf(log_message, sizeof(log_message), "Weight: %.2f kg, Timestamp: %s\n", raw_weight, timestamp);
            write(file_handle, log_message, strlen(log_message) + 1);

            // Drive solenoid lock
            gpioSetValue(GPIO27, 1);
            sleep(1);
            gpioSetValue(GPIO27, 0);

            // Log the event
            timestamp[0] = '\0';
            snprintf(log_message, sizeof(log_message), "Solenoid lock driven for 5 seconds\n");
            write(file_handle, log_message, strlen(log_message) + 1);
        }

        // Wait for user input
        printf("Enter weight in kg (or 'q' to quit): ");
        char input[32];
        fgets(input, sizeof(input), stdin);
        if (input[0] == 'q') {
            break;
        }

        // Save calibration factor to file
        snprintf(calibration_file, sizeof(calibration_file), "/tmp/calibration.txt");
        char calibration_message[128];
        sprintf(calibration_message, "%.2f\n", calibration_factor);
        write(file_handle, calibration_message, strlen(calibration_message) + 1);
    }

    // Clean up
    gpioTerminate();
    close(file_handle);
    unlink(calibration_file);
    unlink(security_log_file);

    return 0;
}

