#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x1A // Keywish KY-022 IR sensor I2C address

#define GPIO_FILE "/dev/gpiochip0"
#define RELAY_FILE "/dev/gpiochip1"

#define SENSOR_GPIO 16
#define RELAY_GPIO 20

#define SENSOR_NAME "KY-022"
#define RELAY_NAME "SRD-05VDC-SL"

#define RELAY_STATE_OFF 0
#define RELAY_STATE_ON 1

#define RELAY_EVENT_LOG_FILE "relay_events.log"

#define ISO8601_TIMESTAMP_FORMAT "%Y-%m-%dT%H:%M:%S"

int main() {
    int chip_fd;
    int sensor_fd;
    int relay_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpiod_chip *chip;
    struct gpiod_line *sensor_line;
    struct gpiod_line *relay_line;
    struct timespec timestamp;
    char relay_state_str[10];
    char log_message[100];
    int error;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open the chip by its name
    chip = gpiod_chip_open_by_name(I2C_BUS, I2C_ADDR, SENSOR_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open chip for sensor %s\n", SENSOR_NAME);
        gpiod_exit();
        return 1;
    }

    // Open the sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (sensor_line == NULL) {
        fprintf(stderr, "Failed to get line for sensor %s\n", SENSOR_NAME);
        gpiod_chip_release(chip);
        gpiod_exit();
        return 1;
    }

    // Open the relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (relay_line == NULL) {
        fprintf(stderr, "Failed to get line for relay\n");
        gpiod_chip_release(chip);
        gpiod_exit();
        return 1;
    }

    // Request GPIO inputs/outputs
    if (gpiod_line_request_bulk_inputs(sensor_line, 1) < 0) {
        fprintf(stderr, "Failed to request GPIO inputs for sensor\n");
        gpiod_chip_release(chip);
        gpiod_exit();
        return 1;
    }

    if (gpiod_line_request_bulk_outputs(relay_line, 1) < 0) {
        fprintf(stderr, "Failed to request GPIO outputs for relay\n");
        gpiod_chip_release(chip);
        gpiod_exit();
        return 1;
    }

    // Get the sensor's state
    if (gpiod_line_get_value(sensor_line, &sensor_state) < 0) {
        fprintf(stderr, "Failed to get sensor state\n");
        gpiod_chip_release(chip);
        gpiod_exit();
        return 1;
    }

    // Check if the sensor is active-low
    if (sensor_state == 0) {
        sensor_state = 1;
    }

    // Log the initial state
    timestamp.tv_sec = time(NULL);
    timestamp.tv_nsec = 0;
    strftime(relay_state_str, sizeof(relay_state_str), "%s", &timestamp);
    strcat(log_message, "Initial relay state: ");
    strcat(log_message, relay_state_str);
    log_message[strlen(log_message) - 1] = '\0'; // Remove trailing newline

    // Open the log file
    if ((relay_events_log = fopen(RELAY_EVENT_LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_release(chip);
        gpiod_exit();
        return 1;
    }

    // Log the initial state
    timestamp.tv_sec = time(NULL);
    timestamp.tv_nsec = 0;
    strftime(relay_state_str, sizeof(relay_state_str), "%s", &timestamp);
    strcat(log_message, "Initial relay state: ");
    strcat(log_message, relay_state_str);
    fprintf(relay_events_log, "%s\n", log_message);
    fclose(relay_events_log);

    // Toggle the relay state
    while (1) {
        // Check if the sensor detects an obstacle
        if (sensor_state == 0) {
            sensor_state = 1;
            strftime(relay_state_str, sizeof(relay_state_str), "%s", &timestamp);
            strcat(log_message, "Obstacle detected: ");
            strcat(log_message, relay_state_str);
            fprintf(relay_events_log, "%s\n", log_message);

            // Toggle the relay state
            if (sensor_state == RELAY_STATE_ON) {
                if (gpiod_line_set_value(relay_line, 1) < 0) {
                    fprintf(stderr, "Failed to set relay state to ON\n");
                    continue;
                }
                relay_state_str[0] = '0';
                relay_state_str[1] = '0';
                relay_state_str[2] = '0';
                relay_state_str[3] = '0';
                relay_state_str[4] = '0';
                relay_state_str[5] = '0';
                relay_state_str[6] = '0';
                relay_state_str[7] = '0';
                relay_state_str[8] = '0';
                relay_state_str[9] = '0';
                strftime(relay_state_str + 10, sizeof(relay_state_str) - 10, "%Y-%m-%dT%H:%M:%S", &timestamp);
                strcat(log_message, "Relay state toggled: ");
                strcat(log_message, relay_state_str);
                fprintf(relay_events_log, "%s\n", log_message);
            } else if (sensor_state == RELAY_STATE_OFF) {
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    fprintf(stderr, "Failed to set relay state to OFF\n");
                    continue;
                }
                relay_state_str[0] = '1';
                relay_state_str[1] = '0';
                relay_state_str[2] = '0';
                relay_state_str[3] = '0';
                relay_state_str[4] = '0';
                relay_state_str[5] = '0';
                relay_state_str[6] = '0';
                relay_state_str[7] = '0';
                relay_state_str[8] = '0';
                relay_state_str[9] = '0';
                strftime(relay_state_str + 10, sizeof(relay_state_str) - 10, "%Y-%m-%dT%H:%M:%S", &timestamp);
                strcat(log_message, "Relay state toggled: ");
                strcat(log_message, relay_state_str);
                fprintf(relay_events_log, "%s\n", log_message);
            }
        }

        // Wait for sensor to report an obstacle
        nanosleep(NULL, &timestamp);
    }

    // Release all GPIO lines
    gpiod_chip_release(chip);
    gpiod_exit();

    return 0;
}

