#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>

#include <gpiod.h>

#define VALVE_GPIO 18
#define VALVE_LINE "/dev/gpio18"

volatile sig_atomic_t valve_on = false;

void sigint_handler(int signum) {
    valve_on = false;
}

void sigterm_handler(int signum) {
    valve_on = false;
}

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_value value;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open the chip and line
    if ((fd = gpiod_open(GPIDO_CHIP_DEFAULT, GPIDO_LINE_DEFAULT, &chip)) < 0) {
        fprintf(stderr, "Failed to open chip or line\n");
        gpiod_exit();
        return 1;
    }

    if ((line = gpiod_chip_line(chip, VALVE_GPIO)) < 0) {
        fprintf(stderr, "Failed to open line\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Read configuration file
    FILE *fp = fopen("watering.conf", "r");
    if (!fp) {
        fprintf(stderr, "Failed to open configuration file\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    char line_buffer[256];
    char *duration_str = NULL;
    char *duration_end = NULL;
    int duration_value = 0;

    while (fgets(line_buffer, sizeof(line_buffer), fp) != NULL) {
        if (sscanf(line_buffer, "duration=%s", duration_str) == 1) {
            duration_end = strchr(duration_str, '\n');
            if (duration_end) {
                *duration_end = '\0';
                duration_value = atoi(duration_str);
                if (duration_value >= 1 && duration_value <= 3600) {
                    break;
                }
            }
        }
    }

    fclose(fp);

    // Check if duration is valid
    if (!duration_str) {
        fprintf(stderr, "Invalid duration in watering.conf\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set the valve on
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set line to on\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Wait for configured duration
    struct timespec start_time, end_time;
    start_time.tv_sec = 0;
    start_time.tv_nsec = 1000000;

    if (nanosleep(&start_time, &end_time) < 0) {
        fprintf(stderr, "Failed to wait for duration\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set the valve off
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set line to off\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Clean up
    gpiod_close(fd);
    gpiod_exit();

    return 0;
}

