#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/input.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <time.h>

#include <pigpio.h>

#define MAX_SPEED 255
#define IR_SENSORS_COUNT 3
#define IR_SENSOR_PIN_LEFT 4
#define IR_SENSOR_PIN_RIGHT 17
#define IR_SENSOR_PIN_CENTER 27
#define IR_SENSOR_PWM_PIN_LEFT 22
#define IR_SENSOR_PWM_PIN_RIGHT 23
#define IR_SENSOR_PWM_PIN_BACK 24
#define IR_SENSOR_PWM_PIN_FORWARD 25

int main() {
    int err;
    int motor_speeds[2] = {0, 0};
    struct gpiod_event_data event_data;
    struct gpiod_event_data *event_data_ptr;
    struct timespec start_time, stop_time;
    struct sigaction sa;
    char trace_log_filename[128] = "trace_log.txt";
    FILE *trace_log_file;

    // Initialize pigpio with error checking
    if ((err = pigpio_init()) < 0) {
        fprintf(stderr, "Error initializing pigpio: %d\n", err);
        return 1;
    }

    // Open log file
    if ((trace_log_file = fopen(trace_log_filename, "a")) == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", trace_log_filename);
        return 1;
    }

    // Set up IR sensor pins
    if ((err = gpiod_set_direction(IR_SENSOR_PIN_LEFT, GPIO_OUTPUT)) < 0) {
        fprintf(stderr, "Error setting IR sensor left direction: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_level(IR_SENSOR_PIN_LEFT, GPIO_HIGH)) < 0) {
        fprintf(stderr, "Error setting IR sensor left level: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_direction(IR_SENSOR_PIN_RIGHT, GPIO_OUTPUT)) < 0) {
        fprintf(stderr, "Error setting IR sensor right direction: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_level(IR_SENSOR_PIN_RIGHT, GPIO_HIGH)) < 0) {
        fprintf(stderr, "Error setting IR sensor right level: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_direction(IR_SENSOR_PIN_CENTER, GPIO_OUTPUT)) < 0) {
        fprintf(stderr, "Error setting IR sensor center direction: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_level(IR_SENSOR_PIN_CENTER, GPIO_HIGH)) < 0) {
        fprintf(stderr, "Error setting IR sensor center level: %d\n", err);
        return 1;
    }

    // Set up PWM for motors
    if ((err = gpiod_set_direction(IR_SENSOR_PWM_PIN_LEFT, GPIO_OUTPUT)) < 0) {
        fprintf(stderr, "Error setting PWM left direction: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_level(IR_SENSOR_PWM_PIN_LEFT, GPIO_HIGH)) < 0) {
        fprintf(stderr, "Error setting PWM left level: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_direction(IR_SENSOR_PWM_PIN_RIGHT, GPIO_OUTPUT)) < 0) {
        fprintf(stderr, "Error setting PWM right direction: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_level(IR_SENSOR_PWM_PIN_RIGHT, GPIO_HIGH)) < 0) {
        fprintf(stderr, "Error setting PWM right level: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_direction(IR_SENSOR_PWM_PIN_BACK, GPIO_OUTPUT)) < 0) {
        fprintf(stderr, "Error setting PWM back direction: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_level(IR_SENSOR_PWM_PIN_BACK, GPIO_HIGH)) < 0) {
        fprintf(stderr, "Error setting PWM back level: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_direction(IR_SENSOR_PWM_PIN_FORWARD, GPIO_OUTPUT)) < 0) {
        fprintf(stderr, "Error setting PWM forward direction: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_level(IR_SENSOR_PWM_PIN_FORWARD, GPIO_HIGH)) < 0) {
        fprintf(stderr, "Error setting PWM forward level: %d\n", err);
        return 1;
    }

    // Set up motor control
    if ((err = gpiod_set_level(IR_SENSOR_PWM_PIN_LEFT, GPIO_LOW)) < 0) {
        fprintf(stderr, "Error setting left motor PWM low: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_level(IR_SENSOR_PWM_PIN_RIGHT, GPIO_LOW)) < 0) {
        fprintf(stderr, "Error setting right motor PWM low: %d\n", err);
        return 1;
    }

    // Set up motor speeds
    if ((err = gpiod_set_level(IR_SENSOR_PWM_PIN_LEFT, GPIO_HIGH)) < 0) {
        fprintf(stderr, "Error setting left motor PWM high: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_level(IR_SENSOR_PWM_PIN_RIGHT, GPIO_HIGH)) < 0) {
        fprintf(stderr, "Error setting right motor PWM high: %d\n", err);
        return 1;
    }

    // Set up control law
    for (int i = 0; i < IR_SENSORS_COUNT; i++) {
        while (1) {
            // Read IR sensor values
            int left_sensor_value = gpiod_get_level(IR_SENSOR_PIN_LEFT);
            int right_sensor_value = gpiod_get_level(IR_SENSOR_PIN_RIGHT);
            int center_sensor_value = gpiod_get_level(IR_SENSOR_PIN_CENTER);

            // Apply control law
            if (left_sensor_value == GPIO_LOW && right_sensor_value == GPIO_LOW && center_sensor_value == GPIO_LOW) {
                // Drive straight
                motor_speeds[0] = (MAX_SPEED - 150) / 255;
                motor_speeds[1] = 0;
            } else if (left_sensor_value == GPIO_LOW && right_sensor_value == GPIO_HIGH && center_sensor_value == GPIO_LOW) {
                // Turn right
                motor_speeds[0] = 0;
                motor_speeds[1] = (MAX_SPEED - 150) / 255;
            } else if (left_sensor_value == GPIO_HIGH && right_sensor_value == GPIO_LOW && center_sensor_value == GPIO_LOW) {
                // Turn left
                motor_speeds[0] = 0;
                motor_speeds[1] = -(MAX_SPEED - 150) / 255;
            } else if (left_sensor_value == GPIO_HIGH && right_sensor_value == GPIO_HIGH && center_sensor_value == GPIO_LOW) {
                // Stop both motors
                motor_speeds[0] = 0;
                motor_speeds[1] = 0;
            }

            // Log control cycle
            struct timespec start_time, stop_time;
            gettimeofday(&start_time, NULL);
            // Log control cycle here
            gettimeofday(&stop_time, NULL);
            double elapsed_time = (stop_time.tv_sec - start_time.tv_sec) + (stop_time.tv_usec - start_time.tv_usec) / 1000000.0;
            int sensor_states[2] = {left_sensor_value, right_sensor_value};
            int motor_speeds[2] = {motor_speeds[0], motor_speeds[1]};
            int log_entry[4] = {sensor_states[0], sensor_states[1], motor_speeds[0], motor_speeds[1]};
            int log_entry_len = sizeof(log_entry);

            // Write log entry to file
            if (write(trace_log_file, log_entry, log_entry_len) != log_entry_len) {
                fprintf(stderr, "Error writing log entry: %s\n", strerror(errno));
                return 1;
            }

            // Wait for 10 ms
            usleep(10000);
        }
    }

    // Stop motors
    for (int i = 0; i < IR_SENSORS_COUNT; i++) {
        gpiod_set_level(IR_SENSOR_PWM_PIN_LEFT, GPIO_LOW);
        gpiod_set_level(IR_SENSOR_PWM_PIN_RIGHT, GPIO_LOW);
        gpiod_set_level(IR_SENSOR_PWM_PIN_BACK, GPIO_LOW);
        gpiod_set_level(IR_SENSOR_PWM_PIN_FORWARD, GPIO_LOW);
    }

    // Close log file
    if (close(trace_log_file) < 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return 1;
    }

    // Terminate pigpio
    if (pi_term() < 0) {
        fprintf(stderr, "Error terminating pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Release GPIOs
    for (int i = 0; i < IR_SENSORS_COUNT; i++) {
        gpiod_set_level(IR_SENSOR_PWM_PIN_LEFT, GPIO_HIGH);
        gpiod_set_level(IR_SENSOR_PWM_PIN_RIGHT, GPIO_HIGH);
        gpiod_set_level(IR_SENSOR_PWM_PIN_BACK, GPIO_HIGH);
        gpiod_set_level(IR_SENSOR_PWM_PIN_FORWARD, GPIO_HIGH);
    }
    if (pi_close() < 0) {
        fprintf(stderr, "Error closing pigpio: %s\n", strerror(errno));
        return 1;
    }

    return 0;
}

