    if ((err = gpiod_set_direction(IR_SENSOR_PIN_RIGHT, GPIO_OUTPUT)) < 0) {
        fprintf(stderr, "Error setting IR sensor right direction: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_level(IR_SENSOR_PIN_RIGHT, GPIO_HIGH)) < 0) {
        fprintf(stderr, "Error setting IR sensor right level: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_direction(IR_SENSOR_PIN_CENTER, GPIO_OUTPUT)) < 0) {
        fprintf(stderr, "Error setting IR sensor center direction: %d\n", err);
