    if ((err = gpiod_set_level(IR_SENSOR_PIN_CENTER, GPIO_HIGH)) < 0) {
        fprintf(stderr, "Error setting IR sensor center level: %d\n", err);
        return 1;
    }

    // Set up PWM for motors
    if ((err = gpiod_set_direction(IR_SENSOR_PWM_PIN_LEFT, GPIO_OUTPUT)) < 0) {
        fprintf(stderr, "Error setting PWM left direction: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_level(IR_SENSOR_PWM_PIN_LEFT, GPIO_HIGH)) < 0) {
        fprintf(stderr, "Error setting PWM left level: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_direction(IR_SENSOR_PWM_PIN_RIGHT, GPIO_OUTPUT)) < 0) {
        fprintf(stderr, "Error setting PWM right direction: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_level(IR_SENSOR_PWM_PIN_RIGHT, GPIO_HIGH)) < 0) {
        fprintf(stderr, "Error setting PWM right level: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_direction(IR_SENSOR_PWM_PIN_BACK, GPIO_OUTPUT)) < 0) {
        fprintf(stderr, "Error setting PWM back direction: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_level(IR_SENSOR_PWM_PIN_BACK, GPIO_HIGH)) < 0) {
        fprintf(stderr, "Error setting PWM back level: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_direction(IR_SENSOR_PWM_PIN_FORWARD, GPIO_OUTPUT)) < 0) {
        fprintf(stderr, "Error setting PWM forward direction: %d\n", err);
        return 1;
