    if ((err = gpiod_set_level(IR_SENSOR_PWM_PIN_FORWARD, GPIO_HIGH)) < 0) {
        fprintf(stderr, "Error setting PWM forward level: %d\n", err);
        return 1;
    }

    // Set up motor control
    if ((err = gpiod_set_level(IR_SENSOR_PWM_PIN_LEFT, GPIO_LOW)) < 0) {
        fprintf(stderr, "Error setting left motor PWM low: %d\n", err);
        return 1;
    }
    if ((err = gpiod_set_level(IR_SENSOR_PWM_PIN_RIGHT, GPIO_LOW)) < 0) {
        fprintf(stderr, "Error setting right motor PWM low: %d\n", err);
        return 1;
    }

    // Set up motor speeds
    if ((err = gpiod_set_level(IR_SENSOR_PWM_PIN_LEFT, GPIO_HIGH)) < 0) {
        fprintf(stderr, "Error setting left motor PWM high: %d\n", err);
        return 1;
