            int right_sensor_value = gpiod_get_level(IR_SENSOR_PIN_RIGHT);
            int center_sensor_value = gpiod_get_level(IR_SENSOR_PIN_CENTER);

            // Apply control law
            if (left_sensor_value == GPIO_LOW && right_sensor_value == GPIO_LOW && center_sensor_value == GPIO_LOW) {
                // Drive straight
                motor_speeds[0] = (MAX_SPEED - 150) / 255;
                motor_speeds[1] = 0;
            } else if (left_sensor_value == GPIO_LOW && right_sensor_value == GPIO_HIGH && center_sensor_value == GPIO_LOW) {
