                motor_speeds[0] = 0;
                motor_speeds[1] = (MAX_SPEED - 150) / 255;
            } else if (left_sensor_value == GPIO_HIGH && right_sensor_value == GPIO_LOW && center_sensor_value == GPIO_LOW) {
                // Turn left
                motor_speeds[0] = 0;
