            } else if (left_sensor_value == GPIO_HIGH && right_sensor_value == GPIO_HIGH && center_sensor_value == GPIO_LOW) {
                // Stop both motors
                motor_speeds[0] = 0;
                motor_speeds[1] = 0;
            }

            // Log control cycle
            struct timespec start_time, stop_time;
            gettimeofday(&start_time, NULL);
            // Log control cycle here
            gettimeofday(&stop_time, NULL);
            double elapsed_time = (stop_time.tv_sec - start_time.tv_sec) + (stop_time.tv_usec - start_time.tv_usec) / 1000000.0;
            int sensor_states[2] = {left_sensor_value, right_sensor_value};
            int motor_speeds[2] = {motor_speeds[0], motor_speeds[1]};
            int log_entry[4] = {sensor_states[0], sensor_states[1], motor_speeds[0], motor_speeds[1]};
            int log_entry_len = sizeof(log_entry);

            // Write log entry to file
            if (write(trace_log_file, log_entry, log_entry_len) != log_entry_len) {
                fprintf(stderr, "Error writing log entry: %s\n", strerror(errno));
                return 1;
            }

            // Wait for 10 ms
            usleep(10000);
        }
    }

    // Stop motors
    for (int i = 0; i < IR_SENSORS_COUNT; i++) {
        gpiod_set_level(IR_SENSOR_PWM_PIN_LEFT, GPIO_LOW);
        gpiod_set_level(IR_SENSOR_PWM_PIN_RIGHT, GPIO_LOW);
        gpiod_set_level(IR_SENSOR_PWM_PIN_BACK, GPIO_LOW);
        gpiod_set_level(IR_SENSOR_PWM_PIN_FORWARD, GPIO_LOW);
    }

    // Close log file
    if (close(trace_log_file) < 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return 1;
    }

    // Terminate pigpio
    if (pi_term() < 0) {
        fprintf(stderr, "Error terminating pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Release GPIOs
    for (int i = 0; i < IR_SENSORS_COUNT; i++) {
        gpiod_set_level(IR_SENSOR_PWM_PIN_LEFT, GPIO_HIGH);
        gpiod_set_level(IR_SENSOR_PWM_PIN_RIGHT, GPIO_HIGH);
        gpiod_set_level(IR_SENSOR_PWM_PIN_BACK, GPIO_HIGH);
        gpiod_set_level(IR_SENSOR_PWM_PIN_FORWARD, GPIO_HIGH);
    }
    if (pi_close() < 0) {
        fprintf(stderr, "Error closing pigpio: %s\n", strerror(errno));
        return 1;
    }

    return 0;
}
