#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS_1 1
#define I2C_ADDRESS 0x23
#define RELAY_GPIO_PIN 23

int main() {
    int i2c_fd;
    int relay_fd;
    int i2c_gpio_gpio_fd;
    int lux_reading;
    int relay_state;
    char grow_log_file[] = "grow_log.txt";

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("Error initializing pigpio");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    if ((i2c_fd = pigpioOpen(I2C_BUS_1)) < 0) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Open relay GPIO
    if ((relay_fd = open(Grow_Lamp_Relay_Filename, O_RDWR)) < 0) {
        perror("Error opening relay GPIO file");
        exit(EXIT_FAILURE);
    }

    // Set relay GPIO as output
    if (ioctl(relay_fd, GPIO_SET_DIR, RELAY_GPIO_PIN) < 0) {
        perror("Error setting relay GPIO direction");
        exit(EXIT_FAILURE);
    }

    // Set relay GPIO as active
    if (ioctl(relay_fd, GPIO_SET_VALUE, RELAY_GPIO_PIN) < 0) {
        perror("Error setting relay GPIO value");
        exit(EXIT_FAILURE);
    }

    // Set I2C bus speed to high resolution
    if (piGoToHighResolution(i2c_fd) < 0) {
        perror("Error setting I2C bus to high resolution");
        exit(EXIT_FAILURE);
    }

    // Set I2C delay to 180 ms
    if (piI2cSetDelay(i2c_fd, 0) < 0) {
        perror("Error setting I2C delay");
        exit(EXIT_FAILURE);
    }

    // Set I2C address to 0x23
    if (piI2cSetAddress(i2c_fd, I2C_ADDRESS) < 0) {
        perror("Error setting I2C address");
        exit(EXIT_FAILURE);
    }

    // Set I2C mode to continuous high-resolution mode
    if (piI2cSetMode(i2c_fd, I2C_CONT_HIGH_RES) < 0) {
        perror("Error setting I2C mode");
        exit(EXIT_FAILURE);
    }

    // Read illuminance from the sensor
    if (piI2cReadReg16(i2c_fd, BH1750_REG_R, &lux_reading) < 0) {
        perror("Error reading illuminance from sensor");
        exit(EXIT_FAILURE);
    }

    // Check if the sensor is detected
    if (lux_reading == 0xFFFF) {
        printf("Error: Sensor not detected\n");
        exit(EXIT_FAILURE);
    }

    // Log the lux reading and relay state change
    if (logLuxReading(grow_log_file, lux_reading) < 0) {
        perror("Error logging lux reading");
        exit(EXIT_FAILURE);
    }

    // Check if the relay state change is needed
    if (lux_reading < 150) {
        if (activateGrowLamp(relay_fd) < 0) {
            perror("Error activating grow lamp");
            exit(EXIT_FAILURE);
        }
    }

    // Wait for user input to exit
    printf("Press Ctrl+C to exit...\n");
    getchar();

    // Close I2C handle
    if (piI2cClose(i2c_fd) < 0) {
        perror("Error closing I2C handle");
        exit(EXIT_FAILURE);
    }

    // Close relay GPIO
    if (close(relay_fd) < 0) {
        perror("Error closing relay GPIO file");
        exit(EXIT_FAILURE);
    }

    // Release pigpio resources
    if (gpioTerminate() < 0) {
        perror("Error terminating pigpio");
        exit(EXIT_FAILURE);
    }

    return 0;
}

