    int unlockButtonPin = UNLOCK_BUTTON_PIN;
    int servoPwmValue = PULSE_WIDTH;
    int debounceCount = 0;
    int pulseWidth = 0;
    int pulseWidthLocked = 0;
    int pulseWidthUnlocked = 0;
    int previousButtonState = 0;
    int previousPwmValue = 0;
    int exitCode = 0;

