        fprintf(stderr, "Failed to set servo range: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (!pigpio_set_servo_pulsewidth(gpioHandle, PI_SERVO_MIN, servoPwmValue)) {
        fprintf(stderr, "Failed to set servo pulse width: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (!pigpio_set_pullup_en(gpioHandle, servoButtonPin)) {
        fprintf(stderr, "Failed to enable pull-up on servo button pin: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (!pigpio_set_pullup_en(gpioHandle, lockButtonPin)) {
