    if (!pigpio_set_interrupt_edge(gpioHandle, PI_INT_RISING | PI_INT_FALLING)) {
        fprintf(stderr, "Failed to set GPIO interrupt edge: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

