        exit(EXIT_FAILURE);
    }

    if (!pigpio_set_pullup_en(gpioHandle, servoButtonPin)) {
        fprintf(stderr, "Failed to enable pull-up on servo button pin: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

