                pigpio_set_servo_pulsewidth(gpioHandle, servoPin, pulseWidthLocked);
            }

            pulseWidth = pulseWidthLocked;
            pulseWidthLocked = pulseWidthUnlocked;
            pulseWidthUnlocked = 0;
            debounceCount = 100;
        }

        if (pigpio_get_gpio_level(gpioHandle, lockButtonPin) == 0) {
            printf("Lock button pressed\n");
            pigpio_set_servo_pulsewidth(gpioHandle, servoButtonPin, pulseWidthLocked);
