#define SOUND_SENSOR_MODE 1
#define ALARM_NODE_MODE 2

int main(int argc, char *argv[]) {
    int gpio_fd;
    int sound_sensor_gpio = 17;
    int alarm_node_gpio = 27;
    int sound_sensor_mode = SOUND_SENSOR_MODE;
    int alarm_node_mode = ALARM_NODE_MODE;
    int sound_sensor_threshold = 500;
    int alarm_node_duration = 1;

    if (argc != 2) {
        printf("Usage: %s <mode>\n", argv[0]);
        return 1;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        gpio_fd = gpio_open(sound_sensor_gpio);
        if (gpio_fd < 0) {
            perror("Failed to open GPIO");
            return 1;
        }

        gpio_set_mode(gpio_fd, PI_OUTPUT);
        gpio_set_dir(gpio_fd, 1);

        while (1) {
            if (sound_sensor_mode == SOUND_SENSOR_MODE) {
                gpio_set_level(gpio_fd, 0);
                usleep(10000);
                gpio_set_level(gpio_fd, 1);
            }

            gpio_read(gpio_fd, &gpio_state);
            if (gpio_state == 0) {
                printf("Sound detected!\n");
                // Publish alerts via ZeroMQ
                // ...
            }

            usleep(10000);
        }
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        gpio_fd = gpio_open(alarm_node_gpio);
        if (gpio_fd < 0) {
            perror("Failed to open GPIO");
            return 1;
        }

        gpio_set_mode(gpio_fd, PI_INPUT);
        gpio_set_dir(gpio_fd, 1);

        gpio_fd2 = gpio_open(alarm_node_gpio);
        if (gpio_fd2 < 0) {
            perror("Failed to open GPIO");
            return 1;
        }

        gpio_set_mode(gpio_fd2, PI_OUTPUT);
        gpio_set_dir(gpio_fd2, 1);

        while (1) {
            gpio_read(gpio_fd, &gpio_state);
            if (gpio_state == 1) {
                printf("Alarm triggered!\n");
                // Light the alarm LED
                // ...
            }

            gpio_read(gpio_fd2, &gpio_state);
            if (gpio_state == 0) {
                printf("No sound detected!\n");
            }

            usleep(10000);
        }
    } else {
        printf("Invalid mode. Use 'sound_sensor' or 'alarm_node'.\n");
        return 1;
    }

    gpio_close(gpio_fd);
    gpio_close(gpio_fd2);
    gpio_unexport(sound_sensor_gpio);
    gpio_unexport(alarm_node_gpio);

    return 0;
}

