                usleep(10000);
                gpio_set_level(gpio_fd, 1);
            }

            gpio_read(gpio_fd, &gpio_state);
            if (gpio_state == 0) {
                printf("Sound detected!\n");
                // Publish alerts via ZeroMQ
                // ...
            }

            usleep(10000);
        }
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        gpio_fd = gpio_open(alarm_node_gpio);
        if (gpio_fd < 0) {
            perror("Failed to open GPIO");
            return 1;
        }

        gpio_set_mode(gpio_fd, PI_INPUT);
        gpio_set_dir(gpio_fd, 1);

        gpio_fd2 = gpio_open(alarm_node_gpio);
        if (gpio_fd2 < 0) {
            perror("Failed to open GPIO");
            return 1;
        }

        gpio_set_mode(gpio_fd2, PI_OUTPUT);
        gpio_set_dir(gpio_fd2, 1);

        while (1) {
            gpio_read(gpio_fd, &gpio_state);
            if (gpio_state == 1) {
                printf("Alarm triggered!\n");
                // Light the alarm LED
                // ...
            }

            gpio_read(gpio_fd2, &gpio_state);
            if (gpio_state == 0) {
                printf("No sound detected!\n");
            }

            usleep(10000);
        }
    } else {
        printf("Invalid mode. Use 'sound_sensor' or 'alarm_node'.\n");
        return 1;
    }

    gpio_close(gpio_fd);
    gpio_close(gpio_fd2);
    gpio_unexport(sound_sensor_gpio);
    gpio_unexport(alarm_node_gpio);

    return 0;
}
