#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESSES 0x23, 0x24, 0x25, 0x26
#define NUM_SENSORS 4
#define SENSOR_READINGS_PER_SECOND 1000
#define SENSOR_READINGS_PER_MULTICAST_PACKET 10

int main() {
    int sock, i;
    struct sockaddr_in multicast_addr, local_addr;
    struct i2c_msg msgs[NUM_SENSORS];
    int num_msgs;
    int sensor_readings[NUM_SENSORS][2];
    int sensor_id;
    float lux;

    // Open I2C bus
    if ((sock = open(I2C_BUS, O_RDWR)) == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(sock, I2C_SLAVE, SENSOR_ADDRESSES) == -1) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    // Initialize sensor readings
    for (i = 0; i < NUM_SENSORS; i++) {
        memset(sensor_readings[i], 0, sizeof(sensor_readings[i]));
    }

    // Loop to read sensor readings and broadcast them as a UDP multicast packet
    while (1) {
        // Wait for sensor readings
        for (i = 0; i < NUM_SENSORS; i++) {
            if (ioctl(sock, I2C_RDWR, SENSOR_ADDRESSES) == -1) {
                perror("Failed to read from I2C bus");
                exit(EXIT_FAILURE);
            }

            // Read sensor data
            msgs[i].addr = SENSOR_ADDRESSES;
            msgs[i].flags = 0;
            msgs[i].buf = &sensor_readings[i][0];
            msgs[i].len = sizeof(sensor_readings[i]);
            num_msgs = 1;

            if (ioctl(sock, I2C_MULTI_TRANSACTION, msgs, num_msgs) == -1) {
                perror("Failed to read from I2C bus");
                exit(EXIT_FAILURE);
            }

            // Convert sensor data to lux
            lux = ((sensor_readings[i][0] << 8) | sensor_readings[i][1]) / 1.2;

            // Broadcast sensor readings as a UDP multicast packet
            memset(&local_addr, 0, sizeof(local_addr));
            local_addr.sin_family = AF_INET;
            local_addr.sin_addr.s_addr = inet_addr("239.255.255.250");
            local_addr.sin_port = htons(5005);

            if (inet_pton(AF_INET, "239.255.255.250", &local_addr.sin_addr) <= 0) {
                perror("Invalid IP address");
                exit(EXIT_FAILURE);
            }

            if (sendto(sock, &lux, sizeof(lux), 0, (struct sockaddr *)&local_addr, sizeof(local_addr)) == -1) {
                perror("Failed to send UDP multicast packet");
                exit(EXIT_FAILURE);
            }
        }

        // Wait for a short period of time
        sleep(1);
    }

    // Close I2C bus and socket
    close(sock);
    close(sock);

    return 0;
}

