#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x28

int main() {
    int fd;
    int ret;
    int i;
    int retryCount = 3;
    int delayMs = 100;

    // Initialize I2C bus
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        return 1;
    }

    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        goto close_fd;
    }

    // Set up the sensor for reading
    if (gpioSetMode(GPIO_PWM0) < 0) {
        fprintf(stderr, "Failed to set PWM0 mode\n");
        goto close_fd;
    }

    if (gpioSetPWMFrequency(GPIO_PWM0, 100000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        goto close_fd;
    }

    if (gpioSetPWMOutput(GPIO_PWM0) < 0) {
        fprintf(stderr, "Failed to set PWM output\n");
        goto close_fd;
    }

    if (gpioSetPWM(GPIO_PWM0, 0) < 0) {
        fprintf(stderr, "Failed to set PWM to 0\n");
        goto close_fd;
    }

    // Read flow data from the sensor
    if ((ret = gpioRead(GPIO_PWM0, 0)) < 0) {
        fprintf(stderr, "Failed to read PWM\n");
        goto close_fd;
    }

    if (ret > 0) {
        // Read flow data
        uint16_t rawData;
        if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
            fprintf(stderr, "Failed to set I2C slave address\n");
            goto close_fd;
        }

        if (ioctl(fd, I2C_RDWR, I2C_ADDR) < 0) {
            fprintf(stderr, "Failed to read I2C device\n");
            goto close_fd;
        }

        if (ioctl(fd, I2C_RD, &rawData, sizeof(rawData)) < 0) {
            fprintf(stderr, "Failed to read I2C device\n");
            goto close_fd;
        }

        // Convert raw data to flow value
        uint16_t flow = (rawData & 0x3FFF) * 0.1;

        // Log the flow rate
        FILE *logFile = fopen("airflow_log.txt", "a");
        if (logFile == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            goto close_fd;
        }

        fprintf(logFile, "Timestamp: %lu, Flow Rate: %.2f SLPM\n", (unsigned long)time(NULL), flow);

        fclose(logFile);
    }

    // Close the I2C file descriptor
    if (close(fd) < 0) {
        fprintf(stderr, "Failed to close I2C device\n");
        goto close_fd;
    }

    // Cleanup
    gpioTerminate();

close_fd:
    close(fd);
    gpioTerminate();
    return 1;
}

