#define I2C_ADDRESS 0x37
#define I2C_SLAVE 0x37
#define I2C_BUFFER_SIZE 6
#define I2C_RETRIES 3
#define I2C_BACKOFF_TIME 10

void i2c_init(int i2c_fd) {
    struct i2c_rdwr_ioctl_data data;
    memset(&data, 0, sizeof(data));
    data.flags = 0;
    data.timeout_ns = 100000;
    data.mode = I2C_MODE_I2C;
    data.function = I2C_FUNCTION_I2C;
    data.i2c_fd = i2c_fd;
    data.buf = malloc(I2C_BUFFER_SIZE * sizeof(int));
    if (data.buf == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    data.buf[0] = I2C_SLAVE;
    data.buf[1] = 0x28;
    data.buf[2] = 0x00;
    data.buf[3] = 0x00;
    data.buf[4] = 0x00;
    data.buf[5] = 0x00;
    data.buf[6] = 0x00;
    data.buf[7] = 0x00;
    data.buf[8] = 0x00;
    data.buf[9] = 0x00;
    data.buf[10] = 0x00;
    data.buf[11] = 0x00;
    data.buf[12] = 0x00;
    data.buf[13] = 0x00;
    data.buf[14] = 0x00;
    data.buf[15] = 0x00;
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_RDWR, I2C_SLAVE) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_RDWR_WAIT, &data) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
}

