#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x23
#define UDP_ADDR "239.255.255.250"
#define UDP_PORT 5000
#define TTL 1

int i2c_fd;
struct sockaddr_in udp_addr;

void i2c_init() {
    int ret;

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_fd, I2C_FUNCS, 0x01);
    if (ret < 0) {
        perror("Failed to set I2C function mode");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_fd, I2C_G_CR, 0x10);
    if (ret < 0) {
        perror("Failed to set I2C continuous high-resolution mode");
        exit(EXIT_FAILURE);
    }
}

void i2c_cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void read_sensor() {
    uint16_t raw_value;
    int ret;

    ret = ioctl(i2c_fd, I2C_RDWR, 0);
    if (ret < 0) {
        perror("Failed to enter I2C read-write mode");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_fd, I2C_RD, &raw_value);
    if (ret < 0) {
        perror("Failed to read raw value from sensor");
        exit(EXIT_FAILURE);
    }

    uint16_t lux = raw_value / 1.2;
    printf("Ambient light: %.2f lux\n", lux);
}

void broadcast_lux(uint16_t lux) {
    struct sockaddr_in broadcast_addr;
    int ret;

    memset(&broadcast_addr, 0, sizeof(broadcast_addr));
    broadcast_addr.sin_family = AF_INET;
    broadcast_addr.sin_port = htons(UDP_PORT);
    inet_pton(AF_INET, UDP_ADDR, &broadcast_addr.sin_addr);

    ret = sendto(i2c_fd, &lux, sizeof(uint16_t), 0, (struct sockaddr *)&broadcast_addr, sizeof(broadcast_addr));
    if (ret < 0) {
        perror("Failed to broadcast lux value");
        exit(EXIT_FAILURE);
    }
}

void handle_signal(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    i2c_cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    i2c_init();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        read_sensor();
        broadcast_lux(lux);
        sleep(1);
    }

    i2c_cleanup();

    return 0;
}

