#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <sys/select.h>
#include <signal.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/time.h>

#include <gpiod.h>
#include <pigpio.h>

#define UART_DEVICE_PATH "/dev/serial0"
#define UART_BAUD_RATE 115200
#define UART_LINE_BUFFER_SIZE 1024

int main() {
    int uart_fd;
    struct termios options;
    struct sigaction sa;
    struct timeval timeout;
    char buffer[UART_LINE_BUFFER_SIZE];
    char *line = NULL;
    char *timestamp = NULL;
    char *range = NULL;
    int line_length = 0;
    int sensor_absent = 0;
    int bus_error = 0;
    int exit_code = 0;

    // Initialize GPIO and UART
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        goto cleanup;
    }

    if (gpioSetBrightness(0, 0) < 0) {
        fprintf(stderr, "Failed to set brightness to 0.\n");
        goto cleanup;
    }

    if (gpioSetBrightness(255, 255) < 0) {
        fprintf(stderr, "Failed to set brightness to 255.\n");
        goto cleanup;
    }

    if (gpioOpen(GPIO_UNUSED, &uart_fd) < 0) {
        fprintf(stderr, "Failed to open UART.\n");
        goto cleanup;
    }

    if (tcgetattr(uart_fd, &options) < 0) {
        fprintf(stderr, "Failed to get UART options.\n");
        goto cleanup;
    }

    options.c_cflag = UART_BAUD_RATE | CS8 | CLOCAL | CREAD;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;

    if (tcsetattr(uart_fd, TCSANOW, &options) < 0) {
        fprintf(stderr, "Failed to set UART options.\n");
        goto cleanup;
    }

    timeout.tv_sec = 2;
    timeout.tv_usec = 0;

    while (1) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        // Wait for data or timeout
        int ready = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);
        if (ready == -1) {
            if (errno == EINTR) {
                continue;
            } else {
                fprintf(stderr, "select failed: %s\n", strerror(errno));
                goto cleanup;
            }
        }

        // Check for data availability
        if (FD_ISSET(uart_fd, &readfds)) {
            // Read data from UART
            if (read(uart_fd, buffer, UART_LINE_BUFFER_SIZE) < 0) {
                fprintf(stderr, "Failed to read from UART.\n");
                goto cleanup;
            }

            // Parse data
            if (sscanf(buffer, "%d,%d\n", &line_length, &range) == 2) {
                if (line_length > 0 && range != NULL) {
                    // Log valid detection
                    timestamp = strdup(strftime("%Y-%m-%d %H:%M:%S", localtime(&line_length)));
                    if (timestamp == NULL) {
                        fprintf(stderr, "Failed to format timestamp.\n");
                        goto cleanup;
                    }

                    // Log detection
                    fprintf(stdout, "Timestamp: %s, Range: %f meters\n", timestamp, range);

                    // Release resources
                    free(timestamp);
                    free(range);
                }
            }
        }

        // Check for sensor-absent or bus-error paths
        if (sensor_absent || bus_error) {
            break;
        }
    }

cleanup:
    // Close UART
    gpioClose(uart_fd);

    // Release GPIO resources
    gpioUninitialise();

    return exit_code;
}

